```c
#include <stdlib.h>
#include <stdio.h>

typedef struct { /* Define FSA structure */
    int id;
    int* next;
    int numClasses;
    char** classes;
    int hasId;
    char* idName;
} Node;

int testSelector(Node* node, int selector);

void freeStateList(int** stateList, int size);

int** traverseFSA(int* states, int numStates, Node* fsa, int lastState, const char* selector) {
    if (fsa == NULL || *fsa == -1) return NULL; // base case: no more nodes to explore

    Node* currentNode = &fsa[lastState];
    if (testSelector(currentNode, selector)) {
        states[numStates] = lastState;
        numStates++;
    }

    int* newStateList = malloc((numStates + 1) * sizeof(int));
    if (newStateList == NULL) return NULL; // out of memory

    for (int i = 0; i < numStates; ++i) {
        newStateList[i] = states[i];
    }

    int* nextStateList = traverseFSA(newStateList, numStates + 1, currentNode->next, currentNode - fsa, selector);
    if (nextStateList != NULL) {
        free(states);
        return nextStateList;
    }

    free(newStateList); // no matching nodes were found in the newly traversed states
    return states;
}

int testSelector(Node* node, int selector) {
    if (selector == node->id) return 1;
    for (int i = 0; i < node->numClasses; ++i) {
        if (node->classes[i] == selector) return 1;
    }
    return 0;
}

void freeStateList(int** stateList, int size) {
    free(*stateList);
}
