public delegate bool MatchSelectorCallback(XmlNode node);

public IEnumerable<XmlNode> FindElementsBySelector(XmlNode currentNode, string selector, MatchSelectorCallback matchCallback)
{
    if (currentNode == null) throw new ArgumentNullException(nameof(currentNode));

    if (matchCallback(currentNode))
        yield return currentNode;

    foreach (var node in currentNode.ChildNodes)
    {
        if (node.NodeType == XmlNodeType.Element)
        {
            var elements = FindElementsBySelector(node as XmlElement, selector, matchCallback);
            foreach (var e in elements)
                yield return e;
        }

        if (node is XmlElement xmlElement && node.LocalName == "#text")
            continue;

        var results = FindElementsBySelector(node as XmlNode, selector, matchCallback);
        foreach (var result in results)
            yield return result;
    }
}
