using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

public class CustomObject
{
    public string Property1 { get; set; }
    // Add other properties as needed
}

public static async Task<List<CustomObject>> ExecuteStoredProcedureAsync(string connectionString, List<SqlParameter> inputParameters, string storedProcedureName)
{
    var cacheKey = string.Join(",", inputParameters.Select(p => p.ParameterName + ":" + p.Value));
    var cachedResult = HttpContext.Current.Items[cacheKey];

    if (cachedResult != null)
        return (List<CustomObject>)cachedResult;

    using (var connection = new SqlConnection(connectionString))
    {
        await connection.OpenAsync();
        using (var command = new SqlCommand(storedProcedureName, connection))
        {
            command.CommandType = CommandType.StoredProcedure;
            inputParameters.ForEach(command.Parameters.Add);

            var result = new List<CustomObject>();
            using (var reader = await command.ExecuteReaderAsync())
            {
                var customObjectMapper = Mapper.CreateMap<DataRow, CustomObject>();
                result = reader.AsEnumerable().Select(customObjectMapper.Map).ToList();
            }

            HttpContext.Current.Items[cacheKey] = result;
        }
    }

    return result;
}
```

