#include <fstream>
#include <vector>
#include <RapidJSON/Document.h>
#include <RapidJSON/Writer.h>
#include <RapidJSON/StringBuffer.h>
#include <memory>

class Node {
public:
    int key;
    std::string value;

    Node(int k, const std::string& v) : key(k), value(v) {}
};

std::vector<Node*> readNodesFromFile(const std::string& filename, size_t threshold) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Unable to open file");
    }

    rapidjson::Document jsonDoc;
    char c;
    while (file >> c) {
        jsonDoc.ParseIterative(c);
    }

    if (jsonDoc.HasParseError()) {
        throw std::runtime_error("JSON parsing error");
    }

    const rapidjson::Value& nodes = jsonDoc["nodes"];
    size_t currentSize = nodes.Size();
    std::vector<Node*> nodeVec(currentSize);

    for (size_t i = 0; i < currentSize; ++i) {
        const rapidjson::Value& node = nodes[i];
        int key = node["key"].GetInt();
        std::string value = node["value"].GetString();
        nodeVec[i] = new Node(key, value);
    }

    size_t maxSize = threshold;
    if (currentSize > maxSize) {
        maxSize += threshold;
        for (size_t i = currentSize; i < maxSize; ++i) {
            nodeVec.push_back(new Node(-1, "")); // Add a placeholder node
        }
    }

    return nodeVec;
}

rapidjson::Document serializeNodesToJson(const std::vector<Node*>& nodes) {
    rapidjson::Document jsonDoc(rapidjson::kObjectType);
    rapidjson::Document::AllocatorType& allocator = jsonDoc.GetAllocator();

    jsonDoc.AddMember("nodes", rapidjson::Value(rapidjson::kArrayType), allocator);

    size_t i = 0;
    for (const Node* node : nodes) {
        if (node != nullptr) {
            rapidjson::Value nodeJson(rapidjson::kObjectType);
            nodeJson.AddMember("key", node->key, allocator);
            nodeJson.AddMember("value", node->value, allocator);
            jsonDoc["nodes"][i++] = nodeJson;
        }
    }

    return jsonDoc;
}
