import java.net.*;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;

public class GameCharacter {
    private SocketChannel socketChannel;
    private boolean connected = false;
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private AtomicBoolean attacking = new AtomicBoolean(false);
    private Random random = new Random();

    public void initialize() throws IOException {
        Socket socket = new Socket("remote-address", port);
        this.socketChannel = SocketChannel.open(socket.getSocketAddress());
        connected = true;
        executor.submit(() -> handleConnection());
    }

    private void handleConnection() throws IOException {
        while (connected) {
            if (!attacking.get()) {
                int attackNumber = random.nextInt(2);
                System.out.println("Selected attack: " + attackNumber);
                attacking.set(true);
                Timer timer = new Timer();
                timer.schedule(new TimerTask() {
                    @Override
                    public void run() {
                        attacking.set(false);
                    }
                }, TimeUnit.SECONDS.toMillis(9));
            }
            socketChannel.read(ByteBuffer.allocateDirect(1024));
        }
        socketChannel.close();
        executor.shutdownNow();
    }
}
