using System;
using UnityEngine;

public class CustomRandomGenerator
{
    private float _minValue;
    private float _maxValue;
    private bool _isExclusive;
    private bool _seeded;
    private int? _seed;

    public CustomRandomGenerator(float min, float max, bool isExclusive, bool seeded, int? seed)
    {
        SetRange(min, max, isExclusive);
        SetSeed(seeded, seed);
    }

    private void SetRange(float min, float max, bool isExclusive)
    {
        if (max <= min)
            throw new ArgumentException($"Invalid range: {nameof(min)} > {nameof(max)}");
        _minValue = min;
        _maxValue = max;
        _isExclusive = isExclusive;
    }

    private void SetSeed(bool seeded, int? seed)
    {
        if (seed != null && !seeded)
            throw new ArgumentException($"{nameof(seed)} cannot be specified when {nameof(seeded)} is false");
        _seeded = seeded;
        _seed = seed;
        if (_seed.HasValue)
            UnityEngine.Random.Seed(_seed.Value);
    }

    public float CustomRange(bool inclusive, int? overrideSeed = null)
    {
        if (overrideSeed.HasValue && !_seeded)
            throw new InvalidOperationException($"{nameof(CustomRange)} cannot be used with a seed when {nameof(_seeded)} is false");

        float range = _maxValue - (_isExclusive ? _minValue : 0);
        float randomValue = UnityEngine.Random.value * range;
        if (inclusive)
            return _minValue + randomValue;
        else
            return _minValue + randomValue + (_isExclusive ? 0 : 1);
    }

    public int CustomRange(bool inclusive, int? overrideSeed = null)
    {
        if (overrideSeed.HasValue && !_seeded)
            throw new InvalidOperationException($"{nameof(CustomRange)} cannot be used with a seed when {nameof(_seeded)} is false");

        float range = _maxValue - (_isExclusive ? _minValue : 0);
        int randomValue = (int)(UnityEngine.Random.value * range + (_minValue - Convert.ToSingle(Math.Ceiling(_minValue))));
        if (inclusive)
            return (int)_minValue + (randomValue - (int)Math.Ceiling(_minValue));
        else
            return (int)_minValue + (randomValue - (int)Math.Ceiling(_minValue)) + (_isExclusive ? 0 : 1);
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        sb.Append($"Range: [{_minValue}, {(_isExclusive ? _maxValue - 1 : _maxValue}]");
        if (_seeded && _seed.HasValue)
            sb.AppendFormat(", Seed: {0}", _seed);
        return sb.ToString();
    }
}
