import importlib.util
from functools import lru_cache
from typing import Dict, Any, Type

@lru_cache(maxsize=128)  # Caching for performance improvement
def _get_module(module_name: str) -> Any:
    try:
        spec = importlib.util.find_spec(module_name)
        return importlib.import_module(module_name, spec.origin)
    except (AttributeError, ImportError):
        return None

def _get_protocols_config() -> Dict[str, Any]:
    with open("protocols_config.json", "r") as f:
        return json.load(f)

@lru_cache(maxsize=128)  # Caching for performance improvement
def _get_protocol(name: str) -> Type[Any] or None:
    if name not in protocols_config:
        return None
    module_path = os.path.join(PROTOCOL_DIR, protocols_config[name]["module"])
    mod = _get_module(module_path)
    if not mod or not hasattr(mod, protocols_config[name]["class"]):
        return None
    return getattr(mod, protocols_config[name]["class"])

def get_available_protocols() -> Dict[str, Dict[str, Any]]:
    config = _get_protocols_config()
    available_protocols = {}
    for name in config.keys():
        protocol = _get_protocol(name)
        if protocol is not None:
            available_protocols[name] = {
                "name": name,
                "implementation_class": protocol,
                "description": config[name]["description"],
                "supported_features": config[name]["supported_features"]
            }
    return available_protocols

