```javascript
class DependencyResolver {
  constructor() {
    this.modules = new Map();
    this.dependencies = new Set();
  }

  addModule(id, dependencies) {
    if (this.modules.has(id)) return;

    const module = { id, isLoaded: false };
    this.modules.set(id, module);

    for (const depId of dependencies) {
      if (!this.modules.has(depId)) throw new Error(`Circular dependency detected: ${depId}`);

      if (!this.modules.get(depId).isLoaded) {
        this.dependencies.add(depId);
      }
    }
  }

  loadModules() {
    const promises = [...this.dependencies].map(id =>
      import(`./${id}.js`).then(module => {
        this.modules.get(id).module = module;
        this.modules.get(id).isLoaded = true;

        // Execute the main function of the loaded module if it exists
        const mainFnName = 'main';
        if (this.modules.get(id)[mainFnName]) {
          this.modules.get(id)[mainFnName]();
        }
      })
    );

    return Promise.all(promises);
  }
}

// Usage example
const resolver = new DependencyResolver();

// Add modules to the resolver, specifying their dependencies
resolver.addModule('module1', []);
resolver.addModule('module2', ['module1']);
resolver.addModule('module3', ['module1', 'module2']);

// Load all the added modules and execute them
resolver.loadModules().then(() => console.log("All modules have been loaded."));
```

