using System;
using UnityEngine;

public enum RangeType { Closed, Open, HalfOpen }
public delegate void SeedCallback(int seed);

public class AdvancedRandomGenerator
{
    private readonly Random _random;
    private int _seed;
    private readonly Dictionary<(float min, float max, RangeType rangeType), ulong> _cache;

    public AdvancedRandomGenerator(bool seeded = false, int? seed = null, SeedCallback? callback = null)
    {
        _random = new Random(seed ?? UnityEngine.Random.Seed);
        _seed = seed ?? UnityEngine.Random.Seed;
        _cache = new Dictionary<(float min, float max, RangeType rangeType), ulong>();
        if (callback != null) callback(_seed);
    }

    public void SetSeed(int seed, SeedCallback? callback = null)
    {
        _random = new Random(seed);
        _seed = seed;
        if (callback != null) callback(_seed);
    }

    public float CustomRange(float min, float max, RangeType rangeType, bool includeMax = true)
    {
        var key = (min, max, rangeType);
        ulong cacheKey;

        if (_cache.TryGetValue(key, out cacheKey))
        {
            // Use cached result if available
            return BitConverter.ToSingle(BitConverter.GetBytes((double)cacheKey), 8);
        }

        double randomValue;

        switch (rangeType)
        {
            case RangeType.Closed:
                randomValue = _random.NextDouble() * (max - min) + min;
                break;
            case RangeType.Open:
                if (includeMax)
                    randomValue = _random.NextDouble() * (max - min);
                else
                    randomValue = _random.NextDouble() * (max - min) + min;
                break;
            case RangeType.HalfOpen:
                if (includeMax)
                    randomValue = _random.NextDouble() * max + min;
                else
                    randomValue = _random.NextDouble() * max;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(rangeType), rangeType, null);
        }

        cacheKey = BitConverter.DoubleToUInt64Bits((double)randomValue);
        _cache[key] = cacheKey;
        return (float)BitConverter.ToSingle(BitConverter.GetBytes(cacheKey), 8);
    }

    public int CustomRange(int min, int max, RangeType rangeType, bool includeMax = true) =>
        (int)CustomRange((float)min, (float)max, rangeType, includeMax);
}
