import boto3
import time
import tempfile
import requests
from PIL import Image

s3 = boto3.client('s3')

def get_image_hash(img_path):
    with open(img_path, "rb") as file:
        return hashlib.md5(file.read()).hexdigest()

def upload_image_to_s3(bucket_name, key_name, file_obj):
    try:
        s3.put_object(Bucket=bucket_name, Key=key_name, Body=file_obj)
        return True
    except Exception as e:
        print(f"Error uploading image to S3: {e}")
        return False

def cache_directory(cache_dir='./cache', max_age_hours=24):
    now = int(time.time())

    for file in list(os.listdir(cache_dir)):
        path = os.path.join(cache_dir, file)
        if not os.path.isfile(path):
            continue
        mtime = os.stat(path).st_mtime
        age = now - mtime
        if age > max_age_hours * 3600:
            os.remove(path)
    return cache_dir

def upload_image_from_url(url, bucket_name, cache_dir=None):
    if not cache_dir:
        cache_dir = cache_directory()

    img_hash = url.split("/")[-1]
    cached_img_path = os.path.join(cache_dir, img_hash)

    if os.path.isfile(cached_img_path):
        with open(cached_img_path, "rb") as file:
            return s3.generate_presigned_url('get_object', Params={'Bucket': bucket_name, 'Key': img_hash})

    try:
        response = requests.get(url)
        response.raise_for_status()

        with tempfile.TemporaryFile() as file:
            file.write(response.content)
            file.seek(0)

            img = Image.open(file)
            img_hash = get_image_hash(BytesIO(img))

            if not upload_image_to_s3(bucket_name, img_hash, file):
                return None

            with open(cached_img_path, "wb") as cache_file:
                for chunk in img:
                    cache_file.write(chunk)

        return s3.generate_presigned_url('get_object', Params={'Bucket': bucket_name, 'Key': img_hash})

    except requests.exceptions.RequestException as e:
        print(f"Error fetching image from URL: {e}")
        return None
