using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Net.Http;
using System.Linq;
using Microsoft.Extensions.Logging;

namespace MyProject.Services
{
    public class CipherService
    {
        private readonly ILogger<CipherService> _logger;
        private readonly HttpClient _httpClient;
        private readonly string _tokenEndpoint;
        private readonly byte[] _encryptionKey;
        private readonly byte[] _iv;

        public CipherService(ILogger<CipherService> logger, HttpClient httpClient, string tokenEndpoint, byte[] encryptionKey, byte[] iv)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
            _tokenEndpoint = tokenEndpoint;
            _encryptionKey = encryptionKey;
            _iv = iv;
        }

        public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext)
        {
            if (ciphertext == null || ciphertext.Length == 0)
                throw new ArgumentException("Ciphertext cannot be null or empty.");

            var tokenTask = RetrieveTokenAsync();
            await Task.WhenAll(tokenTask, Task.Delay(TimeSpan.FromSeconds(10))); // Timeout after 10 seconds if token fails to retrieve

            using (var aesAlg = Aes.Create())
            {
                await using var tokenStream = await tokenTask;
                var decryptedToken = DecryptData(ciphertext, aesAlg.Key, _iv);
                var token = Encoding.UTF8.GetString(decryptedToken);

                if (!ValidateToken(token))
                    throw new InvalidOperationException("Invalid or expired token.");

                await using var decryptionStream = tokenStream as MemoryStream;
                aesAlg.Key = _encryptionKey;
                aesAlg.IV = _iv;

                using (var cryptoTransform = aesAlg.CreateDecryptor())
                {
                    var plaintext = new MemoryStream();
                    cryptoTransform.TransformBlock(decryptionStream.ToArray(), 0, decryptionStream.Length, plaintext, 0);
                    plaintext.Close();

                    return plaintext.ToArray();
                }
            }
        }

        private async Task<Stream> RetrieveTokenAsync()
        {
            try
            {
                var response = await _httpClient.GetAsync(_tokenEndpoint);
                if (!response.IsSuccessStatusCode)
                    throw new HttpRequestException($"Error retrieving token: {response.ReasonPhrase}");

                return await response.Content.ReadAsStreamAsync();
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to retrieve token.");
                throw;
            }
        }

        private bool ValidateToken(string token)
        {
            // Implement your custom token validation logic here.
            return true;
        }

        private byte[] DecryptData(byte[] data, byte[] key, byte[] iv)
        {
            using (var aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;

                using (var cryptoTransform = aesAlg.CreateDecryptor())
                {
                    var plaintext = new MemoryStream();
                    cryptoTransform.TransformBlock(data, 0, data.Length, plaintext, 0);
                    plaintext.Close();

                    return plaintext.ToArray();
                }
            }
        }
    }
}
