void insertString(std::forward_list<std::string>& myList, const std::string& searchStr, const std::string& insertStr, int repeat = 1) {
    auto it = myList.begin();
    if (myList.empty()) {
        std::cerr << "Error: List is empty." << std::endl;
        return;
    }

    try {
        DatabaseConnection& dbInstance = DatabaseConnection::getInstance();
        auto startTime = std::chrono::system_clock::now();

        if (std::next(it, searchStr.size()) != myList.end() && *it == searchStr) {
            it = std::prev(myList.insertAfter(*it, insertStr));
            for (int i = 1; i < repeat; ++i) {
                it = myList.insertAfter(*it, insertStr);
                ++it;
            }
        } else {
            myList.insertAfter(myList.end(), insertStr);
        }

        logOperation("Inserted string " + insertStr + " after " + searchStr + (repeat > 1 ? (" with repetition " + std::to_string(repeat)) : ""), myList);

        auto endTime = std::chrono::system_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
        // Log the time taken for this operation
        logOperation("Time taken for insertion: " + std::to_string(elapsed) + " milliseconds", {});
    } catch (const std::exception& e) {
        std::cerr << "Error: Database connection failed. Error message: " << e.what() << std::endl;
