        for (int i = 0; i < MAX_ATTEMPTS && !isConnected; ++i) {
            if (!seedSource->Connect()) {
                continue;
            }
            isConnected = true;
            auto seedData = FetchSeed();
            if (seedData.has_value()) {
                seed = *seedData;
                engine.seed(seed);
            } else {
                seed = rd();
                spdlog::warn("No initial seed from SeedSource, using default random seed.");
