void insert_and_log(Database& db, std::forward_list<std::string>& list, const std::string& target, const std::string& replacement) {
    try {
        auto it = list.begin();
        if (it == list.end()) {
            throw std::runtime_error("List is empty");
        }

        it = list.before_begin();
        ++it; // Move to the first element

        while (it != list.end() && *it != target) {
            ++it;
        }

        if (it == list.end()) {
            list.push_back(replacement);
        } else {
            list.insertafter(it, replacement);
        }

        std::vector<std::string> oldList;
        std::copy(list.begin(), list.end(), std::back_inserter(oldList));
        db.log(oldList, target, replacement, std::vector<std::string>(list.begin(), list.end()));
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }
}
