```csharp
using System;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Data;
using System.Text;

public class SqlQueryHelper
{
    private readonly IDbConnection _connection;

    public SqlQueryHelper(IDbConnection connection)
    {
        _connection = connection;
    }

    public DataTable ExecuteDynamicQuery(string commandTemplate, Dictionary<string, object> parameters, out string logMessage)
    {
        using (var command = new SqlCommand(commandTemplate, _connection as SqlConnection))
        {
            PrepareCommandParameters(parameters, command);

            try
            {
                _connection.Open();
                using (var transaction = _connection.BeginTransaction())
                {
                    command.Transaction = transaction;
                    var dataTable = new DataTable();

                    using (var reader = command.ExecuteReader())
                    {
                        dataTable.Load(reader);
                    }

                    transaction.Commit();

                    logMessage = string.Empty;
                    return dataTable;
                }
            }
            catch (Exception ex)
            {
                _connection.Close();
                logMessage = $"Error executing dynamic SQL query: {ex.Message}";
                throw;
            }
        }
    }

    private void PrepareCommandParameters(Dictionary<string, object> parameters, SqlCommand command)
    {
        foreach (var parameter in parameters)
        {
            command.Parameters.AddWithValue($"@{parameter.Key}", parameter.Value);
        }
    }
}
```

