2. Recursive JavaScript Function `FindElementsBySelector`:

```javascript
function FindElementsBySelector(callback, rootElement, selectors) {
    let elements = [];

    function traverse(element, currentSelectors) {
        if (currentSelectors.length === 0) {
            if (callback(element)) {
                elements.push(element);
            }
            return;
        }

        const selector = currentSelectors[0];
        const attributes = element.attributes || {};

        for (let i = 1; i < currentSelectors.length; i++) {
            if (!attributes[currentSelectors[i]]) {
                return;
            }
        }

        if (element.tagName.toLowerCase() === selector) {
            if (callback(element)) {
                elements.push(element);
            }
            return;
        }

        Array.from(element.children).forEach((childElement) => traverse(childElement, currentSelectors));
    }

    selectors.split(',').forEach((selector) => {
        const rootElements = rootElement.querySelectorAll(selector);
        [...rootElements].forEach((rootElement) => traverse(rootElement, selector.split('.')));
    });

    return elements;
}
