using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using RestSharp;

public delegate bool ConfigUpdateCallback(IDictionary<string, object> settings);

public class DynamicRandomNumberGenerator
{
    private Random _random;
    private long _seed;
    private double _minValue;
    private double _maxValue;
    private RangeType _rangeType;
    private ConfigUpdateCallback _configUpdateCallback;
    private static readonly object _lock = new object();
    private static IDictionary<string, dynamic> _cache;

    public DynamicRandomNumberGenerator(double minValue, double maxValue, RangeType rangeType, long seed)
    {
        Initialize(minValue, maxValue, rangeType, seed);
    }

    public async Task Initialize(double minValue, double maxValue, RangeType rangeType, long seed)
    {
        if (seed < 0)
            throw new ArgumentOutOfRangeException(nameof(seed), "The seed value must be non-negative.");

        _minValue = Math.Max(minValue, double.MinValue);
        _maxValue = Math.Min(maxValue, double.MaxValue);
        _rangeType = rangeType;
        _seed = seed;
        _cache = new Dictionary<string, dynamic>();

        await SetupConfigurationAsync();
    }

    private async Task SetupConfigurationAsync()
    {
        var client = new RestClient("http://external-api.com");
        var request = new RestRequest("/config", Method.GET);

        IRestResponse response = await client.ExecuteAsync(request);

        if (response.StatusCode != HttpStatusCode.OK)
            throw new Exception($"Error communicating with external API: {response.StatusCode}");

        dynamic config = JsonConvert.DeserializeObject<dynamic>(response.Content);
        _configUpdateCallback = DeserializeConfigUpdateCallback(config.callback);
    }

    private ConfigUpdateCallback DeserializeConfigUpdateCallback(string callbackJson)
    {
        return (Func<IDictionary<string, object>, bool>)(settings => JsonConvert.DeserializeObject<bool>(callbackJson));
    }

    public double GenerateCustomRandom(double minValue, double maxValue, RangeType rangeType, bool seeded = false)
    {
        lock (_lock)
        {
            if (minValue < double.MinValue || maxValue > double.MaxValue)
                throw new ArgumentOutOfRangeException("The provided range values are outside the acceptable limits.");

            Initialize(minValue, maxValue, rangeType, seeded ? _seed : Environment.TickCount64);
        }

        var random = _random ?? (_random = new Random(_seed));
        return GetRandomNumber(minValue, maxValue, rangeType);
    }

    private double GetRandomNumber(double minValue, double maxValue, RangeType rangeType)
    {
        switch (rangeType)
        {
            case RangeType.Closed:
                return random.NextDouble() * (maxValue - minValue) + minValue;
            case RangeType.Open:
                return random.NextDouble() * (maxValue - minValue);
            case RangeType.HalfOpenLowerBound:
                return minValue + random.NextDouble() * (maxValue - minValue);
            case RangeType.HalfOpenUpperBound:
                return minValue + random.NextDouble() * (maxValue - minValue) + maxValue;
        }
    }

    public void RegisterConfigUpdateCallback(ConfigUpdateCallback callback) => _configUpdateCallback = callback;

    private async Task UpdateConfigurationAsync()
    {
        if (_configUpdateCallback == null) return;

        var client = new RestClient("http://external-api.com");
        var request = new RestRequest("/config", Method.PUT);

        try
        {
            var settings = new Dictionary<string, object>
            {
                ["minValue"] = _minValue,
                ["maxValue"] = _maxValue,
                ["rangeType"] = _rangeType,
                ["seed"] = _seed
            };

            if (_configUpdateCallback(settings))
            {
                await SetupConfigurationAsync();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error updating configuration: {ex.Message}");
        }
    }
}

public enum RangeType
{
    Closed,
    Open,
    HalfOpenLowerBound,
    HalfOpenUpperBound
}
