using Microsoft.EntityFrameworkCore;

public void ConfigureServices(IServiceCollection services)
{
    services.AddDbContext<ApplicationDbContext>(options =>
        options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

    services.AddDefaultIdentity<IdentityUser>()
        .AddEntityFrameworkStores<ApplicationDbContext>()
        .AddDefaultTokenProviders()
        .AddUserStore<CustomUserStore<IdentityUser>>()
        .AddSignInManager<CustomSignInManager>();
}

public class CustomUserStore : UserStore<IdentityUser>
{
    public CustomUserStore(DbContext context) : base(context) { }

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);
        // Customize your user model here, for example:
        builder.Entity<IdentityUser>().Property(u => u.UserName).HasMaxLength(256);
        builder.Entity<IdentityUser>.HasIndex(u => u.NormalizedUserName).IsUnique();
    }
}

public class CustomSignInManager : SignInManager<IdentityUser>
{
    public CustomSignInManager(IUserValidator<IdentityUser> userValidator, IPasswordHasher<IdentityUser> passwordHasher, IEnumerable<INextPasswordServiceProvider> passwordServiceProviders, IUserClaimsPrincipalFactory<IdentityUser> claimsFactory, IAuthenticationManager authenticationManager, IHttpContextAccessor contextAccessor)
        : base(userValidator, passwordHasher, passwordServiceProviders, claimsFactory, authenticationManager, contextAccessor) { }

    public override Task<SignInResult> PasswordSignInAsync(string userName, string password, bool rememberMe, bool lockoutOnFailure)
    {
        // Customize your login logic here if needed.
        return base.PasswordSignInAsync(userName, password, rememberMe, lockoutOnFailure);
    }
}
