use std::env;
use std::fs::create_dir_all;

pub fn setup_directory(path: &str) {
    if env::var("MYDIR").is_ok() {
        let path = env::var("MYDIR").unwrap();
        println!("Using existing directory: {}", path);
    } else {
        create_dir_all(path).expect("Failed to create directory");
        env::set_var("MYDIR", path);
        println!("Created and set new directory: {}", path);
    }
}
