```csharp
using System;
using System.IO;
using System.Linq;
using Microsoft.Web.Administration;
using log4net;

namespace WebsiteManager
{
    public class TaskResult
    {
        public bool Success { get; set; }
        public string ErrorMessage { get; set; }
    }

    public class IisHelper
    {
        private static readonly ILog _log = LogManager.GetLogger(typeof(IisHelper));

        public TaskResult AddAndStartWebsite(string directoryPath, string siteName)
        {
            try
            {
                if (!Directory.Exists(directoryPath))
                {
                    _log.Error($"Specified directory does not exist: {directoryPath}");
                    return new TaskResult { Success = false };
                }

                if (!File.Exists(Path.Combine(directoryPath, "web.config")))
                {
                    _log.Error($"Directory '{directoryPath}' does not contain a 'web.config' file.");
                    return new TaskResult { Success = false };
                }

                var serverManager = new ServerManager();
                var site = serverManager.Sites.Cast<Site>().FirstOrDefault(s => s.Name == siteName);

                if (site != null)
                {
                    _log.Info($"Website '{siteName}' already exists.");
                    return new TaskResult { Success = false };
                }

                var appPool = CreateApplicationPoolIfNotExists("MyAppPool");
                var webSite = CreateWebsite(appPool, siteName);
                CreateBindingRule(webSite, directoryPath);
                webSite.Start();

                _log.Info($"Successfully added and started website '{siteName}'.");
                return new TaskResult { Success = true };
            }
            catch (Exception ex)
            {
                _log.Error(ex);
                return new TaskResult { Success = false, ErrorMessage = ex.Message };
            }
        }

        private ApplicationPool CreateApplicationPoolIfNotExists(string appPoolName)
        {
            var serverManager = new ServerManager();
            var applicationPool = serverManager.ApplicationPools.Cast<ApplicationPool>().FirstOrDefault(a => a.Name == appPoolName);

            if (applicationPool != null) return applicationPool;

            applicationPool = serverManager.CreateApplicationPool();
            applicationPool.Name = appPoolName;
            applicationPool.ManagedPipelineMode = ManagedPipelineMode.Integrated;
            applicationPool.AutoStart = true;
            serverManager.CommitChanges();

            return serverManager.GetApplicationPool(appPoolName);
        }

        private Site CreateWebsite(ApplicationPool appPool, string siteName)
        {
            var serverManager = new ServerManager();
            var site = serverManager.Sites.AddWebSite(siteName, appPool.Name);
            site.PhysicalPath = directoryPath;
            serverManager.CommitChanges();
            return site;
        }

        private Bindings CreateBindingRule(Site site, string physicalPath)
        {
            var serverManager = new ServerManager();
            var bindings = site.Bindings;

            foreach (var port in Enum.GetValues(typeof(HttpPort)))
            {
                try
                {
                    var binding = bindings.AddBinding(":", (int)port, "http", physicalPath);
                    binding.HostNames.AddRange(new[] { "*" });
                    serverManager.CommitChanges();
                    break;
                }
                catch (Exception ex)
                {
                    _log.Error($"Failed to bind site '{site.Name}' on port {port}. Error: {ex.Message}");
                }
            }

            return site.Bindings;
        }
    }
}
```

Please note that this code assumes you have already set up log4net for logging and the using statements are correctly imported in your project. Additionally, this example demonstrates a basic integration with IIS, so it may require adjustments to work seamlessly with different versions of IIS and Windows Server as per your specific environment requirements. Finally, remember to unit test this method to ensure its functionality under various conditions.

