#include <iostream>
#include <fstream>
#include <cstdlib>
#include <ctime>
#include <string>
#include <cstring>
#include <sys/stat.h>

const int MAX_PATH_LENGTH = 255;
const char DELIMITER = '_';

std::string generateUniqueFileName(const std::string& inputFilePath) {
    if (inputFilePath.length() > MAX_PATH_LENGTH) {
        throw std::invalid_argument("Input file path is too long.");
    }

    char timestring[19];
    time_t now = time(0);
    strftime(timestring, sizeof(timestring), "%Y%m%d_%H%M%S", localtime(&now));

    int randomLength = rand() % 8 + 4;
    char randomString[randomLength];
    for (int i = 0; i < randomLength; ++i) {
        randomString[i] = isalpha(drand48()) ? toupper((rand() % 26) + 'A') : rand() % 10 + '0';
    }
    randomString[randomLength] = '\0';

    char fileName[MAX_PATH_LENGTH];
    snprintf(fileName, sizeof(fileName), "%s%s%s", inputFilePath.c_str(), DELIMITER, timestring);
    strncat(fileName, randomString, MAX_PATH_LENGTH - strlen(fileName) - 1);

    return fileName;
}
