#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <pthread.h>

typedef struct RequestBuilder_t {
    CURL *handle;
    char *url;
} RequestBuilder;

// Function to check if JSON object is valid
bool is_valid_oauth2_response(char *json);

// Function to create a RequestBuilder for a given URL with certificate validation disabled.
RequestBuilder* request_builder_create(const char *url);

// Cache for frequently used tokens
typedef struct TokenCache_t {
    pthread_mutex_t lock;
    char **tokens;
} TokenCache;

// Initialize token cache
TokenCache token_cache = { .lock = PTHREAD_MUTEX_INITIALIZER, .tokens = NULL };

bool is_valid_oauth2_response(char *json) {
    // Parse JSON object
    json_object *jo = json_tokener_parse(json);
    if (!jo) return false;

    bool ret = true;

    // Check required fields and values
    if (!json_object_get_exact(jo, "access_token")) ret = false;
    if (json_object_get_type(json_object_get_object(jo, "access_token")) != json_type_string) ret = false;

    if (!json_object_get_exact(jo, "expires_in")) ret = false;
    if (json_object_get_type(json_object_get_object(jo, "expires_in")) != json_type_int) ret = false;

    if (!json_object_get_exact(jo, "token_type")) ret = false;
    if (strcasecmp(json_object_get_string(json_object_get_object(jo, "token_type")), "Bearer")) ret = false;

    if (json_object_get_exact(jo, "refresh_token")) {
        if (json_object_get_type(json_object_get_object(jo, "refresh_token")) != json_type_string) ret = false;
    }

    // Check expires_in field
    int expires_in = json_object_get_int(json_object_get_object(jo, "expires_in"));
    if (expires_in <= 0) ret = false;

    json_object_put(jo);
    return ret;
}

RequestBuilder* request_builder_create(const char *url) {
    RequestBuilder *rb = malloc(sizeof(RequestBuilder));
    if (!rb) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }

    rb->handle = curl_easy_init();
    if (!rb->handle) {
        fprintf(stderr, "curl_easy_init() failed\n");
        exit(1);
    }

    curl_easy_setopt(rb->handle, CURLOPT_URL, url);
    curl_easy_setopt(rb->handle, CURLOPT_SSL_VERIFYPEER, false);

    rb->url = strdup(url);
    return rb;
}

// Add your token caching mechanism here

// ...
