using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;

public class DecryptionService
{
    private readonly IConfiguration _configuration;
    private TripleDESCryptoServiceProvider _tripleDES;
    private byte[] _key;
    private byte[] _iv;

    public DecryptionService(IConfiguration configuration)
    {
        _configuration = configuration;
        LoadKeyAndIV();
    }

    private void LoadKeyAndIV()
    {
        var configFile = File.ReadAllText("encryptedConfig.json");
        var configData = JsonConvert.DeserializeObject<Config>(configFile);

        using (Aes aes = Aes.Create())
        {
            byte[] decryptedKey = DecryptData(configData.Key, aes);
            _key = TripleDES.CreateKey(decryptedKey);
            byte[] decryptedIV = DecryptData(configData.IV, aes);
            _iv = _tripleDES.CreateIV(decryptedIV);
        }
    }

    private byte[] DecryptData(string data, Aes aes)
    {
        var encryptedBytes = Convert.FromBase64String(data);
        var decryptor = aes.CreateDecryptor(_key, _iv);
        using (var ms = new MemoryStream(encryptedBytes))
        {
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                return cs.ToArray();
        }
    }

    public string DecryptMessage(string base64EncodedMessage)
    {
        try
        {
            var messageBytes = Convert.FromBase64String(base64EncodedMessage);
            using (var tripleDES = TripleDESCryptoServiceProvider.Create())
            {
                tripleDES.Key = _key;
                tripleDES.IV = _iv;
                using (ICryptoTransform transform = tripleDES.CreateDecryptor())
                {
                    using (MemoryStream ms = new MemoryStream(messageBytes))
                    {
                        using (CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Read))
                            return Encoding.UTF8.GetString(cs.ToArray());
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LoggingSystem.LogError($"Decryption error: {ex.Message}");
            throw;
        }
    }

    public string ValidateSignature(string decryptedMessage, string signature)
    {
        // Implement digital signature verification logic here
        return "Validated successfully";
    }
}

public class Config
{
    public string Key { get; set; }
    public string IV { get; set; }
}
