import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.concurrent.*;
import java.util.Random;
import java.util.logging.*;

public class GameCharacter {
    private final Logger log = Logger.getLogger(GameCharacter.class.getName());
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final AtomicBoolean isAttacking = new AtomicBoolean(false);
    private final AtomicInteger cooldownTimer = new AtomicInteger(0);
    private final SelectableChannel channel;
    private final Random random = new Random();

    public GameCharacter(String host, int port) throws IOException {
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.connect(new InetSocketAddress(host, port));
        channel = ((ServerSocketChannel)socketChannel).accept();
        channel.configureBlocking(false);
    }

    public void selectAttack() {
        if (!isAttacking.get() && cooldownTimer.get() <= 0) {
            isAttacking.set(true);
            int attackNumber = random.nextInt(2) + 1;
            log.info("Selected Attack: " + attackNumber);
            // Send the attack number to the remote logging service and game server API here
            cooldownTimer.set(9);
            scheduler.scheduleAtFixedRate(() -> {
                if (cooldownTimer.decrementAndGet() <= 0) {
                    isAttacking.set(false);
                }
            }, 1, 1, TimeUnit.SECONDS);
        }
    }

    // Handle connection state changes and I/O operations here
}
```

