#include <stdio.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdlib.h>
#include <fcntl.h>
#include <time.h>

// Key storage mechanism (abstracted)
typedef struct key_storage {
    const char *password;
    EVP_PKEY *private_key;
    EVP_PKEY *public_key;
} KeyStorage;

// Function to load key storage from a file or other secure source
KeyStorage *load_key_storage(const char *filename);

// Function to save key storage back to a file or other secure source
void save_key_storage(KeyStorage *ks, const char *filename);

// Function to encrypt data using the provided cipher and mode
int encrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *in, size_t inlen, unsigned char *out);

// Progress callback function
typedef void (*ProgressCallback)(const double progress);
void set_progress_callback(ProgressCallback cb);

// Structure for managing file operations and logging
struct FileOperation {
    int fd;
    const char *path;
    FILE *log_file;
};

// Function to handle file operations in a thread-safe manner
void *handle_file_operation(void *arg);

// Main function to encrypt a file using the OpenSSL library and user-specified options
EVP_CIPHER_CTX *encrypt_file(const char *input, const char *output, KeyStorage *ks, const char *cipher, const char *mode, ProgressCallback cb) {
    if (!input || !output || !ks || !cipher || !mode) {
        fprintf(stderr, "Invalid argument\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = NULL;
    int rc;

    // Initialize OpenSSL errors and create cipher context
    ERR_load_BIO_strings();
    OpenSSL_add_all_algorithms();
    ctx = EVP_CIPHER_CTX_new();

    // Set cipher, mode, and key for the context
    if (!(rc = EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(cipher), NULL, ks->private_key, NULL))) {
        goto error;
    }
    if (!(rc = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_MODE, EVP_ENCRYPTION_MODE_OFB, NULL))) {
        goto error;
    }

    // Create and initialize file operations structure
    struct FileOperation fo = {-1, input, NULL};
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, handle_file_operation, &fo)) {
        goto error;
    }

    // Start reading the file in chunks and encrypting the data
    size_t buffer_size = 4096;
    unsigned char *buffer = malloc(buffer_size);
    FILE *output_file = fopen(output, "wb");

    int bytes_read;
    while ((bytes_read = read(fo.fd, buffer, buffer_size)) > 0) {
        size_t encrypted_len;
        unsigned char *outbuf = malloc(buffer_size);
        if (!encrypt_data(ctx, buffer, bytes_read, outbuf)) {
            goto error;
        }
        fwrite(outbuf, 1, bytes_read, output_file);
        free(outbuf);

        // Call the progress callback to report the encryption status
        if (cb) cb((double)fo.fd >= 0 ? ((double)fo.fd / sizeof(char)) * 100 / fo.filesize : 100.0);
    }

    free(buffer);
    fclose(output_file);
    close(fo.fd);
    pthread_join(thread_id, NULL);

    // Clean up and return the cipher context
    EVP_CIPHER_CTX_free(ctx);
    save_key_storage(ks, "keys.bin");
    return ctx;

error:
    ERR_print_errors_fp(fo.log_file);
    fputc('\n', fo.log_file);
    if (output_file) fclose(output_file);
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (buffer) free(buffer);
    if (fo.fd != -1) close(fo.fd);
    if (fo.log_file) fclose(fo.log_file);
    return NULL;
}

// Implementation of the helper functions goes here...
```

