```python
import threading
from collections import OrderedDict
from bs4 import BeautifulSoup

class ElementCache:
    def __init__(self):
        self.cache = OrderedDict()  # FIFO order for up to 100 items
        self._lock = threading.Lock()

    def get(self, tag, attribute, value):
        with self._lock:
            if (tag, attribute, value) in self.cache:
                return self.cache[(tag, attribute, value)]

    def put(self, tag, attribute, value, soup_elements):
        with self._lock:
            if len(self.cache) >= 100:
                self.cache.popitem(last=False)
            self.cache[(tag, attribute, value)] = soup_elements

def get_matching_elements(html_doc: str, tag: str, attribute: str, value: str) -> List[BeautifulSoup]:
    soup = BeautifulSoup(html_doc, 'html.parser')
    cache = ElementCache()
    matching_elements = []

    for element in soup.find_all(tag):
        if getattr(element, attribute) == value:
            matching_elements.append(element)

    cache.put(tag, attribute, value, matching_elements)

    return matching_elements
