#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

/* Semaphore manager structure */
typedef struct semaphore_manager {
    const char* host;
    int port;
    sem_t semaphore;
    int socket;
} semaphore_manager_t;

/* Initialize semaphore manager */
void init_semaphore_manager(semaphore_manager_t* sm, const char* host, int port) {
    memset(sm, 0, sizeof(semaphore_manager_t));
    sm->host = host;
    sm->port = port;
}

/* Create and initialize the semaphore */
int create_and_init_sem(const semaphore_manager_t* sm) {
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, sm->host, &server_addr.sin_addr);
    server_addr.sin_port = htons(sm->port);

    if (connect(socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(socket);
        return -1;
    }

    sem_t* sem = sem_open("database_connection_pool", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 0);
    if (sem == SEM_FAILED) {
        perror("sem_open");
        close(socket);
        return -1;
    }

    sm->semaphore = *sem;
    sm->socket = socket;
    return 0;
}

/* Acquire semaphore */
int sem_acquire(const semaphore_manager_t* sm) {
    int ret = sem_wait(&sm->semaphore);
    if (ret < 0 && errno != EINTR) {
        perror("sem_wait");
    }

    /* Send acquire message to the server */
    char msg[10] = "acquire";
    send(sm->socket, msg, strlen(msg), 0);
    return ret;
}

/* Release semaphore */
void sem_release(semaphore_manager_t* sm) {
    /* Receive release message from the server */
    char buf[10];
    recv(sm->socket, buf, sizeof(buf), 0);

    sem_post(&sm->semaphore);
}

/* Delete semaphore manager */
void delete_semaphore_manager(semaphore_manager_t* sm) {
    close(sm->socket);
    sem_destroy(&sm->semaphore);
    memset(sm, 0, sizeof(semaphore_manager_t));
}
```

This code provides a basic implementation of the semaphore manager. It uses the `pthread.h` and `semaphore.h` libraries for thread synchronization and semaphores, respectively. The `init_semaphore_manager()` function initializes the structure containing the host and port information, as well as the socket and semaphore pointers.

The `create_and_init_sem()` function creates a new semaphore and connects to an external service for managing it. The function sends an "acquire" message when the semaphore is acquired using `sem_wait()`, and receives a confirmation from the server when the semaphore is released using `recv()`.

Finally, the `delete_semaphore_manager()` function cleans up the resources used by the semaphore manager. This code snippet does not include error handling for edge cases or performance optimization, but you can build upon it and add those features as needed.

