    FILE *file;
    long size;
    char *buffer;
} FileHandle;

struct thread_data {
    int index;
    FileHandle *file_handle;
};

static pthread_mutex_t log_cache = PTHREAD_MUTEX_INITIALIZER;
static bool cache[1000] = { false };

void* process_file(void *arg) {
    struct thread_data *data = arg;
    FileHandle *file_handle = data->file_handle;

    // Process the file content here, assuming you have a function parse_line() to extract the last two numerical fields and calculate the average.

    pthread_mutex_unlock(&log_cache);
    free(file_handle->buffer);
    fclose(file_handle->file);
    free(file_handle);
    return NULL;
}

void read_and_process_files() {
    DIR *dir = opendir("./logs");
    if (!dir) {
        fprintf(stderr, "Error: Unable to open logs directory.\n");
        exit(1);
    }

    struct dirent *entry;
    int thread_count = 0;
    pthread_t threads[1024];

    while ((entry = readdir(dir)) != NULL) {
        if (isdigit(entry->d_name[0])) {
            FileHandle *file_handle = malloc(sizeof(FileHandle));
            file_handle->filename = strdup(entry->d_name);
            struct stat st;
            stat(entry->d_name, &st);
            file_handle->size = st.st_size;
            file_handle->file = fopen(entry->d_name, "r");

            if (!file_handle->file) {
                fprintf(stderr, "Error: Unable to open file %s.\n", entry->d_name);
                continue;
            }

            file_handle->buffer = malloc(file_handle->size + 1);
            fread(file_handle->buffer, file_handle->size, 1, file_handle->file);
            file_handle->buffer[file_handle->size] = '\0';

            struct thread_data td;
            td.index = thread_count++;
            td.file_handle = file_handle;

            pthread_mutex_lock(&log_cache);
            if (!cache[td.index]) {
                pthread_create(&threads[td.index], NULL, process_file, &td);
                cache[td.index] = true;
            }
        }
    }
    closedir(dir);

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void ingest_data_to_api() {
    // Implement your API request here using the curl library.
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <logs_directory> <API_ENDPOINT>\n", argv[0]);
        return 1;
    }

    const char *logs_dir = argv[1];
    const char *api_endpoint = argv[2];

    read_and_process_files();
    ingest_data_to_api();

    return 0;
}
