import requests
from PIL import Image
from aiofiles import os_scandir, ProxyOS

class ProfilePictureDao:
    def __init__(self, cloud_storage_api_key, cache_expiration=300):
        self.cloud_storage_api_key = cloud_storage_api_key
        self.cache_expiration = cache_expiration
        self.cached_images = {}

    async def update_profile_picture(self, user_id, image_data):
        # Validate image data (file size and format)
        _, ext = os.path.splitext(image_data.filename)
        if ext not in ['jpg', 'jpeg', 'png'] or len(image_data) > 10000000:  # 10MB limit
            raise ValueError("Invalid image file size or format.")

        temp_file = None
        try:
            temp_file, temp_file_obj = tempfile.tmp_uploadedfile(
                fileobj=image_data, max_length=10*1024*1024)  # 10MB limit for temporary file

            image = Image.open(temp_file)
            # Cache the updated profile picture (if not already cached)
            if user_id not in self.cached_images:
                self.cached_images[user_id] = {}

            with temp_file as f:
                img_bytes = f.read()
                cache_key = f'{user_id}.{ext}'
                self.cached_images[user_id][cache_key] = (img_bytes, self.cache_expiration)

            # Store the updated image in cloud storage and handle retries for failed API calls
            retries = 3
            while True:
                try:
                    response = requests.put(
                        'https://cloud-storage-api.com/v1/user/{user_id}/profile-picture'.format(user_id=user_id),
                        headers={'Authorization': self.cloud_storage_api_key},
                        data=img_bytes)
                    response.raise_for_status()
                    break
                except requests.exceptions.RequestException as e:
                    if retries <= 0:
                        raise e
                    retries -= 1

            # Serve the cached profile picture from cache for faster retrieval
            cache_key = next(iter(self.cached_images[user_id].keys()))
            img_bytes, expiration = self.cached_images[user_id][cache_key]
            return base64.b64encode(img_bytes).decode('utf-8')
        finally:
            if temp_file is not None:
                temp_file.close()
                os.remove(temp_file.name)

