fn set_and_get_directory(dir_name: &str) -> PathBuf {
    let mut dir = env::var("MY_DIRECTORY");

    if dir.is_err() {
        let new_dir = create_dir_all(PathBuf::from(dir_name)).unwrap();
        dir = Some(new_dir.into_os_string());
