using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

public class FileChunkProcessor
{
    private readonly int _chunkSize;
    private readonly int _bufferSize;
    private readonly Action<string> _loggingCallback;

    public FileChunkProcessor(int chunkSize, int bufferSize)
    {
        _chunkSize = chunkSize;
        _bufferSize = bufferSize;
    }

    public void SetLoggingCallback(Action<string> callback)
    {
        _loggingCallback = callback;
    }

    private void Log(string message)
    {
        if (_loggingCallback != null)
            _loggingCallback(message);
    }

    public string DecryptFileChunk(string filePath, byte[] key, byte[] iv)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open))
        {
            var decrytor = TripleDESCryptoServiceProvider.Create();
            decrytor.Key = key;
            decrytor.IV = iv;

            var encryptedChunks = new List<byte[]>();

            long currentPosition = 0;
            while (currentPosition < fileStream.Length)
            {
                var chunkSizeBytes = Math.Min(_chunkSize, fileStream.Length - currentPosition);
                var buffer = new byte[chunkSizeBytes];

                int bytesRead = fileStream.Read(buffer, 0, chunkSizeBytes);
                if (bytesRead <= 0) break;

                encryptedChunks.Add(buffer);

                currentPosition += bytesRead;
            }

            var decryptedChunks = ParallelEnumerable.Select(encryptedChunks, chunk => Decrypt(chunk, decrytor)).ToList();
            return string.Concat(decryptedChunks);
        }
    }

    private byte[] Decrypt(byte[] encryptedData, TripleDESCryptoServiceProvider decrytor)
    {
        using (var memoryStream = new MemoryStream())
        using (var cryptoStream = new CryptoStream(memoryStream, decrytor.CreateDecryptor(), CryptoStreamMode.Write))
        {
            cryptoStream.Write(encryptedData, 0, encryptedData.Length);
            cryptoStream.FlushFinalBlock();
            return memoryStream.ToArray();
        }
    }

    // Thread-safe methods for reading and writing chunks omitted for brevity.
}
