        }
        return script;
    });
}

function renderScript(scriptObj) {
    const key = Math.random().toString();
    if (!scriptObj || !scriptObj.code || !scriptObj.type) {
        console.warn(`Invalid script object: ${JSON.stringify(scriptObj)}`);
        return '';
    }

    const scriptTag = document.createElement('script');
    scriptTag.key = key;
    scriptTag.innerHTML = scriptObj.code;
    scriptTag.type = scriptObj.type;

    footerElements.push(scriptTag);

    return `<script key="${key}" type="${scriptObj.type}">${scriptObj.code}</script>`;
}

