import threading
from werkzeug.security import safe_str_cmp, generate_password_hash, check_password_hash
from flask import request, current_app as app
from flask_sqlalchemy import SQLAlchemy

db = SQLAlchemy()

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))
    token = db.Column(db.String(32), unique=True, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

def validate_request():
    if not request.is_json or 'username' not in request.json or 'email' not in request.json or 'password' not in request.json or 'token' not in request.json:
        return False
    return True, request.json

def authenticate(username, password):
    user = User.query.filter_by(username=username).first()
    if user and check_password_hash(user.password_hash, password):
        return user
    return None

def save_account(user):
    db.session.add(user)
    db.session.commit()

def delete_account(user_id):
    user = User.query.filter_by(id=user_id).first()
    if user:
        db.session.delete(user)
        db.session.commit()

def handle_request():
    validated, data = validate_request()
    if not validated:
        return {'status': 'error', 'message': 'Invalid request'}
    user = User.query.filter_by(username=data['username']).first()
    if user and safe_str_cmp(user.token, data['token']):
        sub_action = data.get('sub_action')
        if sub_action == 'delete':
            handle_delete(user)
        else:
            handle_create_or_update(user, data)
    else:
        return {'status': 'error', 'message': 'Invalid username or token'}

def handle_create_or_update(user, data):
    if user:
        user.email = data['email']
        user.password_hash = generate_password_hash(data['password'])
    else:
        user = User(username=data['username'], email=data['email'], password_hash=generate_password_hash(data['password']), token=str(uuid.uuid4()))
    save_account(user)

def handle_delete(user):
    if user:
        expiration_time = datetime.utcnow() + timedelta(hours=24)
        reset_token = str(uuid.uuid4())
        user.token = reset_token
        user.expiration_time = expiration_time
        save_account(user)
        send_confirmation_email(user.email, reset_token)

def send_confirmation_email(email, token):
    # Integrate with an external API for sending emails here.
    pass

# Lock the database access to avoid race conditions in high-concurrency environments
db_lock = threading.Lock()

@app.route('/api/account', methods=['POST'])
def account():
    with db_lock:
        return jsonify(handle_request())
