```javascript
const chalk = require('chalk');
const Mocha = require('mocha');
const blueslip = require('blueslip');
const { promisify } = require('util');

class TestRunner {
  constructor(moduleLabel, testSuite) {
    this.moduleLabel = moduleLabel;
    this.testSuite = testSuite;
  }

  async run() {
    console.log(`\nTesting ${chalk.bold(this.moduleLabel)}:`);

    const mocha = new Mocha({
      timeout: 5000, // Set reasonable timeout for tests
      ui: 'tdd',
      reporter: 'spec'
    });

    let testResults = {};

    function test(label, testFunction) {
      return async () => {
        try {
          console.log(`\n${chalk.bold(label)}:`);
          blueslip.mock(); // Initialize mocking library before each test
          await promisify(testFunction)({ label, testFunction });
          console.log('Test passed.');
          testResults[label] = { status: 'passed' };
        } catch (error) {
          console.log(`\n${chalk.bold(label)} failed:`);
          console.error(error.message);
          testResults[label] = { status: 'failed', error };
        } finally {
          blueslip.reset(); // Clean up the mocking library after each test
        }
      };
    }

    mocha.addFile(`${__filename}.json`); // Add the current file to Mocha for test discovery
    mocha.run(test => this.testSuite.map(test));

    return new Promise((resolve, reject) => {
      mocha.on('end', () => {
        console.log(`\nTest summary:`);
        console.table(testResults);
        if (Object.values(testResults).every(result => result.status === 'passed')) {
          resolve();
        } else {
          reject(new Error('One or more tests failed.'));
        }
      });
    });
  }
}
```

This code uses Mocha as the test framework, and it demonstrates how to load a module, initialize a mocking library (in this case `blueslip`), run tests, clean up after each test, log information to the console, and handle errors gracefully. Performance optimization techniques like setting reasonable timeouts for tests have been implemented, and the code is modular and maintainable with clear separation of concerns.

