```cpp
#include <forward_list>
#include <string>
#include <functional>
#include <iterator>
#include <algorithm>
#include <stdexcept>

bool insertAfter(std::forward_list<std::string>& lst, const std::string& target, const std::string& value, std::function<bool(const std::string&, const std::string&)> compFunc) {
    if (!compFunc) {
        compFunc = [](const std::string& a, const std::string& b) { return a == b; };
    }

    auto it = std::find_if(lst.begin(), lst.end(), [&](const std::string& str) { return compFunc(str, target); });

    if (it != lst.end()) {
        it = lst.insert_after(it, value);
    } else {
        try {
            lst.emplace_back(value);
        } catch (...) {
            throw std::runtime_error("Failed to insert value");
        }
    }

    return it != lst.end();
}
```
