import re
import requests

# Define regular expressions for different types of book titles
FICTION = r'\b(Book\s+Title\s+(of\s+)?(?:The)?\s*[A-Z]{2,}\s*[\w'"\s-]+(?:,|;|:|)\s*[A-Z]{2,}\s*[\w'"\s-]+)\b'
NONFICTION = r'\b(How\s+to\s+|The\s+Art\s+of|An\s+Introduction\s+to|Principles\s+of)\s*(?:[A-Z]{2,}\s*[\w'"\s-]+(?:,|;|:|)\s*[A-Z]{2,}\s*[\w'"\s-]+)+(?:\s+(?:About|On|For))?\s*(?:[A-Z]{2,}\s*[\w'"\s-]+)*\b'
POETRY = r'\b(Sonnets\s+of|Odes\s+to|Poems\s+on|Verses\s+from)\s*(?:[A-Z]{2,}\s*[\w'"\s-]+(?:,|;|:|)\s*[A-Z]{2,}\s*[\w'"\s-]+)*\b'

def extract_books(text, api_key, min_appearances=1):
    # Remove punctuation and special characters from the text
    text = ''.join(c for c in text if c.isalpha() or c.isspace())

    books = {}

    # Find matches using regular expressions and update the books dictionary
    for pattern, title_type in ((FICTION, 'Fiction'), (NONFICTION, 'Non-fiction'), (POETRY, 'Poetry')):
        matches = re.findall(pattern, text, re.IGNORECASE)
        for match in matches:
            if match not in books:
                books[match] = 1
            else:
                books[match] += 1

    # Filter out books that appear fewer than the specified minimum number of times
    books = {book: count for book, count in books.items() if count >= min_appearances}

    # Make API requests for verified book titles
    verified_books = {}

    for book, count in books.items():
        try:
            response = requests.get(f'https://book-api.example.com/search?q={book}', headers={'Authorization': api_key})
            if response.status_code == 200:
                data = response.json()
                if data['total_results'] > 0:
                    verified_books[book] = {'title': data['items'][0]['title'], 'author': data['items'][0]['author'], 'isbn': data['items'][0]['isbn']}
            else:
                print(f'Error {response.status_code}: Unable to verify book {book}.')
        except Exception as e:
            print(f'Error: {e}. Unable to verify book {book}.')

    return verified_books
