import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Random;
import java.util.HashSet;

public class RandomStringGenerator {
    private static final String CHARACTER_SET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final MessageDigest MD5 = MessageDigest.getInstance("MD5");

    public String generateRandomString(byte[] serializedObject) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(serializedObject))) {
            Object obj = ois.readObject();
            if (obj == null) {
                throw new RuntimeException("Failed to deserialize object");
            }

            Class<?> clazz = obj.getClass();
            if (!clazz.isAssignableFrom(String.class)) {
                throw new RuntimeException("Deserialized object is not of type String");
            }

            String randomString = generateRandomString((String) obj, 10);
            String hashedPassword = hashPassword("password");

            return randomString + "|" + hashedPassword;
        } catch (Exception e) {
            throw new RuntimeException("Error during deserialization", e);
        }
    }

    private String generateRandomString(String seed, int length) {
        HashSet<Character> characterSet = new HashSet<>();
        for (char c : CHARACTER_SET.toCharArray()) {
            characterSet.add(c);
        }
        StringBuilder sb = new StringBuilder();
        Random random = new Random();

        for (int i = 0; i < length; i++) {
            sb.append(characterSet.remove(random.nextInt(characterSet.size())));
        }

        return seed + sb.toString();
    }

    private String hashPassword(String password) {
        byte[] hashedBytes = MD5.digest(password.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(Integer.toString((b & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }
}
