```java
import java.io.File;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutionException;
import java.nio.file.Files;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;

public class FileHashCalculator {
    private static final Cache<String, String> cache = CacheBuilder.newBuilder()
            .maximumSize(1000)
            .expireAfterAccess(1, org.threeten.bp.Duration.HOURS)
            .build();

    public String calculateMD5Hash(String filePath) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] fileContent;

            // If the hash is already in the cache, return it immediately
            if (cache.containsKey(filePath)) {
                return cache.getIfPresent(filePath);
            }

            try {
                fileContent = Files.readAllBytes(new File(filePath).toPath());
            } catch (IOException e) {
                throw new RuntimeException("Error reading the file: " + filePath, e);
            }

            digest.update(fileContent);
            byte[] hash = digest.digest();

            // Encode the bytes to a readable hexadecimal string
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }

            // Save the calculated hash in the cache for future use
            cache.put(filePath, sb.toString());

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unknown MD5 algorithm");
        }
    }

    public boolean compareMD5Hashes(String file1Path, String file2Path) {
        try {
            String hash1 = calculateMD5Hash(file1Path);
            String hash2 = calculateMD5Hash(file2Path);

            return hash1.equals(hash2);
        } catch (ExecutionException | InterruptedException e) {
            throw new RuntimeException("Error comparing file hashes", e);
        }
    }
}
```

