using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using Dapper;
using Microsoft.Extensions.Caching.Memory;

public class MyCustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add other properties as needed
}

public async Task<List<MyCustomObject>> ExecuteStoredProcedureAsync(string connectionString, List<dynamic> inputParams, string procedureName)
{
    var cache = new MemoryCacheAdapter();
    var key = GetCacheKey(inputParams, procedureName);
    var result = cache.Get(key);

    if (result != null) return result;

    using (var connection = new SqlConnection(connectionString))
    {
        await connection.OpenAsync();
        var query = $"EXEC {procedureName} @{string.Join(", ", inputParams.Select((p, i) => $"@{nameof(inputParams[i])}"))}";
        result = await connection.QueryAsync<MyCustomObject>(query, inputParams);
        cache.Set(key, result, CacheExpirationPolicy.Absolute(TimeSpan.FromMinutes(5)));
    }

    return result;
}

private string GetCacheKey(List<dynamic> inputParams, string procedureName) => $"{procedureName}:{string.Join(":", inputParams)}";

public class MemoryCacheAdapter : IMemoryCache
{
    // Implement the necessary methods for caching (e.g., Set, Get, Remove, etc.)
}
