using Microsoft.Extensions.Caching.Memory;
using ILoggingSystem = YourNamespace.ILoggingSystem; // Interface for your logging system

public class CustomObject
{
    public string Property1 { get; set; }
    public int Property2 { get; set; }
    // Add other properties as needed
}

public class StoredProcedureExecutor
{
    private readonly IMemoryCache _cache;
    private readonly ILoggingSystem _logger;

    public StoredProcedureExecutor(IMemoryCache cache, ILoggingSystem logger)
    {
        _cache = cache;
        _logger = logger;
    }

    public async Task<List<CustomObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<SqlParameter> parameters, string procedureName)
    {
        // Validate input parameters to prevent SQL injection attacks
        if (!parameters.Any()) throw new ArgumentException("Input parameters cannot be empty.");

        var cacheKey = GetCacheKey(procedureName, parameters);

        if (_cache.TryGetValue(cacheKey, out List<CustomObject> cachedResult))
        {
            _logger.LogInfo($"Retrieved stored procedure result from cache: {procedureName}");
            return cachedResult;
        }

        try
        {
            await using var command = new SqlCommand(procedureName, connection)
            {
                CommandType = CommandType.StoredProcedure
            };

            command.Parameters.AddRange(parameters);

            await using var reader = await command.ExecuteReaderAsync();
            var customObjectsList = new List<CustomObject>();

            while (await reader.ReadAsync())
            {
                var customObject = new CustomObject();
                var properties = customObject.GetType().GetProperties();

                for (int i = 0; i < reader.FieldCount && i < properties.Length; i++)
                {
                    if (!reader.IsDBNull(i))
                    {
                        var propertyInfo = properties[i];
                        var fieldName = reader.GetName(i);

                        if (propertyInfo.CanWrite && propertyInfo.SetMethod != null)
                            propertyInfo.SetValue(customObject, reader[fieldName]);
                    }
                }

                customObjectsList.Add(customObject);
            }

            _cache.Set(cacheKey, customObjectsList, new MemoryCacheEntryOptions()
                .SetSlidingExpiration(TimeSpan.FromMinutes(10))); // Set cache expiration policy here (10 minutes in this example)
            _logger.LogInfo($"Executed stored procedure successfully: {procedureName}");

            return customObjectsList;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to execute stored procedure: {procedureName}. Error: {ex.Message}");
            throw;
        }
    }

    private string GetCacheKey(string procedureName, List<SqlParameter> parameters)
    {
        var hashCode = HashCode.Combine(procedureName, parameters);
        return hashCode.ToString();
    }
}
