    private int getBitsPerSample(BufferedImage image) {
        TiffIFD ifd = new TiffIFD(new ByteArrayInputStream(image.getData().getDataBuffer().data));
        for (TiffField field : ifd.getFields()) {
            if (field.getTag() == TiffTag.SAMPLES_PER_PIXEL) {
                return field.getAsInt();
            }
        }
        throw new IllegalArgumentException("No samples per pixel found in the TIFF image");
    }

