        try {
            this.socket = new Socket("remote-address", 8080);
        } catch (IOException e) {
            LOGGER.error("Error connecting to server", e);
        }

        Thread connectionThread = new Thread(() -> {
            while (!this.socket.isClosed()) {
                try (DataOutputStream out = new DataOutputStream(this.socket.getOutputStream())) {
                    if (this.canAttack && System.currentTimeMillis() - this.attackCooldown > 9000) {
                        synchronized (this) {
                            this.canAttack = false;
                            this.attackCooldown = System.currentTimeMillis();
                        }

                        int attackNumber = random.nextInt(2);
                        LOGGER.info("Attack {} selected", attackNumber);

