                                "bitsPerSample = " + bitsPerSample + ';' +
                                "samplePerPixel = " + 1 + ';' +
                                // Add more struct fields with their values here...
                                "}");
                    }
                } catch (IOException e) {
                    LOGGER.error("Error sending data to server", e);
                }

                try {
