void* map_file(const char *path, size_t *len) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) return NULL;
    off_t filesize = lseek(fd, 0, SEEK_END);
    if (filesize == -1 || filesize > (1ULL << 31)) { /* Handle large files */ }
    char *buf = mmap(NULL, filesize + 4096, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (buf == MAP_FAILED) return NULL;
    *len = filesize;
    return buf;
}
