using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Serilog;

namespace FileHasher
{
    public class FileHasher
    {
        private const int ChunkSize = 64 * 1024; // 64 KB chunk size

        private readonly ILogger _logger;

        public FileHasher(ILogger logger)
        {
            _logger = logger;
        }

        public async Task<byte[]> ComputeHashAsync(string filePath, Action<double> progressCallback = null)
        {
            using (var sha256 = SHA256.Create())
            {
                await UsingFileStreamAsync(filePath, async stream =>
                {
                    var buffer = new byte[ChunkSize];
                    int bytesRead;

                    while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                    {
                        sha256.TransformBlock(buffer, 0, bytesRead, _);

                        if (progressCallback != null)
                            progressCallback((double)stream.Position / filePath.Length * 100);
                    }

                    sha256.TransformFinalBlock(_byteArrayOutput);
                });

                return _byteArrayOutput;
            }
        }

        private readonly byte[] _byteArrayOutput = new byte[SHA256.Size];

        private async Task UsingFileStreamAsync(string filePath, Func<Stream, Task> action)
        {
            try
            {
                using (var fileStream = await File.OpenReadAsync(filePath))
                {
                    await action(fileStream);
                }
            }
            catch (Exception ex)
            {
                _logger.Error(ex, $"An error occurred while computing hash for file: {filePath}");
                throw;
            }
        }
    }
}
