std::forward_list<std::string> myList;
std::mutex mtx;

void insertWithLog(const std::string& str) {
    unique_lock<mutex> lock(mtx);
    myList.insert_after(myList.begin(), str);
}

std::string readFileSync(const fs::path& path) {
    ifstream file(path, ios::in | ios::binary | ios::ate);
    if (!file) return "";

    size_t fileSize = static_cast<size_t>(file.tellg());
    vector<char> buffer(fileSize + 1);

    file.seekg(0);
    file.read(buffer.data(), buffer.size());
    buffer[fileSize] = '\0';

    return string(buffer.begin(), buffer.end());
}

std::forward_list<std::string> processList(const std::forward_list<std::string>& input, const std::string& target, const std::string& replacement) {
    for (auto it = input.cbegin(); it != input.cend(); ) {
        auto pos = it->find(target);
        if (pos != string::npos) {
            string s = move(*it);
            insertWithLog(replacement + s.substr(pos + target.size()));
            it = myList.erase_after(it);
        } else {
            ++it;
        }
    }
    return myList;
}

void replaceInList(const std::forward_list<std::string>& input, const std::string& target, const std::string& replacement) {
    processList(input, target, replacement);
}

