TEST_CASE("Replace in list with concurrent modifications") {
    std::vector<thread> threads;
    myList = forward_list<string>({"Hello", "World", "Tester"});

    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(replaceInList, ref(myList), "world", "EARTH");
