    private final int maxConnections;
    private final int connectionTimeout;
    private final ConnectionConfigCallback callback;
    private final ReentrantLock lock = new ReentrantLock();
    private final Map<Integer, ConcurrentSkipListSet<Connection>> resourcePools;
    private boolean seeded;
    private volatile int seed;

    public DynamicResourcePoolManager(int minConnections, int maxConnections, int connectionTimeout, ConnectionConfigCallback callback) {
        this.minConnections = minConnections;
        this.maxConnections = maxConnections;
        this.connectionTimeout = connectionTimeout;
        this.callback = callback;
        resourcePools = new HashMap<>();
    }

    public void initializeResourcePool(int minConnections, int maxConnections, int connectionTimeout, boolean seeded, int? seed, ConnectionConfigCallback? callback) {
        if (minConnections <= 0 || maxConnections <= 0 || connectionTimeout <= 0) {
            throw new IllegalArgumentException("Invalid input parameters. Minimum and maximum number of connections and connection timeout must be greater than zero.");
        }

        synchronized(this) {
            this.seeded = seeded;
            if (seed != null && !seeded) {
                throw new IllegalStateException("Seed value cannot be provided when not seeding the resource pool.");
            }
            this.seed = seed;
            this.callback = callback != null ? callback : this.callback;
        }

        if (resourcePools.containsKey(hashCode())) {
            lock.lock();
            try {
                ConcurrentSkipListSet<Connection> currentPool = resourcePools.get(hashCode());
                if (currentPool == null || currentPool.size() < minConnections) {
                    initializePool(minConnections, maxConnections, connectionTimeout);
                }
            } finally {
                lock.unlock();
            }
        } else {
            initializePool(minConnections, maxConnections, connectionTimeout);
        }
    }

