    public function setConfig(array $newConfig): bool
    {
        // Extract only valid configuration keys and merge with the existing config.
        $updatedConfig = array_diff_key($newConfig, array_flip(array_keys($this->config)));

        if (empty($updatedConfig)) {
            return false;
        }

        $validatedConfig = $this->validateConfiguration($updatedConfig);
        if (!$validatedConfig) {
            return false;
        }

        $this->config = array_merge($this->config, $updatedConfig);
        return true;
    }

    public function setSeed(int $seed): void
    {
        if (time() - $this->seed > self::SEED_LIFETIME) {
            $this->randomGenerator->setSeed($seed);
            $this->seed = $seed;
        }
