// Module for fetching scripts
function fetchScript(url, config) {
  const defaultConfig = {
    timeout: 5000, // Timeout in milliseconds (optional)
    cacheKey: url, // Cache key based on script URL (optional)
    retryInterval: 1000, // Retry interval in milliseconds (optional)
    maxRetries: 3, // Maximum number of retries (optional)
    onLoad: () => {}, // Callback for successful load (optional)
    onError: console.error // Error callback (optional)
  };

  const configOptions = { ...defaultConfig, ...config };

  let cachedScript;

  return new Promise((resolve, reject) => {
    if (localStorage.getItem(configOptions.cacheKey)) {
      cachedScript = JSON.parse(localStorage.getItem(configOptions.cacheKey));
      if (cachedScript && !configOptions.onError(new Error(`Cache hit but script is stale or invalid`))) {
        return resolve(cachedScript);
      }
    }

    const xhr = new XMLHttpRequest();
    xhr.open("GET", url, true);

    xhr.responseType = "text";
    xhr.onload = () => {
      if (xhr.status === 200 && !configOptions.onError(new Error(`Script fetching failed with status code ${xhr.status}`))) {
        localStorage.setItem(configOptions.cacheKey, JSON.stringify(xhr.responseText));
        resolve(xhr.responseText);
      } else {
        configOptions.onError(new Error(`Script fetching failed with status code ${xhr.status} and error: ${xhr.statusText}`));
      }
    };

    xhr.ontimeout = () => {
      if (!configOptions.onError(new Error(`Script fetch timed out after ${configOptions.timeout} milliseconds`))) {
        xhr.abort();
      }
    };

    xhr.send();
  });
}

// Module for rendering scripts
function renderScript(scriptText) {
  const scriptElement = document.createElement("script");
  scriptElement.type = "text/javascript";
  scriptElement.innerHTML = scriptText;
  const key = `script-${Date.now()}`;
  scriptElement.setAttribute("data-key", key);
  document.body.appendChild(scriptElement);

  return new Promise((resolve) => {
    scriptElement.onload = () => resolve(scriptElement);
  });
}

// Main function to dynamically render a set of scripts as a web page footer
async function renderScripts(scripts, config) {
  const defaultConfig = {
    spinnerElement: document.getElementById("loading-spinner"), // Spinner element (optional)
    footerElement: document.getElementById("footer"), // Footer element to append scripts (optional)
    onAllLoaded: () => {}, // Callback for all scripts loaded successfully (optional)
  };

  const configOptions = { ...defaultConfig, ...config };

  let fetchedScripts = [];

  if (!Array.isArray(scripts)) {
    scripts = [scripts];
  }

  configOptions.footerElement.innerHTML = "";

  if (configOptions.spinnerElement) {
    configOptions.spinnerElement.style.display = "block";
  }

  const promises = [];

  for (const script of scripts) {
    if (!script.code || !script.type) {
      script.code = "";
      script.type = "text/javascript";
    }

    promises.push(fetchScript(`${script.url}`, { cacheKey: `${script.id}` }).then((scriptText) => renderScript(scriptText)));
  }

  try {
    const loadedScripts = await Promise.all(promises);
    fetchedScripts = fetchedScripts.concat(loadedScripts);
    configOptions.onAllLoaded(fetchedScripts);
  } catch (error) {
    console.error("An error occurred while rendering scripts:", error);
  } finally {
    if (configOptions.spinnerElement) {
      configOptions.spinnerElement.style.display = "none";
    }
  }

  // Implement clean-up and memory leak prevention logic here as needed.
}
