import java.nio.channels.*;
import java.net.InetSocketAddress;
import java.util.concurrent.*;
import java.time.*;
import java.util.LinkedList;
import java.util.Map;
import com.google.gson.*;

public class ConnectionManager {
 private static final ExecutorService executor = Executors.newCachedThreadPool();
 private static final ScheduledExecutorService cooldownScheduler = Executors.newScheduledThreadPool(1);
 private static final Logger logger = LoggerFactory.getLogger(ConnectionManager.class);

 private SelectorGroup group;
 private SocketChannel socketChannel;
 private String serverAddress;
 private long lastConnectAttempt;
 private int retriesLeft;
 private long cooldownPeriod;
 private Map<Character, CharacterState> characters;
 private Gson gson;

 public ConnectionManager(String serverAddress) {
 this.serverAddress = serverAddress;
 this.gson = new Gson();
 this.retriesLeft = 3;
 this.cooldownPeriod = 1000L; // Default cooldown period in milliseconds
 this.characters = new HashMap<>();
 this.lastConnectAttempt = System.currentTimeMillis();
 }

 public void connect() {
 if (System.currentTimeMillis() - lastConnectAttempt < retriesLeft * cooldownPeriod) {
 logger.info("Connection not attempted, still on cool-down.");
 return;
 }
 lastConnectAttempt = System.currentTimeMillis();

 try {
 group = Selector.open();
 SocketChannel socket = SocketChannel.open();
 socket.connect(new InetSocketAddress(serverAddress, 8080));
 socketChannel = socket;

 while (!socketChannel.finishConnect()) {
 if (--retriesLeft == 0) {
 logger.error("Connection failed after retries.");
 return;
 }
 cooldownPeriod *= 2;
 Thread.sleep(Math.min((long) Math.pow(2, retriesLeft), 10_000L));
 }
 logger.info("Connected to server.");
 executor.submit(() -> handleConnection());
 } catch (Exception e) {
 logger.error("Failed to connect.", e);
 retriesLeft--;
 cooldownPeriod *= 2;
 }
 }

 private void handleConnection() throws IOException {
 SelectionKey key = socketChannel.register(group, SelectionKey.OP_READ);
 while (key.isValid()) {
 group.select();
 if (group.selectNow()) {
 SocketChannel channel = (SocketChannel) key.channel();
 ByteBuffer buffer = ByteBuffer.allocate(1024);
 int bytesRead = channel.read(buffer);
 if (bytesRead > 0) {
 processServerResponse(buffer);
 } else if (bytesRead == -1) {
 logger.info("Connection closed by server.");
 closeConnection();
 return;
 }
 }
 }
 }

 private void processServerResponse(ByteBuffer buffer) throws IOException {
 // Analyze the response, handle potential DoS attacks, and adjust cooldown period or select an attack accordingly
 // ...
 }

 private void closeConnection() {
 try {
 if (socketChannel != null && socketChannel.isConnected()) {
 socketChannel.close();
 }
 group.wakeup();
 } catch (IOException e) {
 logger.error("Failed to close connection.", e);
 }
 }

 // CharacterState class and attack selection logic omitted for brevity
}
