const zlib = require('zlib');
const asyncMap = require('async-map');

function copyBuffer(srcBuffers, destLength) {
  const destBuffer = Buffer.allocUnsafe(destLength);

  let offset = 0;
  return asyncMap(srcBuffers, (srcBuffer) => {
    const len = Math.min(srcBuffer.length - offset, destLength);
    destBuffer.write(srcBuffer, offset, len, 'utf8', 'utf8');
    offset += len;

    // Error handling and logging...

    return Promise.resolve();
  }, { concurrency: 8 });
}
