```csharp
using System;
using UnityEngine;
using NUnit.Framework;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;

public class DynamicRandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private Func<float, float> distributionFunction = null;

    public DynamicRandomValueGenerator(float min, float max)
    {
        MinValue = min;
        MaxValue = max;
    }

    public float MinValue { get => minValue; set => minValue = value; }
    public float MaxValue { get => maxValue; set => maxValue = value; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public float GetRandomFloat()
    {
        if (distributionFunction != null) return distributionFunction(UnityEngine.Random.Range(minValue, maxValue));
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public int GetRandomInt() => (int)Mathf.Round(GetRandomFloat());

    public override string ToString()
    {
        var distribution = distributionFunction == null ? "Uniform" : distributionFunction.Method.Name;
        return $"Range: [{minValue}, {maxValue}] (Distribution: {distribution})";
    }

    // Unit Tests
    [Test]
    public void TestRandomFloat()
    {
        var generator = new DynamicRandomValueGenerator(0, 1);
        Assert.GreaterOrEqual(generator.GetRandomFloat(), 0);
        Assert.LessOrEqual(generator.GetRandomFloat(), 1);
    }

    [Test]
    public void TestRandomInt()
