And here's the JavaScript code for the `FindElementsBySelector` function:

```javascript
function FindElementsBySelector(node, selector, callback) {
    const queue = [node];
    const result = [];

    while (queue.length > 0) {
        const currentNode = queue.shift();

        if (!currentNode || currentNode.nodeType !== Node.ELEMENT_NODE) continue;

        if (callback(currentNode, selector)) {
            result.push(currentNode);
        }

        for (let i = 0; i < currentNode.children.length; i++) {
            queue.push(currentNode.children[i]);
        }
    }

    return result;
}
```

