```csharp
using System;
using System.Xml;
using System.Xml.XPath;
using System.Net.Http;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Collections.Generic;
using Newtonsoft.Json.Schema;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XPathParser
{
    private readonly ILogger<XPathParser> _logger;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IMemoryCache _memoryCache;
    private readonly JschmeaGallery _jsonSchemaGallery;

    public XPathParser(ILogger<XPathParser> logger, IHttpClientFactory httpClientFactory, IMemoryCache memoryCache, JschmeaGallery jsonSchemaGallery)
    {
        _logger = logger;
        _httpClientFactory = httpClientFactory;
        _memoryCache = memoryCache;
        _jsonSchemaGallery = jsonSchemaGallery;
    }

    public async Task<XmlNode> GetFirstMatchingElementAsync(string xpath, string xmlUrl)
    {
        var cachedXml = _memoryCache.Get(xmlUrl);

        if (cachedXml != null)
            return await Task.FromResult((XmlNode)cachedXml);

        try
        {
            var httpResponse = await _httpClientFactory.CreateClient().GetAsync(xmlUrl);
            var xmlStream = await httpResponse.Content.ReadAsStreamAsync();

            using var reader = XmlReader.Create(xmlStream);
            var document = new XmlDocument();
            document.Load(reader);

            ValidateSchema(document);

            var nodeList = document.SelectNodes(xpath);

            if (nodeList == null || nodeList.Count > 1)
                throw new Exception($"No single match for XPath query '{xpath}'.");

            return nodeList[0];
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while fetching or parsing XML document.");
            throw;
        }
    }

    private void ValidateSchema(XmlDocument xmlDocument)
    {
        var json = JsonConvert.SerializeXmlNode(xmlDocument);
        var schemaUri = "http://json-schema.org/draft-07/schema#";
        using var schemaStream = _httpClientFactory.CreateClient().GetStreamAsync($"https://json-schema.org/latest/json-schema-validation.json").Result;

        var jsonSchema = JsonConvert.DeserializeObject<JsonSchema>(new StreamReader(schemaStream).ReadToEnd());

        using var validator = new JsonSchemaValidator(jsonSchema, schemaUri);
        var validationResult = validator.Validate(json, out var messages);

        if (!validationResult.IsValid)
            throw new Exception($"The provided XML does not conform to the expected schema. Messages: {string.Join(", ", messages)}");
    }
}
