use Predis\Client as RedisClient;

function generateRandomString($length = 32, $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    $randomString = '';
    for ($i = $length; $i > 0; $i--) {
        $index = rand(0, strlen($charSet) - 1);
        $randomString .= $charSet[$index];
    }

    return $randomString;
}

function generateToken($length = 32) {
    // Generate and validate the token length
    if ($length < 16 || $length > 64) {
        throw new \Exception('Invalid token length');
    }

    // Generate a secure random string
    $token = generateRandomString($length);

    return $token;
}

function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
    $salt = mt_rand(0, 1 << 32) . strtotime("now");
    $hash = (new PasswordHash(8, true))->HashPassword($password, $salt);

    return [$hash, $salt];
}

function storeTokenOrHash($db, $collection, $key, $value) {
    try {
        $client = new MongoDB\Client('mongodb://username:password@host/database');
        $tokenCollection = $client[$db][$collection];
        $document = ['key' => $key, 'value' => $value];
        $result = $tokenCollection->insertOne($document);
        return $result->getInsertedId();
    } catch (\Exception $e) {
        throw new \Exception('Error during storage: ' . $e->getMessage());
    }
}

function getTokenOrHash($db, $collection, $key) {
    try {
        $client = new MongoDB\Client('mongodb://username:password@host/database');
        $tokenCollection = $client[$db][$collection];
        $filter = ['key' => $key];
        $result = $tokenCollection->findOne($filter);
        if (!$result) {
            throw new \Exception('Key not found');
        }

        return $result['value'];
    } catch (\Exception $e) {
        throw new \Exception('Error during retrieval: ' . $e->getMessage());
    }
}

function getRedisClient() {
    // Configuration for Redis connection
    $redisConfig = [
        'host' => '127.0.0.1',
        'port' => 6379,
        'password' => '',
        'database' => 0
    ];

    return new RedisClient($redisConfig);
}

function setCache($key, $value) {
    try {
        $redis = getRedisClient();
        $result = $redis->set($key, $value);
        return $result;
    } catch (\Exception $e) {
        throw new \Exception('Error during caching: ' . $e->getMessage());
    }
}

function getCache($key) {
    try {
        $redis = getRedisClient();
        $value = $redis->get($key);
        return $value;
    } catch (\Exception $e) {
        throw new \Exception('Error during caching retrieval: ' . $e->getMessage());
    }
}
