using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private float _minValue;
    private float _maxValue;
    private bool _inclusive;

    public ValueGenerator(float minValue, float maxValue, bool inclusive = false)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _inclusive = inclusive;
    }

    public float GenerateFloat(bool withinBounds = false, float minBound = 0f, float maxBound = 1f)
    {
        if (withinBounds && (minBound > maxBound || minBound >= _maxValue || maxBound <= _minValue))
            throw new ArgumentException("Invalid bounds specified for generating a random float.");

        return withinBounds ? UnityEngine.Random.value * (_maxValue - _minValue) + _minValue : UnityEngine.Random.Range(_minValue, _maxValue);
    }

    public int GenerateInt(bool withinBounds = false, int minBound = 0, int maxBound = int.MaxValue)
    {
        if (withinBounds && (minBound > maxBound || minBound >= _maxValue || maxBound <= _minValue))
            throw new ArgumentException("Invalid bounds specified for generating a random integer.");

        return withinBounds ? Mathf.RoundToInt(UnityEngine.Random.value * (_maxValue - _minValue) + _minValue) : Mathf.RoundToInt(UnityEngine.Random.Range(_minValue, _maxValue));
    }

    public int[] GenerateIntArray(int size, int minBound = 0, int maxBound = int.MaxValue)
    {
        if (size <= 0) throw new ArgumentException("Size of the array must be greater than zero.");

        var result = new int[size];

        for (var i = 0; i < size; ++i)
            result[i] = GenerateInt(true, minBound, maxBound);

        return result;
    }

    public float[] GenerateFloatArray(int size, bool withinBounds = false, float minBound = 0f, float maxBound = 1f)
    {
        if (size <= 0) throw new ArgumentException("Size of the array must be greater than zero.");

        var result = new float[size];

        for (var i = 0; i < size; ++i)
            result[i] = GenerateFloat(withinBounds, minBound, maxBound);

        return result;
    }

    public override string ToString()
    {
        var inclusiveStr = _inclusive ? " (Inclusive)" : " (Exclusive)";
        return $"ValueGenerator: Range [{_minValue.ToString("F2")}..{_maxValue.ToString("F2")}{inclusiveStr}";
    }
}
