using System;
using System.Collections.Concurrent;
using System.Data;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicDatabaseConnectionManager
{
    public class DynamicDatabaseConnectionManager : IDynamicDatabaseConnectionManager
    {
        private readonly ConcurrentQueue<IDbConnection> _connectionPool;
        private readonly int _maxPoolSize;
        private readonly Func<string, string, IDbConnection> _dbConnectionFactory;
        private readonly IExternalConfigurationManager _externalConfigManager;

        public DynamicDatabaseConnectionManager(Func<string, string, IDbConnection> dbConnectionFactory, IExternalConfigurationManager externalConfigManager)
        {
            _dbConnectionFactory = dbConnectionFactory;
            _externalConfigManager = externalConfigManager;
            _connectionPool = new ConcurrentQueue<IDbConnection>();
            _maxPoolSize = GetMaxPoolSize();
            InitializeFromConfiguration();
        }

        private int GetMaxPoolSize()
        {
            // Adjust max pool size based on current load and memory constraints.
            // This is a placeholder implementation and should be refined according to your needs.
            return 50;
        }

        public IDbConnection GetConnection(string provider, string connectionString)
        {
            var dbConnection = _connectionPool.TryDequeue(out var existingConnection);

            if (dbConnection != null)
            {
                return dbConnection;
            }

            lock (_connectionPool)
            {
                if (_connectionPool.Count < _maxPoolSize && _connectionPool.Count + 1 < GetMaxPoolSize())
                {
                    dbConnection = _dbConnectionFactory(provider, connectionString);
                    _connectionPool.Enqueue(dbConnection);
                }
            }

            return dbConnection ?? _dbConnectionFactory(provider, connectionString);
        }

        public void ReleaseConnection(IDbConnection connection)
        {
            if (connection != null && !_connectionPool.TryEnqueue(connection))
            {
                connection.Close();
                Debug.WriteLine($"Releasing unmanaged IDbConnection back to the pool.");
            }
        }

        public void InitializeFromConfiguration()
        {
            var config = _externalConfigManager.Load();

            // Handle scenarios where the external configurations might change during runtime, re-initializing as needed.
            if (config != null)
            {
                foreach (var provider in config.Providers.Keys)
                {
                    var connectionString = config.Providers[provider];
                    _dbConnectionFactory = (p, c) => _dbConnectionFactory(p, c); // Seeded initialization for reproducibility purposes.
                    _dbConnectionFactory = (p, c) => _dbConnectionFactory(p, connectionString);
                }
            }
        }

        public override string ToString()
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine($"DynamicDatabaseConnectionManager:");
            sb.AppendLine($" - Pool Size: {_connectionPool.Count}");
            sb.AppendLine($" - Active Connections: {_connectionPool.Count + _connectionPool.Count(c => !c.State.Equals(ConnectionState.Closed))}");
            return sb.ToString();
        }
    }
}
