typedef struct {
    int value;
} record;

void load_and_execute(size_t num_files, const char* const *file_names) {
    long *offsets = (long *)malloc(num_files * sizeof(long));
    int *keys = (int *)calloc(num_files, sizeof(int));
    record *records = (record *)calloc(num_files, sizeof(record));

    for (size_t i = 0; i < num_files; ++i) {
        records[i].value = rand() % 100 + 1; // Random value within range 1-100
        offsets[i] = ftell(NULL); // Save current file position for each file
    }

    bool *loaded = calloc(num_files, sizeof(bool));
    bool *executed = calloc(num_files, sizeof(bool));
    bool *error = calloc(num_files, sizeof(bool));
    bool *has_circular_dependency = calloc(num_files, sizeof(bool));

    // Use a queue to manage file loading and execution
    size_t queue_size = num_files;
    size_t head = 0;
    size_t tail = 0;
    const char **queue = malloc(sizeof(const char *) * num_files);

    for (size_t i = 0; i < num_files; ++i) {
        if (!loaded[i]) {
            queue[tail++] = file_names[i];
        }
    }

    FILE *script_file;
    char script_path[1024];
    const char *current_file;

    while (queue_size > 0) {
        if (tail == num_files) tail = 0;
        current_file = queue[head++];
        snprintf(script_path, sizeof(script_path), "%s", current_file);

        // Check for circular dependencies
        for (size_t i = 0; i < num_files; ++i) {
            if (!loaded[i] && !executed[i]) {
                if (strstr(script_path, current_file)) {
                    has_circular_dependency[i] = true;
                }
            }
        }

        // Load and execute the file asynchronously
        script_file = fopen(current_file, "r");
        if (!script_file) {
            error[head - 1] = true;
            fprintf(stderr, "Error: Failed to open file '%s'\n", current_file);
            continue;
        }

        pthread_t thread_id;
        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

        void *(*script_loader)(const char*) = NULL; // Load your JavaScript loading function here
        void* result = script_loader(script_path);

        if (result != 0) {
            error[head - 1] = true;
            fprintf(stderr, "Error: Failed to load or execute file '%s'\n", current_file);
        } else {
            executed[head - 1] = true;

            // Process the results of the loaded script, such as adding new files to the queue
            // ...
        }

        pthread_join(thread_id, NULL);
        fclose(script_file);

        if (!error[head - 1]) {
            loaded[head - 1] = true;
            queue_size--;

            for (size_t i = 0; i < num_files; ++i) {
                if (!loaded[i] && !executed[i] && has_circular_dependency[i]) {
                    // Add the file with a circular dependency to the queue, removing it from the list of potential dependencies
                    has_circular_dependency[i] = false;
                    queue[tail++] = file_names[i];
                }
            }
        }
    }

    // Clean up memory and logs
    free(records);
    free(offsets);
    free(keys);
    free(loaded);
    free(executed);
    free(error);
    free(has_circular_dependency);
    free(queue);
}

