```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

// Define a struct to store the extracted image information
typedef struct {
  int bits_per_sample;
  int sample_per_pixel;
  int extra_samples;
} TIFFInfo;

// Function to parse a TIFF image file and extract information about the image
TIFFInfo tiffParse(const char *filename) {
  TIFF *tif = TIFFOpen(filename, "r");

  if (!tif) {
    perror("Error opening file");
    exit(1);
  }

  int bits_per_sample;
  tdata_t *samples = TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL);
  if (samples == NULL) {
    samples = &TIFFDefaultSamplePerPixel;
  }

  switch (*samples) {
    case 1:
      bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
      break;
    case 2:
      {
        tdata_t bps1, bps2;
        bps1 = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE);
        bps2 = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE + 1);
        if (bps1 != bps2) {
          fprintf(stderr, "Error: Image has unexpected number of bits per sample\n");
          exit(1);
        }
        bits_per_sample = bps1;
      }
      break;
    case 4:
      bits_per_sample = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, 2);
      break;
    case 8:
      bits_per_sample = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, 3);
      break;
    case 16:
      bits_per_sample = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, 4);
      break;
    default:
      fprintf(stderr, "Error: Image has unsupported number of bits per sample\n");
      exit(1);
  }

  int sampleCount = *samples + (TIFFGetFieldDefaulted(tif, TIFFTAG_EXTRASAMPLES, 0));
  if (sampleCount != 1 && sampleCount != 3 && sampleCount != 4) {
    fprintf(stderr, "Error: Image has unexpected number of samples\n");
    exit(1);
  }

  TIFFInfo info = {
    .bits_per_sample = bits_per_sample,
    .sample_per_pixel = *samples,
    .extra_samples = sampleCount - 1,
  };

  TIFFClose(tif);
  return info;
}
```

