    public class ProductLoader
    {
        private static readonly ILog Log = LogManager.GetLogger(typeof(ProductLoader));

        private readonly Queue<string> _filePaths;
        private List<Product> _products;
        private object _lockObject = new object();

        public ProductLoader(IEnumerable<string> filePaths)
        {
            _filePaths = new Queue<string>(filePaths);
            _products = new List<Product>();
        }

        public async Task LoadAndMergeAsync()
        {
            while (_filePaths.Count > 0)
            {
                string filePath = _filePaths.Dequeue();

                try
                {
                    using (FileStream stream = File.OpenRead(filePath))
                    {
                        BinaryFormatter formatter = new BinaryFormatter();
                        var loadedProducts = formatter.Deserialize(stream) as List<Product>;

                        if (loadedProducts != null && loadedProducts.Any())
                        {
                            lock (_lockObject)
                            {
                                _products.AddRange(loadedProducts);
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    Log.Error($"Error loading file '{filePath}': {ex.Message}", ex);
                }
            }
        }

        public IEnumerable<Product> GetMergedProducts()
        {
            return _products;
        }
    }
}
