#include <sqlite3.h>

typedef struct {
    char* line;
    size_t len;
} LogEntry;

static sqlite3* db = NULL;
static pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

void* process_log(void* arg) {
    LogEntry* entry = (LogEntry*)arg;
    // Parse fields and calculate average here
    double average = (atof(strchr(entry->line, ',') + 1) + atof(strchr(entry->line, ',', strlen(entry->line)-1))) / 2.0;
    // Append average to the end of the line and print it in a comma-separated format
    char* new_line = (char*)malloc(entry->len + 6); // +6 for the two commas and average as string
    strncpy(new_line, entry->line, entry->len);
    sprintf(new_line + entry->len, ",%f", average);
    printf("%s\n", new_line);

    store_to_db(new_line);
    free(entry->line);
    free(new_line);
    free(entry);
}

void store_to_db(char* line) {
    pthread_mutex_lock(&db_lock);
    int rc = sqlite3_open("log.db", &db);
    if (rc) {
        // Reconnect to the database or handle failure here
    }
    char* errMsg = NULL;
    rc = sqlite3_exec(db, "INSERT INTO logs VALUES (?)", line, 0, &errMsg);
    if (rc != SQLITE_OK) {
        // Handle error here
    }
    pthread_mutex_unlock(&db_lock);
}

int main() {
    FILE* file = fopen("log.txt", "r");
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        size_t len = strlen(buffer);
        LogEntry* entry = malloc(sizeof(LogEntry));
        entry->line = strdup(buffer);
        entry->len = len;
        pthread_t thread;
        pthread_create(&thread, NULL, process_log, entry);
    }
    fclose(file);
    // Wait for all threads to finish processing their log entries
    pthread_exit(NULL);
}
