```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int val;
    struct SubNode* subList;
    size_t subListSize;
} Node;

typedef struct SubNode {
    char str[64];
    double dVal;
    struct SubNode* next;
} SubNode;

void initSubNode(SubNode* node) {
    node->next = NULL;
    sprintf(node->str, "%.*s", 63, ""); // Reserve one character for the null terminator
}

Node* createNodes(size_t size, size_t subListSize, size_t range) {
    Node* nodes = malloc(size * sizeof(Node));
    if (!nodes) {
        perror("Error allocating memory for Node array");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        nodes[i].val = rand() % range;
        nodes[i].subList = malloc(subListSize * sizeof(SubNode));
        if (!nodes[i].subList) {
            perror("Error allocating memory for SubNode linked list");
            free(nodes);
            return NULL;
        }

        nodes[i].subListSize = subListSize;
        for (size_t j = 0; j < subListSize; ++j) {
            initSubNode(&nodes[i].subList[j]);
            nodes[i].subList[j].dVal = (double)rand() / RAND_MAX * 100.0; // Generate double values between 0 and 100
        }
    }

    return nodes;
}

void freeNodes(Node* nodes, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (nodes[i].subList) {
            SubNode* temp = nodes[i].subList;
            while (temp != NULL) {
                SubNode* next = temp->next;
                free(temp);
                temp = next;
            }
        }
    }

    free(nodes);
}
```

This code defines a `Node` structure containing an integer value, a pointer to a linked list of `SubNode` structures, and the size of that linked list. It also defines a `SubNode` structure holding a character string and a double value, as well as a pointer to the next node in the linked list.

The `initSubNode()` function initializes a SubNode by setting its `next` pointer to NULL and reserving memory for a 64-character string (including the null terminator).

The `createNodes()` function allocates memory for a given number of Node structures, populates their integer values with random integers within the specified range, and initializes their linked lists. It handles memory allocation errors by printing an error message and freeing any previously allocated memory if an error occurs.

Finally, the `freeNodes()` function deallocates all memory used by the Node structures and their linked lists when they are no longer needed.

