using IWebServerConfig = MyExternalConfigurationManagementSystem.IWebServerConfig; // Your external configuration management system interface

public class WebSiteManager
{
    private readonly ILogger<WebSiteManager> _logger;
    private readonly IWebServerConfig _config;
    private readonly TimeSpan _timeout = TimeSpan.FromSeconds(10);

    public WebSiteManager(ILogger<WebSiteManager> logger, IWebServerConfig config)
    {
        _logger = logger;
        _config = config;
    }

    public async Task<Process?> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        if (string.IsNullOrWhiteSpace(directoryPath))
            throw new ArgumentNullException(nameof(directoryPath));
        if (string.IsNullOrWhiteSpace(siteName))
            throw new ArgumentNullException(nameof(siteName));

        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"Invalid directory path: {directoryPath}");
            return null;
        }

        lock (directoryPath) // Lock to handle concurrent access
        {
            var webConfigFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigFilePath))
            {
                _logger.LogInformation($"No web.config found in directory: {directoryPath}");
                await ConfigureDefaultSettingsAsync(directoryPath); // If no web.config, configure defaults using external system
                if (string.IsNullOrWhiteSpace(siteName))
                {
                    _logger.LogError("Site name is empty after default configuration.");
                    return null;
                }
            }

            var port = FindAvailablePort(); // Get an available port for the site
            if (port == 0)
            {
                _logger.LogError($"Failed to find an available port for site: {siteName}.");
                return null;
            }

            var startupArgs = $"/site:{siteName}:{port}";
            var startInfo = new ProcessStartInfo(Path.Combine(directoryPath, "webserver.exe"), startupArgs)
            {
                RedirectStandardError = true,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
                WorkingDirectory = directoryPath
            };

            var process = new Process
            {
                StartInfo = startInfo
            };

            try
            {
                process.Start();

                var started = await Task.Run(() => process.Start() != false);

                if (started)
                {
                    _logger.LogInformation($"Successfully added and started site: {siteName}");
                    return process;
                }

                var result = await GetProcessExitCodeAndReasonAsync(process);

                if (result.Item1 != 0) // Non-zero exit code indicates an error
                {
                    _logger.LogError($"Site: {siteName} failed to start with error: {result.Item2}");
                    CleanupProcessResources(process);
                    return null;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to add and start site: {siteName}\n{ex}");
                CleanupProcessResources(process);
                return null;
            }
        }

        return null;
    }

    private async Task<(int, string)> GetProcessExitCodeAndReasonAsync(Process process)
    {
        await Task.Delay(_timeout); // Wait for a reasonable amount of time before giving up

        var exitCode = process.ExitCode;
        if (exitCode == null)
        {
            _logger.LogError($"Site failed to start: Unable to get exit code.");
            return (-1, "Unable to get exit code");
        }

        var reason = await GetReasonForExitAsync(process);
        return (exitCode.Value, reason);
    }

    private async Task ConfigureDefaultSettingsAsync(string directoryPath)
    {
        // Implement logic for configuring default settings using your external configuration management system
    }

    private int FindAvailablePort()
    {
        // Implement logic to find an available port within the expected range (e.g., 8000-10000)
    }

    private async Task<string> GetReasonForExitAsync(Process process)
    {
        if (!process.StandardError.EndOfStream)
        {
            var errorOutput = await new StreamReader(process.StandardError).ReadToEndAsync();
            return errorOutput;
        }

        return string.Empty;
    }

    private void CleanupProcessResources(Process process)
    {
        try
        {
            if (!process.HasExited)
                process.Kill();
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to kill process: {ex}");
        }
    }
}
