                int seed = -1;

                static json cons_serializer() {
                    return {{"distribution", &Config::distribution}, {"mean", &Config::mean}, {"standard_deviation", &Config::standard_deviation}, {"seed", &Config::seed}};
                }

                static Config deserialize(const json& j) {
                    Config c;
                    c.distribution = j["distribution"].get<std::string>();
                    c.mean = j["mean"].get<double>();
                    c.standard_deviation = j["standard_deviation"].get<double>();
                    c.seed = j["seed"].get<int>();
                    return c;
                }
            };

            static std::mutex config_mutex;
            static Config config;
            std::mt19937 generator;
            int thread_id;

            RandomGenerator(int tid) : thread_id(tid) {}

            virtual ~RandomGenerator() = default;

            void setConfigFile(const std::string& file) {
                jsoncons::parse(std::ifstream(file), Simulation::RandomGenerator::config);
            }

            double uniform() {
                return uniform_real_distribution<>{}(generator);
            }

            double normal() {
                std::normal_distribution<> dist(config.mean, config.standard_deviation);
                return dist(generator);
            }

            double exponential() {
                std::exponential_distribution<> dist(1.0 / config.mean);
                return dist(generator);
            }

            static void seedFromTime() {
                unsigned long long seed = std::chrono::high_resolution_clock::now().time_since_epoch().count();
                generator.seed(seed);
            }

