```python
import concurrent.futures
import logging
from functools import wraps
import time

def log_test_start(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        logging.info(f"Testing API endpoint: {kwargs['endpoint']}")
        return func(*args, **kwargs)
    return wrapper

def log_test_end(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        end = time.time()
        duration = end - kwargs['start']
        logging.info(f"API endpoint test for {kwargs['endpoint']} completed in {duration:.4f} seconds.")
        return func(*args)
    return wrapper

def execute_api_endpoints_tests(app_name, test_modules, num_workers):
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.INFO)

    test_results = {}

    def run_test_module(module_name):
        module = __import__(module_name, fromlist=['*'])
        for name in dir(module):
            obj = getattr(module, name)
            if callable(obj) and not obj.__qualname__ == '<lambda>':  # Exclude lambda functions that are not real test cases
                if obj.__annotations__.get('client'):
                    test_results[f"{app_name}: {name}"] = {'status': 'Not yet executed'}
        return test_results[f"{app_name}: *"]

    with concurrent.futures.ThreadPoolExecutor(max_workers=num_workers) as executor:
        results = list(executor.map(run_test_module, test_modules))

    for result in results:
        result['total'] = len(result)  # Count the number of tests in this module

    test_summary = {app_name: {'passed': 0, 'failed': 0, 'errors': 0}}
    for result in results:
        for test, data in result.items():
            test_function = test[test.index(':') + 1:]
            try:
                client = requests.Session()
                for key, value in data['params'].items():
                    client.params[key] = value
                decorated_func = log_test_start(log_test_end(getattr(result[test], test_function)))
                decorated_func(client=client, start=time.time())

                if decorated_func['status'] == 'Failed':
                    test_summary[app_name]['failed'] += 1
                elif decorated_func['status'] == 'Error':
                    test_summary[app_name]['errors'] += 1
                else:
                    test_summary[app_name]['passed'] += 1
            finally:
                client.close()  # Close the connection after usage

    return test_summary
```

