using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace StringHasher
{
    public class StringHasher
    {
        private readonly HashAlgorithm _hashAlgorithm;
        private readonly ILogger<StringHasher> _logger;
        private readonly Settings _settings;

        public StringHasher(HashAlgorithm hashAlgorithm, ILogger<StringHasher> logger, Settings settings)
        {
            _hashAlgorithm = hashAlgorithm;
            _logger = logger;
            _settings = settings;
        }

        public string Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input));

            var bytes = Encoding.UTF8.GetBytes(input);
            return BitConverter.ToString(_hashAlgorithm.ComputeHash(bytes)).Replace("-", string.Empty).ToLowerInvariant();
        }

        public async Task<string[]> HashAsync(string[] inputs, CancellationToken cancellationToken)
        {
            if (inputs == null || !inputs.Any())
                throw new ArgumentNullException(nameof(inputs));

            var tasks = inputs.Select(input => Task.Run(() => Hash(input), cancellationToken)).ToArray();
            await Task.WhenAll(tasks);
            return tasks.Select(t => t.Result).ToArray();
        }

        public bool ValidateHash(string input, string expectedHash)
        {
            if (string.IsNullOrEmpty(input) || string.IsNullOrEmpty(expectedHash))
                throw new ArgumentNullException();

            return Hash(input).Equals(expectedHash, StringComparison.OrdinalIgnoreCase);
        }

        public void LogError(Exception exception)
        {
            if (exception != null)
            {
                _logger.LogError(exception, "An error occurred while hashing strings");

                // Integration with external logging service (e.g., Serilog, NLog) can be achieved by implementing the ILogger<T> interface according to the specific logging service documentation
            }
        }
    }

    public class Settings
    {
        public HashAlgorithm Algorithm { get; set; } = SHA256.Create();
        public string LogFilePath { get; set; }
        public bool UseExternalLoggingService { get; set; }
    }
}
