```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>
#include <pthread.h>

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

// Function to validate the resource file format
bool isValidResourceFile(const char* filePath) {
    // Implement validation logic here, e.g., checking the magic number or structure of entries
}

ResourceBundle* loadResourceBundle(const char* filePath) {
    if (!isValidResourceFile(filePath)) {
        perror("Invalid resource file");
        return NULL;
    }

    FILE* fp = fopen(filePath, "rb");
    if (!fp) {
        perror("Failed to open the file");
        return NULL;
    }

    fseek(fp, 0, SEEK_END);
    size_t fileSize = ftell(fp);
    rewind(fp);

    ResourceBundle* bundle = mmap(NULL, sizeof(ResourceBundle), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (bundle == MAP_FAILED) {
        perror("Failed to allocate memory for the ResourceBundle");
        fclose(fp);
        return NULL;
    }

    bundle->items = calloc(fileSize / sizeof(ResourceItem), 1);
    if (!bundle->items) {
        free(bundle);
        perror("Failed to allocate memory for the resource items");
        fclose(fp);
        return NULL;
    }

    bundle->totalItemCount = 0;
    pthread_mutex_init(&bundle->mutex, NULL);

    size_t currentOffset = 0;
    while (currentOffset < fileSize) {
        enum ResourceType type;
        size_t size;
        fread(&type, sizeof(enum ResourceType), 1, fp);
        fread(&size, sizeof(size_t), 1, fp);

        if (!loadResource(fp, currentOffset + sizeof(enum ResourceType) + sizeof(size_t), type, &bundle->items[bundle->totalItemCount])) {
            return NULL;
        }

        currentOffset += sizeof(enum ResourceType) + sizeof(size_t) + size;
        bundle->totalItemCount++;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&bundle->mutex, &attr);
    pthread_mutexattr_destroy(&attr);

    for (size_t i = 0; i < NUM_TYPES; i++) {
        bundle->itemCount[i] = 0;
    }

    for (size_t i = 0; i < bundle->totalItemCount; i++) {
        bundle->itemCount[(enum ResourceType)bundle->items[i].type]++;
    }

    return bundle;
}

bool loadResource(FILE* fp, size_t offset, enum ResourceType type, ResourceItem** item) {
    // Implement loading logic for each resource type here
    // ...
}

void freeResourceBundle(ResourceBundle* bundle) {
    if (bundle == NULL) return;

    for (size_t i = 0; i < bundle->totalItemCount; i++) {
        free(bundle->items[i].data);
    }

    free(bundle->items);
    pthread_mutex_destroy(&bundle->mutex);
    munmap(bundle, sizeof(ResourceBundle));
}
