```python
import os
import json
import time
from datetime import timedelta
import requests
from unittest.mock import Mock, patch
from collections import defaultdict

API_KEY = os.environ['OPENWEATHERMAP_API_KEY']
CACHE_FILE = 'weather_cache.json'
CACHE_EXPIRE = timedelta(hours=1)
RATE_LIMIT_SECS = 10

class WeatherApi:
    def __init__(self):
        self.cache = self._load_cache() if os.path.exists(CACHE_FILE) else {}

    def _api_call(self, city_id):
        url = f'http://api.openweathermap.org/data/2.5/weather?id={city_id}&appid={API_KEY}'
        response = requests.get(url)
        if response.status_code != 200:
            time.sleep(RATE_LIMIT_SECS)
            return self._api_call(city_id)
        data = response.json()
        self._cache[(city_id, data['dt']) = (city_id, int(data['dt']))] = data
        return data

    def _load_cache(self):
        if not os.path.exists(CACHE_FILE):
            return {}
        with open(CACHE_FILE) as f:
            return json.load(f)

    def __call__(self, city_id):
        if city_id in self.cache:
            data = self.cache[(city_id,)]
        else:
            data = self._api_call(city_id)
        return data

@patch('http.client.HTTPConnection')
def test_weather_api(mock_http):
    mock = Mock()
    mock.request.return_value = (mocks.mkresponse(200, {"temp": 25, "humidity": 50, "wind": {"speed": 10}}), '')
    mock_http.return_value = mock
    api = WeatherApi()
    response = api(12345)
    assert response['temp'] == 25
    assert response['humidity'] == 50
    assert response['wind']['speed'] == 10

def report_weather(cities, days=7):
    api = WeatherApi()
    data = defaultdict(lambda: {'avg_temp': 0, 'avg_humidity': 0, 'avg_wind_speed': 0})
    for city in cities:
        for day in range(days):
            timestamp = (day * timedelta(days=1) + datetime.now()).timestamp()
            response = api(city)['list'][0]
            data[city][('avg_temp', 'humidity', 'wind_speed')[day % 3]] += response['main'][('temp', 'humidity', 'wind')[day % 3]]
    for city, avg in data.items():
        print(f"City: {city}, Average Temperature: {avg['avg_temp']}, Humidity: {avg['avg_humidity']}, Wind Speed: {avg['avg_wind_speed']}")
```

This code defines a `WeatherApi` class that makes API calls to OpenWeatherMap and caches responses for an hour. It includes a test using the `unittest.mock` library to simulate API responses during testing. Additionally, there is a `report_weather` function that takes a list of cities and reports the average temperature, humidity, and wind speed for each city over a specified time period (7 days by default).

