import io.netty.channel.*;
import io.netty.bootstrap.*;
import java.nio.ByteBuffer;
import java.util.Random;

public class GameCharacter {
    private final Channel channel;
    private final ImageInfo imageInfo;
    private long lastAttackTime = System.currentTimeMillis();

    public GameCharacter(SocketAddress address) {
        EventLoopGroup group = new NioEventLoopGroup();
        try (Bootstrap b = new Bootstrap()
                .group(group)
                .channel(NioSocketChannel.class)
                .handler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) throws Exception {
                        channel = ch;
                        channel.pipeline().addLast(new GameCharacterHandler());
                    }
                })
                .connect(address)) {
            b.channel().closeFuture().sync();
        }

        imageInfo = new ImageInfo(); // Initialize your ImageInfo here...
    }

    public void attack() {
        if (System.currentTimeMillis() - lastAttackTime < 9000) return;

        Random rand = new Random();
        int attackType = rand.nextInt(2);

        LogEvent logEvent = new LogEvent(imageInfo, attackType);

        channel.writeAndFlush(logEvent.encode());

        lastAttackTime = System.currentTimeMillis();
    }
}
