    class SecureRandomNumberGenerator {
        std::mutex mtx;
        std::mt19937_64 engine;
        bool isRunning = true;

      public:
        SecureRandomNumberGenerator() {
            // Securely seed the random number generator using current time, system entropy and network entropy
            unsigned long long seeds[] = {
                std::chrono::high_resolution_clock::now().time_since_epoch().count(),
                getSystemEntropy(),
                getNetworkEntropy()
            };
            engine.seed(std::make_tuple(seeds...));
        }

        ~SecureRandomNumberGenerator() { isRunning = false; }

        static std::string generateSessionId() {
            // Cache recently generated session IDs to reduce database queries
            static boost::interprocess::shared_memory_object shm(
                "session_id_cache", sizeof(std::map<std::string, bool>), true);
            auto shmMap = reinterpret_cast<std::map<std::string, bool>*>(shm.get_address());
            if (shmMap->empty()) { // Initialize empty cache if not already initialized
                (*shmMap)[""] = false;
            }

            std::uniform_int_distribution<> dist(0, numeric_limits<uint64_t>::max());
            uint64_t randomNumber = engine();
            auto it = shmMap->find(base64_encode(reinterpret_cast<const char*>(&randomNumber), sizeof(randomNumber)));

            // Check if the generated session ID is already in use or not
            while (it != shmMap->end() && it->second) {
                randomNumber = engine();
                it = shmMap->find(base64_encode(reinterpret_cast<const char*>(&randomNumber), sizeof(randomNumber)));
            }

            if (it == shmMap->end()) { // Add the generated session ID to the cache if it's unique
                (*shmMap)[base64_encode(reinterpret_cast<const char*>(&randomNumber), sizeof(randomNumber))] = true;
            }
            return base64_encode(reinterpret_cast<const char*>(&randomNumber), sizeof(randomNumber));
        }

        static void invalidateOldSessions() {
