using Amazon.S3;
using Amazon.S3.Model;

public class StorageService
{
    private readonly IAmazonS3 _s3Client;

    public StorageService(IAmazonS3 s3Client) => _s3Client = s3Client;

    public void UploadFile(string bucketName, string key, Stream fileStream)
    {
        var putRequest = new PutObjectRequest
        {
            BucketName = bucketName,
            Key = key,
            FileName = Path.GetFileName(key),
            ContentBody = fileStream
        };

        _s3Client.PutObjectAsync(putRequest).Wait();
    }

    public void UploadFileWithTransformedName(string bucketName, string originalFileName, string transformedFileName, Stream fileStream)
    {
        UploadFile(bucketName, TransformFilename(originalFileName, transformedFileName), fileStream);
    }

    private string TransformFilename(string originalFileName, string transformPattern)
    {
        // Implement specific rules for filename transformation using sprintf or equivalent functions
        return string.Format(transformPattern, originalFileName);
    }
}
