```csharp
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public static class IdentitySetup
{
    public static void AddCustomizableIdentity(this IServiceCollection services, Action<UserValidator<ApplicationUser>> customUserValidator)
    {
        services.AddDbContext<ApplicationDbContext>(options => options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));
        services.AddIdentity<ApplicationUser, IdentityRole>()
            .AddEntityFrameworkStores<ApplicationDbContext>()
            .AddDefaultTokenProviders()
            .AddDefaultUI()
            .AddUserManager<ApplicationUserManager>()
            .AddSignInManager<SignInManager<ApplicationUser>>();

        services.Configure<IdentityOptions>(options =>
        {
            // Configure lockout defaults
            options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
            options.Lockout.MaxFailedAccessAttempts = 10;
            options.Lockout.AllowedForNewUsers = true;
        });

        services.Configure<PasswordHasherOptions>(options =>
        {
            options.HashLength = 60;
            options.IterationCount = 10;
        });

        // Register custom user validator
        var userValidator = new UserValidator<ApplicationUser>();
        customUserValidator(userValidator);
    }
}
```

