            _config = config;
            _externalConfigManager = externalConfigManager;
        }

        public async Task AddSiteAsync(string directoryPath, string siteName, int basePortNumber)
        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The provided directory path '{directoryPath}' is invalid.");

            var validSiteName = ValidateSiteName(siteName);

            lock (directoryPath) // Ensure concurrent access is safe
            {
                if (File.Exists($"{directoryPath}/web.config"))
                {
                    await StartSiteAsync(directoryPath, siteName, basePortNumber);
                }
                else
                {
                    var defaultSettings = await _externalConfigManager.GetDefaultSettingsAsync();
                    IntegrateDefaultSettings(defaultSettings, directoryPath);
                    await StartSiteAsync(directoryPath, siteName, basePortNumber);
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private string ValidateSiteName(string siteName)
        {
            if (string.IsNullOrWhiteSpace(siteName))
                throw new ArgumentException("The provided site name cannot be empty or null.");
            // Additional validation rules for special characters and other naming conventions...
            return siteName;
        }

        private async Task StartSiteAsync(string directoryPath, string siteName, int basePortNumber)
        {
            var portNumber = GetAvailablePort(basePortNumber);
            var processStartInfo = GetProcessStartInfo(directoryPath, siteName, portNumber);

            try
            {
                using (var process = Process.Start(processStartInfo))
                {
                    await Task.Delay(TimeSpan.FromSeconds(_config["HealthCheckInterval"])); // Implement health check mechanism here...

                    if (!process.HasExited)
                        _logger.LogError("The site '{SiteName}' failed to start.", siteName);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred while starting the site '{SiteName}'.", siteName);
            }
        }

        private int GetAvailablePort(int basePortNumber)
        {
            var usedPorts = Enumerable.Range(basePortNumber, 100).ToList();
            foreach (var process in Process.GetProcesses().Where(p => p.ProcessName == "IISExpress"))
                usedPorts.Remove((int)process.Id); // Assuming all IISExpress processes have the same name...

            return usedPorts.First();
        }

        private ProcessStartInfo GetProcessStartInfo(string directoryPath, string siteName, int portNumber)
        {
            var commandLineArguments = new StringBuilder()
                .AppendFormat("-site '{0}' -p {1}", siteName, portNumber);

            return new ProcessStartInfo(new FileInfo($"{directoryPath}/{_config["WebServerExecutable"]}").FullName)
            {
                UseShellExecute = false,
                RedirectStandardOutput = true,
                Arguments = commandLineArguments.ToString(),
                WorkingDirectory = directoryPath
            };
        }

        private void IntegrateDefaultSettings(Dictionary<string, string> defaultSettings, string directoryPath)
        {
            var webConfigPath = $"{directoryPath}/web.config";
            XElement webConfig = XElement.Load(webConfigPath);

            foreach (var setting in defaultSettings)
                webConfig.SetElementValue("application", setting.Key, setting.Value);

            webConfig.Save(webConfigPath);
        }
    }
}
