               throw new IllegalArgumentException("Invalid input parameters for resource pool configuration.");
           }

           lock.lock();
           try {
               if (!pools.containsKey(poolName)) {
                   pools.put(poolName, new ResourcePool(poolName, minConnections, maxConnections, timeout));
               }
               pools.get(poolName).configure(callback);
           } finally {
               lock.unlock();
           }
       }

