using System;
using System.IO;
using System.Security.Cryptography;
using System.Web;
using System.Web.Services;

[WebService(Namespace = "http://tempuri.org/")]
[WebServiceBinding(ConformsTo = WsiProfiles.BasicProfile1_1)]
public class PageUpdater : WebService
{
    [WebMethod]
    public Response UpdateElementContent(string pageSectionId, string elementId, string htmlContent)
    {
        var service = new ContentService(); // Your custom service class for updating content
        var decryptedContent = TripleDESCrypt(htmlContent); // Custom method for Triple DES encryption
        service.UpdateElementHtml(pageSectionId, elementId, decryptedContent);
        return new Response { RefreshRequired = true };
    }

    private string TripleDESCrypt(string originalData)
    {
        var key = new TripleDESCryptoServiceProvider(); // Triple DES encryption key
        var iv = new byte[key.IV.Length]; // Initialization Vector
        using (var ms = new MemoryStream())
        {
            var rng = RandomNumberGenerator.Create();
            rng.GetBytes(iv);
            ms.Write(iv, 0, iv.Length);
            key.IV = iv;
        }

        using (var encryptor = key.CreateEncryptor())
        {
            using (var msEncrypt = new MemoryStream())
            {
                using (var cs = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    var bytes = Encoding.UTF8.GetBytes(originalData);
                    cs.Write(bytes, 0, bytes.Length);
                    cs.Close();
                }
                return Convert.ToBase64String(msEncrypt.ToArray()); // Base64 encoding of encrypted data
            }
        }
    }
}

public class Response
{
    public bool RefreshRequired { get; set; }
}
