import sys
import importlib
import time
import logging
import concurrent.futures
from queue import Queue
import threading

def execute_module_tests(module_name, test_functions):
    logger = logging.getLogger(__name__)

    # Dynamically import the specified module
    module = importlib.import_module(module_name)

    # Initialize a queue to store test functions and a semaphore for concurrent execution
    tests_queue = Queue()
    tests_semaphore = threading.Semaphore(len(test_functions))

    # Add test functions to the queue
    for test in test_functions:
        tests_queue.put((test, f"{module.__name__}.{test.__name__}"))

    # Initialize a logger for each test and start concurrent execution
    with concurrent.futures.ThreadPoolExecutor() as executor:
        results = list(executor.map(run_test, tests_queue, [tests_semaphore] * len(test_functions)))

def run_test(test, test_info):
    start_time = time.time()
    try:
        test()
    except Exception as e:
        log_error(f"Test '{test_info}' failed with error: {e}")
    else:
        log_result(test_info, "success", time.time() - start_time)

def log_error(msg):
    logger.error(msg)

def log_result(test_info, status, execution_time):
    logger.info(f"Test '{test_info}' {status} in {execution_time:.4f} seconds")

# Log configuration
logging.basicConfig(level=logging.INFO)

