typedef struct {
    uint32_t rxi_ue_information_tag;
    uint32_t rnti;
    uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static uint16_t list_size = 0;
static size_t max_list_size = 0;

void generateNFAPduList(uint32_t num_elements) {
    if (num_elements <= 0 || num_elements > max_list_size) {
        fprintf(stderr, "Invalid number of elements for the list\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    // Reallocate memory if necessary
    if (list_size + num_elements > max_list_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, (max_list_size *= 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Reallocation failure");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list = new_list;
    }

    // Populate the list with valid structures
    for (size_t i = list_size; i < list_size + num_elements; ++i) {
        list[i].rxi_ue_information_tag = rand();
        list[i].rnti = rand();
