Here is a high-level design of the requested Python program, which uses asyncio for asynchronous loading, Flask-RESTful for the REST API integration, and Redis for caching:

```python
import json
import os
import redis
import asyncio
from flask import Flask, request, jsonify
from flask_restful import Resource, Api
from marshmallow import Schema, fields, validate

class JSONObject(object):
    def __init__(self, data):
        self._data = data

    @staticmethod
    def dumps(obj):
        return json.dumps(obj, default=lambda o: str(o))

    @classmethod
    def loads(cls, json_str):
        return cls(json.loads(json_str))

    def to_dict(self):
        return self._data

registry = {}

async def load_file(filename):
    try:
        with open(filename) as f:
            data = json.load(f)
            obj = JSONObject.loads(JSONObject.dumps(data))
            return obj
    except Exception as e:
        print(f"Error loading {filename}: {e}")
        return None

def add_factory(id, factory):
    registry[id] = factory

async def create_instance(id):
    if id not in registry:
        raise KeyError(f"Unknown ID: {id}")

    factory = registry[id]
    obj = await asyncio.get_event_loop().run_in_executor(None, factory)
    return JSONObject.loads(JSONObject.dumps(obj))

class App(Resource):
    def __init__(self):
        self.rdb = redis.Redis()

    @staticmethod
    def schema():
        class MySchema(Schema):
            id = fields.String(required=True, validate=validate.Length(min=1))
            factory = fields.Function()

    async def post(self):
        data = await self.request.get_json()
        schema = App.schema()
        errors = schema().validate(data)
        if errors:
            return jsonify({"errors": errors}), 400

        id, factory = data["id"], data["factory"]
        add_factory(id, factory)
        self.rdb.set(id, factory.__name__)
        return jsonify({"message": f"Factory function added with ID: {id}"}), 201

def main():
    app = Flask(__name__)
    api = Api(app)
    api.add_resource(App, "/add")

    loop = asyncio.get_event_loop()
    tasks = []
    for filename in os.listdir("./files"):
        if filename.endswith(".json"):
            tasks.append(asyncio.ensure_future(load_file(os.path.join("./files", filename))))

    loaded_objects = await loop.gather(*tasks)

    for obj in loaded_objects:
        if obj is not None:
            try:
                registry[obj.to_dict()["id"]](obj)
            except Exception as e:
                print(f"Error creating instance from {obj.to_dict()['id']}: {e}")

    if __name__ == "__main__":
        loop.run_until_complete(main())
```

