```c
#include <tiffio.h>

void parse_tiff(const char *filename) {
  TIFF *tif;
  int samples, bits_per_sample;

  tif = TIFFOpen(filename, "r");
  if (!tif) return error("Unable to open file.");

  if (TIFFGetField(tif, TIFFTAG_SAMPLES_PERPIXEL, &samples) != 1 || samples < 1 || samples > 8)
    return error("Unsupported number of samples per pixel.");

  if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample) != 1 ||
      !((bits_per_sample == 1) || (bits_per_sample == 2) || (bits_per_sample == 4) ||
        (bits_per_sample == 8) || (bits_per_sample == 16)))
    return error("Unsupported number of bits per sample.");

  // Parse the image data and report any extra samples if necessary.

  TIFFClose(tif);
}
