// ResourceController.js
const { body, validationResult } = require('express-validator');
const ResourceModel = require('../models/ResourceModel');
const errorHandler = require('../utils/errorHandler');

exports.findById = async (req, res) => {
  try {
    const resource = await ResourceModel.findOne({ _id: req.params.id }).exec();
    if (!resource) return res.status(404).send('Resource not found.');
    res.json(resource);
  } catch (err) {
    errorHandler(res, err);
  }
};

exports.updateById = [
  body('version').isNumeric(),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    try {
      const resource = await ResourceModel.findOne({ _id: req.params.id }).exec();
      if (!resource) return res.status(404).send('Resource not found.');
      if (resource.version !== parseInt(req.body.version)) return res.status(412).send('Precondition Failed');

      // Update the resource and save it to the database
      // ...
    } catch (err) {
      errorHandler(res, err);
    }
  },
];

exports.deleteById = async (req, res) => {
  try {
    const resource = await ResourceModel.findOne({ _id: req.params.id }).exec();
    if (!resource) return res.status(404).send('Resource not found.');

    // Check if the resource has been modified since the last fetch
    // ...
    if (resource.hasBeenModified) return res.status(409).send('Conflict');

    // Delete the resource and save it to the database
    // ...
  } catch (err) {
    errorHandler(res, err);
  }
};
