    {
        private readonly PerformanceContext _context;
        private readonly IEnumerable<string> _testMethods;
        private readonly string _apiEndpoint;
        private readonly int _maxRetries;
        private readonly TimeSpan _retryInterval;
        private readonly PythonEngine _pythonEngine;
        private DirectoryInfo _directory;

        public ProcessAndSyncData(PerformanceContext context, IEnumerable<string> testMethods, string apiEndpoint, int maxRetries = 5, TimeSpan retryInterval = TimeSpan.FromSeconds(2))
        {
            _context = context;
            _testMethods = testMethods;
            _apiEndpoint = apiEndpoint;
            _maxRetries = maxRetries;
            _retryInterval = retryInterval;
            _pythonEngine = Python.CreateEngine();
        }

        public async Task ProcessAndSyncDataAsync()
        {
            var sw = Stopwatch.StartNew();

            // Load and run performance tests
            await RunTestsAsync(_testMethods);
            Console.WriteLine($"All tests completed in: {sw.Elapsed}");

            // Configure Environment variable and directory
            SetEnvironmentVariableAndCreateDirectoryIfNeededAsync().Wait();

            // Synchronize data using the external REST API
            var dataToSend = GetDataToSend();
            await SendDataToApiAsync(dataToSend);
        }

        private async Task RunTestsAsync(IEnumerable<string> testMethods)
        {
            foreach (var method in testMethods)
            {
                var type = typeof(YourModule).GetType();
                var methodInfo = type.GetMethod(method);

                if (methodInfo == null)
                    throw new Exception($"Test method '{method}' not found.");

                var sw = Stopwatch.StartNew();
                var testResult = methodInfo.Invoke(Activator.CreateInstance(type), null);
                Console.WriteLine($"Test {method} completed in: {sw.Elapsed}");
            }
        }

        private async Task SetEnvironmentVariableAndCreateDirectoryIfNeededAsync()
        {
            var pyScript = _pythonEngine.CreateScript(@"
def check_env_var(envVarName):
    if envVarNotSet(envVarName):
        new_dir = create_directory('YourDirectoryName')
        setenv(envVarName, new_dir)

def main():
    check_env_var('YOUR_ENV_VARIABLE')

main()");
            pyScript.Execute();

            _pythonEngine.GetScope().Global["create_directory"] += (string name) =>
            {
                Directory.CreateDirectory(name);
                return new DirectoryInfo(name);
            };

            _pythonEngine.GetScope().Global["envVarNotSet"] += (name) =>
            {
                if (!Environment.GetEnvironmentVariable(name).Any())
                    return true;
                return false;
            };

            _pythonEngine.GetScope().Global["setenv"] += (key, value) =>
            {
                Environment.SetEnvironmentVariable(key, value);
            };

            _directory = new DirectoryInfo(_pythonEngine.GetScope().Global["YOUR_ENV_VARIABLE"].ToString());
        }

        private async Task<List<YourDataModel>> GetDataToSend()
        {
            // Implement logic for getting data to send here
            // You may use Entity Framework Core or other data access methods
        }

        private async Task SendDataToApiAsync(IEnumerable<YourDataModel> data)
        {
            var client = new RestClient(_apiEndpoint);
            var request = new RestRequest();

            request.AddHeader("Content-Type", "application/json");

            using (var writer = new JsonTextWriter(request.Write))
            {
                JsonSerializer serializer = new JsonSerializer();
                serializer.Serialize(writer, data);
            }

            var apiResponse = await client.ExecuteAsync(request);

            if (!apiResponse.IsSuccessful)
            {
                Console.WriteLine($"API call failed with status code: {apiResponse.StatusCode}");

                for (int i = 0; i < _maxRetries; i++)
                {
                    try
                    {
                        await SendDataToApiAsync(data);
                        return;
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"API call retry #{i + 1} failed with exception: {ex.Message}");
                        await Task.Delay(_retryInterval);
                    }
                }
            }

            Console.WriteLine("Data sent to API successfully.");
        }
    }
}
