#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <memory>
#include <limits>

class OctreeNode {
public:
    int depth;
    std::vector<std::unique_ptr<OctreeNode>> children;
    double data[8]; // 8 data points per node for octree
    mutable std::mutex nodeMutex;
    std::condition_variable childChangedCondition;

    OctreeNode(int depth, bool isLeaf) : depth(depth), isLeaf(isLeaf) {}

    void lock() { nodeMutex.lock(); }
    void unlock() { nodeMutex.unlock(); }

    bool isLeaf() const { return is_leaf; }

    void split() {
        if (children.size() == 0) {
            for (int i = 0; i < 8; ++i) {
                children.emplace_back(std::make_unique<OctreeNode>(depth + 1, false));
            }
        }
    }

private:
    bool is_leaf;
};

class Octree {
public:
    Octree() : rootNode(std::make_unique<OctreeNode>(0, true)) {}

    void insertDataPoint(const double dataPoint[3]) {
        // Validate input data and system resources
        if (!validateInputData(dataPoint) || !validateSystemResources()) {
            std::cerr << "Invalid input or insufficient system resources." << std::endl;
            return;
        }

        insertDataPointRecursive(rootNode.get(), dataPoint);
    }

private:
    bool validateInputData(const double dataPoint[3]) const {
        // Validate input data
        if (std::any_of(dataPoint, dataPoint + 3, [](double d) { return !std::isfinite(d); })) {
            return false;
        }
        return true;
    }

    bool validateSystemResources() const {
        // Validate system resources
        // ... Implement your own resource validation logic here ...
        return true;
    }

    void insertDataPointRecursive(OctreeNode* currentNode, const double dataPoint[3]) {
        if (currentNode->isLeaf()) {
            // Replace the first empty slot with the new data point
            int index = 0;
            for (int i = 0; i < 8; ++i) {
                if (std::isfinite(currentNode->data[i])) continue;
                index = i;
                break;
            }
            if (index == 0) {
                std::cerr << "No empty slot found in the leaf node." << std::endl;
                return;
            }

            currentNode->data[index] = dataPoint[index];
            // Check if the node is over capacity and should be split
            double capacityUsage = (currentNode->data[index] + 1.0) / static_cast<double>(std::numeric_limits<decltype(currentNode->data[0])>::max());
            if (capacityUsage > 1.2) {
                currentNode->split();
                insertDataPointRecursive(currentNode->children[index].get(), dataPoint);
            }
        } else {
            currentNode->lock();
            // Check if any of the children have empty slots and are not over capacity
            int emptyChildIndex = -1;
            for (const auto& child : currentNode->children) {
                if (!child->isLeaf() && child->data[0] < std::numeric_limits<decltype(currentNode->data[0])>::max()) {
                    emptyChildIndex = static_cast<int>(currentNode->children.size() * 0.5 + 0.5);
                    break;
                }
            }
            currentNode->unlock();

            if (emptyChildIndex != -1) {
                insertDataPointRecursive(currentNode->children[emptyChildIndex].get(), dataPoint);
            } else {
                // The children are either full or over capacity, split the node and recursively add the new data point
                currentNode->split();

                int childIndex;
                double x = dataPoint[0];
                double y = dataPoint[1];
                double z = dataPoint[2];

                if (x < std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0) {
                    childIndex = static_cast<int>(std::floor((y + z) * 2));
                } else if (x >= std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0 && x < std::numeric_limits<decltype(currentNode->data[0])>::max()) {
                    childIndex = static_cast<int>(std::ceil((y + z) * 2));
                } else if (y < std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0) {
                    childIndex = static_cast<int>(std::floor(x * 2));
                } else if (y >= std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0 && y < std::numeric_limits<decltype(currentNode->data[0])>::max()) {
                    childIndex = static_cast<int>(std::ceil(x * 2));
                } else if (z < std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0) {
                    childIndex = static_cast<int>(std::floor((x + y) * 2));
                } else if (z >= std::numeric_limits<decltype(currentNode->data[0])>::max() / 2.0 && z < std::numeric_limits<decltype(currentNode->data[0])>::max()) {
                    childIndex = static_cast<int>(std::ceil((x + y) * 2));
                } else {
                    throw std::runtime_error("Invalid data point coordinates.");
                }

                insertDataPointRecursive(currentNode->children[childIndex].get(), dataPoint);
            }
        }
    }

    std::unique_ptr<OctreeNode> rootNode;
};
