#include <iostream>
#include <fstream>
#include <vector>
#include <numeric>
#include <stdexcept>

void process_file(const std::string& filename) {
    std::ifstream inputFile(filename);

    if (!inputFile.is_open()) {
        std::cerr << "Error: Could not open file: " << filename << "\n";
        return;
    }

    int maxValue = INT32_MIN;
    int sum = 0;
    int count = 0;
    int num;
    std::vector<int> numbers;

    while (inputFile >> num) {
        if (num > maxValue) {
            maxValue = num;
        }

        sum += num;
        ++count;
        numbers.push_back(num);
    }

    if (!inputFile.eof()) {
        std::cerr << "Error: Unexpected end of file while reading integers.\n";
        return;
    }

    double average = static_cast<double>(sum) / count;
    std::cout << "Largest integer: " << maxValue << "\n";
    std::cout << "Average of all integers: " << average << "\n";
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <filename>\n";
        return EXIT_FAILURE;
    }

    process_file(argv[1]);
    return EXIT_SUCCESS;
}
