#include <semaphore.h>
#include <pthread.h>
#include <sys/mman.h>
#include <errno.h>
#include <stdio.h>
#include <unistd.h>

// Custom semaphore structure to hold semaphore ID, value, and associated attributes
struct my_semaphore {
    sem_t sem;
    int value;
    char *shm_name; // Shared memory name for inter-process communication
    size_t shm_size; // Size of shared memory region
    void *shm_ptr;   // Pointer to shared memory region
    pthread_mutex_t mutex;
};

// Custom semaphore operations with timeout support
int my_sem_init(struct my_semaphore *sem, int value, char *shm_name, size_t shm_size) {
    sem->value = value;
    sem->shm_name = shm_name;
    sem->shm_size = shm_size;
    if (posix_memalign((void**)&sem->shm_ptr, SYS_PAGE_SIZE, shm_size) != 0) {
        perror("posix_memalign");
        return -1;
    }
    pthread_mutex_init(&sem->mutex, NULL);

    // Map shared memory region for inter-process communication
    if (mmap(sem->shm_ptr, shm_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_FIXED, shm_open(shm_name, O_CREAT | O_EXCL, 0644), 0) == MAP_FAILED) {
        perror("mmap");
        free(sem->shm_ptr);
        pthread_mutex_destroy(&sem->mutex);
        return -1;
    }

    // Initialize semaphore with the given value and attributes
    if (sem_init_named(&sem->sem, shm_name, value) != 0) {
        perror("sem_init_named");
        munmap(sem->shm_ptr, shm_size);
        free(sem->shm_ptr);
        pthread_mutex_destroy(&sem->mutex);
        return -1;
    }

    return 0;
}

void my_sem_destroy(struct my_semaphore *sem) {
    // Unmap shared memory region
    if (munmap(sem->shm_ptr, sem->shm_size) != 0) {
        perror("munmap");
    }

    // Close shared memory and remove the file if no other processes are using it
    if (shm_unlink(sem->shm_name) == -1 && errno != EEXIST) {
        perror("shm_unlink");
    }

    free(sem->shm_ptr);
    sem_destroy(&sem->sem);
    pthread_mutex_destroy(&sem->mutex);
}

int my_sem_wait(struct my_semaphore *sem, const struct timespec *timeout) {
    int ret;

    // Lock the mutex to prevent concurrent operations on semaphore state
    pthread_mutex_lock(&sem->mutex);

    // Wait for the semaphore or timeout
    if (timeout == NULL) {
        ret = sem_wait(&sem->sem);
    } else {
        struct timespec now, remaining;
        clock_gettime(CLOCK_REALTIME, &now);
        remaining = *timeout;
        while (remaining.tv_sec > 0 || remaining.tv_nsec > 0) {
            ret = sem_timedwait(&sem->sem, &remaining);
            clock_gettime(CLOCK_REALTIME, &now);
            if (remaining.tv_sec <= 0 && remaining.tv_nsec <= 0) {
                break;
            }
            remaining.tv_sec = remaining.tv_sec - now.tv_sec + (remaining.tv_nsec - now.tv_nsec) / 1000000000;
            remaining.tv_nsec = (remaining.tv_nsec - now.tv_nsec) % 1000000000;
        }
    }

    // Update semaphore value and unlock the mutex
    if (ret == 0) {
        sem->value--;
    }
    pthread_mutex_unlock(&sem->mutex);

    return ret;
}

int my_sem_post(struct my_semaphore *sem) {
    int ret;

    // Lock the mutex to prevent concurrent operations on semaphore state
    pthread_mutex_lock(&sem->mutex);

    // Post to the semaphore and unlock the mutex
    ret = sem_post(&sem->sem);
    if (ret > 0) {
        sem->value++;
    }
    pthread_mutex_unlock(&sem->mutex);

    return ret;
}

int my_sem_getvalue(struct my_semaphore *sem) {
    int value;

    // Lock the mutex to prevent concurrent operations on semaphore state
    pthread_mutex_lock(&sem->mutex);

    // Get semaphore current value and unlock the mutex
    value = sem->value;
    pthread_mutex_unlock(&sem->mutex);

    return value;
}
