```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
using System.Threading;

public class DataPointGenerator
{
    private readonly int _minValue;
    private readonly int _maxValue;
    private readonly System.Random _random;
    private XDocument _document;

    public DataPointGenerator(int minValue, int maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new System.Random();
    }

    public void SetDocument(XDocument document)
    {
        _document = document;
    }

    public float NextFloat()
    {
        lock (_random)
        {
            return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
        }
    }

    public int NextInt()
    {
        lock (_random)
        {
            return _random.Next(_minValue, _maxValue + 1);
        }
    }

    public IEnumerable<XElement> SelectMatchingElements(XNode node, string selector, Func<XElement, bool> matchFunc)
    {
        var visited = new HashSet<XElement>();
        var queue = new Queue<XNode>(new[] { node });

        while (queue.Any())
        {
            var currentNode = queue.Dequeue();

            if (currentNode is XElement element)
            {
                if (!visited.Contains(element))
                {
                    visited.Add(element);

                    if (matchFunc(element))
                    {
                        yield return element;
                    }

                    foreach (var child in element.Elements())
                    {
                        queue.Enqueue(child);
                    }
                }
            }
            else if (currentNode is XContainer container)
            {
                foreach (var child in container.Nodes())
                {
                    queue.Enqueue(child);
                }
            }
        }
    }

    public List<float> GenerateDataPoints(int count)
    {
        return Enumerable.Repeat(0, count).Select(i => NextFloat()).ToList();
    }

    public List<int> GenerateDataPoints(int count)
    {
        return Enumerable.Repeat(0, count).Select(i => NextInt()).ToList();
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    private static void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
    }
}
```

