        }

        // Log the authentication attempt, including successful and failed ones, and provide detailed error messages for debugging purposes
        $this->logger->logAuthenticationAttempt($userInfoResponse['username'], isset($userInfoResponse['email']), $state, true);

        if (!empty($userInfoResponse)) {
            // Store the user data in a database safely
            $sanitizedData = sanitizeUserData($userInfoResponse);
            $this->db->insertUserData($sanitizedData);
        }

        // Integrate with a third-party logging service
        $this->thirdPartyLoggingService->logAuthenticationSuccess($userInfoResponse['username']);

        // Redirect the user to their dashboard or any other desired page
        header('Location: /dashboard');
    }
}

