    private $rateLimit;

    public function __construct(DatabaseConnector $db, Logger $logger, RateLimiter $rateLimit) {
        $this->db = $db;
        $this->logger = $logger;
        $this->rateLimit = $rateLimit;
    }

    public function addFactoryFunction(string $id, callable $factory) {
        $this->factoryRegistry[$id] = $factory;
    }

    public function updateClinicStatus(int $clinicId, string $newStatus) {
        $this->rateLimit->check();

        $clinicClass = $this->factoryRegistry[$clinicId] ?? Clinic::class;
        $clinic = $this->db->getClinicById($clinicId);

        if (!$clinic) {
            throw new Exception("Clinic not found.");
        }

        try {
            $this->db->beginTransaction();

            // Validate clinic status...
            if ($newStatus !== $clinic->status) {
                $clinic->status = $newStatus;
                $clinic->lastModifiedIp = $_SERVER['REMOTE_ADDR'];
                $clinic->lastModifiedDate = new DateTime();
            }

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollback();
            throw $e;
        }

        // Record changes with the logging service...
        $this->logger->log($clinicId, $newStatus, $_SERVER['REMOTE_ADDR'], $clinic->lastModifiedDate);
    }

    public function fromJson(string $json) {
        $data = json_decode($json);
        return new $this->factoryRegistry[$data->id]($data);
    }
}

