```rust
use std::fs::{self, File};
use std::io::{Write, Read};
use std::process::{Command, Stdio};
use std::sync::SyncLazy;
use std::time::{SystemTime, Duration};
use std::os::unix::io::AsRawFd;
use libc::execvp;
use rustc_driver::{rustc_options, catch_with_exit_code, FileId};
use log::*;

static LOGGER: SyncLazy<Logger> = SyncLazy::new(|| {
    // Initialize external logging system here
});

fn compile_and_log(source_file: &str) -> Result<i32, Box<dyn std::error::Error> {
    let start = SystemTime::now();

    if !fs::metadata(source_file).is_ok() {
        error!("Invalid or non-existent file path: {}", source_file);
        return Err(Box::new(std::io::Error::new(
            std::io::IoErrno,
            2,
        )));
    }

    // Handle case where rustc is not available

    let rustc = Command::new("rustc")
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    let output = rustc
        .arg(source_file)
        .args(&rustc_options())
        .spawn()?;

    // Measure memory usage changes
    let initial_rss = output.as_mut().unwrap().get_resident_set_size();

    {
        // Use ice hook to initialize logging during compilation
        let _guard = LOGGER.with(|logger| {
            // Log start of compilation here
            logger.log(Level::Info, "Compilation started");
        });
    }

    let exit_code = catch_with_exit_code(move || output.wait_with_output())?;

    // Measure time taken for the compilation process
    let elapsed = Duration::new(
        SystemTime::now().duration_since(start).unwrap().as_secs(),
        0,
    );

    let final_rss = output.as_mut().unwrap().get_resident_set_size();

    info!(
        "Compilation finished with exit code: {}, time taken: {}s, RSS difference: {}",
        exit_code, elapsed.as_secs(), final_rss - initial_rss
    );

    Ok(exit_code)
}
```

