```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Net.Http;
using System.Runtime.Serialization.Json;
using Newtonsoft.Json;

public class SecureCipherService
{
    private readonly HttpClient _httpClient;
    private readonly string _tokenEndpoint;
    private readonly string _clientId;
    private readonly string _clientSecret;
    private readonly TimeSpan _tokenExpirationThreshold = TimeSpan.FromMinutes(30);

    private readonly object _lock = new object();
    private Dictionary<string, (TokenResponse Token, DateTime ExpirationTime)> _cachedTokens = new Dictionary<string, (TokenResponse, DateTime)>();
    private int _maxConcurrentRequests = 10;

    public SecureCipherService(HttpClient httpClient, string tokenEndpoint, string clientId, string clientSecret)
    {
        _httpClient = httpClient;
        _tokenEndpoint = tokenEndpoint;
        _clientId = clientId;
        _clientSecret = clientSecret;
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] encryptionKey, byte[] iv, int startOffset = 0)
    {
        await EnsureTokenIsValidOrRefreshAsync();

        var decryptedBytes = new List<byte>();
        using (var aes = Aes.Create())
        {
            using (var memoryStream = new MemoryStream(ciphertext))
            {
                aes.Key = encryptionKey;
                aes.IV = iv;

                var cbc = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Read);
                var buffer = new byte[4096]; // Adjust buffer size as needed

                int read;
                do
                {
                    read = await cbc.ReadAsync(buffer, 0, buffer.Length);
                    if (read > 0) decryptedBytes.AddRange(buffer.Take(startOffset + read));
                    Array.Copy(buffer, startOffset, buffer, 0, read); // Shift buffer for next iteration
                }
                while (read > 0);
            }
        }

        return decryptedBytes.ToArray();
    }

    private async Task EnsureTokenIsValidOrRefreshAsync()
    {
        if (_cachedTokens.TryGetValue(nameof(DecryptMessageAsync), out var tokenInfo))
        {
            if (tokenInfo.ExpirationTime > DateTime.UtcNow) return;
        }

        lock (_lock)
        {
            if (_cachedTokens.TryGetValue(nameof(DecryptMessageAsync), out tokenInfo))
            {
                if (tokenInfo.ExpirationTime > DateTime.UtcNow) return;
            }

            var tokenResponse = await FetchTokenAsync();
            _cachedTokens[nameof(DecryptMessageAsync)] = (tokenResponse, DateTime.UtcNow + _tokenExpirationThreshold);
        }
    }

    private async Task<TokenResponse> FetchTokenAsync()
    {
        try
        {
            var request = new HttpRequestMessage
            {
                Method = HttpMethod.Post,
                RequestUri = new Uri(_tokenEndpoint),
                Content = new FormUrlEncodedContent(new[] { ("grant_type", "client_credentials"), ("client_id", _clientId), ("client_secret", _clientSecret) })
            };

            var response = await _httpClient.SendAsync(request);
            if (!response.IsSuccessStatusCode) throw new Exception("Failed to fetch token");

            var serializedResponse = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<TokenResponse>(serializedResponse);
        }
        catch (HttpRequestException ex)
        {
            // Retry on network issues
            await Task.Delay(TimeSpan.FromSeconds(5));
            return await FetchTokenAsync();
        }
    }
}

public class TokenResponse
{
    [JsonProperty("access_token")]
    public string AccessToken { get; set; }

    // Add other properties as needed, e.g., RefreshToken, ExpirationTime
}
```

