```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <future>
#include <deque>
#include <chrono>

const int MIN_VALUE = -1000000;
const int MAX_VALUE = 1000000;

struct Processor {
    std::mutex mtx;
    int max, sum, count;

    void operator()(const std::vector<int>& data) {
        max = MIN_VALUE;
        sum = 0;
        count = 0;

        for (const auto& num : data) {
            if (num >= MIN_VALUE && num <= MAX_VALUE) {
                ++count;
                sum += num;
                max = std::max(max, num);
            }
        }
    }
};

std::deque<int> readFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return {};
    }

    std::deque<int> numbers;
    int num;

    while (file >> num) {
        if (!std::cin.eof()) {
            numbers.push_back(num);
        } else {
            break;
        }
    }

    return numbers;
}

void processAndReportProgress(Processor& processor, const std::deque<int>& data) {
    processor(data);
    double progress = static_cast<double>(processor.count) / (data.size() * 100.0);
    std::cout << "Processing file: " << progress << "%" << std::endl;
}

void processFiles(const std::vector<std::string>& filenames, Processor& processor) {
    std::vector<std::future<void>> futures;

    for (const auto& filename : filenames) {
        auto data = readFile(filename);
        if (!data.empty()) {
            futures.emplace_back(std::async(std::launch::async, processAndReportProgress, std::ref(processor), data));
        }
    }

    for (auto& future : futures) {
        future.wait();
    }
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: ./program input_file1 input_file2 ...\n";
        return 1;
    }

    Processor processor;
    std::vector<std::string> filenames(argv + 1, argv + argc);

    processFiles(filenames, processor);

    std::cout << "Largest integer: " << processor.max << "\n";
    std::cout << "Average of all integers: " << static_cast<double>(processor.sum) / processor.count << "\n";

    return 0;
}
```

