```python
import time
import concurrent.futures
import json
from typing import Dict, Any, List, Callable, Union
import requests
from functools import wraps
import logging
from datetime import timedelta
from collections import namedtuple
from cachetools import TTLCache

class APIResponseError(Exception):
    pass

class ValidationRule:
    def __init__(self, rule_func: Callable, error_message: str):
        self.rule_func = rule_func
        self.error_message = error_message

def log_results(result: bool, endpoint: str, response: Union[dict, None]):
    if result:
        logging.info(f"Validation passed for {endpoint}: {response}")
    else:
        logging.warning(f"Validation failed for {endpoint}: {response} - {ValidationRule.error_message}")

def validate_web_service_responses(api_client, response_criteria, base_url, request_throttle_limit=5):
    endpoint_paths = list(response_criteria.keys())
    api_endpoints = [f"{base_url}/{path}" for path in endpoint_paths]
    rate_limiter = concurrent.futures.ThreadPoolExecutor(max_workers=request_throttle_limit)

    cache = TTLCache(maxsize=100, ttl=timedelta(minutes=5))

    def validate_endpoint(endpoint: str):
        try:
            response = api_client.get(endpoint)
            response.raise_for_status()  # Raises HTTPError if status code is not successful (2xx)

            validated_response = cache.get(endpoint, None)
            if validated_response is not None:
                return validated_response

            validated_response = {}
            for key, rule in response_criteria[endpoint].items():
                try:
                    result = rule.rule_func(response[key])
                    if not result:
                        raise APIResponseError(rule.error_message)
                    validated_response[key] = True
                except (KeyError, APIResponseError) as e:
                    logging.error(f"Failed to validate response for {endpoint}: {e}")
                    validated_response[key] = False

            cache[endpoint] = validated_response
            return validated_response
        except (requests.exceptions.RequestException, TimeoutError) as e:
            logging.error(f"Failed to fetch response from {endpoint}: {e}")
            return None

    def wrapped_validate_endpoint(endpoint):
        @wraps(validate_endpoint)
        def inner(*args, **kwargs):
            result = validate_endpoint(endpoint)
            if result is not None:
                log_results(True, endpoint, result)
            else:
                log_results(False, endpoint, None)
            return result
        return inner

    for endpoint in api_endpoints:
        validate_endpoint = wrapped_validate_endpoint(endpoint)
        rate_limiter.submit(validate_endpoint)

    # Wait for all concurrent requests to complete and collect their results
    with concurrent.futures.as_completed(rate_limiter) as completed_tasks:
        validated_responses = [t.result() for t in completed_tasks]

    return validated_responses

# Example usage
def is_valid_json(data):
    try:
        json.loads(data)
        return True
    except ValueError:
        return False

response_criteria = {
    "endpoint1": {"key1": ValidationRule(is_valid_json, "Invalid JSON format")},
    "endpoint2": {"key2": ValidationRule(lambda x: x > 100, "Value must be greater than 100")}
}

class CustomAPIClient:
    # Implement your API client class here
    pass

if __name__ == "__main__":
    api_client = CustomAPIClient()
    validated_responses = validate_web_service_responses(api_client, response_criteria, "https://example.com")
```

