```javascript
angular.module('myApp').service('FieldService', ['$q', '$http', function ($q, $http) {
    var _fieldMap = {};
    var _activeRequests = {};

    function refreshFields(fieldNames, resourceId, url) {
        var deferred = $q.defer();
        var activeRequests = _activeRequests[resourceId] || [];

        if (activeRequests.includes(fieldNames)) {
            return deferred.resolve(); // Skip if the same request is already in progress
        }

        activeRequests.push(fieldNames);
        _activeRequests[resourceId] = activeRequests;

        var requests = fieldNames.map(function (fieldName) {
            if (!_fieldMap[fieldName]) {
                throw new Error(`Invalid field name: ${fieldName}`);
            }

            return $http.get(`${url}/${fieldName}?resourceId=${resourceId}`)
                .then(function (response) {
                    _fieldMap[fieldName].refresh(response.data);
                    activeRequests = _activeRequests[resourceId].filter(fn => fn !== fieldNames);
                    deferred.resolve();
