#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <json-c/json.h>

typedef enum { STRING, INTEGER, FLOAT } ResourceType;

struct ResourceItem {
    const char* key;
    ResourceType type;
    union {
        const char* str;
        int integer;
        double float_;
    } value;
};

typedef struct ResourceBundle {
    size_t size;
    size_t capacity;
    struct ResourceItem* items;
} ResourceBundle;

ResourceBundle* resource_bundle_new() {
    return calloc(1, sizeof(ResourceBundle));
}

void resource_bundle_delete(ResourceBundle* bundle) {
    for (size_t i = 0; i < bundle->size; ++i) {
        free((void*)bundle->items[i].key);
        switch (bundle->items[i].type) {
            case STRING:
                break;
            case INTEGER:
                free(&(bundle->items[i].value.integer));
                break;
            case FLOAT:
                free(&(bundle->items[i].value.float_));
                break;
        }
    }
    free(bundle->items);
    free(bundle);
}

bool resource_bundle_load_from_file(ResourceBundle* bundle, const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) return false;

    json_object* json = json_tokener_parse(file);
    fclose(file);

    if (json_obj_get_type(json) != json_obj_t::json_obj_map) {
        json_object_put(json);
        return false;
    }

    json_object* items = json_obj_get_obj(json, "items");

    size_t capacity = 16;
    bundle->capacity = capacity;
    bundle->items = malloc(capacity * sizeof(struct ResourceItem));
    bundle->size = 0;

    for (json_object_iterator it = json_obj_iter_begin(items); !json_obj_iter_next(&it);) {
        const char* key = json_iter_peek_key(&it);
        if (!key) continue;

        struct ResourceItem item = {};
        item.key = strdup(key);

        const char* value_type = json_iter_peek_val(&it)->string;
        if (strcmp(value_type, "s") == 0) {
            item.type = STRING;
            item.value.str = strdup(json_iter_get_member_as_string(&it));
        } else if (strcmp(value_type, "i") == 0) {
            item.type = INTEGER;
            item.value.integer = json_iter_get_member_as_int(&it);
        } else if (strcmp(value_type, "f") == 0) {
            item.type = FLOAT;
            item.value.float_ = json_iter_get_member_as_double(&it);
        } else {
            continue;
        }

        if (!bundle->items) {
            capacity *= 2;
            bundle->capacity = capacity;
            bundle->items = realloc(bundle->items, capacity * sizeof(struct ResourceItem));
        }

        bundle->items[bundle->size++] = item;
    }

    json_object_put(json);
    return true;
}

void resource_bundle_to_json(const ResourceBundle* bundle, json_object** json) {
    *json = json_object_new_object();
    json_object* items = json_object_new_array();

    for (size_t i = 0; i < bundle->size; ++i) {
        struct ResourceItem item = bundle->items[i];
        json_object* obj = NULL;

        switch (item.type) {
            case STRING:
                obj = json_object_new_string(item.key);
                json_object_object_add(*json, item.key, obj);
                obj = json_object_new_string(item.value.str);
                json_object_array_append(items, obj);
                break;
            case INTEGER:
                obj = json_object_new_int(item.key);
                json_object_object_add(*json, item.key, obj);
                obj = json_object_new_int(item.value.integer);
                json_object_array_append(items, obj);
                break;
            case FLOAT:
                obj = json_object_new_double(item.key);
                json_object_object_add(*json, item.key, obj);
                obj = json_object_new_double(item.value.float_);
                json_object_array_append(items, obj);
                break;
        }
    }

    json_object_object_add(*json, "items", items);
}
```

