def create_and_set_env(directory_name, parent_dir=None, max_retries=retries, retry_delay=retry_delay):
    if parent_dir:
        path = os.path.join(parent_dir, directory_name)
    else:
        path = directory_name

    with mutex:
        if not os.path.exists(path):
            try:
                os.makedirs(path)
                sys.argv.append(f"{path}")
                return path
            except Exception as e:
                if max_retries > 0 and 'FileExistsError' not in str(e):
