using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Data.Entity;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using System.Reflection;
using Newtonsoft.Json;
using log4net;
using Microsoft.Extensions.Caching.Memory;

public class StoredProcedureExecutor
{
    private readonly IMemoryCache _cache;
    private readonly ILog _logger;
    private readonly string _connectionString;

    public StoredProcedureExecutor(IMemoryCache cache, ILog logger, string connectionString)
    {
        _cache = cache;
        _logger = logger;
        _connectionString = connectionString;
    }

    public async Task<List<T>> ExecuteStoredProcedureAsync<T>(string storedProcedureName, List<SqlParameter> parameters) where T : class, new()
    {
        var cacheKey = GetCacheKey(storedProcedureName, parameters);
        var resultFromCache = _cache.Get(cacheKey);

        if (resultFromCache != null)
            return JsonConvert.DeserializeObject<List<T>>(resultFromCache.ToString());

        using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();

        try
        {
            using var command = new SqlCommand(storedProcedureName, connection)
            {
                CommandType = CommandType.StoredProcedure
            };

            foreach (var parameter in parameters)
            {
                command.Parameters.Add(parameter);
            }

            using var reader = await command.ExecuteReaderAsync();

            if (!reader.HasRows) return new List<T>();

            var outputSchema = GetOutputSchemaFromStoredProcedure(storedProcedureName);
            var resultList = new List<T>();

            while (await reader.ReadAsync())
            {
                var item = Activator.CreateInstance<T>();
                MapReaderToObject(reader, outputSchema, item);
                resultList.Add(item);
            }

            _cache.Set(cacheKey, JsonConvert.SerializeObject(resultList), new MemoryCacheEntryOptions() { AbsoluteExpiration = DateTimeOffset.MaxValue });
            _logger.InfoFormat("Successfully executed stored procedure: {0}", storedProcedureName);
            return resultList;
        }
        catch (Exception ex)
        {
            _logger.ErrorFormat("Failed to execute stored procedure: {0}. Error: {1}", storedProcedureName, ex.Message);
            throw;
        }
        finally
        {
            await connection.DisposeAsync();
        }
    }

    private static string GetCacheKey(string storedProcedureName, List<SqlParameter> parameters)
    {
        var parametersWithTypes = parameters.Select(p => $"{p.ParameterName}-{p.Value}-{p.DbType}");
        return $"{storedProcedureName}:{string.Join(",", parametersWithTypes)}";
    }

    private static PropertyInfo[] GetOutputSchemaFromStoredProcedure(string storedProcedureName)
    {
        var type = new StoredProcedureSchemaQuery()
            .From("Information_Schema.Parameters")
            .Where("Specific_Schema = @Schema", new { Schema = "_Default" })
            .Where("Routine_Name = @StoredProc", new { StoredProc = storedProcedureName })
            .Select("Parameter_Name AS Name, Data_Type AS Type")
            .ToList()
            .AsQueryable()
            .Distinct()
            .ToArray();
        return type;
    }

    private static void MapReaderToObject(DbDataReader reader, PropertyInfo[] schema, object instance)
    {
        for (int i = 0; i < schema.Length; i++)
        {
            var property = schema[i];
            var value = reader[property.Name];
            if (!DBNull.Value.Equals(value))
                property.SetValue(instance, Convert.ChangeType(value, property.PropertyType));
        }
    }
}

public class StoredProcedureSchemaQuery : IQueryable<PropertyInfo>
{
    private readonly IQueryable _source;

    public StoredProcedureSchemaQuery(IQueryable source)
    {
        _source = source;
    }

    public Type ElementType => typeof(PropertyInfo);

    public Expression Expression => _source.Expression;

    public IQueryProvider Provider => _source.Provider;
}
```

