```c
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <zlib.h>
#include <sys/stat.h>
#include <time.h>
#include <map>
#include <memory>
#include <vector>
#include <iostream>
#include <fstream>
#include <sstream>
#include <functional>

struct ResourceSchema {
    int version;
    std::string metadata;
};

struct CompressedResourceItem {
    std::unique_ptr<char[]> data;
    gzfile file;
};

class ResourceBundle {
public:
    ResourceBundle() : totalItemCount(0), itemCount{}, mutex(PTHREAD_MUTEX_INITIALIZER) {}

    void addResource(const char* filePath, enum ResourceType type, const ResourceSchema& schema) {
        pthread_mutex_lock(&mutex);
        auto it = std::find_if(resources.begin(), resources.end(), [filePath](const CompressedResourceItem& item) { return strcmp(item.data.get(), filePath) == 0; });

        if (it != resources.end()) {
            ++(it->second[static_cast<int>(type)]);
            pthread_mutex_unlock(&mutex);
            return;
        }

        auto decompressedData = std::make_unique<char[]>(std::ifstream(filePath, std::ios::binary).rdbuf()->size());
        std::ifstream ifs(filePath, std::ios::binary);
        ifs.read(decompressedData.get(), ifs.rdbuf()->size());
        ifs.close();

        auto compressedSize = decompressedData->size();
        auto compressedData = std::make_unique<char[]>(compressedSize);
        std::memcpy(compressedData.get(), decompressedData.get(), compressedSize);

        CompressedResourceItem newResource{std::move(compressedData), gzopen(filePath, "rb")};

        if (!newResource.file) {
            delete[] decompressedData.release();
            throw std::runtime_error("Failed to open compressed resource file");
        }

        gzread(newResource.file, decompressedData.get(), decompressedData->size());
        gzclose(newResource.file);

        resources[std::move(decompressedData)] = {0};
        resources[std::move(decompressedData)][static_cast<int>(type)]++;
        pthread_mutex_unlock(&mutex);
    }

    ResourceItem* getResource(enum ResourceType type, size_t index) {
        pthread_mutex_lock(&mutex);
        auto it = resources.find(std::to_string(index));
        if (it == resources.end()) {
            pthread_mutex_unlock(&mutex);
            throw std::out_of_range("Resource not found");
        }

        ResourceItem* resource = new ResourceItem{type, it->second[static_cast<int>(type)] ? it->second[static_cast<int>(type)][index] : nullptr};
        pthread_mutex_unlock(&mutex);
        return resource;
    }

    size_t getResourceCount(enum ResourceType type) {
        pthread_mutex_lock(&mutex);
        auto count = itemCount[type];
        pthread_mutex_unlock(&mutex);
        return count;
    }

    void printLoadingLog() {
        // Implement logging system here
    }

private:
    std::map<std::string, std::vector<ResourceItem>> resources;
    ResourceItem* items;
    size_t totalItemCount;
    size_t itemCount[NUM_TYPES];
    pthread_mutex_t mutex;
};

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    auto bundle = new ResourceBundle();

    if (std::ifstream(filePath).is_open()) {
        std::string line;
        std::getline(std::ifstream(filePath), line); // Read schema version and metadata

        std::istringstream iss(line);
        ResourceSchema schema;
        iss >> schema.version;
        std::getline(iss, schema.metadata);

        while (std::getline(std::ifstream(filePath), line)) {
            if (line[0] == '#') continue; // Skip comments

            ResourceItem resource;
            std::istringstream resIss(line);
            resIss >> resource.type;

            if (resIss.peek() != ',') {
                bundle->printLoadingLog("Incomplete resource definition");
                continue;
            }
            resIss.ignore(); // Skip comma separator

            auto decompressedData = std::make_unique<char[]>(std::ifstream(line.substr(0, line.find('\n')).c_str(), std::ios::binary).rdbuf()->size());
            std::ifstream ifs(line.substr(0, line.find('\n')).c_str(), std::ios::binary);
            ifs.read(decompressedData.get(), ifs.rdbuf()->size());
            ifs.close();

            auto compressedSize = decompressedData->size();
            auto compressedData = std::make_unique<char[]>(compressedSize);
            std::memcpy(compressedData.get(), decompressedData.get(), compressedSize);

            CompressedResourceItem newResource{std::move(compressedData), gzopen(line.substr(0, line.find('\n')).c_str(), "rb")};

            if (!newResource.file) {
                delete[] decompressedData.release();
                throw std::runtime_error("Failed to open compressed resource file");
            }

            gzread(newResource.file, decompressedData.get(), decompressedData->size());
            gzclose(newResource.file);

            bundle->addResource(line.substr(0, line.find('\n')).c_str(), resource.type, schema);
        }
    } else {
        throw std::runtime_error("Failed to open resource file");
    }

    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    delete bundle;
}
```

