use std::env;
use std::fs::{self, create_dir_all, remove_dir_all};
use std::io::{BufRead, BufWriter, Write};
use std::path::Path;
use tempfile::NamedTempFile;
use serde::{Serialize, Deserialize};
use reqwest::{Client, Response};
use log::{debug, error, warn};
use crossbeam_channel::{unbounded, Receiver, Sender};

const CI_CONFIG: &str = "./ci-config.json";
const DEFAULT_DIR_LIFETIME: u64 = 300; // in seconds
const DEFAULT_CLEANUP_INTERVAL: u64 = 60; // in seconds

#[derive(Serialize, Deserialize)]
struct CIConfig {
    dir_lifetime: Option<u64>,
    cleanup_interval: Option<u64>,
    pre_actions: Vec<String>,
    post_actions: Vec<String>,
}

fn main() {
    let work_dir = match env::var("WORK_DIR") {
        Ok(val) => Path::new(&val),
        Err(_) => create_temp_dir(),
    };

    setup_directory(&work_dir);

    load_and_execute_config(work_dir.to_path_buf());
}

fn create_temp_dir() -> Path {
    let temp_file = NamedTempFile::new_in("/tmp").unwrap();
    temp_file.into_path()
}

fn setup_directory(work_dir: &Path) {
    if !fs::metadata(work_dir).is_ok() || !work_dir.can_write() {
        error!("Unable to set up the working directory. It is either missing or unwritable.");
        std::process::exit(1);
    }
}

fn load_and_execute_config(work_dir: PathBuf) {
    let config = match load_ci_config() {
        Ok(val) => val,
        Err(_) => CIConfig {
            dir_lifetime: Some(DEFAULT_DIR_LIFETIME),
            cleanup_interval: Some(DEFAULT_CLEANUP_INTERVAL),
            pre_actions: Vec::new(),
            post_actions: Vec::new(),
        },
    };

    let (pre_sender, pre_receiver) = unbounded();
    let (post_sender, post_receiver) = unbounded();

    execute_pre_actions(&config.pre_actions, &pre_sender);
    execute_pipeline(work_dir, &pre_receiver, &post_sender);
    execute_post_actions(&config.post_actions, &post_receiver);
}

fn load_ci_config() -> Result<CIConfig, std::io::Error> {
    let mut file = match fs::File::open(CI_CONFIG) {
        Ok(val) => val,
        Err(_) => return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No ci-config.json found")),
    };

    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    serde_json::from_str::<CIConfig>(&contents)
}

fn execute_pre_actions(actions: &[String], sender: &Sender<String>) {
    for action in actions {
        match Client::new().get(action).send() {
            Ok(res) => {
                if !res.status().is_success() {
                    error!("Pre-Action {} failed with status code {}", action, res.status());
                }
            },
            Err(e) => error!("Failed to execute pre-action {}: {}", action, e),
        };

        if let Ok(msg) = sender.send(action.clone()) {
            debug!("Sent pre-action message: {}", msg);
        }
    }
}

fn execute_pipeline(work_dir: PathBuf, pre_receiver: Receiver<String>, post_sender: Sender<String>) {
    // Implement the pipeline execution logic here.
}

fn execute_post_actions(actions: &[String], receiver: &Receiver<String>) {
    while let Ok(action) = receiver.recv() {
        match Client::new().get(action).send() {
            Ok(res) => {
                if !res.status().is_success() {
                    error!("Post-Action {} failed with status code {}", action, res.status());
                }
            },
            Err(e) => error!("Failed to execute post-action {}: {}", action, e),
        };
    }
}

fn clean_up_directory(work_dir: &Path) {
    if fs::metadata(work_dir).is_ok() && work_dir.can_write() {
        remove_dir_all(work_dir)?;
    }
}

fn run_on_interval(f: fn(&Path), interval: u64, work_dir: &Path) {
    loop {
        f(work_dir);
        std::thread::sleep(std::time::Duration::from_secs(interval));
    }
}

fn main() {
    let work_dir = match env::var("WORK_DIR") {
        Ok(val) => Path::new(&val),
        Err(_) => create_temp_dir(),
    };

    setup_directory(&work_dir);

    load_and_execute_config(work_dir.to_path_buf());

    let config = match load_ci_config() {
        Ok(val) => val,
        Err(_) => CIConfig {
            dir_lifetime: Some(DEFAULT_DIR_LIFETIME),
            cleanup_interval: Some(DEFAULT_CLEANUP_INTERVAL),
            pre_actions: Vec::new(),
            post_actions: Vec::new(),
        },
    };

    let (pre_sender, pre_receiver) = unbounded();
    let (post_sender, post_receiver) = unbounded();

    execute_pre_actions(&config.pre_actions, &pre_sender);
    execute_pipeline(work_dir.to_path_buf(), &pre_receiver, &post_sender);
    execute_post_actions(&config.post_actions, &post_receiver);

    run_on_interval(|w| clean_up_directory(w), config.cleanup_interval.unwrap_or(DEFAULT_CLEANUP_INTERVAL), work_dir);
}
