using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Xml.Linq;
using System.Threading.Tasks;
using System.Diagnostics;

namespace LargeFileProcessingApp
{
    public class Site
    {
        public string Name { get; set; }
        public int Port { get; set; }
    }

    public class ProcessResult
    {
        public bool Success { get; set; }
        public string ErrorMessage { get; set; }
    }

    public class Program
    {
        static readonly object _lock = new object();
        static List<Site> _sites = new List<Site>();
        static Dictionary<string, int[]> _dataByFile = new Dictionary<string, int[]>();

        static async Task Main(string[] args)
        {
            if (!Directory.Exists(args[0]))
            {
                Console.WriteLine("Invalid directory path.");
                return;
            }

            var webConfigPath = Path.Combine(args[0], "web.config");
            if (!File.Exists(webConfigPath))
            {
                Console.WriteLine("Web.config file not found.");
                return;
            }

            var config = XDocument.Load(webConfigPath);
            foreach (var siteElement in config.Root.Elements("site"))
            {
                if (!ValidateSiteName(siteElement.Attribute("name").Value))
                {
                    Console.WriteLine("Invalid site name format.");
                    continue;
                }

                var portElement = siteElement.Element("port");
                int port;
                if (!int.TryParse(portElement?.Value, out port))
                {
                    Console.WriteLine($"Invalid port number for site '{siteElement.Attribute("name").Value}'.");
                    continue;
                }

                _sites.Add(new Site { Name = siteElement.Attribute("name").Value, Port = port });
            }

            var tasks = _sites.Select(SiteProcessor).ToList();
            await Task.WhenAll(tasks);

            if (_dataByFile.Count == 0)
            {
                Console.WriteLine("No data found across all sites.");
                return;
            }

            lock (_lock)
            {
                int maxValue = _dataByFile.Values.Select(v => v.Max()).Max();
                double average = _dataByFile.Sum(kvp => kvp.Value.Sum()) / _dataByFile.Count;

                Console.WriteLine($"Largest integer: {maxValue}");
                Console.WriteLine($"Average of all integers: {average}");
            }
        }

        private static async Task<ProcessResult> SiteProcessor(Site site)
        {
            try
            {
                var process = new Process
                {
                    StartInfo = new ProcessStartInfo($"dotnet run", $"--project {Path.Combine(args[0], $"{site.Name}.csproj")}"),
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                };

                process.Start();
                process.Exited += (sender, args) =>
                {
                    if (process.ExitCode != 0)
                    {
                        Console.WriteLine($"Site '{site.Name}' failed to start.");
                    }
                    else
                    {
                        var output = process.StandardOutput.ReadToEnd();
                        var data = output.Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries)
                            .Select(int.Parse)
                            .ToArray();

                        lock (_lock)
                        {
                            _dataByFile[Path.GetFileName(args[0])] = data;
                        }
                    }
                };

                process.StartInfo.RedirectStandardError = true;
                process.OutputDataReceived += (sender, args) => Console.WriteLine(args.Data);
                process.ErrorDataReceived += (sender, args) => Console.WriteLine(args.Data);

                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();

                await Task.Delay(TimeSpan.FromSeconds(10)); // Add timeout mechanism
                process.Kill();

                return new ProcessResult { Success = true };
            }
            catch (Exception ex)
            {
                return new ProcessResult { ErrorMessage = ex.Message };
            }
        }

        private static bool ValidateSiteName(string name)
        {
