class DirectoryManager:
    def __init__(self, base_dir, timeout=10, max_retries=5, backoff_factor=2):
        self.base_dir = base_dir
        self.timeout = timeout
        self.max_retries = max_retries
        self.backoff_factor = backoff_factor

    def create_directory(self, dir_name):
        attempts = 0
        while attempts < self.max_retries:
            try:
                os.makedirs(os.path.join(self.base_dir, dir_name))
                break
            except OSError as e:
                if e.errno != 17:  # EEXIST error for existing directory
                    attempts += 1
                    time.sleep(attempts * self.backoff_factor)
                else:
                    break
        else:
            raise Exception(f"Failed to create directory {dir_name} after {self.max_retries} retries.")

    def remove_directory(self, dir_name):
        try:
            shutil.rmtree(os.path.join(self.base_dir, dir_name))
        except OSError as e:
            pass  # Ignore errors when removing non-existent directories

    def create_tempfile(self):
        return tempfile.TemporaryFile(dir=self.base_dir)

    def log_error(self, error, **kwargs):
