```php
function authenticateUser($password, $newPassword = null) {
    // Use a CSPRNG for generating random strings suitable as salt
    $salt = random_int(0, (1 << 32) - 1);

    try {
        // Call the external authentication API to check if user exists
        $userExists = callExternalAPI('authenticate', ['username' => $_POST['username']]);

        if (!$userExists) {
            throw new Exception("User not found.");
        }
    } catch (Exception $e) {
        error_log($e->getMessage());
        return false;
    }

    // Hash the password using password_hash() with the generated salt
    $hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['salt' => decbin($salt)]);

    if ($newPassword !== null) {
        // Regenerate the hash when changing the password
        $regeneratedHashedPassword = password_hash($newPassword, PASSWORD_BCRYPT, ['salt' => decbin($salt)]);
        return $regeneratedHashedPassword;
    }

    // Compare hashed password with the provided plain text password
    if (password_verify($password, $hashedPassword)) {
        return true;
    }

    return false;
}
```

