<?php

namespace App\Classes;

class SecureTokenSession {
    private $characterSet = '';
    private $length = 32;
    private $tokenAlgo = 'bcrypt'; // bcrypt, Argon2id, etc.
    private $passwordAlgo = 'bcrypt'; // bcrypt, Argon2id, etc.
    private $hasher;
    private $salt = '';
    private static $instance;

    public function __construct() {
        $this->characterSet = config('settings.token_characters');
        $this->hasher = Hash::make($this->salt);
    }

    public static function getInstance(): self {
        if (!self::$instance) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    /**
     * Generate a secure random token.
     */
    public function generateToken($length = null, $characterSet = null): string {
        // Validate and sanitize input
        if ($length && !is_numeric($length) || $length < 8 || $length > 64) {
            throw new InvalidArgumentException('Invalid token length.');
        }

        if ($characterSet && !is_string($characterSet)) {
            throw new InvalidArgumentException('Invalid character set.');
        }

        $token = '';
        if (!empty($length)) {
            $tokenLength = intval($length);
        } else {
            $tokenLength = $this->length;
        }

        if (!empty($characterSet)) {
            $this->characterSet = $characterSet;
        }

        $validChars = str_split(preg_replace('#[^ alnum0123456789]#i', '', $this->characterSet));
        for ($i = 0; $i < $tokenLength; $i++) {
            $token .= $validChars[array_rand($validChars)];
        }

        return strtolower($token);
    }

    /**
     * Hash a password using the specified algorithm.
     */
    public function hashPassword($password): string {
        if (!in_array($this->passwordAlgo, ['bcrypt', 'Argon2id'])) {
            throw new InvalidArgumentException('Invalid password hashing algorithm.');
        }

        if (strlen($password) < 8 || strlen($password) > 72) {
            throw new InvalidArgumentException('Password must be between 8 and 72 characters long.');
        }

        return password_hash($password, $this->passwordAlgo);
