```javascript
async function readFiles(directoryPath) {
    const fs = require('fs');
    const path = require('path');

    let fileNames = [];
    const files = await fs.readdirSync(directoryPath);

    for (const file of files) {
        const fullPath = path.join(directoryPath, file);
        if (fs.lstatSync(fullPath).isDirectory()) {
            // Recursively read subdirectories
            await readFiles(fullPath);
        } else {
            // Add the current file to the list if it's a valid file
            const isValidFile = /\.(txt|json)$/.test(file);
            if (isValidFile) {
                fileNames.push(path.join(directoryPath, file));
            }
        }
    }

    // Read and return the content of all valid files as a string
    let contents = '';
    for (const fileName of fileNames) {
        contents += fs.readFileSync(fileName, 'utf8');
    }

    return contents;
}
