```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

namespace YourNamespace
{
    public class DatabaseManager
    {
        private readonly string _connectionString;
        private readonly IMemoryCache _memoryCache;
        private readonly ILogger<DatabaseManager> _logger;
        private readonly int _cacheLimit;

        public DatabaseManager(string connectionString, IMemoryCache memoryCache, ILogger<DatabaseManager> logger, int cacheLimit = 10)
        {
            _connectionString = connectionString;
            _memoryCache = memoryCache;
            _logger = logger;
            _cacheLimit = cacheLimit;
        }

        public async Task<IDataReader> ExecuteParameterizedQuery(SqlConnection connection, string commandText, List<object> parameters, bool returnList = false)
        {
            var key = CreateCacheKey(commandText);
            if (_memoryCache.TryGetValue(key, out IDataReader cachedResult))
            {
                _logger.LogInformation("Retrieved query result from cache.");
                return cachedResult;
            }

            lock (this)
            {
                var command = new SqlCommand(commandText, connection);
                AddParametersToCommand(command, parameters);

                Task<IDataReader> task;
                if (returnList)
                {
                    var executor = Task.Factory.StartNew(() => command.ExecuteReader());
                    task = Task.FromResult(executor.Result);
                }
                else
                {
                    task = Task.Run(() => command.ExecuteReaderAsync());
                }

                try
                {
                    var result = await task;
                    if (!returnList)
                    {
                        _memoryCache.Set(key, result);
                        if (_memoryCache.Count > _cacheLimit)
                        {
                            _memoryCache.Remove(GetOldestCachedQueryKey());
                        }
                    }
                    return result;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to execute query.");
                    throw;
                }
            }
        }

        private void AddParametersToCommand(DbCommand command, IList<object> parameters)
        {
            if (parameters == null || !parameters.Any()) return;

            var parameterIndex = 0;
            foreach (var parameter in parameters)
            {
                var dbParameter = command.CreateParameter();
                dbParameter.Value = parameter;
                dbParameter.ParameterName = $"@{parameterIndex}";
                command.Parameters.Add(dbParameter);
                parameterIndex++;
            }
        }

        private string CreateCacheKey(string commandText) => $"DbCache_{commandText}";

        private string GetOldestCachedQueryKey() => _memoryCache.Keys.OrderByDescending(x => x).First();
    }
}
```

