typedef struct Node {
    int value;
    struct SubNode *head;
} Node;

typedef struct SubNode {
    char string[STRING_LENGTH];
    double value;
    struct SubNode *next;
} SubNode;

Node* create_node_array(size_t size) {
    Node *nodes = malloc(sizeof(Node) * size);

    if (!nodes) {
        perror("Memory allocation error");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        nodes[i].value = rand() % (MAX_INTEGER - MIN_INTEGER + 1) + MIN_INTEGER;
        nodes[i].head = NULL;
    }

    return nodes;
}

SubNode* create_subnode(char *string, double value) {
    SubNode *new_node = malloc(sizeof(SubNode));

    if (!new_node) {
        perror("Memory allocation error");
        return NULL;
    }

    strncpy(new_node->string, string, STRING_LENGTH);
    new_node->value = value;
    new_node->next = NULL;

    return new_node;
}

void init_linked_list(Node *node, SubNode **head) {
    *head = create_subnode("Example", (double)rand() / RAND_MAX);

    if (!*head) {
        perror("Memory allocation error");
        return;
    }

    node->head = *head;
}

void add_to_linked_list(Node *node, SubNode *current, SubNode **head) {
    SubNode *new_node = create_subnode("Example", (double)rand() / RAND_MAX);

    if (!new_node) {
        perror("Memory allocation error");
        return;
    }

    current->next = new_node;
    *head = new_node;
}

void free_memory(Node *nodes, SubNode *head) {
    Node *current_node;
    SubNode *current_subnode;

    for (size_t i = 0; i < NODE_ARRAY_SIZE; ++i) {
        current_node = &nodes[i];

        while (current_node->head != NULL) {
            current_subnode = current_node->head;
            current_node->head = current_node->head->next;
            free(current_subnode);
        }
    }

    free(nodes);
}

void *initialize_and_populate_nodes(void *args) {
    Node *nodes = create_node_array(NODE_ARRAY_SIZE);

    if (!nodes) {
        return NULL;
    }

    SubNode *head = NULL;

    for (size_t i = 0; i < NODE_ARRAY_SIZE; ++i) {
        init_linked_list(&nodes[i], &head);

        if (!head) {
            perror("Memory allocation error");
            return NULL;
        }

        for (size_t j = 0; j < LINKED_LIST_SIZE; ++j) {
            add_to_linked_list(&nodes[i], head, &head);

            if (!head) {
                perror("Memory allocation error");
                return NULL;
            }
        }
    }

    // Implement serialization and deserialization functions here...

    free_memory(nodes, head);

    return NULL;
}
