public class GameClient {
    private static final Logger LOGGER = LogManager.getLogger(GameClient.class);
    private final ScheduledExecutorService cooldownScheduler = Executors.newScheduledThreadPool(1);
    private final GameServerApi gameServerApi;
    private final LoggingService loggingService;
    private final AtomicBoolean connected = new AtomicBoolean(false);
    private final Semaphore semaphore = new Semaphore(1);
    private long attackCooldownEndTime;

    public GameClient(GameServerApi gameServerApi, LoggingService loggingService) {
        this.gameServerApi = gameServerApi;
        this.loggingService = loggingService;
    }

    @GuardedBy("this")
    private Selector selector;

    public void connectToGameServer(String serverAddress) {
        try (var socketChannel = SocketChannel.open()) {
            socketChannel.connect(new InetSocketAddress(serverAddress, 80)); // Replace with appropriate game server port

            synchronized (this) {
                selector = Selector.open();
                socketChannel.configureBlocking(false);
                selector.register(socketChannel, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
                connected.set(true);
            }

            Thread thread = new Thread(() -> handleConnectionStateChanges());
            thread.start();
        } catch (Exception e) {
            LOGGER.error("Failed to connect to game server", e);
        }
    }

    private void handleConnectionStateChanges() {
        try {
            semaphore.acquire();
            while (connected.get()) {
                selector.select();
                Iterator<SelectionKey> keyIterator = selector.selectedKeys().iterator();

                while (keyIterator.hasNext()) {
                    var selectionKey = keyIterator.next();
                    keyIterator.remove();

                    if (selectionKey.isReadable()) {
                        handleReadOperation(selectionKey);
                    } else if (selectionKey.isWritable()) {
                        handleWriteOperation(selectionKey);
                    }
                }
            }
        } catch (Exception e) {
            LOGGER.error("Error in connection handling", e);
        } finally {
            semaphore.release();
        }
    }

    private void handleReadOperation(SelectionKey selectionKey) throws Exception {
        // Handle incoming data from the game server and process attack requests here
    }

    private void handleWriteOperation(SelectionKey selectionKey) throws Exception {
        // Send outgoing data to the game server, such as character's position or selected attacks
    }

    public void selectAttack(@Nonnull Attack attack) {
        if (attackCooldownEndTime > System.currentTimeMillis()) {
            LOGGER.info("Character on cooldown, cannot perform attack");
            return;
        }

        synchronized (this) {
            semaphore.acquireUninterruptibly();
        }

        try {
            // Prioritize urgent attacks by checking the urgency of the attack and modifying the code accordingly

            long currentTime = System.currentTimeMillis();
            attackCooldownEndTime = currentTime + 9_000; // Set cooldown end time for next 9 seconds

            handleAttack(attack);
        } catch (Exception e) {
            LOGGER.error("Error during attack execution", e);
        } finally {
            semaphore.release();
        }
    }

    private void handleAttack(@Nonnull Attack attack) throws Exception {
        // Implement game server API calls, logging, and other required functionality here
    }

    public void disconnectFromGameServer() {
        if (connected.compareAndSet(true, false)) {
            selector.wakeup();
        }
    }
}
