#include <format>

class Character {
public:
    enum class Attack { ATTACK1, ATTACK2 };
    static constexpr int MAX_USAGE = 100;

private:
    std::map<Attack, std::pair<int, std::mutex>> usageCounts_;
    std::atomic_bool sessionEnd_{false};

public:
    void Attack() {
        auto now = std::chrono::steady_clock::now();
        auto elapsed = now - lastAttackTime_;

        if (elapsed < std::chrono::seconds(9)) {
            std::this_thread::sleep_until(lastAttackTime_ + std::chrono::seconds(9) - elapsed);
        }

        auto [usage, mtx] = usageCounts_[selectedAttack_];
        std::unique_lock<std::mutex> lock(mtx);
        lock.unlock(); // Acquire the lock but allow the mutex to be re-entered for this session

        if (++usage > MAX_USAGE) {
            if (!sessionEnd_) {
                std::cout << "Warning: Attack limit reached, preventing further use.\n";
                sessionEnd_ = true;
            }
            return;
        }

        selectedAttack_ = (selectedAttack_ + 1) % 2;
        lastAttackTime_ = now;

        std::cout << "Attack: " << static_cast<int>(selectedAttack_) << "\n";
    }

private:
    Attack selectedAttack_{Attack::ATTACK1};
    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime_;

    friend class GameEngine; // Allow the game engine to access private members for integration
};

class GameEngine {
public:
    void Update() {
        character_.Attack();
        // Other game logic updates...
    }

private:
    Character character_;
};

