interface ElementMetadata {
    id: string;
    class: string;
    description: Promise<string>;
    children: ElementMetadata[];
    element: HTMLElement;
}

async function getMatchingElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean): Promise<HTMLElement[]> {
    const queue: ElementMetadata[] = [{id: rootElement.id, class: rootElement.className, description: Promise.resolve(await getDescriptionFromAPI(rootElement.id)), children: [], element: rootElement}];

    let currentNode: ElementMetadata | null = queue.shift();
    const matchingElements: HTMLElement[] = [];

    while (currentNode) {
        if (matchesSelector(currentNode.element, selector)) {
            if (filterFn(currentNode)) {
                matchingElements.push(currentNode.element);
            }
        }

        currentNode.children = Array.from(currentNode.element.children).reduce((acc, child) => {
            const childMetadata: ElementMetadata = {id: child.id, class: child.className, description: Promise.resolve(await getDescriptionFromAPI(child.id)), children: [], element: child};
            acc.push(childMetadata);
            return acc;
        }, []);

        currentNode = queue.length ? queue.shift() : null;
    }

    return matchingElements;
}

function matchesSelector(element: HTMLElement, selector: string) {
    try {
        const matches = element.matches || element.webkitMatchesSelector || element.mozMatchesSelector || element.msMatchesSelector;
        return matches(selector);
    } catch (error) {
        console.warn(`Error matching selector for element ${element.id}:`, error);
        return false;
    }
}

async function getDescriptionFromAPI(id: string): Promise<string> {
    // Implement the call to your external API here
}
```

This code creates a recursive `getMatchingElements()` function that takes a root element, selector, and filter function. It uses a queue to traverse the DOM tree in a depth-first manner and stores metadata about each element, including its children, ID, class, description (from an asynchronous API call), and the matched HTMLElement.

The `matchesSelector()` function checks if the given element matches the specified selector using a polyfill for various browser compatibility issues. The `getDescriptionFromAPI()` function should be replaced with your actual implementation of making an asynchronous call to the external API.

