using System;
using System.Security.Cryptography;
using System.Text;
using BCrypt.Net;
using Dapper;
using Newtonsoft.Json;

public class SecurePasswordManager
{
    private const int SALT_LENGTH = 16;
    private readonly IDbConnection _dbConnection;
    private readonly string _authenticationApiKey;

    public SecurePasswordManager(IDbConnection dbConnection, string authenticationApiKey)
    {
        _dbConnection = dbConnection;
        _authenticationApiKey = authenticationApiKey;
    }

    public string HashPassword(string password, HashingAlgorithm algorithm = HashingAlgorithm.SHA256)
    {
        var salt = GenerateSalt();
        byte[] passwordBytes = Encoding.UTF8.GetBytes($"{password}:{salt}");

        switch (algorithm)
        {
            case HashingAlgorithm.SHA256:
                using (var sha256 = SHA256.Create())
                    return BitConverter.ToString(sha256.ComputeHash(passwordBytes)).Replace("-", "").ToLower();
            case HashingAlgorithm.bcrypt:
                BCrypt.Net.BCrypt.GenerateSalt(SALT_LENGTH, out byte[] saltBytes);
                return BCrypt.Net.BCrypt.HashPassword(passwordBytes, saltBytes).ToString();
        }
    }

    public bool VerifyPassword(string hashedPassword, string plainTextPassword, HashingAlgorithm algorithm = HashingAlgorithm.SHA256)
    {
        var storedHashedPassword = RetrieveStoredPasswordHash(hashedPassword);

        if (storedHashedPassword == null)
            return false;

        byte[] passwordBytes = Encoding.UTF8.GetBytes($"{plainTextPassword}:{storedHashedPassword}");

        switch (algorithm)
        {
            case HashingAlgorithm.SHA256:
                using (var sha256 = SHA256.Create())
                    return BitConverter.ToString(sha256.ComputeHash(passwordBytes)).Equals(hashedPassword);
            case HashingAlgorithm.bcrypt:
                return BCrypt.Net.BCrypt.Verify(passwordBytes, hashedPassword);
        }
    }

    public void StorePasswordHash(string userId, string hashedPassword)
    {
        _dbConnection.Open();
        _dbConnection.Execute("INSERT INTO UserHashedPasswords (UserId, HashedPassword) VALUES (@UserId, @HashedPassword)", new { UserId = userId, HashedPassword = hashedPassword });
        _dbConnection.Close();
    }

    public string RetrieveStoredPasswordHash(string hashedPassword)
    {
        var result = _dbConnection.QuerySingleOrDefault<string>("SELECT HashedPassword FROM UserHashedPasswords WHERE HashedPassword = @HashedPassword", new { HashedPassword = hashedPassword });
        return result;
    }

    private string GenerateSalt()
    {
        byte[] salt;
        using (var rngCryptoServiceProvider = new RNGCryptoServiceProvider())
            salt = new byte[SALT_LENGTH];
        rngCryptoServiceProvider.GetBytes(salt);
        return Convert.ToBase64String(salt);
    }

    public bool AuthenticateUser(string userId, string password)
    {
        var hashedPassword = RetrieveStoredPasswordHash(userId);
        if (hashedPassword == null)
            return false;
        return VerifyPassword(hashedPassword, password);
    }

    public void CallExternalAuthenticationApi(string userId, string token)
    {
        using (var httpClient = new HttpClient())
        {
            var request = new HttpRequestMessage
            {
                Method = HttpMethod.Post,
                RequestUri = new Uri($"https://authentication-api.com/api/v1/verify/{userId}/{token}"),
                Headers = { { "Authorization", _authenticationApiKey } }
            };

            using (var response = httpClient.SendAsync(request).Result)
            {
                if (!response.IsSuccessStatusCode)
                    throw new Exception("Error while calling external authentication API");

                var apiResponse = response.Content.ReadAsStringAsync().Result;
                // Handle and process the API response here
            }
        }
    }
}

public enum HashingAlgorithm { SHA256, bcrypt }
