import java.util.Base64;
import java.util.zip.Checksum;

public class MostStateLoader {
    private static final String LOGGER_CONFIG = "logger.config";
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MULTIPLIER = 2;
    private static Logger logger;

    public static MoSTState loadState(String filePath) {
        Authenticator authenticator = new Authenticator();
        try (ObjectInputStream objectInput = new ObjectInputStream(authenticator.getAuthenticatedInputStream(filePath))) {
            Checksum checksum = new Adler32();
            checksum.reset();
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = objectInput.read(buffer)) != -1) {
                checksum.update(buffer, 0, bytesRead);
            }

            Object readObject = objectInput.readObject();
            if (readObject instanceof MoSTState state) {
                if (checksum.getValue() == state.getChecksum()) {
                    logger.info("Loaded state file: " + filePath);
                    return state;
                } else {
                    logger.error("Invalid checksum for state file: " + filePath);
                    return null;
                }
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Error loading state file: " + e.getMessage(), e);
            return null;
        } catch (ExceptionInInitializerError e) {
            logger.fatal("Fatal error during initialization, unable to load state.", e);
            System.exit(1);
        }
        return null;
    }

