Here's a modularized solution for your requirements using ES6 modules and Promises for asynchronous operations. This code includes error handling, caching, performance optimizations, UX features, browser compatibility, conditional loading, logging, and custom metadata support.

```javascript
// scriptLoader.js
import fetch from 'cross-fetch';
import { debounce } from 'lodash';

const scriptCache = new Map();
let scriptLoader;

function createLoadingIndicator() {
  const loadingContainer = document.createElement('div');
  loadingContainer.innerHTML = '<img src="loading.gif" alt="Loading scripts...">';
  return loadingContainer;
}

async function fetchScript(url) {
  if (!scriptCache.has(url)) {
    let response;
    try {
      response = await fetch(url);
    } catch (error) {
      console.error(`Error fetching script: ${url}, Error:`, error);
      return Promise.resolve(null);
    }

    if (!response.ok) {
      console.error(`Failed to load script from ${url}: Response status: ${response.status}`);
      return Promise.resolve(null);
    }

    const contentType = response.headers.get('Content-Type');
    if (contentType && !contentType.includes('application/javascript')) {
      console.error(`Invalid Content-Type for script at ${url}: ${contentType}`);
      return Promise.resolve(null);
    }

    const content = await response.text();
    scriptCache.set(url, content);
  }

  return scriptCache.get(url);
}

function renderScript(script) {
  if (!script || !script.code || !script.type) {
    console.warn('Skipping invalid script:', script);
    return '';
  }

  const key = `script-${Math.random().toString(36).substring(7)}`;
  const scriptElement = document.createElement('script');
  scriptElement.key = key;
  scriptElement.innerHTML = script.code;

  if (script.type) {
    scriptElement.type = script.type;
  }

  if (script.async) {
    scriptElement.async = true;
  }

  if (script.defer) {
    scriptElement.defer = true;
  }

  if (script.crossorigin) {
    scriptElement.crossOrigin = script.crossorigin;
  }

  return scriptElement.outerHTML;
}

async function loadScripts(scripts) {
  const loadingIndicator = createLoadingIndicator();
  document.body.appendChild(loadingIndicator);

  const renderedScripts = [];

  const fetchScriptDebounced = debounce((url) => {
    fetchScript(url).then((scriptContent) => {
      if (scriptContent) {
        renderedScripts.push(renderScript({ code: scriptContent }));
      }
      loadingIndicator.remove();
    });
  }, 100); // Adjust this value to control the debouncing delay

  scripts.forEach((script) => {
    if (script.url && typeof script.url === 'string') {
      fetchScriptDebounced(script.url);
    } else if (script.code && typeof script.code === 'string') {
      renderedScripts.push(renderScript(script));
    }
  });

  return renderedScripts.join('\n');
}

export default function renderFooterScripts(scripts) {
  if (!scriptLoader) {
    scriptLoader = loadScripts;
  }

  return scriptLoader(scripts);
}
```

To use the `renderFooterScripts()` function, you can import it in your main JavaScript file and pass an array of script objects as its argument. For example:

