using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

public interface IDeserializer<T>
{
    T Deserialize(Stream stream);
}

public abstract class BaseDeserializer<T> : IDeserializer<T>
{
    protected readonly ILogger<BaseDeserializer<T>> Logger;
    protected readonly JsonSerializerSettings SerializerSettings;

    protected BaseDeserializer(ILogger<BaseDeserializer<T>> logger, JsonSerializerSettings serializerSettings)
    {
        Logger = logger;
        SerializerSettings = serializerSettings;
    }

    public abstract T Deserialize(Stream stream);
}

public class JsonDeserializer<T> : BaseDeserializer<T>
{
    private readonly IJsonFileTypeResolver fileTypeResolver;
    private readonly Func<Version, bool> isCompatibleVersionChecker;

    public JsonDeserializer(ILogger<JsonDeserializer<T>> logger, JsonSerializerSettings serializerSettings, IJsonFileTypeResolver fileTypeResolver, Func<Version, bool> isCompatibleVersionChecker) : base(logger, serializerSettings)
    {
        this.fileTypeResolver = fileTypeResolver;
        this.isCompatibleVersionChecker = isCompatibleVersionChecker;
    }

    public override T Deserialize(Stream stream)
    {
        var reader = new StreamReader(stream);
        string jsonContent = reader.ReadToEnd();
        Type deserializedType = typeof(T);

        JsonSerializer serializer = new JsonSerializer();

        if (fileTypeResolver.ResolveFileType(Path.GetExtension(stream.Name)) != FileType.Json)
        {
            throw new Exception($"Invalid file type: {stream.Name}");
        }

        var versionInfo = JObject.Parse(jsonContent).SelectToken("version");
        if (versionInfo == null)
        {
            throw new Exception("Missing or invalid version information in the file.");
        }

        Version fileVersion;
        if (!Version.TryParse(versionInfo.ToString(), out fileVersion))
        {
            throw new Exception("Invalid version format in the file.");
        }

        if (!isCompatibleVersionChecker(fileVersion))
        {
            throw new Exception($"Incompatible file version: {fileVersion}");
        }

        JsonTextReader jsonReader = new JsonTextReader(new StringReader(jsonContent));

        try
        {
            return serializer.Deserialize<T>(jsonReader);
        }
        catch (JsonSerializationException ex)
        {
            Logger.LogError(ex, "Failed to deserialize JSON data.");
            throw;
        }
    }
}

public interface IFileTypeResolver
{
    FileType ResolveFileType(string extension);
}

public enum FileType
{
    Json
}

