public class DataLoaderService : IDataLoaderService
{
    private readonly IDictionary<FileType, Func<Stream, T>> deserializers;
    private readonly IConfiguration configuration;
    private readonly ILogger<DataLoaderService> logger;
    private readonly SemaphoreSlim throttler = new SemaphoreSlim(5);

    public DataLoaderService(ILogger<DataLoaderService> logger, IConfiguration configuration, IDictionary<FileType, Func<Stream, T>> deserializers)
    {
        this.logger = logger;
        this.configuration = configuration;
        this.deserializers = deserializers;
    }

    public async Task<T> LoadDataAsync(string path, CancellationToken cancellationToken = default)
    {
        await throttler.WaitAsync(cancellationToken);

        try
        {
            using (FileStream fileStream = File.OpenRead(path))
            {
                FileType fileType = fileTypeResolver.ResolveFileType(Path.GetExtension(path));
                Func<Stream, T> deserializer = deserializers[fileType];
                return await Task.Run(() => deserializer(fileStream), cancellationToken);
            }
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to load data from file.");
            throw;
        }
        finally
        {
            throttler.Release();
        }
    }
}
