class BreadthFirstIterator {
    constructor(private queue: Node[], private visited: Set<Node>) {}

    static fromElement(element: HTMLElement, visited = new Set<Node>()): BreadthFirstIterator {
        const queue = [[element, 0]];
        return new BreadthFirstIterator(queue, visited);
    }

    next(): Node | null {
        if (!this.queue.length) return null;
        const [node, depth] = this.queue.shift() as [Node, number];
        this.visited.add(node);

        for (const child of node.children || []) {
            if (!this.visited.has(child)) {
                this.queue.push([child, depth + 1]);
            }
        }

        return node;
    }
}

class ApiClientQueue {
    private queue: ((() => Promise<ApiClient>)[]);

    constructor(private maxConcurrentRequests: number) {}

    enqueue(factoryFn: () => Promise<ApiClient>): void {
        if (this.queue.length < this.maxConcurrentRequests) {
            this.queue.push(factoryFn);
        }
    }

    dequeue(): Promise<ApiClient> {
        const fn = this.queue.shift();
        return fn ? fn() : Promise.resolve(null);
    }
}

class ApiClient implements ApiClient {
    constructor(private apiUrl: string) {}

    async fetchDescriptions(elements: HTMLElement[]): Promise<Map<string, string>> {
        // Implementation to make API calls and process responses
    }

    async fetchImages(elements: HTMLElement[]): Promise<Map<string, string>> {
        // Implementation to make API calls and process responses
    }
}

async function fetchAndFilterElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean, apiClientFactory: ApiClientFactory): Promise<HTMLElement[]> {
    const visited = new Set<Node>();
    const matchingElements = [];
    const iterator = BreadthFirstIterator.fromElement(rootElement, visited);

    while (const element = iterator.next()) {
        if (!element) break;

        const matchesSelector = element.matches(selector);
        if (matchesSelector) {
            matchingElements.push(element as HTMLElement);
        }

        if (!visited.has(element)) {
            visited.add(element);
        }
    }

    const apiClientQueue = new ApiClientQueue(10); // Adjust maxConcurrentRequests to suit your needs
    const apiClients: ApiClient[] = [];

    for (const clientFn of apiClientFactory.createApiClient.bind(apiClientFactory)) {
        apiClientQueue.enqueue(() => clientFn());
    }

    while (apiClients.length < matchingElements.length) {
        const apiClient = await apiClientQueue.dequeue();
        if (!apiClient) continue;

        apiClients.push(apiClient);
        const elementMetadatas: ElementMetadata[] = [];

        for (const element of matchingElements) {
            if (element && !elementMetadatas.includes(element)) {
                // Implement logic to populate `ElementMetadata` object with element attributes and API responses
                const metadata: ElementMetadata = {
                    id: element.id,
                    class: [...element.classList],
                    descriptions: apiClient.fetchDescriptions([element]),
                    images: apiClient.fetchImages([element]),
                };
                if (filterFn(metadata)) {
                    elementMetadatas.push(metadata);
                }
            }
        }
    }

    // Filter the matched elements based on the provided filtering function and return the result
    // You can use Array.prototype.filter() for this purpose or any other appropriate method you prefer
}
