**Java:** Secure NIO Connection (Using Netty as it is designed to be high-performance, scalable, and includes SSL/TLS support):

```java
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioSocketChannel;
import org.bouncycastle.cert.X509CertificateHolder;
import javax.net.ssl.*;

public class SecureConnection {
    private final String host;
    private final int port;

    public SecureConnection(String host, int port) {
        this.host = host;
        this.port = port;
    }

    public Channel Future() {
        EventLoopGroup group = new NioEventLoopGroup();
        try {
            SSLContext sslCtx = SSLContextBuilder.forClient().trustManager(new TrustSelfSignedStrategy()).build();
            SSLEngine engine = sslCtx.createSSLEngine();
            engine.setUseClientMode(true);

            Bootstrap b = new Bootstrap();
            b.group(group)
                    .channel(NioSocketChannel.class)
                    .handler(new ChannelInitializer<Channel>() {
                        @Override
                        public void initChannel(Channel ch) throws Exception {
                            ChannelPipeline p = ch.pipeline();
                            SSLHandler sslHandler = new SSLHandler(engine);
                            p.addLast(sslHandler);
                            // Add your custom handlers after the SSL handler
                        }
                    })
                    .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 5000)
                    .remoteAddress(new InetSocketAddress(host, port));

            ChannelFuture cf = b.connect().sync();
            return cf;
        } catch (Exception e) {
            // Handle exceptions and close resources here if needed
            throw new RuntimeException(e);
        } finally {
            group.shutdownGracefully();
        }
    }
}
```

