using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Reflection;
using System.Threading.Tasks;
using System.Xml.Linq;
using MersenneTwister = System.Security.Cryptography.RNGCryptoServiceProvider;

namespace SimpleRandomGenerator
{
    public class RandomNumberGenerator
    {
        private static readonly MersenneTwister _rng = new MersenneTwister();
        private static List<int> _integers;
        private static string[] _files;
        private static int? _largest;
        private static double _average;
        private static bool _webConfigFound;

        public RandomNumberGenerator()
        {
            _integers = new List<int>();
        }

        ~RandomNumberGenerator()
        {
            Cleanup();
        }

        public async Task RunAsync(string[] args)
        {
            if (!args.Any())
                return;

            var directory = args[0];
            _files = Directory.GetFiles(directory, "*.txt").ToArray();

            if (!File.Exists($"{directory}\\web.config"))
                return;

            _webConfigFound = true;

            await Task.WhenAll(_files.Select(ProcessFile));

            if (_largest is null || _average is 0)
                Console.WriteLine("No data found or an error occurred.");
            else
            {
                Console.WriteLine($"Largest integer: {_largest}");
                Console.WriteLine($"Average of all integers: {_average}");
            }
        }

        private static async Task ProcessFile(string filePath)
        {
            try
            {
                if (!Uri.IsWellFormedUriString(Path.GetDirectoryName(filePath), UriKind.Absolute))
                    throw new ArgumentException($"Invalid directory path: '{Path.GetDirectoryName(filePath)}'");

                using (var reader = new StreamReader(filePath))
                {
                    var lines = await reader.ReadLinesAsync();
                    foreach (var line in lines)
                    {
                        if (!int.TryParse(line, out int number))
                            continue;

                        lock (_integers)
                            _integers.Add(number);

                        if (number > _largest ?? int.MinValue)
                            _largest = number;

                        _average += number;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file: '{filePath}', Error: {ex.Message}");
            }
        }

        private static void Cleanup()
        {
            _files = null;
            _integers?.Clear();
            GC.SuppressFinalize(this);
        }
    }
}
```

