async function readDynamicFiles(directoryPath, callback, encoding = 'utf8') {
    try {
        const fs = require('fs');
        const { promisify } = require('util');
        const readdir = promisify(fs.readdir);
        const stat = promisify(fs.stat);
        const readFile = promisify(fs.readFile);

        let files = await readdir(directoryPath);

        for (let file of files) {
            const fullFilePath = `${directoryPath}/${file}`;
            const isDirectory = await stat(fullFilePath).then(stats => stats.isDirectory()).catch(() => false);

            if (!isDirectory) {
                let content = await readFile(fullFilePath, encoding);
                callback(content, fullFilePath);
            } else {
                await readDynamicFiles(fullFilePath, readDynamicFiles, encoding);
            }
        }
    } catch (err) {
        // Handle errors here, such as file not found or permission issues
        console.error(err);
    }
}
