import re
import json
import logging
from bs4 import BeautifulSoup as BS
import requests
from urllib.parse import urlparse
import lxml
from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache, wraps
from io import BytesIO

# Set up logging
logging.basicConfig(format='%(asctime)s - %(message)s', level=logging.INFO)

def extract_and_cache_elements(html_doc: str, tag: str, attribute: str, value: str) -> List[BS]:
    cache_key = f"{tag}_{attribute}_{value}"

    def cache_wrapper(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if cache_key not in CACHE or len(CACHE[cache_key]) >= 500:
                result = func(*args, **kwargs)
                CACHE[cache_key] = result
            else:
                result = CACHE[cache_key]
            logging.info(f"Cache hit or miss: {('hit' if cache_key in CACHE else 'miss')}")
            return result
        return wrapper

    @lru_cache(maxsize=500)
    def _extract_elements(html_doc):
        try:
            soup = BS(html_doc, "lxml")
            if attribute == "":
                raise ValueError("Attribute must not be empty.")

            if tag not in ["div", "span", "a", "img"]:
                raise ValueError(f"Invalid tag '{tag}'.")

            attr_values = re.findall(r'([^,]+)', attribute)
            elements = [element for element in soup.find_all(tag)]

            if not attr_values:
                return elements

            for value in attr_values:
                if not value:
                    continue

                for sub_element in elements:
                    if f'{attribute}="{value}"' not in str(sub_element):
                        elements.remove(sub_element)

            return [e for e in elements if len(e) > 0]

        except Exception as e:
            logging.error(f"Error extracting elements: {str(e)}")
            raise e

    CACHE = {}
    return cache_wrapper(_extract_elements)(html_doc)

def get_html_content(url):
    response = requests.get(url)
    if response.status_code != 200:
        raise Exception(f"Failed to load URL '{url}'.")
    return response.content.decode(response.apparent_encoding or "utf-8")

def main():
    url = "https://example.com"
    html_doc = get_html_content(url)

    tag = "div"
    attribute = 'class="example1, example2"'  # Multiple values separated by commas
    value = "example1"

    elements = extract_and_cache_elements(html_doc, tag, attribute, value)
    print(f"Found {len(elements)} elements matching '{tag}', '{attribute}', and '{value}'.")

if __name__ == "__main__":
    main()
```

