const cache = new Map(); // Cache for scripts
let loadingSpinner; // Loading spinner element

function renderFooterScripts(scripts) {
  const renderedScriptsHTML = [];

  function fetchScripts() {
    if (scripts.length === 0) return Promise.resolve(scripts);

    const scriptToFetch = scripts.find(script => !cache.has(script.src));

    if (!scriptToFetch) return Promise.resolve(scripts);

    return fetch(scriptToFetch.src)
      .then(response => {
        if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
        return response.text();
      })
      .then(code => {
        const script = Object.assign({ code, type: scriptToFetch.type || "text/javascript" }, scriptToFetch);
        cache.set(script.src, script);
        renderedScriptsHTML.push(renderScript(script));
        return fetchScripts(); // Recursively call to get the remaining scripts
      })
      .catch(error => {
        console.error(`Error while fetching script: ${error}`);
        // Handle the error and add an appropriate error message to the DOM
      });
  }

  function renderScript({ code, type }) {
    const scriptElement = document.createElement("script");
    scriptElement.innerHTML = code;
    scriptElement.type = type;
    return scriptElement.outerHTML;
  }

  loadingSpinner = document.createElement("div");
  loadingSpinner.textContent = "Loading scripts...";
  document.body.appendChild(loadingSpinner);

  fetchScripts()
    .then(() => {
      document.body.removeChild(loadingSpinner);
      // Render the script elements to the DOM and optimize as needed
    })
    .catch(error => {
      console.error(`Error while rendering scripts: ${error}`);
      // Handle the error and add an appropriate error message to the DOM
    });
}
