#include <atomic>
#include <memory>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <shared_mutex>
#include <functional>
#include <stdexcept>
#include <cassert>

class OctreeNode {
public:
    enum class NodeType { INTERNAL, LEAF };

    NodeType type;
    std::atomic<int> childCount = 0;
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::mutex nodeMutex;
    std::condition_variable cv;

    OctreeNode(NodeType t) : type(t) {}
};

class Octree {
public:
    using Data = std::shared_ptr<void>; // Replace with your specific data type

    Octree() : root_(std::make_unique<OctreeNode>(OctreeNode::NodeType::INTERNAL)) {}

    void insert(const Data& data, double x, double y, double z) {
        std::lock_guard<std::shared_mutex> lock(dataMut);
        insert_(root_.get(), data, x, y, z, 0);
    }

    void query(const std::function<void(const Data&)>& callback, double minX, double minY, double minZ, double maxX, double maxY, double maxZ) const {
        std::lock_guard<std::shared_mutex> lock(dataMut);
        query_(root_.get(), minX, minY, minZ, maxX, maxY, maxZ, callback);
    }

private:
    void insert_(OctreeNode* node, const Data& data, double x, double y, double z, int depth) {
        if (node->type == OctreeNode::NodeType::LEAF && depth < maxDepth) {
            if (++(node->childCount) >= leafCapacity_) {
                splitNode_(node);
            }
            node->children[depth] = std::make_unique<OctreeNode>(OctreeNode::NodeType::LEAF);
            node->children[depth]->data_ = data;
        } else {
            int index = findChildIndex(node, x, y, z);
            if (index != -1 && depth < maxDepth) {
                std::unique_lock<std::mutex> lock(node->nodeMutex);
                node->cv.wait(lock, [this, node]() { return node->children[index].get() != nullptr; });
                insert_(node->children[index].get(), data, x, y, z, depth + 1);
            }
        }
    }

    void query_(const OctreeNode* node, double minX, double minY, double minZ, double maxX, double maxY, double maxZ, const std::function<void(const Data&)>& callback) const {
        if (node->type == OctreeNode::NodeType::LEAF && isWithinBounds(node->data_->get<std::vector<double>>(), minX, minY, minZ, maxX, maxY, maxZ)) {
            callback(node->data_);
        } else if (node->type == OctreeNode::NodeType::INTERNAL) {
            for (const auto& child : node->children) {
                std::unique_lock<std::mutex> lock(child.get()->nodeMutex);
                if (child.get() != nullptr) {
                    query_(child.get(), minX, minY, minZ, maxX, maxY, maxZ, callback);
                }
            }
        }
    }

    int findChildIndex(const OctreeNode* node, double x, double y, double z) const {
        int index;
        if (x < (node->children[0].get()->data_->get<std::vector<double>>(1) / 2)) {
            if (y < (node->children[1].get()->data_->get<std::vector<double>>(3) / 2)) {
                if (z < (node->children[2].get()->data_->get<std::vector<double>>(5) / 2)) {
                    index = 0;
                } else if (z >= (node->children[3].get()->data_->get<std::vector<double>>(5))) {
                    index = 4;
                }
            } else if (y >= (node->children[1].get()->data_->get<std::vector<double>>(3))) {
                if (z < (node->children[2].get()->data_->get<std::vector<double>>(5) / 2)) {
                    index = 1;
                } else if (z >= (node->children[3].get()->data_->get<std::vector<double>>(5))) {
                    index = 5;
                }
            }
        } else if (x >= (node->children[0].get()->data_->get<std::vector<double>>(1))) {
            if (y < (node->children[1].get()->data_->get<std::vector<double>>(3) / 2)) {
                if (z < (node->children[2].get()->data_->get<std::vector<double>>(5) / 2)) {
                    index = 2;
                } else if (z >= (node->children[3].get()->data_->get<std::vector<double>>(5))) {
                    index = 6;
                }
            } else if (y >= (node->children[1].get()->data_->get<std::vector<double>>(3))) {
                if (z < (node->children[2].get()->data_->get<std::vector<double>>(5) / 2)) {
                    index = 3;
                } else if (z >= (node->children[3].get()->data_->get<std::vector<double>>(5))) {
                    index = 7;
                }
            }
        }
        return index == -1 ? -1 : static_cast<int>(node->children[index].get()->type);
    }

    bool isWithinBounds(const Data& data, double minX, double minY, double minZ, double maxX, double maxY, double maxZ) const {
        // Replace this with your specific data bounds check
        return true;
    }

    void splitNode_(OctreeNode* node) {
        auto newNodes = std::make_unique<std::vector<std::unique_ptr<OctreeNode>>>(8);
        for (int i = 0; i < 8; ++i) {
            newNodes[i] = std::make_unique<OctreeNode>(OctreeNode::NodeType::INTERNAL);
        }

        auto splitData = [this, node](double* data, int start, int end, double splitValue, int& childIndex) {
            for (int i = start; i < end; ++i) {
                if (data[i] < splitValue) {
                    newNodes[childIndex]->children[0] = std::move(node->children[i]);
                    ++childIndex;
                } else {
                    newNodes[childIndex + 8]->children[7 - (i - start)] = std::move(node->children[i]);
                }
            }
        };

        splitData(&node->data_->get<std::vector<double>>(), 0, node->data_->get<std::vector<double>>().size(), node->data_->get<std::vector<double>>(1) / 2, 0);
        splitData(&node->data_->get<std::vector<double>>(), 0, node->data_->get<std::vector<double>>().size(), node->data_->get<std::vector<double>>(3) / 2, 4);
        splitData(&node->data_->get<std::vector<double>>(), 0, node->data_->get<std::vector<double>>().size(), node->data_->get<std::vector<double>>(5) / 2, 2);

        std::lock_guard<std::mutex> lock(nodeMutex);
        for (int i = 0; i < newNodes->size(); ++i) {
            if (!newNodes->at(i).get()) {
                continue;
            }
            node->children[i] = std::move(newNodes->at(i));
            newNodes->at(i)->type = OctreeNode::NodeType::INTERNAL;
        }
        node->childCount.store(0);
    }

    mutable std::shared_mutex dataMut;
    std::unique_ptr<OctreeNode> root_;
    static constexpr int maxDepth_ = 25; // Adjust as necessary
    static constexpr int leafCapacity_ = 32; // Adjust as necessary
};
