class ClinicManager {
    private $registry = [];
    private $cache = [];
    private $db; // Database connection object (abstracted)
    private $logger; // Logging service instance
    private $rateLimiter; // Rate limiter instance
    private $monitoringSystem; // Real-time monitoring system instance

    public function __construct(DatabaseConnection $db, LoggerInterface $logger, RateLimiter $rateLimiter, MonitoringSystem $monitoringSystem) {
        $this->db = $db;
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
        $this->monitoringSystem = $monitoringSystem;
    }

    public function addFactoryFunction(string $id, callable $factory) {
        $this->registry[$id] = $factory;
    }

    public function getClinicByID($id) {
        if (isset($this->cache[$id])) {
            return $this->cache[$id];
        }

        $clinic = $this->db->getClinicByID($id);
        if ($clinic) {
            $this->cache[$id] = $clinic;
        }

        return $clinic;
    }

    public function updateClinicStatus(int $id, array $data) {
        $this->rateLimiter->check($id);

        if (!$this->isValidID($id)) {
            throw new InvalidArgumentException('Invalid clinic ID.');
        }

        try {
            $this->db->beginTransaction();

            // Handle partial updates based on the provided data keys (e.g., status)
            $clinic = $this->getClinicByID($id);
            if ($clinic) {
                foreach ($data as $key => $value) {
                    switch ($key) {
                        case 'status':
                            $clinic[$key] = $value;
                            break;
                        default:
                            continue 2; // Skip the rest of the loop if an invalid key is provided
                    }
                }
            }

            $this->db->updateClinic($id, $clinic);
            $this->logger->log($this->getLogMessage('clinic_status_updated', ['id' => $id, 'ip' => $_SERVER['REMOTE_ADDR'], 'timestamp' => time()]), true);
            $this->cache[$id] = $this->db->getClinicByID($id);

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollback();
            throw $e;
        }
    }

    // Add other methods for JSON serialization, new clinic creation, notifications, error handling, internationalization, performance optimization, database switching, and real-time monitoring as required

    private function isValidID(int $id) {
        return is_int($id) && $id > 0;
    }

    private function getLogMessage($key, array $context = []) {
        // Implement multi-language logging based on the logging service interface
        return $this->logger->getMessage($key, $context);
    }
}
