      const params: S3.Types.PutObjectRequest = {
        Bucket: 'my-bucket',
        Key: `${userId}/${file.name}`,
        Body: file,
        ContentType: contentType,
        ACL: 'public-read'
      };

      for (let i = 0; i < MAX_UPLOAD_RETRIES; i++) {
        try {
          await s3.putObject(params).promise();
          break;
        } catch (error) {
          console.error(`Upload retry #${i + 1}: ${error.message}`);
          if (i === MAX_UPLOAD_RETRIES - 1) {
            throw error;
          }
        }
      }
    }

    const publicUrl = `https://s3.us-west-2.amazonaws.com/${params.Bucket}/${params.Key}`;
    console.log(`File uploaded successfully: ${publicUrl}`);
    return publicUrl;
  } catch (error) {
    console.error('Error uploading file:', error.message);
    throw error;
  }
}
