namespace YourNamespace
{
    public class SqlQueryRunner
    {
        private readonly string _connectionString;
        private readonly int _maxBatchSize;
        private readonly TimeSpan _retryTimeout;
        private readonly int _cacheDurationInMinutes;

        public SqlQueryRunner(string connectionString, int maxBatchSize = 100, TimeSpan retryTimeout = TimeSpan.FromSeconds(5), int cacheDurationInMinutes = 5)
        {
            _connectionString = connectionString;
            _maxBatchSize = maxBatchSize;
            _retryTimeout = retryTimeout;
            _cacheDurationInMinutes = cacheDurationInMinutes;
        }

        public async Task<IDataReader> ExecuteDynamicQueryAsync(string commandTemplate, List<object> parameters, Func<IDataReader, object> cacheKeySelector)
        {
            var cachedResult = await GetFromCache(cacheKeySelector(await this.ExecuteDynamicQueryInternalAsync(commandTemplate, parameters)));
            if (cachedResult != null)
                return cachedResult;

            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                var command = BuildCommand(commandTemplate, parameters);
                var transaction = connection.BeginTransaction();
                var reader = await ExecuteBatchInternalAsync(command, transaction);

                transaction.Commit();
                await AddToCache(cacheKeySelector(reader), reader, _cacheDurationInMinutes);
                return reader;
            }
        }

        private SqlCommand BuildCommand(string commandTemplate, List<object> parameters)
        {
            var command = new SqlCommand(commandTemplate, new SqlConnection(_connectionString))
            {
                CommandType = CommandType.Text
            };

            for (int i = 0; i < parameters.Count; i++)
            {
                command.Parameters.Add($"@param{i}", parameters[i]);
            }

            return command;
        }

        private async Task<IDataReader> ExecuteBatchInternalAsync(SqlCommand command, SqlTransaction transaction)
        {
            var allResults = new List<IDataReader>();

            int currentBatchSize = 0;
            while (true)
            {
                try
                {
                    if (currentBatchSize >= _maxBatchSize)
                    {
                        await transaction.CommitAsync();
                        transaction = null;
                        command.Transaction = connection.BeginTransaction();
                    }

                    var reader = await command.ExecuteReaderAsync(transaction: transaction);

                    allResults.Add(reader);
                    currentBatchSize++;

                    if (!reader.Read())
                        break;
                }
                catch (Exception ex)
                {
                    if (_retryTimeout > TimeSpan.Zero && DateTime.Now < DateTime.Now.Add(_retryTimeout))
                    {
                        await Task.Delay(TimeSpan.FromSeconds(5));
                        continue;
                    }
                    throw;
                }
            }

            if (transaction != null)
                await transaction.CommitAsync();

            return allResults[0];
        }

