#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <signal.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>

#define MAX_CMDS 10
#define TIMEOUT 5 // seconds

pid_t background_processes[MAX_CMDS];
int num_running = 0;
int log_fd;

void log_command(const char *cmd, int status) {
    char timestr[20];
    time_t now = time(NULL);
    strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", localtime(&now));
    dprintf(log_fd, "[%s] Command '%s' %s\n", timestr, cmd, (status == 0) ? "failed" : "success");
}

void terminate_processes() {
    for (int i = 0; i < num_running; ++i) {
        kill(background_processes[i], SIGTERM);
    }
}

int executeBackgroundCommand(const char *command, const char **args) {
    pid_t child_pid = fork();

    if (child_pid == 0) {
        // Child process
        char *envp[] = {getenv("environ"), NULL};
        char timeout_env[32];
        snprintf(timeout_env, sizeof(timeout_env), "TIMEOUT=%d", TIMEOUT);
        envp = realloc(envp, sizeof(char *) * (1 + arraySize(envp) + 1));
        envp[arraySize(envp)] = timeout_env;

        char *cmdline = concatStrings(command, " &&", args != NULL ? args[0] : NULL);
        execv("/bin/bash", (char*[]) { "/bin/bash", "-c", cmdline, NULL });
        free(cmdline);
        exit(EXIT_FAILURE);
    } else if (child_pid > 0) {
        // Parent process
        background_processes[num_running++] = child_pid;
        if (num_running >= MAX_CMDS) wait(&status);
    }

    int ret = (child_pid != -1);
    if (ret && num_running < MAX_CMDS) log_command(command, 1);

    return ret;
}

// Helper functions for string manipulation and array management
void* realloc(void *ptr, size_t size);
int arraySize(const char **array);
char* concatStrings(const char *str1, const char *str2, ...);

int main() {
    log_fd = open("commands.log", O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    const char *commands[] = { "command1 arg1 arg2", "command2 arg3" };
    for (int i = 0; i < arraySize(commands); ++i) {
        if (!executeBackgroundCommand(commands[i], (const char*[]) { commands[i], NULL })) return EXIT_FAILURE;
    }

    // Wait for all background processes to finish
    for (int i = 0; i < num_running; ++i) {
        int status;
        wait(&status);
        log_command(background_processes[i] ? commandForPid(background_processes[i]) : "(unknown)", WIFEXITED(status) ? WEXITSTATUS(status) : (WIFSIGNALED(status) ? "signal" : "(unknown)"));
    }

    // Cleanup and exit
    terminate_processes();
    close(log_fd);
    return EXIT_SUCCESS;
}
```

