using System.Linq;

public class XmlParser
{
    private readonly IMemoryCache _cache;
    private readonly IConfiguration _configuration;
    private readonly Logger _logger;
    private readonly XDocumentSchemaValidator _schemaValidator;

    public XmlParser(IMemoryCache cache, IConfiguration configuration, Logger logger, XDocumentSchemaValidator schemaValidator)
    {
        _cache = cache;
        _configuration = configuration;
        _logger = logger;
        _schemaValidator = schemaValidator;
    }

    public async Task<XElement> GetFirstElementAsync(string xpathQuery)
    {
        if (!IsValidXPathQuery(xpathQuery))
            throw new ArgumentException("Invalid XPath query");

        var cacheKey = GetCacheKey(xpathQuery);
        var cachedResult = _cache.Get(cacheKey);

        if (cachedResult != null)
            return (XElement)cachedResult;

        var xmlContentTask = FetchXmlAsync(_configuration["ApiBaseUrl"] + _configuration["XmlDocumentEndpoint"], xpathQuery);

        var xmlContent = await xmlContentTask;

        var xml = XDocument.Load(new StringReader(xmlContent));

        if (!_schemaValidator.Validate(xml))
            throw new Exception("XML document does not conform to the schema");

        var result = xml.XPathSelectElement(xpathQuery);

        if (result == null)
            throw new Exception("No element found with given name");

        if (_cache.GetCount() > _configuration.GetValue<int>("CacheSize"))
            _cache.Remove(_cache.CreateDelegateHandle());

        _cache.Set(cacheKey, result, new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromMinutes(10)));

        _logger.Info($"Query execution time: {DateTime.Now - queryStartTime.Value:0.000} ms");
        _logger.Info($"Cache hits: {_cache.GetCacheHitRatio().ToString("P", CultureInfo.InvariantCulture)}");

        return result;
    }

    private bool IsValidXPathQuery(string xpathQuery)
    {
        // Implement a parser that generates a syntax tree from valid XPath queries to enable better validation and suggestions
        // ...
    }

    private string GetCacheKey(string xpathQuery)
    {
        return $"{xpathQuery}_cache";
    }

    private async Task<string> FetchXmlAsync(string url, string xpathQuery)
    {
        var request = (HttpWebRequest)WebRequest.Create(url);

        var retryCount = _configuration.GetValue<int>("RetryCount");
        var retryInterval = _configuration.GetValue<int>("RetryInterval");

        for (var i = 0; i < retryCount; i++)
        {
            try
            {
                using var response = await request.GetResponseAsync();
                using var streamReader = new StreamReader(response.GetResponseStream());
                return await streamReader.ReadToEndAsync();
            }
            catch (WebException ex) when (i < retryCount - 1)
            {
                _logger.Error($"Failed to fetch XML document: {ex.Message}");
                await Task.Delay(TimeSpan.FromSeconds(retryInterval));
            }
        }

        throw new Exception("Failed to fetch XML document after retries");
    }
}
