from functools import lru_cache
import redis

class JWTValidator:
    def __init__(self, token_service_url, user_db):
        self.token_service_url = token_service_url
        self.user_db = user_db
        self.redis_client = redis.Redis(host='localhost', port=6379)
        self.cache_timeout = 60 * 5  # 5 minutes cache timeout

    @lru_cache(maxsize=128, typed=True)
    def _validate_token(self, token):
        response = requests.post(f'{self.token_service_url}/validate', json={'jwt': token})
        if response.status_code == 200:
            return response.json()['valid']
        return False

    def validate(self, jwt_str):
        try:
            data = json.loads(jwt_str)
        except ValueError as e:
            return False, f"Invalid JSON format: {e}"

        required_fields = ['sub', 'exp', 'iat', 'aud', 'scope']
        if not all(field in data for field in required_fields):
            return False, "Missing required fields"

        user_id = data['sub']
        if not self.user_exists(user_id):
            return False, f"User ID {user_id} does not exist"

        token_valid = self._validate_token(jwt_str)
        if not token_valid:
            if data['exp'] <= int(time.time()):
                return False, "Token is expired"
            else:
                return False, "Invalid JWT"

        # Handle additional validation for admin tokens here

        self.cache_token(jwt_str)
        return True, ""

    def user_exists(self, user_id):
        # Query the user database and return True if the user exists, False otherwise
        pass

    def cache_token(self, jwt_str):
        self.redis_client.setex(jwt_str, self.cache_timeout, "valid")
