using System;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Text;

public class SqlCommandGenerator
{
    public SqlCommandGenerator(string connectionString, string command)
    {
        Command = command;
        Connection = new SqlConnection(connectionString);
    }

    public void Execute(IList<object> parameters)
    {
        using (var cmd = new SqlCommand(CreateParameterizedCommand(parameters), Connection))
        {
            Connection.Open();
            cmd.ExecuteNonQuery();
        }
    }

    private string CreateParameterizedCommand(IList<object> parameters)
    {
        var commandText = Command;
        var parameterIndex = 0;

        foreach (var param in parameters)
        {
            if (param is DBNull) continue; // Skip null values

            if (parameterIndex > 0) commandText += ", ";
            commandText += $"@{parameterIndex}";
            parameterIndex++;
        }

        return commandText;
    }

    public SqlConnection Connection { get; set; }
    public string Command { get; }
}
