class ThreadFactoryNamed implements ThreadFactory {
    private final String name;

    public ThreadFactoryNamed(String name) {
        this.name = name;
    }

    @Override
    public Thread newThread(Runnable r) {
        Thread thread = Executors.defaultThreadFactory().newThread(r);
        thread.setName(name + "-" + thread.getId());
        return thread;
    }
}

class RejectedExecutionHandlerNamed implements RejectedExecutionHandler {
    private final String name;

    public RejectedExecutionHandlerNamed(String name) {
        this.name = name;
    }

    @Override
    public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
        LOGGER.error("{} rejected execution: {}", name, r.toString());
    }
}
