2. JavaScript FindElementsBySelector:

```javascript
function findElementsBySelector(node, selector, callback) {
    let stack = [node];
    const visited = new Set();

    function traverse(currentNode) {
        if (currentNode && !visited.has(currentNode)) {
            visited.add(currentNode);

            if (callback(currentNode, selector)) {
                return [currentNode];
            }

            const nodeList = currentNode.querySelectorAll(selector);

            for (let i = 0; i < nodeList.length; ++i) {
                const element = nodeList[i];
                stack.push(element);
                traverse(element);
            }
        }

        return [];
    }

    let results = [];
    for (let i = 0; i < stack.length; ++i) {
        const tempResults = traverse(stack[i]);
        results = results.concat(tempResults);
    }

    return results;
}
```

