class MyForwardList {
public:
    // Constructor, destructor, and other necessary member functions

    void insertAfterNode(const T& newValue, const T& nodeValue) {
        pthread_mutex_lock(&mutex); // Lock to protect the list from concurrent modifications

        auto it = std::find_if(begin(), end(), [nodeValue](T value) { return value == nodeValue; });

        if (it == end()) {
            // Node not found, insert at the end of the list
            forwardList.emplace_back(newValue);
            LoggingFramework::logInfo("Inserted new node at the end of the list.");
        } else {
            // Node found, insert after the specified node
            forwardList.insert(it, newValue);
            LoggingFramework::logInfo("Inserted new node after the specified node.");
        }

        // Persist changes to the database
        try {
            DatabaseAPI::beginTransaction();
            for (auto& node : forwardList) {
                DatabaseAPI::persistNode(node);
            }
            DatabaseAPI::commitTransaction();
        } catch (const std::exception& e) {
            DatabaseAPI::rollbackTransaction();
            LoggingFramework::logError("Failed to persist changes in the database: " + std::string(e.what()));
        }

        pthread_mutex_unlock(&mutex); // Unlock the list for other threads
    }

private:
    std::forward_list<T> forwardList;
    TERM_LOCK mutex; // Replace TERM_LOCK with your chosen lock type
};
```

