<?php
class UserAuthentication {
    private $database;
    private $emailService;
    private $cache;

    public function __construct(Database $database, EmailService $emailService) {
        $this->database = $database;
        $this->emailService = $emailService;
        $this->cache = new Cache();
    }

    public function authenticateUser($username, $password) {
        try {
            $salt = $this->retrieveSalt($username);
            $storedPassword = $this->hashPassword($salt, $password);

            if (!$this->database->userExistsWithPassword($username, $storedPassword)) {
                throw new UserNotFoundException("Username not found or password is incorrect");
            }
        } catch (UserNotFoundException $e) {
            return $e->getMessage();
        }
    }

    public function changeUserPassword($username, $newPassword) {
        try {
            $salt = $this->generateSalt();
            $hashedNewPassword = $this->hashPassword($salt, $newPassword);

            $this->database->updateUserPasswordAndSalt($username, $hashedNewPassword, $salt);
        } catch (Exception $e) {
            // Handle potential race conditions here, e.g., by implementing optimistic locking or version control
        }
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return "Invalid email address";
        }

        $user = $this->database->getUserByEmail($email);

        if (!$user) {
            return "User not found";
        }

        $token = bin2hex(random_bytes(32));
        $expirationTime = time() + 60 * 60; // Token expires in an hour
        $this->database->storePasswordResetToken($user['id'], $token, $expirationTime);

        $this->emailService->sendPasswordResetEmail($email, $token);
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        try {
            $data = $this->database->getPasswordResetToken($token);

            if (!$data || time() > $data['expiration_time']) {
                throw new Exception("Invalid or expired token");
            }

            $user = $this->database->getUserById($data['user_id']);
            $salt = $this->cache->getSalt($user['username']);

            if (!$salt) {
                $salt = $this->generateSalt();
                $this->cache->storeSalt($user['username'], $salt);
            }

            $hashedNewPassword = $this->hashPassword($salt, $newPassword);
            $this->database->updateUserPasswordAndSalt($user['username'], $hashedNewPassword, $salt);
        } catch (Exception $e) {
            // Handle cases where the token is invalid or has expired
        }
    }

    public function retrieveSalt($username) {
        return $this->cache->getSalt($username);
    }

    private function hashPassword($salt, $password) {
        return password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    private function generateSalt() {
        return bin2hex(random_bytes(16));
    }
}
```

