const path = require('path');
const fs = require('fs');
const { default: Mocha } = require('mocha');
const blueslip = require('blueslip'); // Assuming you have installed the mocking library

class TestRunner {
  constructor(moduleLabel, testSuite) {
    this.moduleLabel = moduleLabel;
    this.testSuite = testSuite;
  }

  async run() {
    try {
      const modulePath = path.resolve(__dirname, '..', 'modules', this.moduleLabel);
      const module = require(modulePath);

      // Initialize and clean up blueslip before and after each test
      const suite = new Mocha.Suite();
      this.testSuite.forEach(({ label, testFunction }) => {
        const test = new Mocha.Test(label);
        test.timeout(5000); // Set a reasonable timeout for tests
        blueslip.mock.reset();
        test.setup(() => {
          blueslip.mock.init();
        });
        test.teardown(() => {
          blueslip.mock.cleanUp();
        });
        test.timeout(5000); // Set a reasonable timeout for setup and teardown
        suite.addTest(test);
        testFunction(label, (...args) => new Promise((resolve, reject) => {
          try {
            testFunction(...args).then(resolve).catch(reject);
          } catch (error) {
            console.error(`[Error] Test "${label}" failed:`, error);
            reject(error);
          }
        }));
      });

      // Run the tests with Mocha and log information to the console
      const options = {
        ui: 'tdd',
        reporter: 'spec'
      };
      Mocha.run(suite, options).then((failures) => {
        if (failures > 0) {
          console.log(`[FAIL] ${this.moduleLabel}: ${failures} tests failed`);
        } else {
          console.log(`[PASS] ${this.moduleLabel}: All tests passed`);
        }
      }).catch((error) => {
        console.error('Test runner encountered an error:', error);
      });
    } catch (error) {
      console.error('An error occurred while loading the module:', error);
    }
  }
}
```

