```javascript
function FindElementsBySelector(node, selector, callback) {
    const queue = [node];
    const visited = new Set();
    let result = [];

    function traverse(currentNode) {
        if (currentNode === null || visited.has(currentNode)) return;

        visited.add(currentNode);
        const isMatch = callback(currentNode);

        if (isMatch) result.push(currentNode);

        Array.from(currentNode.querySelectorAll('*')).forEach((child) => {
            traverse(child);
        });
    }

    while (queue.length > 0) {
        const currentNode = queue.shift();
        traverse(currentNode);

        Array.from(currentNode.children).forEach((child) => {
            if (!visited.has(child)) queue.push(child);
        });
    }

    return result;
}
```

