```php
<?php
class UserAuthentication {
    private $rateLimit;
    private $db; // Simulated database connection
    private $cache; // Simulated cache connection

    public function __construct() {
        $this->rateLimit = new RateLimiter();
        $this->db = new DatabaseConnection();
        $this->cache = new CacheConnection();
    }

    public function authenticateUser($username, $password) {
        try {
            $salt = $this->retrieveSalt($username);
            $hash = bcrypt($password . $salt);

            if (!$user = $this->db->getUserByUsername($username)) {
                throw new UserNotFoundException();
            }

            if ($user['hashed_password'] !== $hash) {
                throw new InvalidCredentialsException('Incorrect password');
            }

            $this->rateLimit->reset($username);
            return $user;
        } catch (RateLimitExceededException $e) {
            throw new TooManyAttemptsException();
        }
    }

    public function changeUserPassword($username, $newPassword) {
        // Implement pessimistic locking here
        $this->db->lockRecord($username);

        try {
            $salt = base64_encode(random_bytes(16));
            $hashedPassword = bcrypt($newPassword . $salt);

            $this->db->updateUserPasswordByUsername($username, $hashedPassword, $salt);

        } catch (DBException $e) {
            // Handle exceptions here
        } finally {
            $this->db->unlockRecord($username);
        }
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new InvalidEmailException();
        }

        if (!$user = $this->db->getUserByEmail($email)) {
            throw new UserNotFoundException('No user found with that email address');
        }

        // Implement CAPTCHA verification and token generation here
        $token = bin2hex(random_bytes(32));
        $this->db->storeResetToken($user['id'], $token, time() + 60 * 60 * 5);

        // Send password reset email here
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        if (!$resetToken = $this->db->getResetTokenByToken($token)) {
            throw new InvalidTokenException();
        }

        if (time() > $resetToken['expires_at']) {
            throw new TokenExpiredException();
        }

        // Implement optimistic locking here
        $this->db->lockRecordByResetToken($token);

        try {
            $user = $this->db->getUserByResetToken($token);
            $salt = base64_encode(random_bytes(16));
            $hashedPassword = bcrypt($newPassword . $salt);

            $this->db->updateUserPasswordByUsername($user['username'], $hashedPassword, $salt);

        } catch (DBException $e) {
            // Handle exceptions here
        } finally {
            $this->db->unlockRecordByResetToken($token);
            $this->db->deleteResetTokenByToken($token);
        }
    }

    public function retrieveSalt($username) {
        if (!$salt = $this->cache->get('user_' . $username . '_salt')) {
            $salt = $this->db->getUserSaltByUsername($username);
            $this->cache->set('user_' . $username . '_salt', $salt, 60 * 60 * 24); // Cache for a day
        }

        return $salt;
    }
}

class RateLimiter {
    private $limits = [];

    public function __construct() {}

    public function allow($username) {
        if (!isset($this->limits[$username])) {
            $this->limits[$username] = 3;
        }

        return --$this->limits[$username] >= 0;
    }

    public function reset($username) {
        unset($this->limits[$username]);
    }
}
```

