            var provider = _configuration["DatabaseProvider"];
            var connectionString = _configuration[provider + ":ConnectionString"];

            for (int i = 0; i < maxPoolSize; i++)
            {
                _connectionPool.Enqueue(CreateConnection(connectionString, seedValue));
            }

            SaveConnectionPoolToRedis();
        }

        private void RestoreConnectionPool(IDatabase redisDatabase)
        {
            var connectionStrings = new List<string>();

            for (int i = 0; i < maxPoolSize; i++)
            {
                connectionStrings.AddRange(redisDatabase.ListRangeByIndex("connectionPool", i, -1));
            }

            _connectionPool = new ConnectionPool(connectionStrings);
        }

        private void SaveConnectionPoolToRedis()
        {
            var connectionStrings = _connectionPool.Select(conn => conn.ConnectionString).ToList();

            _redisDatabase.KeyDelete("connectionPool");
            for (int i = 0; i < connectionStrings.Count; i++)
                _redisDatabase.ListRightPush("connectionPool", connectionStrings[i]);
