#include <filesystem>
#include <boost/log/trivial.hpp> // Include your logging library here

namespace fs = std::filesystem;
using FileData = std::vector<int>;
using FileMap = std::map<fs::path, FileData>;

// Function to process a single file and update shared variables
void processFile(const fs::path& path, FileMap& files, std::mutex& mtx) {
    std::ifstream inputFile(path);
    if (!inputFile.is_open()) {
        BOOST_LOG_TRIVIAL(error) << "Failed to open file: " << path;
        return;
    }

    FileData data;
    int num;
    while (inputFile >> num) {
        data.push_back(num);
    }

    std::unique_lock<std::mutex> lock(mtx);
    files[path] = data;
    lock.unlock();
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: ./program input_directory output_file" << std::endl;
        return 1;
    }

    const fs::path inputDir(argv[1]);
    const fs::path outFilePath(argv[2]);

    if (!fs::exists(inputDir) || !fs::is_directory(inputDir)) {
        BOOST_LOG_TRIVIAL(error) << "Input directory does not exist or is not a directory.";
        return 1;
    }

    FileMap files;
    std::mutex mtx;
    std::vector<std::thread> threads;

    for (const auto& entry : fs::recursive_directory_iterator(inputDir)) {
        if (fs::is_regular_file(entry) && entry.path().extension() == ".txt") { // Process only .txt files
            threads.emplace_back(processFile, entry.path(), std::ref(files), std::ref(mtx));
        }
    }

    for (auto& t : threads) {
        t.join();
    }

    int max = *std::max_element(std::begin(files.begin()->second), std::end(files.begin()->second));
    double sum = 0;
    for (const auto& pair : files) {
        sum += std::accumulate(pair.second.cbegin(), pair.second.cend(), 0);
    }

    double avg = sum / files.size();

    std::ofstream outputFile(outFilePath);
    if (outputFile.is_open()) {
        outputFile << "Largest integer: " << max << std::endl;
        outputFile << "Average of all integers: " << avg << std::endl;
        outputFile.close();
    } else {
        BOOST_LOG_TRIVIAL(error) << "Failed to open output file.";
        return 1;
    }

    return 0;
}
```
