namespace YourNamespace
{
    public class Decryptor
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly ICloudSemaphoreManager _cloudSemaphoreManager;
        private readonly ICipherKey _cipherKey;
        private readonly byte[] _iv;
        private readonly string _paddingScheme;

        public Decryptor(ICloudSemaphoreManager cloudSemaphoreManager, ICipherKey cipherKey, byte[] iv, string paddingScheme)
        {
            _cloudSemaphoreManager = cloudSemaphoreManager;
            _cipherKey = cipherKey;
            _iv = iv;
            _paddingScheme = paddingScheme;
            _semaphore = new SemaphoreSlim(1, int.MaxValue); // Unlimited permits in the pool for simplicity, but this can be adjusted based on your requirements.
        }

        public async Task<string> DecryptAsync(byte[] ciphertext)
        {
            await _semaphore.WaitAsync();
            try
            {
                using var aes = Aes.Create();
                aes.Key = _cipherKey.GetBytes();
                aes.IV = _iv;

                using var msDecrypt = new MemoryStream(ciphertext);
                using var csDecrypt = new CryptoStream(msDecrypt, aes.CreateDecryptor(), CryptoStreamMode.Read);
                using var reader = new StreamReader(csDecrypt);
                var plainText = await reader.ReadToEndAsync();

                if (_paddingScheme == "PKCS7")
                    plainText = DecodePadding(plainText, "PKCS7");

                return plainText;
            }
            catch (Exception ex)
            {
                throw new ApplicationException($"Failed to decrypt ciphertext: {ex.Message}", ex);
            }
            finally
            {
                _semaphore.Release();
            }
        }

        private byte[] DecodePadding(byte[] data, string paddingScheme)
        {
            int count = paddingScheme switch
            {
                "PKCS7" => data[^1],
                // Add support for other padding schemes here if needed.
                _ => throw new ArgumentOutOfRangeException(nameof(paddingScheme), paddingScheme, null)
            };

            var result = new byte[data.Length - count];
            Buffer.BlockCopy(data, 0, result, 0, data.Length - count);
