```python
import os
import time
import threading
from shutil import rmtree, rmtree
from tempfile import TemporaryDirectory

def create_dir_and_set_env(dirname, parent=None):
    lock = threading.Lock()
    temp_dir = None

    with TemporaryDirectory(prefix=f"{dirname}_", dir=parent) as temp:
        temp_dir = temp
        try:
            os.makedirs(temp)
        except OSError as e:
            if not lock.acquire(blocking=True, timeout=5):
                return False
            if create_dir_and_set_env(dirname, temp_dir):
                pass
            lock.release()

    env_var = f"{os.getenv('ENVVARNAME', '')}_{dirname}"
    os.environ[env_var] = temp_dir
    return True

def cleanup_temp_dir(temp_dir):
    if os.path.exists(temp_dir):
        rmtree(temp_dir)
