#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <hash_map.h> // Custom data structure for caching mechanism
#include "comparison.h" // Customizable comparison functions

// Define a struct for FSA node
struct FSA_node {
    int state;
    char* tag;
    HashMap_t* attributes; // Custom hash map data structure for storing additional metadata
    struct FSA_node* children[26]; // 26 children for simplicity, can be extended as needed
};

// Define a struct for the traversal context
struct Traversal_context {
    int* states;
    int num_states;
    struct FSA_node* current_fsa;
    struct FSA_node* result_list; // Dynamically allocated memory to store the resulting state list
    int last_state;
    sem_t mem_lock; // Semaphore for managing memory allocation and deallocation
};

// Recursively traverse the DOM tree represented as an FSA
void traverse(struct Traversal_context* context, const char* selector) {
    if (context->current_fsa == NULL) return;

    // Test the current node against the selector using a custom comparison function
    bool match = compare_element(context->current_fsa, selector);
    if (match) {
        // Store the current state in the resulting state list
        context->result_list = realloc(context->result_list, sizeof(struct FSA_node)*(context->last_state + 2));
        context->result_list[context->last_state] = context->current_fsa;
        context->last_state++;
    }

    // Cache the result for future queries using a hash map
    cache_result(selector, context->current_fsa->state);

    // Recursively traverse children nodes
    for (int i = 0; i < 26; ++i) {
        sem_wait(&context->mem_lock);
        struct FSA_node* child = malloc(sizeof(struct FSA_node));
        if (!child) {
            sem_post(&context->mem_lock);
            return;
        }
        memcpy(child, context->current_fsa->children[i], sizeof(struct FSA_node));
        child->state = -1; // Unvisited state
        sem_post(&context->mem_lock);

        if (child->children[0]) {
            struct Traversal_context* sub_context = malloc(sizeof(struct Traversal_context));
            if (!sub_context) {
                free(child);
                continue;
            }
            memcpy(sub_context, context, sizeof(struct Traversal_context));
            sub_context->current_fsa = child->children[0];
            traverse(sub_context, selector);
        }
        if (child->children[1]) {
            struct Traversal_context* sub_context = malloc(sizeof(struct Traversal_context));
            if (!sub_context) {
                free(child);
                continue;
            }
            memcpy(sub_context, context, sizeof(struct Traversal_context));
            sub_context->current_fsa = child->children[1];
            traverse(sub_context, selector);
        }
        free(sub_context); // Free the memory allocated for the sub-context
    }
}

// Function to return a list of states that match a given selector in the DOM tree represented as an FSA
struct FSA_node** find_elements_by_selector(int* states, int num_states, struct FSA_node* root_fsa, const char* selector) {
    // Allocate memory for the traversal context and initialize it
    struct Traversal_context context = { .states = states, .num_states = num_states, .current_fsa = root_fsa };
    sem_init(&context.mem_lock, 0, 1); // Initialize the memory lock semaphore

    // Start the traversal process asynchronously using a separate thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, &traverse, &context) != 0) return NULL;

    // Wait for the traversal to finish and store the resulting state list
    struct FSA_node** result = malloc(sizeof(struct FSA_node*) * context.last_state);
    if (!result) {
        pthread_cancel(thread); // Cancel the traversal if there is insufficient memory
        return NULL;
    }
    memcpy(result, context.result_list, sizeof(struct FSA_node*) * context.last_state);

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    if (context.result_list) context.result_list->next = result;

    // Join the traversal thread and deallocate memory
    pthread_join(thread, NULL);
    free(context.result_list);
    sem_destroy(&context.mem_lock);

    return result;
}
