```python
import os
import json
import asyncio
import aiofiles
import hashlib
from typing import List, Dict, Union, Any

class Registry:
    def __init__(self):
        self.factories = {}

    async def register(self, id: str, factory):
        self.factories[id] = factory

    async def create(self, id: str, **kwargs) -> Any:
        factory = self.factories.get(id)
        if factory is None:
            raise KeyError(f"Factory with ID '{id}' not found.")
        return factory(**kwargs)

class JSONRegistry(Registrable):
    def __init__(self):
        super().__init__()
        self.objects = {}

    async def from_json(self, data: str) -> "JSONRegistry":
        obj = json.loads(data)
        if isinstance(obj, list):
            for item in obj:
                id = item.get("id")
                if id is None:
                    raise ValueError("All items in a list should have an 'id' field.")
                self.objects[id] = await self.create(id, **item)
        else:
            id = obj.get("id")
            if id is None:
                raise ValueError("Objects should have an 'id' field.")
            self.objects[id] = await self.create(id, **obj)
        return self

    async def from_file(self, filepath: str):
        async with aiofiles.open(filepath, "r") as f:
            data = await f.read()
        return await self.from_json(data)

class Registrable:
    def to_json(self) -> str:
        raise NotImplementedError("Subclasses must implement this method.")

    @staticmethod
    async def from_json(data: Union[str, Dict[str, Any]]) -> "Registrable":
        if isinstance(data, str):
            return json.loads(data)
        return Registrable(**data)

class ForwardList(Registrable):
    def __init__(self, data: Union[str, Dict[str, Any]] = None):
        super().__init__()
        if data is not None:
            self.items = self.from_json(data)
        else:
            self.items = []

    def to_json(self) -> str:
        return json.dumps(list(map(lambda x: x.to_json(), self.items)), indent=2)

    async def insert(self, search_str: str, new_str: str, position: int = -1):
        if position < 0:
            if search_str not in self.items:
                raise ValueError(f"'{search_str}' not found in the list.")
            self.items.insert(self.items.index(search_str), new_str)
        else:
            if position >= len(self.items) or search_str not in self.items[position:]:
                raise ValueError(f"'{search_str}' not found at position {position}.")
            self.items.insert(position + 1, new_str)

async def load_files(registry: Registry, filepaths: List[str]):
    tasks = [registry.register(*path) for path in filepaths]
    await asyncio.gather(*tasks)

async def main(filepaths: List[str], json_data: Union[str, Dict[str, Any]], forward_list_path: str = None):
    registry = Registry()
    loaded_files = []

    if isinstance(json_data, str):
        json_obj = await JSONRegistry.from_json(json_data)
    else:
        json_obj = JSONRegistry(**json_data)

    await load_files(registry, filepaths)
    for obj in registry.values():
        if isinstance(obj, JSONRegistry):
            await load_files(obj, obj.objects.keys())

    async with aiofiles.open(forward_list_path, "r") as f:
        forward_list = (await f.read()).split("\n")
    flist = ForwardList(forward_list)

    # Manipulate the forward list here based on your requirements
    flist.insert("search_str1", "new_str1")
    flist.insert("search_str2", "new_str2", 0)
    flist.insert("search_str3", ["new_str3", "new_str4"])

    # You can now use the loaded objects and forward list as needed in your application logic

if __name__ == "__main__":
    filepaths = [os.path.join(os.getcwd(), "file1.json"), os.path.join(os.getcwd(), "file2.json")]
    json_data = {
        "id": "root",
        "items": ["subitem1", "subitem2"]
    }
    forward_list_path = os.path.join(os.getcwd(), "forward_list.txt")

    asyncio.run(main(filepaths, json_data, forward_list_path))
