typedef struct {
    const char *name;
    int (*init)(EVP_CIPHER_CTX *ctx, const EVP_CIPHER *type);
    int (*update)(EVP_CIPHER_CTX *ctx, unsigned char *out, size_t outlen, const unsigned char *in, size_t inlen);
    int (*final)(EVP_CIPHER_CTX *ctx, unsigned char *out, size_t outlen);
} cipher;

typedef struct {
    const char *name;
    int (*init)(EVP_MD_CTX *ctx);
    int (*update)(EVP_MD_CTX *ctx, const unsigned char *data, size_t count);
    int (*final)(EVP_MD_CTX *ctx, unsigned char *md);
} digest;

typedef struct {
    RSA *rsa;
    int (*init)(EVP_PKEY_CTX *ctx);
    int (*sign)(EVP_PKEY_CTX *ctx, unsigned char *out, size_t outlen, const unsigned char *data, size_t data_len);
} rsa;

typedef struct algo {
    enum { CIPHER, DIGEST, RSA } type;
    union {
        cipher cipher;
        digest digest;
        rsa rsa;
    } u;
} Algo;

void *load_module(const char *name) {
    void *mod = dlopen(name, RTLD_NOW | RTLD_LOCAL);
    if (!mod) {
        fprintf(stderr, "Error: Could not load module %s\n", name);
        return NULL;
    }
    return mod;
}

void unload_module(void *mod) { dlclose(mod); }

int init_cryptoLib(const char *config_path) {
    FILE *fp = fopen(config_path, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", config_path);
        return 1;
    }

    char line[256];
    Algo algo;
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%s", algo.u.cipher.name) == 1) {
            void *module = load_module((char *)algo.u.cipher.name);
            if (!module) continue;

