                unload_module(module);
                continue;
            }

            algo.type = RSA;
            algo.u.rsa.init = init;
        } else {
            fprintf(stderr, "Error: Invalid configuration line %s\n", line);
        }
    }

    fclose(fp);
    return 0;
}

