// External logging API interface (pseudocode)
class ILogAPI {
public:
    virtual void log(const std::shared_ptr<LogEntry>& entry) = 0;
    virtual bool isConnected() const = 0;
};

class LogEntry {
public:
    explicit LogEntry(std::string message, std::string level)
        : _message(std::move(message)), _level(std::move(level)) {}

    const std::string& getMessage() const { return _message; }
    const std::string& getLevel() const { return _level; }

private:
    std::string _message;
    std::string _level;
};

std::shared_ptr<LogEntry> createLogEntry(const std::string& message, const std::string& level) {
    return std::make_shared<LogEntry>(message, level);
}

// Function to insert LogEntry after specified log level in the list
void insertLogEntryAfterLevel(std::forward_list<std::shared_ptr<LogEntry>>& logs, const std::string& level,
                               const std::string& message, int repetitions = 1) {
    auto it = logs.begin();
    auto prevIt = logs.before_begin();

    while (it != logs.end()) {
        if ((*it)->getLevel() == level && repetitions > 0) {
            for (int i = 0; i < repetitions; ++i) {
                logs.insert(++it);
            }
            it = logs.erase(it);
            auto newEntry = createLogEntry(message, level);
            logs.insert(++prevIt, newEntry);
            break;
        } else {
            prevIt = it;
            ++it;
        }
    }

    if (it == logs.end()) {
        auto newEntry = createLogEntry(message, level);
        logs.insert(logs.end(), newEntry);
    }
}

void logAndSend(ILogAPI& api, const std::shared_ptr<LogEntry>& entry) {
    if (!api.isConnected()) {
        std::cout << "Failed to send log: Not connected to the logging API." << std::endl;
        return;
    }

    try {
        api.log(entry);
    } catch (const std::exception& e) {
        std::cout << "Failed to send log: " << e.what() << std::endl;
    }
}

void insertLogEntryWithRetries(ILogAPI& api, std::forward_list<std::shared_ptr<LogEntry>>& logs,
                               const std::string& level, const std::string& message, int repetitions = 1) {
    std::mutex mtx;
    std::condition_variable cv;

    auto entry = createLogEntry(message, level);

    auto logAndSendTask = [&](int index) {
        logAndSend(api, entry);
        if (index < repetitions - 1) {
            insertLogEntryAfterLevel(logs, level, message, repetitions - index - 1);
        }
        cv.notify_one();
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < repetitions; ++i) {
        threads.emplace_back(logAndSendTask, i);
    }

    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [&api]() { return api.isConnected(); });

    for (auto& thread : threads) {
        thread.join();
    }
}
```

