#include "resource_bundle.h"
#include <stdarg.h>
#include <string.h>
#include <sys/mman.h>
#include <json-c/json.h>
#include "wrapper.h" // Include the C# wrapper header file (to be implemented separately)

static void free_resource_item(ResourceItem *item) {
    if (item->key != NULL)
        free(item->key);
    if (item->data != NULL && item->size > 0)
        munmap(item->data, item->size);
}

static ResourceBundle *create_resource_bundle() {
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    bundle->count = 0;
    bundle->items = NULL;
    return bundle;
}

ResourceBundle *load_resource_bundle(const char *path) {
    CryptoWrapper crypto;
    init_crypto(&crypto, "your-encryption-key", "your-salt");
    char *decrypted_data = decrypt_file(path, &crypto);

    if (!decrypted_data) {
        fprintf(stderr, "Error: Failed to load resource bundle.\n");
        return NULL;
    }

    json_object *root = json_tokener_parse(decrypted_data, 0);
    json_object_object_foreach(root, key, val) {
        ResourceItem *item = malloc(sizeof(ResourceItem));
        item->key = strdup(key);
        item->size = json_object_get_type(val) == json_type_string ? strlen(json_object_get_string(val)) : json_object_get_length(val);
        if (json_object_get_type(val) == json_type_string) {
            item->data = mmap(NULL, item->size + 1, PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            memcpy(item->data, json_object_get_string(val), item->size);
            ((char *)item->data)[item->size] = '\0';
        } else if (json_object_get_type(val) == json_type_int) {
            item->data = mmap(NULL, sizeof(long long), PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            *(long long *)item->data = json_object_get_int(val);
        } else if (json_object_get_type(val) == json_type_double) {
            item->data = mmap(NULL, sizeof(double), PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            *(double *)item->data = json_object_get_double(val);
        } else {
            fprintf(stderr, "Error: Unsupported item format in resource bundle.\n");
            free_resource_bundle(bundle);
            return NULL;
        }
        bundle->items = realloc(bundle->items, sizeof(ResourceItem *) * (++bundle->count));
        bundle->items[bundle->count - 1] = item;
    }

    json_object_put(root);
    free(decrypted_data);

    return bundle;
}

void free_resource_bundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free_resource_item(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle->key);
    free(bundle);
}
```

