```c
#include "wrapper.h"
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <sys/mman.h>
#include <stdio.h>
#include <stdlib.h>

void init_crypto(CryptoWrapper *crypto, const char *key, const char *salt) {
    AES_set_encrypt_key((const unsigned char *)key, 128, &crypto->key);
    GCmInit(&crypto->ctx, GCM_ENCRYPT, &crypto->key, (unsigned char *)salt, strlen(salt), NULL);
}

char *decrypt_file(const char *path, const CryptoWrapper *crypto) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error: Failed to open file.");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    rewind(file);

    char *buffer = malloc(length);
    size_t read = fread(buffer, 1, length, file);
    if (read != length) {
        perror("Error: Failed to read file.");
        free(buffer);
        return NULL;
    }
    fclose(file);

    char *decrypted_data = mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (GCmDecrypt(&crypto->ctx, decrypted_data, buffer, length, NULL) != 0) {
        perror("Error: Failed to decrypt file.");
        free(decrypted_data);
        free(buffer);
        return NULL;
    }

    return decrypted_data;
}
