    {
        private const int MaximumConcurrentTasks = 10;

        public static async Task<IList<IWebElement>> FindElementsBySelectorAsync(this IWebDriver driver, By selector)
        {
            var elements = await driver.FindElementsAsync(selector);

            if (!elements.Any())
            {
                throw new ElementNotFoundException($"No elements found using selector: {selector}");
            }

            return ParallelEnumerable.Invoke(() => elements.ToList(), MaximumConcurrentTasks)
                .Result;
        }
    }
