typedef std::vector<double> LineData;

// Function to read a line from the input file
LineData readLine(FILE* file) {
    char delim[] = " \t\n";
    LineData line;
    char token[1024];
    size_t len = 0;
    ssize_t read;

    while ((read = fscanf(file, "%s%n", token, &len)) != EOF) {
        if (sscanf(token, "%lf", &line.back()) != 1) {
            LOG4CPLUS_WARN("non-numeric value found: " << token);
        } else {
            line.push_back(0.0);
            if (line.size() > 3)
                line[line.size() - 3] = line.back();
        }

        memmove(token, token + len, strlen(token + len));
        len = strlen(token);
    }

    return line;
}

// Function to compute the average of the last three fields
double computeAverage(const LineData& line) {
    if (line.size() < 3)
        throw std::runtime_error("Not enough values for computation.");

    double sum = 0;
    size_t i;

    for (i = line.size() - 3; i < line.size(); ++i) {
        sum += line[i];
    }

    return sum / 3;
}

// Function to write the processed data to the output file
void writeLine(FILE* outFile, const LineData& line) {
    std::stringstream ss;
    for (size_t i = 0; i < line.size(); ++i) {
        if (i > 0)
            ss << ',';
        ss << line[i];
    }

    fprintf(outFile, "%s\n", ss.str().c_str());
}

