namespace {
constexpr int CHARSET_SIZE = 94; // A-Z, a-z, 0-9, +, / (base64 encoding without padding)

void combine(std::string& str, const std::string& src1, const std::string& src2) {
    auto it1 = std::begin(src1);
    auto it2 = std::begin(src2);
    while (it1 != std::end(src1) || it2 != std::end(src2)) {
        str.push_back(*(it1++));
        str.push_back(*(it2++));
    }
}

std::string generateSessionID() {
    std::random_device rd;
    std::mt19937_64 eng(rd()); // Seed with random device
    std::uniform_int_distribution<> distr(0, CHARSET_SIZE - 1);
    std::string result(22, ' ');
    combine(result, std::to_string(std::chrono::system_clock::now().time_since_epoch().count()),
            std::string((const char*)&eng, sizeof(eng))); // Add system time and random seed
    shuffle(result.begin(), result.end(), eng);
    Base64::Encode(result, result); // Encode base64
    return result;
}
} // namespace
