import com.fasterxml.jackson.databind.ObjectMapper;
import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import javax.validation.Valid;
import javax.ws.rs.*;
import javax.ws.rs.consumers.MultiPartEntity;
import javax.ws.rs.core.*;
import javax.ws.rs.container.AsyncResponse;
import javax.ws.rs.container.Suspended;
import javax.ws.rs.ext.Provider;
import org.hibernate.exception.ConstraintViolationException;
import org.jooq.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import sparkpost.SparkPostClient;
import sparkpost.model.TransactionalMessageRecipient;
import sparkpost.model.TransactionalMessageRequest;
import java.time.Instant;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

@Provider
public class CartUpdateEndpoint {
    private static final Logger LOGGER = LoggerFactory.getLogger(CartUpdateEndpoint.class);
    private static final int MAX_REQUESTS_PER_HOUR = 100;
    private static final Duration REQUEST_RATE_LIMIT_DURATION = Duration.ofHours(1);

    @PersistenceContext
    EntityManager em;

    @POST
    public void updateCart(@FormParam("userId") Long userId,
                            @FormParam("sessionToken") String sessionToken,
                            @FormParam("jsonData") String jsonData,
                            AsyncResponse response) {
        TokenManagementService tokenService = new TokenManagementService(); // Assuming you have a TokenManagementService to validate the session token.

        if (!tokenService.validate(sessionToken)) {
            sendErrorResponse(response, HttpStatus.UNAUTHORIZED, "Invalid session token.");
            return;
        }

        int remainingRequests = RateLimiter.decrementAndGetRemainingRequests(userId);
        if (remainingRequests < 0) {
            sendErrorResponse(response, HttpStatus.TOO_MANY_REQUESTS, "Exceeded the rate limit.");
            return;
        }

        ObjectMapper objectMapper = new ObjectMapper(); // Assuming you have an ObjectMapper for JSON deserialization.

        try {
            ProductCart cartData = objectMapper.readValue(jsonData, ProductCart.class); // Deserialize the JSON data into a ProductCart object.

            if (!cartData.isValid()) {
                sendErrorResponse(response, HttpStatus.BAD_REQUEST, "Invalid or malformed JSON data.");
                return;
            }
        } catch (IOException e) {
            sendErrorResponse(response, HttpStatus.BAD_REQUEST, "Invalid or malformed JSON data.");
            return;
        }

        CartService cartService = new CartService(); // Assuming you have a CartService to update the user's cart in the database.
        User user = em.find(User.class, userId); // Find the user by ID.

        if (user == null) {
            sendErrorResponse(response, HttpStatus.NOT_FOUND, "User not found.");
            return;
        }

        CompletableFuture<Void> cartUpdateFuture = cartService.updateCart(user, cartData); // Update the user's cart using the CartService.
        cartUpdateFuture.whenComplete((result, exception) -> {
            if (exception != null) {
                handleException(exception, response);
                return;
            }

            LOGGER.info("Cart updated for user {} at {}", userId, Instant.now());
            sendConfirmationEmail(user); // Send a confirmation email to the user upon successful cart update.
        });
    }

    private void handleException(Throwable exception, AsyncResponse response) {
        if (exception instanceof ConstraintViolationException) {
            sendErrorResponse(response, HttpStatus.BAD_REQUEST, "Invalid data submitted.");
        } else if (exception instanceof EntityNotFoundException) {
            sendErrorResponse(response, HttpStatus.NOT_FOUND, exception.getMessage());
        } else if (exception instanceof TooManyRequestsException) {
            sendErrorResponse(response, HttpStatus.TOO_MANY_REQUESTS, exception.getMessage());
        } else {
            sendErrorResponse(response, HttpStatus.INTERNAL_SERVER_ERROR, "An error occurred while processing the request.");
        }
    }

    private void sendErrorResponse(AsyncResponse response, StatusType status, String message) {
        ResponseBuilder builder = Response.status(status).entity(message);
        response.resume(builder.build());
    }

    private void sendConfirmationEmail(User user) {
        SparkPostClient sparkPostClient = new SparkPostClient(); // Assuming you have a SparkPostClient for sending emails.

        TransactionalMessageRequest request = new TransactionalMessageRequest()
                .setSubject("Your cart has been updated")
                .setText("Dear user, your cart has been successfully updated.");

        List<TransactionalMessageRecipient> recipients = Arrays.asList(new TransactionalMessageRecipient().addTo(user.getEmail()));
        sparkPostClient.transmissions()
                .post(request)
                .waitForCompletion(1, TimeUnit.HOURS); // Wait for the email to be sent before continuing.
    }
}
