package com.dynamicservice;

import java.time.Instant;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DynamicService {
    private static final String API_KEY = "your-api-key";
    private static final String MONITORING_URL = "https://monitoring-system.com/log";
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager();
        if (args.length > 0 && "start".equalsIgnoreCase(args[0])) {
            serviceManager.start();
        } else if (args.length > 0 && "stop".equalsIgnoreCase(args[0])) {
            serviceManager.stop();
        }
    }
}

interface ExternalApi {
    void configure();
    String getConfigValue(String key);
}

class ConfigApi implements ExternalApi {
    @Override
    public void configure() {
        // API configuration logic here
    }

    @Override
    public String getConfigValue(String key) {
        // API call to retrieve the value of the specified config key
    }
}

class ServiceManager {
    private volatile boolean isRunning = false;
    private final ExternalApi externalApi;
    private HeartbeatTask heartbeatTask;

    public ServiceManager() {
        this.externalApi = new ConfigApi();
    }

    public void start() {
        if (isRunning) {
            throw new IllegalStateException("Service is already running.");
        }
        isRunning = true;
        executor.submit(heartbeatTask = new HeartbeatTask());
        externalApi.configure();
        // Start monitoring service here
    }

    public void stop() {
        if (!isRunning) {
            throw new IllegalStateException("Service is not running.");
        }
        isRunning = false;
        heartbeatTask.cancel();
        // Stop monitoring service here
    }
}

class HeartbeatTask implements Runnable {
    private final long heartbeatIntervalMs;
    private volatile boolean isCancelled = false;

    public HeartbeatTask(long heartbeatIntervalMs) {
        this.heartbeatIntervalMs = heartbeatIntervalMs;
    }

    @Override
    public void run() {
        try {
            // Send heartbeat message and log the status here
            Thread.sleep(heartbeatIntervalMs);
        } catch (InterruptedException e) {
            // Handle interruption and continue retrying here
        }

        if (isCancelled) return;

        Runnable retryLogging = this::logDetailedErrorInfo;
        RetryStrategy retryStrategy = new ExponentialBackoffRetryStrategy();

        while (!isCancelled) {
            retryStrategy.execute(retryLogging);
        }
    }

    public void cancel() {
        isCancelled = true;
    }

    private void logDetailedErrorInfo() {
        // Log detailed error information here
    }
}

interface RetryStrategy {
    void execute(Runnable action);
}

class ExponentialBackoffRetryStrategy implements RetryStrategy {
    private static final int MAX_RETRIES = 10;
    private static final long BASE_DELAY_MS = 500L;

    @Override
    public void execute(Runnable action) {
        int retries = 0;
        long delayMs = BASE_DELAY_MS;

        boolean success = false;
        while (!success && retries < MAX_RETRIES) {
            try {
                action.run();
                success = true;
            } catch (Exception e) {
                if (retries == MAX_RETRIES - 1) {
                    throw new RuntimeException(e);
                }
                delayMs *= 2;
                retries++;
                try {
                    Thread.sleep(delayMs);
                } catch (InterruptedException ignored) {
                }
            }
        }
    }
}
```

