class Node {
public:
    std::vector<std::unique_ptr<Node>> children;
    bool isLeaf = false;
    std::atomic<int> dataCount;
};

class Octree {
private:
    static const int MAX_DEPTH = 16;
    Node root;
    int sizeLimit;
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<std::function<void()>> tasks;
    std::atomic_flag balanceLock = ATOMIC_FLAG_INIT;

public:
    Octree(int sizeLimit) : sizeLimit(sizeLimit), root{} {}

    void insert(const Vec3& point);
    void balance();
};

void Octree::insert(const Vec3& point) {
    std::unique_lock<std::mutex> lock(mtx);
    tasks.emplace([this, point]() {
        int depth = 0;
        Node* currentNode = &root;
        while (++depth < MAX_DEPTH && !currentNode->isLeaf) {
            int idx = getIndex(point, depth);
            if (!currentNode->children[idx]) {
                currentNode->children[idx].reset(new Node());
            }
            currentNode = currentNode->children[idx].get();
        }
        if (depth < MAX_DEPTH) {
            ++(currentNode->dataCount);
            lock.unlock();
            balanceLock.test_and_set();
        } else {
            std::cout << "Reached maximum depth, discarding data point.\n";
        }
    });
    cv.notify_one();
}

void Octree::balance() {
