class DynamicOctreeSpatialPartitioner {
public:
    struct Node {
        std::vector<std::unique_ptr<Node>> children;
        std::atomic<bool> isLeaf = true;
        std::atomic<int> dataCapacity;
        std::atomic<size_t> dataCount;
        double position[3];
    };

    DynamicOctreeSpatialPartitioner();
    ~DynamicOctreeSpatialPartitioner();

    void initialize(unsigned int depth, double maxLeafSize);
    void addDataPoint(const double position[3]);
    std::vector<std::unique_ptr<Node>> querySpatialData(const double position[3], double tolerance);

private:
    Node* createNode(Node* parent, unsigned int depth);
    void splitNode(Node* node);

    std::mutex mtx;
    std::unique_ptr<Node> root_;
    unsigned int depth_;
    double maxLeafSize_;
};
```

2. DynamicOctreeSpatialPartitioner.cpp

```cpp
#include "DynamicOctreeSpatialPartitioner.h"
#include <cmath>
#include <sstream>
#include <iomanip>

DynamicOctreeSpatialPartitioner::DynamicOctreeSpatialPartitioner() : root_(new Node), depth_(0), maxLeafSize_(1.0) {}

DynamicOctreeSpatialPartitioner::~DynamicOctreeSpatialPartitioner() { clear(); }

void DynamicOctreeSpatialPartitioner::initialize(unsigned int depth, double maxLeafSize) {
    std::lock_guard<std::mutex> lock(mtx);
    if (root_) delete root_;
    depth_ = depth;
    maxLeafSize_ = maxLeafSize;
    root_.reset(createNode(nullptr, depth));
}

void DynamicOctreeSpatialPartitioner::addDataPoint(const double position[3]) {
    std::lock_guard<std::mutex> lock(mtx);
    Node* current = root_.get();
    for (int i = 0; i < depth_; ++i) {
        int index = static_cast<int>(position[i / 3] > current->position[i / 3] ? 1 : 0);
        if (current->children.size() <= index) {
            splitNode(current);
        }
        current = current->children[index].get();
    }
    if (!current->isLeaf) {
        throw std::runtime_error("Invalid data addition: node is not a leaf.");
    }
    if (current->dataCount++ >= current->dataCapacity) {
        splitNode(current);
    }
    current->position[2] = position[2];
}

std::vector<std::unique_ptr<Node>> DynamicOctreeSpatialPartitioner::querySpatialData(const double position[3], double tolerance) {
    std::lock_guard<std::mutex> lock(mtx);
    std::vector<std::unique_ptr<Node>> result;
    queryHelper(root_.get(), position, tolerance, &result);
    return result;
}

void DynamicOctreeSpatialPartitioner::queryHelper(Node* node, const double position[3], double tolerance, std::vector<std::unique_ptr<Node>>* result) {
    for (const auto& child : node->children) {
        queryHelper(child.get(), position, tolerance, result);
    }

    if (!node->isLeaf) return;

    double distanceSq = 0.0;
    for (int i = 0; i < 3; ++i) {
        distanceSq += pow(position[i] - node->position[i], 2);
    }

    if (distanceSq <= tolerance * tolerance) {
        result->emplace_back(std::move(node));
    }
}

void DynamicOctreeSpatialPartitioner::splitNode(Node* node) {
    std::lock_guard<std::mutex> lock(mtx);
    if (node->children.size() != 8) {
        for (size_t i = node->children.size(); i < 8; ++i) {
            node->children.emplace_back(createNode(node, node->depth_ + 1));
        }
    }

    double halfSize = maxLeafSize_ / 2;
    for (int i = 0; i < 3; ++i) {
        node->position[i] += halfSize;
    }
    node->isLeaf = false;
}

DynamicOctreeSpatialPartitioner::Node* DynamicOctreeSpatialPartitioner::createNode(Node* parent, unsigned int depth) {
    return new Node();
}

void DynamicOctreeSpatialPartitioner::clear() {
    std::lock_guard<std::mutex> lock(mtx);
    if (root_) {
        for (auto& child : root_->children) {
            clearChild(child.get());
        }
        delete root_;
        root_.reset();
    }
}

void DynamicOctreeSpatialPartitioner::clearChild(Node* node) {
    for (auto& child : node->children) {
        clearChild(child.get());
    }
    delete node;
}
```

