```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    int *neighbors;
    size_t neighbors_count;
    struct Node *next;
} Node;

Node* bfs(int *nodes, size_t nodes_count, Node **graph, int start, int max_hops) {
    if (max_hops <= 0 || start < 0 || start >= nodes_count)
        return NULL;

    Node *queue = malloc(sizeof(Node)), *front = queue, *rear = queue;
    rear->data = start;
    rear->neighbors = graph[start];
    rear->neighbors_count = 0;
    rear->next = NULL;
    front->next = rear;

    Node **visited = malloc(nodes_count * sizeof(Node*));
    for (size_t i = 0; i < nodes_count; ++i) {
        visited[i] = NULL;
    }

    Node **reachable = malloc(sizeof(Node*) * nodes_count);
    size_t reachable_count = 0;

    while (front != rear) {
        Node *temp = front->next;
        int node = front->data;

        if (!visited[node]) {
            visited[node] = temp;
            ++reachable_count;
            reachable[reachable_count - 1] = temp;

            for (size_t i = 0; i < temp->neighbors_count; ++i) {
                int neighbor = temp->neighbors[i];

                if (!visited[neighbor]) {
                    Node *newNode = malloc(sizeof(Node));
                    newNode->data = neighbor;
                    newNode->neighbors = graph[neighbor];
                    newNode->neighbors_count = 0;
                    newNode->next = NULL;

                    if (reachable_count == max_hops) {
                        free(newNode);
                        break;
                    }

                    rear->neighbors[rear->neighbors_count++] = neighbor;
                    rear = rear->next = newNode;
                }
            }
        }

        front = temp;
    }

    free(queue);

    if (reachable_count > 0) {
        reachable[reachable_count] = NULL;
        return reachable;
    }

    free(visited);
    free(reachable);
    return NULL;
}
```

