```python
import json
import os
import asyncio
import aiofiles
import hashlib
from collections import defaultdict, deque
from functools import wraps

class Serializable:
    _registry = defaultdict(lambda: type("Serializable", (Serializable,), {}))
    _instances = deque()

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        Serializable._registry[cls.ID] = cls

    @property
    def ID(cls):
        return cls.__name__

    @staticmethod
    def from_json(data):
        if isinstance(data, bytes):
            data = json.loads(data)
        cls = Serializable._registry[data["class"]]
        instance = cls()
        for key, value in data["properties"].items():
            setattr(instance, key, value)
        return instance

    def to_json(self):
        return {"class": self.ID, "properties": {key: getattr(self, key) for key in self.__dict__}}

    @classmethod
    async def load_file(cls, filepath):
        try:
            async with aiofiles.open(filepath, "r") as file:
                data = await file.read()
                return Serializable.from_json(data)
