const fs = require('fs');

function readFileSync(filePath, encoding = 'utf8') {
  try {
    const fileContents = fs.readFileSync(filePath, encoding);
    return fileContents;
  } catch (error) {
    switch (error.code) {
      case 'ENOENT':
        console.error('File not found');
        break;
      case 'EACCES':
        console.error('Permission denied');
        break;
      default:
        console.error(error);
    }
  }
}
