#include <iostream>
#include <string>
#include <fstream>
#include <filesystem>
#include "libmhash/mhash.h" // Include the MD5 library
#include "poppler-cpp/pdfwriter.hpp" // Include the third-party PDF tool (Poppler)
#include <boost/filesystem.hpp> // Include caching mechanism (Boost Filesystem)

namespace fs = std::filesystem;
using namespace mhash;
using Poppler::PDFWriter;

std::string computeHash(const std::string& filePath) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MSHASH_CTX ctx;
    MSHASH_Init(&ctx);
    MSHASH_Update(&ctx, &filePath[0], filePath.length());
    std::ifstream inputFile(filePath, std::ios::binary | std::ios::ate);
    if (!inputFile) {
        throw std::runtime_error("Failed to open the input file.");
    }
    size_t fileSize = static_cast<size_t>(inputFile.tellg());
    inputFile.seekg(0, std::ios::beg);
    MSHASH_Update(&ctx, inputFile.rdbuf()->inbuf(), fileSize);
    MSHASH_Final(digest, &ctx);
    inputFile.close();

    std::stringstream ss;
    for (unsigned char c : digest) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(c);
    }
    return ss.str();
}

bool createPdfFromJpeg(const std::string& inputFilePath, const std::string& outputFilePath) {
    PDFWriter writer;
    try {
        writer.open(outputFilePath);
        writer.imageFile(inputFilePath);
        return true;
    } catch (const std::exception& e) {
        std::cerr << "Error creating PDF: " << e.what() << std::endl;
        return false;
    }
}

std::string getCachedHash(const std::string& filePath) {
    boost::filesystem::path cachePath = fs::path("cache") / hashFunction(filePath);
    if (!fs::exists(cachePath)) {
        return "";
    }
    std::ifstream cachedFile(cachePath.string());
    if (!cachedFile) {
        throw std::runtime_error("Failed to open the cache file.");
    }
    std::string hash;
    std::getline(cachedFile, hash);
    return hash;
}

void storeCachedHash(const std::string& filePath, const std::string& hash) {
    boost::filesystem::path cachePath = fs::path("cache") / hashFunction(filePath);
    fs::create_directories(cachePath.parent_path());
    std::ofstream cachedFile(cachePath.string());
    if (!cachedFile) {
        throw std::runtime_error("Failed to create the cache file.");
    }
    cachedFile << hash;
}

std::string hashFunction(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MSHASH_CTX ctx;
    MSHASH_Init(&ctx);
    MSHASH_Update(&ctx, &input[0], input.length());
    MSHASH_Final(digest, &ctx);

    std::stringstream ss;
    for (unsigned char c : digest) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(c);
    }
    return ss.str();
}

int mainFunction(const std::string& inputFilePath, const std::string& outputFilePath) {
    try {
        std::string hash = getCachedHash(inputFilePath);
        if (!hash.empty()) {
            storeCachedHash(inputFilePath, hash);
            createPdfFromJpeg(hash, outputFilePath);
        } else {
            hash = computeHash(inputFilePath);
            storeCachedHash(inputFilePath, hash);
            createPdfFromJpeg(inputFilePath, outputFilePath);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
}
