void readAndProcessChunk(std::ifstream& input, DataProcessor& processor) {
    constexpr int chunkSize = 1024;
    char buffer[chunkSize];
    while (input.read(buffer, chunkSize)) {
        std::istream_iterator<int> iter(std::istreambuf_iterator<char>(buffer));
        std::istream_iterator<int> end;
        for (auto num = iter; num != end; ++num) {
            processor.process(*num);
        }
    }
}
