    auto newProgress = static_cast<float>(current) / total;
    if (newProgress > progress) {
        progress = newProgress;
        std::cout << "[";
        for (int i = 0; i < 50 * progress; ++i) {
            std::cout << "#";
        }
        for (int i = 50 * progress; i < 50; ++i) {
