// Define the maximum number of files to load asynchronously and the maximum size for arrays
#define MAX_FILES 100
#define ARRAY_SIZE 1024

typedef struct {
    int key;
    long offset;
} KeyValuePair;

// Define the structure used for asynchronous file loading
typedef struct AsyncFile {
    char *filename;
    void *handle;
    size_t loaded;
    bool done;
} AsyncFile;

sem_t sem; // Semaphore for thread synchronization

// Function to initialize the semaphore
void initSemaphore(int value) {
    sem_init(&sem, 0, value);
}

// Function to delete the semaphore
void destroySemaphore() {
    sem_destroy(&sem);
}

// Function to wait for the semaphore and ensure that the next operation will not be performed concurrently
void waitForSemaphore() {
    sem_wait(&sem);
}

// Function to signal the semaphore, allowing the next operation to proceed
void signalSemaphore() {
    sem_post(&sem);
}

// Function to load a single file asynchronously and return an AsyncFile structure containing its details
AsyncFile *loadFile(const char *filename) {
    // Create and populate an AsyncFile structure
    AsyncFile *file = malloc(sizeof(AsyncFile));
    file->filename = strdup(filename);
    file->handle = NULL;
    file->loaded = 0;
    file->done = false;

    // Load the file asynchronously using dlopen and dlsym functions
    file->handle = dlopen(filename, RTLD_LAZY);
    if (!file->handle) {
        perror("Error loading file");
        free(file->filename);
        free(file);
        return NULL;
    }

    // Get the main function from the loaded library and call it to load the file
    typedef int (*LoadFunction)(void *);
    LoadFunction loadFunc = dlsym(file->handle, "load_function");
    if (!loadFunc) {
        perror("Error finding load function");
        dlclose(file->handle);
        free(file->filename);
        free(file);
        return NULL;
    }

    file->loaded += loadFunc(NULL);
    file->done = true;

    return file;
}

// Function to load multiple files asynchronously and wait for them all to finish before returning
void *loadFiles(int num_files, const char **filenames) {
    // Allocate a list of AsyncFile structures
    AsyncFile *files = malloc(num_files * sizeof(AsyncFile));

    // Load each file asynchronously and add it to the list
    for (int i = 0; i < num_files; ++i) {
        files[i] = loadFile(filenames[i]);
        if (!files[i]) {
            perror("Error loading one or more files");
            // Free all loaded files and exit early
            for (int j = 0; j < i; ++j) {
                dlclose(files[j].handle);
                free(files[j].filename);
            }
            free(files);
            return NULL;
        }
    }

    // Wait for all files to finish loading and then free their memory
    waitForSemaphore();
    for (int i = 0; i < num_files; ++i) {
        if (!files[i].done) {
            perror("Some files did not finish loading");
        }

        dlclose(files[i].handle);
        free(files[i].filename);
    }
    free(files);

    return NULL;
}

