            result = NULL;
            break;
        }

        attempts++;
    }

    if (!result) {
        return RESOLVE_NO_DNS_SERVERS;
    }

    if (attempts >= config.retryCount) {
        freeaddrinfo(result);
        return RESOLVE_TIMEOUT;
    }

    // Save the result in the cache and return success
