// Function to dynamically select an attack
attack selectedAttack(const std::string& characterText, const std::string& currentType) {
    // Extract character type and possible attacks from the user-provided text
    std::smatch matches;
    if (!std::regex_search(characterText, matches, charTypePattern) || !matches[1].matched) {
        throw std::runtime_error("Invalid character text format");
    }
    std::string type = matches[1];

    std::smatch attackMatches;
    std::regex_iterator<std::string::const_iterator> rit(characterText.cbegin(), characterText.cend(), attackNamePattern);
    std::vector<std::string> possibleAttacks;
    while (rit != std::regex_iterator<std::string::const_iterator>()) {
        if (!attackMatches[0].matched) break;
        possibleAttacks.push_back(attackMatches[1]);
        ++rit;
    }

    // Select an attack with cooldown consideration and cache lookup
    std::unique_lock<std::shared_mutex> lock(cacheLock);
    auto it = attackCache.find(type);
    if (it != attackCache.end && it->second.size() > 0) {
        std::set<std::string> availableAttacks;
        for (const auto& a : possibleAttacks) {
            if (it->second.find(a) != it->second.end) {
                availableAttacks.insert(a);
            }
        }
        // Use an efficient data structure to select an attack without repeating previous selections
        auto selected = *availableAttacks.begin();
        // Code for resolving cooldown and selecting another attack if necessary goes here

        lock.unlock();
        return selected;
    } else {
        lock.unlock();
        // Make an API request to fetch the relevant attacks, update the cache, and try again
        // ...
    }
}
