const fs = require('fs');

module.exports = function readFileSync(filePath) {
  try {
    const contents = fs.readFileSync(filePath, 'utf8');
    return contents;
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`File "${filePath}" does not exist`);
    } else if (err.code === 'EACCES') {
      throw new Error(`Permission denied to access file "${filePath}"`);
    } else if (err.code === 'EEXIST' && err.path === filePath) {
      throw new Error(`File "${filePath}" is a directory, not a file`);
    } else {
      throw new Error(err);
    }
  }
};
