import asyncio
import json
import os
import logging
from typing import Any, Dict, Callable, Type
import aiofiles
import traceback
from concurrent.futures import ThreadPoolExecutor

class JsonObject:
    def __init__(self, data: Any):
        self._data = data

    @staticmethod
    def from_json(json_str: str) -> 'JsonObject':
        return JsonObject(json.loads(json_str))

    def to_json(self) -> str:
        return json.dumps(self._data)

class Registry:
    def __init__(self):
        self._registry = {}

    def register(self, id: str, factory: Callable[[], Type[JsonObject]]):
        self._registry[id] = factory

    async def create_instance(self, id: str) -> JsonObject:
        try:
            factory = self._registry[id]
            return await factory()
        except KeyError:
            raise ValueError(f"Unknown ID '{id}' in registry.")

class UploadHandler:
    def __init__(self):
        self.executor = ThreadPoolExecutor()
        self.logger = logging.getLogger(__name__)
        self.registry = Registry()

    async def add_factory(self, id: str, factory: Callable[[], Type[JsonObject]]):
        self.registry.register(id, factory)

    async def handle_upload(self, file_id: str, data: JsonObject) -> Any:
        try:
            upload_class = await self.registry.create_instance(file_id)
            return await upload_class.load(data)
        except Exception as e:
            self.logger.error(f"Failed to load file {file_id}: {e}", exc_info=True)
            raise

    async def load_files(self, files: Dict[str, aiofiles.ABCFile]) -> Dict[str, Any]:
        tasks = {}
        for file_id, file in files.items():
            tasks[file_id] = self.executor.submit(self.handle_upload, file_id, JsonObject.from_json((await file.read()).decode()))
        return await self.executor.shutdown(wait=True) and self.process_results(tasks)

    def process_results(self, tasks: dict):
        results = {}
        for file_id, task in tasks.items():
            try:
                result = task.result()
                results[file_id] = result
            except Exception as e:
                self.logger.error(f"Error processing file {file_id}: {e}", exc_info=True)
        return results

    async def run(self):
        while True:
            # Replace this with a mechanism to receive uploads from a web application context
            uploads = await receive_uploads()
            if not uploads:
                break

            try:
                file_dict = await self.load_files(uploads)
                for file_id, result in file_dict.items():
                    if isinstance(result, Exception):
                        self.logger.error(f"Upload {file_id} failed with error:", exc_info=True)
                    else:
                        self.logger.info(f"Successfully processed upload {file_id}: {result}")
            except Exception as e:
                self.logger.error("An error occurred while processing the uploads:", exc_info=True)

def main():
    # Configure logging to console or logging service here
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

    upload_handler = UploadHandler()

    # Register factories for subclasses of JsonObject here
    upload_handler.add_factory("example", ExampleUpload)

    asyncio.run(upload_handler.run())

class ExampleUpload(JsonObject):
    @classmethod
    def from_json(cls, json_str: str):
        return cls(super().from_json(json_str))

    async def load(self) -> int:
        data = self._data
        if not isinstance(data, dict):
            raise ValueError("Invalid JSON format.")

        # Check for circular dependencies here

        result = 0
        for key, value in data.items():
            if isinstance(value, int):
                result += value
            elif isinstance(value, (int, float)):
                result += 1
            else:
                raise ValueError("Only integers and floating-point numbers are supported.")
        return result
```

