2. JavaScript Recursive File Reader (`readDirectory.js`):

```javascript
const fs = require('fs');
const path = require('path');

function readFile(filePath, callback) {
    const chunks = [];

    function readChunk(file, encoding) {
        file.setEncoding(encoding);
        file.on('data', (chunk) => {
            chunks.push(chunk);
        });

        file.on('end', () => {
            callback(Buffer.concat(chunks));
        });
    }

    fs.readFile(filePath, 'utf8', readChunk);
}

function readDirectory(directoryPath, callback) {
    fs.readdir(directoryPath, (err, files) => {
        if (err) return callback(err);

        let pending = files.length;
        if (!pending) return callback();

        files.forEach((file) => {
            const filePath = path.join(directoryPath, file);
            fs.stat(filePath, (errStat, stat) => {
                if (stat && stat.isDirectory()) {
                    readDirectory(filePath, (errSubdir) => {
                        if (errSubdir) return callback(errSubdir);
                        readDirectory(directoryPath, callback);
                    });
                } else if (stat) {
                    readFile(filePath, (errReadFile, data) => {
                        if (errReadFile) return callback(errReadFile);
                        // Process or yield the file content here
                        // ...
                        pending--;
                        if (!pending) callback();
                    });
                } else if (!pending) {
                    callback();
                }
            });
        });
    });
}
```

