    private readonly ILogger<ElementUpdater> _logger;
    private readonly IDatabase cache;
    private readonly IServiceBusSender notificationSender;
    private readonly YourVersioningSystem versioningSystem; // Integrate with your versioning system here
    private readonly IAuditLogService auditLogService; // Integrate with your audit logging service here

    public ElementUpdater(ILogger<ElementUpdater> logger, IDatabase cache, IServiceBusSender notificationSender, YourVersioningSystem versioningSystem, IAuditLogService auditLogService)
    {
        _logger = logger;
        this.cache = cache;
        this.notificationSender = notificationSender;
        this.versioningSystem = versioningSystem;
        this.auditLogService = auditLogService;
    }

    public async Task<IActionResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
            return BadRequest("All parameters must be provided.");

        if (!Regex.IsMatch(pageSectionId, @"^[a-zA-Z0-9_-]+$") || !Regex.IsMatch(elementId, @"^[a-zA-Z0-9_-]+$"))
            return BadRequest("ID fields must contain only alphanumeric characters, underscores, and hyphens.");

        if (!HtmlDocument.TryParse(htmlContent, out _))
            return BadRequest("Invalid HTML content provided.");

        // Get current version ID from cache (assuming you have a method for this)
        var currentVersion = await cache.StringGetAsync($"ElementVersion:{elementId}");

        if (!versioningSystem.IsValidVersion(currentVersion))
            return BadRequest("Invalid version provided.");

        // Validate the new version against the current one (assuming you have a method for this)
        var newVersion = await versioningSystem.GetNextVersion(currentVersion);
        if (!versioningSystem.IsValidVersion(newVersion))
            return BadRequest("Failed to generate a valid version.");

        // Update element's HTML content in the cache
        await cache.StringSetAsync($"Element:{elementId}", htmlContent, newVersion);

        // Trigger page refresh for all clients by sending a message to the message queue
        await notificationSender.SendMessageAsync(new ServiceBusMessage($"PageRefresh:{pageSectionId}:{elementId}") { ContentType = "application/text" });

        // Audit log the update attempt
        await auditLogService.LogUpdateAttemptAsync(User.Identity.Name, currentVersion, htmlContent, newVersion);

        return Ok();
    }
}
