```java
package com.example;

import java.util.Map;

public interface LogDataParser {
    Map<String, String> parse(String logLine);
}

package com.example;

import org.apache.commons.lang3.StringUtils;
import org.springframework.stereotype.Component;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Component
public class RegexLogDataParser implements LogDataParser {
    private static final Pattern TIMESTAMP_PATTERN = Pattern.compile("(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})");
    private static final Pattern ERROR_CODE_PATTERN = Pattern.compile("(ERROR|INFO)\\s+(\\d+)");
    // Add more patterns as needed

    @Override
    public Map<String, String> parse(String logLine) {
        Map<String, String> result = new HashMap<>();
        Matcher timestampMatcher = TIMESTAMP_PATTERN.matcher(logLine);
        if (timestampMatcher.find()) {
            result.put("timestamp", timestampMatcher.group(1));
        }
        Matcher errorCodeMatcher = ERROR_CODE_PATTERN.matcher(logLine);
        if (errorCodeMatcher.find()) {
            result.put("errorCode", errorCodeMatcher.group(2));
        }
        // Add more field extraction logic as needed
        return result;
    }
}
