import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

@Service
public class FileAnalyzerService {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final Map<String, LogDataParser> parsers = new ConcurrentHashMap<>();

    @Autowired
    public FileAnalyzerService(List<LogDataParser> parsers) {
        this.parsers.putAll(parsers.stream().collect(Collectors.toMap(parser -> parser.getClass().getSimpleName(), parser)));
    }

    public void parseFile(Path filePath) throws IOException, InterruptedException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Files.newInputStream(filePath)))) {
            String line;
            while ((line = reader.readLine()) != null) {
                executor.execute(() -> parseAndProcessLogData(line));
            }
        }
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }

    private void parseAndProcessLogData(String logLine) {
        LogDataParser parser = parsers.getOrDefault(logLine.split("\\s+")[0], this::defaultParseAndProcess);
        Map<String, String> parsedData = parser.parse(logLine);
        if (!parsedData.isEmpty()) {
            // Process the parsed data here. For example, save to a database or send to a logging service.
        }
    }

    private void defaultParseAndProcess(Map<String, String> parsedData) {
        System.out.println("Unknown log format: " + parsedData);
    }
}
