```python
import json
import avro.schema
import avro.datum
import avro.codec
from confluent_kafka import Consumer, KafkaError, KafkaException
from google.cloud import bigquery
from datetime import datetime, timedelta
import threading
import time
import logging
import yaml

class DataProcessor:
    def __init__(self, config):
        self.config = config
        self.consumers = {}  # Store all the consumers keyed by topic name
        self.schema_cache = {}  # Cache for JSON schemas
        self.data_pipeline = DataPipeline(config)
        self.analytics = AnalyticsService(config['analytics'])
        self.notifier = Notifier(config['notifications'])
        self.purge_task = threading.Thread(target=self.purge_old_data)

    def subscribe_to_topics(self):
        for topic, settings in self.config['topics'].items():
            consumer = Consumer(
                {
                    'bootstrap.servers': settings['bootstrap_servers'],
                    'group.id': settings['group_id'],
                    'auto.offset.reset': 'earliest'
                }
            )
            self.consumers[topic] = consumer
            consumer.subscribe([settings['topic']])
            logging.info(f"Subscribed to topic {topic}")
            def on_error(err):
                if err:
                    logging.error(f"Error consuming from topic {topic}: {err}")
                    if err.code() == KafkaError._PARTITION_EOF:
                        # If we reach the end of a partition, just ignore and resume
                        return IgnoreError()
                    else:
                        self.reconnect(topic)
                else:
                    self.reconnect(topic)
            consumer.on_error = on_error
            def on_message(msg):
                data = json.loads(msg.value)
                if not self.validate_data(data):
                    logging.warning(f"Invalid JSON data received from topic {topic}: {json.dumps(data)}")
                    return
                self.data_pipeline.process(data, msg.topic())
            consumer.poll(100)  # Start polling immediately
            consumer.run()

    def validate_data(self, data):
        schema = self.get_schema(data['_type'])
        return avro.codec.AvroDecoder(schema).decode(avro.datum.Binary(data)).schemaIsValid()

    def get_schema(self, type_name):
        if type_name not in self.schema_cache:
            schema = yaml.safe_load(open(f"schemas/{type_name}.yaml", "r").read())['types']
            self.schema_cache[type_name] = avro.schema.Parser().parse(schema)
        return self.schema_cache[type_name]

    def reconnect(self, topic):
        try:
            consumer = self.consumers[topic]
            consumer.pause()
            consumer.close()
            del self.consumers[topic]
            self.subscribe_to_topics()
        except KeyError as e:
            logging.warning(f"Unable to reconnect to topic {topic}: {str(e)}")

    def process(self):
        while True:
            time.sleep(60)  # Process data every minute
            self.analytics.batch_and_analyze()
            self.notifier.send_notifications()
            self.purge_task.start()

    def purge_old_data(self):
        while True:
            for topic, consumer in self.consumers.items():
                consumer.seek_to_beginning()
                while True:
                    msg = consumer.poll(10)
                    if not msg:
                        break
                    timestamp = datetime.fromtimestamp(float(msg.key()) / 1000) + timedelta(seconds=self.config['data_retention']['minutes'])
                    if timestamp < datetime.utcnow():
                        consumer.commit()
                        consumer.poll(100)  # Consume the next message to advance the offset
                        logging.info(f"Purged data older than {self.config['data_retention']['minutes']} minutes from topic {topic}")

class DataPipeline:
    def __init__(self, config):
        self.rules = config['rules']
        self.aggregators = {}  # Store all the aggregators keyed by identifier

    def process(self, data, topic):
        identifier = data['identifier']
        if identifier not in self.aggregators:
            self.aggregators[identifier] = Aggregator(data, topic)
        self.aggregators[identifier].process()

class Aggregator:
