```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

record* create_arrays(size_t *offsets, size_t *keys, size_t num_records, pthread_mutex_t *mutex) {
    record *records = NULL;
    if (!(records = (record*)malloc(num_records * sizeof(record)))) {
        perror("Error allocating memory for records");
        goto cleanup;
    }

    if (!(offsets = (size_t*)realloc(offsets, num_records * sizeof(size_t)))) {
        perror("Error reallocating memory for offsets");
        free(records);
        goto cleanup;
    }

    if (!(keys = (size_t*)realloc(keys, num_records * sizeof(size_t)))) {
        perror("Error reallocating memory for keys");
        free(offsets);
        free(records);
        goto cleanup;
    }

    pthread_mutex_init(mutex, NULL);

cleanup:
    if (records) {
        free(records);
    }
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }

    return records;
}
```

