    [HttpPost("login")]
    public async Task<IActionResult> Login([FromBody] LoginModel model)
    {
        var user = await _context.Users
            .Include(u => u.Roles)
            .FirstOrDefaultAsync(m => m.Username == model.Username && m.Password == ComputeHash(model.Password));

        if (user == null) return Unauthorized();

        var claims = new List<Claim>
        {
            new Claim(ClaimTypes.Name, user.UserName),
            new Claim(ClaimTypes.Role, string.Join(",", user.Roles.Select(r => r.RoleName)))
        };

        var identity = new ClaimsIdentity(claims, "MFA");

        var principal = new ClaimsPrincipal(identity);

        await _authService.AuthenticateAsync(principal);

        return Ok();
    }

