using Microsoft.Extensions.Caching.Memory;

public class DatabaseQueryHelper
{
    private readonly IAuthenticationService _authService;
    private readonly IMemoryCache _memoryCache;
    private readonly string _connectionString;

    public DatabaseQueryHelper(IAuthenticationService authService, IMemoryCache memoryCache, string connectionString)
    {
        _authService = authService;
        _memoryCache = memoryCache;
        _connectionString = connectionString;
    }

    public async Task<IDataReader> ExecuteQueryAsync(DbConnection dbConnection, string commandTemplate, IDictionary<string, object> parameters, int? pageSize = null, int? pageIndex = null)
    {
        if (dbConnection == null || string.IsNullOrEmpty(commandTemplate))
            throw new ArgumentNullException();

        IDataReader reader;
        DbCommand command;
        using (var dbCommandBuilder = new DbCommandBuilder(dbConnection, commandTemplate))
        {
            command = dbCommandBuilder.Build();
            ValidateParameters(parameters);
            SetParameters(command, parameters);
        }

        using (var transaction = dbConnection.BeginTransaction())
        {
            try
            {
                command.Transaction = transaction;
                reader = await ExecuteReaderAsync(command);

                if (pageSize != null && pageIndex != null)
                {
                    reader = Paginate(reader, pageSize.Value, pageIndex.Value);
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                LogError(ex);
                throw;
            }
        }

        if (_authService.IsAuthenticatedUserAuthorizedForSensitiveOperation())
        {
            return reader;
        }

        return Task<IDataReader>.Factory.FromResult(ExecuteAnonymousReader(command));

        async Task<IDataReader> ExecuteReaderAsync(DbCommand command)
        {
            using (var dataReader = await command.ExecuteReaderAsync())
            {
                return dataReader;
            }
        }

        IDataReader ExecuteAnonymousReader(DbCommand command)
        {
            var anonymousReader = new AnonymousDataReader();
            anonymousReader.Read();
            return anonymousReader;
        }

        void ValidateParameters(IDictionary<string, object> parameters)
        {
            if (parameters == null || !parameters.Any())
                throw new ArgumentException("Parameters cannot be empty or null.");
        }

        void SetParameters(DbCommand command, IDictionary<string, object> parameters)
        {
            foreach (var parameter in parameters)
            {
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
            }
        }

        void LogError(Exception ex)
        {
            // Implement your logging mechanism here
        }
    }
}
```

