    def loads(cls, s):
        return cls(json.loads(s))

registry = {}

async def load_files():
    tasks = []
    for file in os.listdir('files'):
        if file.endswith('.json'):
            tasks.append(aiofiles.open(f'files/{file}', 'r'))
    async with aiofiles.open('circles.txt', 'w') as circles_file:
