                json_data = await f.read()
                data[file[:-5]] = JsonParser.loads(json_data)
    for cls in registry.values():
        if issubclass(cls, BaseClass):
            setattr(sys.modules[cls.__module__], cls.__name__, cls)
    await asyncio.gather(*[func() for func in registry.values()])

