            for sub_value in value:
                result.append(BaseClass.from_json(sub_value))
        else:
            result.append(BaseClass.from_json(value))
    for cls in registry.values():
        if issubclass(cls, BaseClass):
            getattr(sys.modules[cls.__module__], cls.__name__).async_method(result)
    return jsonify({'result': result})

