import time
import random
from abc import ABC, abstractmethod
from typing import Dict, Union
from datetime import datetime, timedelta
import logging
from functools import wraps

class PaymentGateway(ABC):
    @abstractmethod
    def process_payment(self, order_id: str, payment_method: str, amount: float) -> str:
        pass

class NetworkError(Exception):
    pass

class TimeoutError(Exception):
    pass

class PaymentProcessor:
    def __init__(self, gateways: Dict[str, PaymentGateway] = {}):
        self.gateways = gateways
        self.logger = logging.getLogger(__name__)

    def process_payment(self, order_id: str, payment_method: str, amount: float) -> str:
        if not order_id or not payment_method or amount <= 0:
            return "Invalid parameters provided."

        gateway = self.gateways.get(payment_method, None)
        if not gateway:
            return f"Unsupported payment method: {payment_method}."

        retry_count = 3
        success = False
        status_message = ""

        def retry(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                for _ in range(retry_count):
                    try:
                        return func(*args, **kwargs)
                    except (NetworkError, TimeoutError):
                        self.logger.warning(f"Failed to process payment ({order_id}). Retrying...")
                        time.sleep(random.uniform(1, 5))
                return f"Payment processing failed after {retry_count} retries."
            return wrapper

        @retry
        def _process_payment():
            status = gateway.process_payment(order_id, payment_method, amount)
            success = True
            status_message = status

        return _process_payment()

    def refund_payment(self, order_id: str, refund_amount: float) -> str:
        if not order_id or refund_amount <= 0:
            return "Invalid parameters provided."

        lockfile = f"order_{order_id}.lock"
        concurrency_timeout = timedelta(minutes=5)

        def acquire_lock():
            if not open(lockfile, 'x').close():
                raise FileExistsError("Another refund request is being processed for this order.")
            return True

        def release_lock():
            try:
                os.remove(lockfile)
            except FileNotFoundError:
                pass

        if not acquire_lock():
            return "Cannot process refund at the moment as another refund request is being processed for this order."

        try:
            refund_status = self._refund_payment_internal(order_id, refund_amount)
        finally:
            release_lock()

        return refund_status

