```javascript
function BatchProcessElementsBySelector(node, selector, callback) {
    let stack = [node];
    const visitedNodes = new Set();

    function traverse(node) {
        if (!visitedNodes.has(node)) {
            visitedNodes.add(node);

            // Traverse through children and recursively call the traverse function
            Array.from(node.children).forEach((child) => {
                if (child.matches(selector)) {
                    callback(child);
                }
                traverse(child);
            });
        }
    }

    stack.forEach((node) => {
        if (!visitedNodes.has(node)) {
            traverse(node);
        }
    });
}
```

