using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;
using System.Security.Cryptography;
using System.Text;

public class Program
{
    private static string _configPath = Environment.GetEnvironmentVariable("CONFIG_PATH") ?? "config.xml";
    private static XDocument _configuration;

    public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        // Ensure key and IV meet specified criteria (length, format)
        if (key.Length != 32 || iv.Length != 16)
            throw new ArgumentException("Invalid key or IV size.");

        using (Aes aes = AES.Create())
        {
            // Set key and IV on the AES object
            aes.Key = key;
            aes.IV = iv;

            // Create a MemoryStream for decryption
            ICryptoTransform cryptoTransform = aes.CreateDecryptor();
            MemoryStream memoryStream = new MemoryStream(ciphertext);
            CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Read);

            // Read the decrypted data into a byte array and close streams
            byte[] plaintext = new byte[memoryStream.Length];
            int bytesRead;
            while ((bytesRead = cryptoStream.Read(plaintext, 0, plaintext.Length)) > 0)
                memoryStream.Read(plaintext, bytesRead, plaintext.Length - bytesRead);
            cryptoStream.Close();

            return plaintext;
        }
    }

    public static void LoadConfiguration()
    {
        if (File.Exists(_configPath))
        {
            _configuration = XDocument.Load(_configPath);

            // Set values based on configuration settings
            int tileSize, worldWidth, worldHeight;
            double cameraSpeed;
            if (TryParseConfiguration(out tileSize, out worldWidth, out worldHeight, out cameraSpeed))
                Console.WriteLine($"Loaded configuration from {_configPath}.");
            else
                throw new Exception("Failed to load or parse the configuration file.");
        }
        else
            throw new FileNotFoundException(_configPath);
    }

    private static bool TryParseConfiguration(out int tileSize, out int worldWidth, out int worldHeight, out double cameraSpeed)
    {
        tileSize = _configuration.Element("TileSize").Value == null ? 0 : int.Parse(_configuration.Element("TileSize").Value);
        worldWidth = _configuration.Element("WorldWidth")?.Value != null ? int.Parse(_configuration.Element("WorldWidth").Value) : 0;
        worldHeight = _configuration.Element("WorldHeight")?.Value != null ? int.Parse(_configuration.Element("WorldHeight").Value) : 0;
        cameraSpeed = _configuration.Element("CameraSpeed")?.Value == null ? 0.0 : double.Parse(_configuration.Element("CameraSpeed").Value);

        return worldWidth > 0 && worldHeight > 0;
    }
}
