import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import org.slf4j.*;

public class GameCharacter {
    private static final Logger LOGGER = LogManager.getLogger(GameCharacter.class);
    private static final int MAX_RETRIES = 5;
    private static final TimeUnit TIME_UNIT = TimeUnit.SECONDS;
    private static final String LOG_FILE = "game-character.log";

    private Random random;
    private Semaphore semaphore = new Semaphore(1);
    private ExecutorService executor = Executors.newFixedThreadPool(2);
    private ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private volatile Connection connection;
    private int attackCooldown = 9;
    private long nextAttackTime = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(attackCooldown);
    private String address;

    public GameCharacter(String address) {
        this.address = validateAddress(address);
        startConnection();
    }

    private String validateAddress(String address) {
        if (!address.matches("^([0-9]{1,3}.){3}[0-9]{1,3}$")) {
            throw new IllegalArgumentException("Invalid IPv4 address");
        }
        return address;
    }

    private void startConnection() {
        AtomicInteger retryAttempt = new AtomicInteger(0);
        Runnable connectionRunner = () -> {
            while (retryAttempt.getAndIncrement() < MAX_RETRIES) {
                try {
                    LOGGER.info("Attempting to connect to {}", address);
                    SocketAddress socketAddress = new InetSocketAddress(address, 8080);
                    SocketChannel channel = SocketChannel.open();
                    channel.connect(socketAddress);
                    this.connection = new Connection(channel);
                    break;
                } catch (IOException e) {
                    LOGGER.error("Connection failed", e);
                    try {
                        Thread.sleep(1000);
                    } catch (InterruptedException ignored) {}
                }
            }
        };
        executor.submit(connectionRunner);
    }

    private void selectAttack() {
        semaphore.acquireUninterruptibly();
        try {
            if (System.currentTimeMillis() >= nextAttackTime) {
                LOGGER.info("Selected attack {}", random.nextInt(2));
                nextAttackTime = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(attackCooldown);
            }
        } finally {
            semaphore.release();
        }
    }

    public void run() {
        while (true) {
            selectAttack();
            if (connection != null && connection.isConnected()) {
                connection.sendData("attack " + random.nextInt(2));
            } else {
                LOGGER.warn("Connection not established, retrying in a moment...");
            }
        }
    }

    public void setAttackCooldown(int attackCooldown) {
        this.attackCooldown = Math.max(1, attackCooldown);
    }

    public static void main(String[] args) {
        if (args.length < 3) {
            System.err.println("Usage: java GameCharacter [address] [attack_cooldown] [logging_level]");
            return;
        }
        String address = args[0];
        int attackCooldown = Integer.parseInt(args[1]);
        Level loggingLevel = Level.toLevel(args[2].toUpperCase());

        LOGGER.setLevel(loggingLevel);
        try (LoggerConfiguration loggerConfig = new LoggerFactoryLoggerAdapter()
                .configure(new File("logback-game-character.xml"))) {
            GameCharacter character = new GameCharacter(address);
            character.setAttackCooldown(attackCooldown);
            Thread gameThread = new Thread(character);
            gameThread.start();
        } catch (IOException e) {
            LOGGER.error("Error during logging configuration", e);
        }
    }
}
```

