    const char *api_endpoint;
    Algorithm algorithm;
};

int init_cryptographic_library(const struct Config *config) {
    EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
    if (!aes_ctx) return 1;

    const EVP_CIPHER *aes = EVP_aes_256_cfb();
    if (!aes) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    if (EVP_add_cipher(config->algorithm, aes) <= 0) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    const EVP_MD *sha256 = EVP_sha256();
    if (!sha256) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    if (EVP_add_digest(config->algorithm, sha256) <= 0 ||
        EVP_add_digest_alias("SHA-256", NID_sha256, NULL)) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    RSA *rsa = RSA_generate_key(config->algorithm, RSA_F4, NULL);
    if (!rsa) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    if (RSA_add_method(config->algorithm, RSA_meth_new, (void *)rsa)) {
        RSA_free(rsa);
        EVP_CIPHER_CTX_free(aes_ctx);
        return 1;
    }

    // Initialize API client and other necessary data structures...

    return 0;
}

