functionRouter.post('/functions/:functionId', async (req, res) => {
  const functionId = req.params.functionId;
  const { code, version, lastDeployTimestamp } = req.body;

  // Check optimistic concurrency control
  if (!cache.get(functionId)) return res.status(412).send();
  const storedVersion = cache.get(functionId).version;
  if (storedVersion !== version) return res.status(412).send();

  // Check if function has been deployed after the specified timestamp
  const currentFunction = await getFunction(functionId);
  if (currentFunction.lastDeployTimestamp > lastDeployTimestamp)
    return res.status(409).send();

  // Deploy function and update cache
  await deployFunction(functionId, code);
  cache.put(`${functionId}:metadata`, { version: ++version, timestamp: Date.now() });

  res.status(200).send();
});

// Function deletion
functionRouter.delete('/functions/:functionId', async (req, res) => {
  const functionId = req.params.functionId;

  // Check optimistic concurrency control
  if (!cache.get(functionId)) return res.status(412).send();
  const storedVersion = cache.get(functionId).version;
  if (storedVersion === null) return res.status(412).send();

  // Check if function has not been modified since the last deployment
  const currentFunction = await getFunction(functionId);
  if (currentFunction.version !== storedVersion) return res.status(412).send();

  await deleteFunction(functionId);
  cache.del(`${functionId}:metadata`);

  res.status(200).send();
});

