import { Transform } from 'stream';
const crypto = require('crypto');

class BufferMerger extends Transform {
  constructor(options) {
    super(options);
    this._chunks = [];
  }

  _transform(chunk, encoding, callback) {
    if (!Buffer.isBuffer(chunk)) throw new TypeError('Expected a buffer');
    this._chunks.push(chunk);
    this.push(Buffer.concat(this._chunks));
    this._chunks = [];
    callback();
  }
}

function copyBytes(buffer, start, count) {
  if (!Buffer.isBuffer(buffer)) throw new TypeError('Expected a buffer');
  if (start < 0 || count < 0 || start >= buffer.length || start + count > buffer.length)
    throw new RangeError('Invalid byte range');

  const copied = Buffer.allocUnsafe(count);
  buffer.copy(copied, start, start, start + count);
  return copied;
}

async function efficientByteCopy(source, count) {
  let offset = 0;
  const result = [];

  for await (const chunk of source) {
    if (!Buffer.isBuffer(chunk)) throw new TypeError('Expected a buffer');
    const currentChunkLength = chunk.length - offset;
    if (count <= currentChunkLength) {
      result.push(copyBytes(chunk, offset, count));
      offset += count;
      count = 0;
    } else {
      result.push(copyBytes(chunk, offset, currentChunkLength));
      offset += currentChunkLength;
      count -= currentChunkLength;
    }
  }

  if (count > 0 && source.length) {
    result.push(copyBytes(source[source.length - 1], offset, count));
  }

  return Buffer.concat(result);
}

