```cpp
#include "session_id_generator.h"

std::mutex session_id::s_seedMutex;

namespace session_id {

SessionIdGenerator::SessionIdGenerator(std::mt19937_64& gen)
    : m_gen(gen), m_redisContext(redisConnect("localhost", 6379)) {
  if (!m_redisContext) {
    std::cerr << "Redis connection failed!" << std::endl;
    exit(EXIT_FAILURE);
  }
  redisCommandArg* args = redisParseArgument(
      "SET", "session-id-counter", "0");
  redisReply* reply = static_cast<redisReply*>(redisCommand(m_redisContext, args));
  delete[] args;
  if (!reply || reply->type != REDIS_REPLY_STATUS) {
    std::cerr << "Failed to increment session-id-counter!" << std::endl;
    exit(EXIT_FAILURE);
  }

  signal(SIGINT, [](int signum) { m_shutdown = true; });
}

void SessionIdGenerator::seedRandomNumberGenerator() {
  if (m_shutdown) return;

  std::lock_guard<std::mutex> lock(s_seedMutex);
  unsigned char seed[128];
  RAND_bytes(seed, sizeof(seed));
  SHA256_CTX ctx;
  SHA256_Init(&ctx);
  SHA256_Update(&ctx, redisContext::server->info.id.c_str(), strlen(redisContext::server->info.id.c_str()));
  SHA256_Update(&ctx, redisContext::server->info.host.c_str(), strlen(redisContext::server->info.host.c_str()));
  SHA256_Update(&ctx, &time(nullptr), sizeof(time_t));
#ifdef _WIN32
  Sha256Final(seed, &ctx);
  for (int i = 0; i < open_sysconf(_SC_CLK_TCK); ++i) {
    unsigned int rand = RAND_long();
    seed[i % sizeof(seed)] ^= static_cast<unsigned char>(rand);
  }
#else
  SHA256_Final(seed, &ctx);
  for (int i = 0; i < sysconf(_SC_CLK_TCK); ++i) {
    unsigned int rand = random();
    seed[i % sizeof(seed)] ^= static_cast<unsigned char>(rand);
  }
#endif

  m_gen.seed(std::mt19937_64::result_type(reinterpret_cast<uint64_t*>(seed)));
}

std::string SessionIdGenerator::generateSessionId() {
  if (m_shutdown) return "";

  std::lock_guard<std::mutex> lock(s_seedMutex);
  seedRandomNumberGenerator();
  uint32_t id = static_cast<uint32_t>(m_gen()) % 1e9;
  redisReply* reply = redisCommand(
      m_redisContext,
      redisParseArgument("EXISTS", "session-id-" + std::to_string(id)));
  if (reply->type == REDIS_REPLY_INTEGER && reply->integer >= 1) {
    regenerateSessionId();
    return generateSessionId();
  }

  char buffer[23];
  sprintf(buffer, "session-id-%09u", id);
  redisReply* setReply = redisCommand(m_redisContext,
      redisParseArgument("SET", buffer, "1"));
  if (setReply->type != REDIS_REPLY_STATUS) {
    std::cerr << "Failed to store session id: " << buffer << std::endl;
    exit(EXIT_FAILURE);
  }

  // Base64 encoding and other necessary operations.
}

void SessionIdGenerator::regenerateSessionId() {
  seedRandomNumberGenerator();
}

} // namespace session_id
