    strcpy(dirpath, (char*)arg);

    DIR *d = opendir(dirpath);
    struct dirent *entry;
    struct stat st;
    double total_avg = 0;

    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char path[1024];
        sprintf(path, "%s/%s", dirpath, entry->d_name);
        if (lstat(path, &st) != 0 || S_ISDIR(st.st_mode)) continue; // Skip directories and files that do not exist or are directories

        FILE* file = fopen(path, "r");
        if (!file) continue; // Skip corrupted files

        double avg = parse_log_file(file);
        total_avg += avg;

        fclose(file);
    }

    closedir(d);
    return &total_avg;
}

