        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char path[1024];
        sprintf(path, "%s/%s", log_dir, entry->d_name);
        if (lstat(path, &st) != 0 || S_ISDIR(st.st_mode)) continue; // Skip directories and files that do not exist or are directories

        cache[cache_count].file_path = strdup(path);
    }

    closedir(d);

    for (int i = 0; i < cache_count; ++i) {
        pthread_create(&threads[i], NULL, process_logs, cache[i].file_path);
    }

    double total_avg = 0;
    for (int i = 0; i < cache_count; ++i) {
        void* avg_ptr;
        pthread_join(threads[i], &avg_ptr);
        total_avg += *(double*)avg_ptr;
    }

    printf("Average: %.6f\n", total_avg);

    for (int i = 0; i < cache_count; ++i) {
        free(cache[i].file_path);
    }
    free(cache);

    process_file(input_file, output_file, rules);

    return 0;
}
