using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Threading;
using Newtonsoft.Json;

public class DynamicRandomValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<(Type type, bool isExclusive), Tuple<double?, double?>> _caches;
    private readonly Random _random;

    public DynamicRandomValueGenerator()
    {
        _httpClient = new HttpClient();
        _caches = new Dictionary<(Type type, bool isExclusive), Tuple<double?, double?>>();
        _random = new Random();
    }

    private async Task<Tuple<double?, double?>> FetchIntervalBoundariesAsync(string endpoint)
    {
        try
        {
            var response = await _httpClient.GetAsync(endpoint);
            response.EnsureSuccessStatusCode();
            var boundaries = JsonConvert.DeserializeObject<dynamic>(await response.Content.ReadAsStringAsync());
            return new Tuple<double?, double?>(boundaries.min, boundaries.max);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error fetching interval boundaries: {ex}");
            return null;
        }
    }

    public int CustomRange(int min, int max, bool isExclusive, bool seeded = false, int? seed = null)
    {
        lock (_caches)
        {
            if (!_caches.TryGetValue((typeof(int), isExclusive), out var boundaries))
            {
                boundaries = FetchIntervalBoundariesAsync("https://your-api-endpoint.com/integers").Result;
                _caches[(typeof(int), isExclusive)] = boundaries;
            }

            double? minBoundary = bounds.min ?? min;
            double? maxBoundary = bounds.max ?? max;
            if (seeded)
            {
                _random = new Random(seed.Value);
            }

            return (int)((_random.NextDouble() * (maxBoundary - minBoundary) + minBoundary).Clamp(min, max));
        }
    }

    public float CustomRange(float min, float max, bool isExclusive, bool seeded = false, int? seed = null)
    {
        lock (_caches)
        {
            if (!_caches.TryGetValue((typeof(float), isExclusive), out var boundaries))
            {
                boundaries = FetchIntervalBoundariesAsync("https://your-api-endpoint.com/floats").Result;
                _caches[(typeof(float), isExclusive)] = boundaries;
            }

            double? minBoundary = bounds.min ?? min;
            double? maxBoundary = bounds.max ?? max;
            if (seeded)
            {
                _random = new Random(seed.Value);
            }

            return (float)((_random.NextDouble() * (maxBoundary - minBoundary) + minBoundary).Clamp(min, max));
        }
    }

    private static T Clamp<T>(T value, T min, T max) where T : IComparable<T>
    {
        if (value.CompareTo(min) < 0) return min;
        if (value.CompareTo(max) > 0) return max;
        return value;
    }
}
