const {promisify} = require('util');
const fs = require('fs');
const { PerformanceObserver, performance_now } = require('web-performance-api');
const db = require('./database'); // Assuming you have a database connection established in database.js file

class MergedBufferStream {
  constructor() {
    this.buffers = new Map();
  }

  addChunk(sourceId, chunk) {
    if (!this.buffers.has(sourceId)) this.buffers.set(sourceId, Buffer.concat([], []));
    const buffer = this.buffers.get(sourceId);
    buffer.write(chunk);
  }

  getMergedBuffer() {
    let mergedBuffer = Buffer.concat(Array.from(this.buffers.values()));
    if (mergedBuffer.length === 0) return Buffer.alloc(0);

    const chunkSize = Math.min(...this.buffers.keys().map(key => this.buffers.get(key).length));
    mergedBuffer = mergedBuffer.slice(0, chunkSize);

    for (let [sourceId, buffer] of this.buffers) {
      const sourceChunk = buffer.slice(mergedBuffer.length);
      if (sourceChunk.length > 0) throw new Error(`Unexpected remaining data from ${sourceId}: ${sourceChunk.toString('hex')}`);
    }

    this.buffers.clear();
    return mergedBuffer;
  }
}

function mergeDataStreams(...dataStreams) {
  const mergedStream = new MergedBufferStream();
  const promisePromisify = promisify(fs.readFile);

  const observer = new PerformanceObserver((list) => {
    list.getEntries().forEach(entry => console.log(`${entry.name}: ${entry.duration} ms`));
  });
  observer.observe({ entryTypes: ['measure'] });

  async function processDataStream(dataStream, index) {
    let currentBuffer = Buffer.alloc(0);

    try {
      for await (const chunk of dataStream) {
        if (!Buffer.isBuffer(chunk)) throw new Error(`Incorrect data type: ${JSON.stringify(chunk)}`);

        measurePerformance('processDataStream', performance_now());
        mergedStream.addChunk(index, chunk);
        currentBuffer = await promisePromisify(currentBuffer);
      }
    } catch (error) {
      console.error(`Error processing data stream ${index}:`, error);
      db.log({ timestamp: new Date(), sourceId: index, details: error });
    } finally {
      measurePerformance('processDataStream', performance_now());
    }
  }

  const promises = dataStreams.map((dataStream, index) => processDataStream(dataStream, index));

  Promise.all(promises).then(() => {
    db.log({ timestamp: new Date(), sourceIds: Array.from(mergedStream.buffers.keys()), data: mergedStream.getMergedBuffer() });
    console.log('All streams merged successfully.');
  }).catch((error) => {
    console.error('Error merging streams:', error);
    db.log({ timestamp: new Date(), sourceIds: Array.from(mergedStream.buffers.keys()), details: error });
  });
}
```
This code defines a `MergedBufferStream` class that handles multiple data streams and merges them into a single buffer stream. It also implements error handling for various cases, logs the merged data to an external database, manages resources carefully, and optimizes for concurrent access and thread safety. The function `mergeDataStreams()` takes in one or more data streams as arguments and processes them asynchronously using the `processDataStream()` function, which measures performance with the Web Performance API.

