```javascript
const { MongoClient, Duplex } = require('mongodb' , 'stream');
const { v4: uuidv4 } = require('uuid');

class NetworkStreamDataCollector {
  constructor(dbUri, collectionName) {
    this.dbUri = dbUri;
    this.collectionName = collectionName;
    this.client = null;
    this.db = null;
    this.collection = null;
    this.stream = new Duplex({
      read() {},
      write(chunk, encoding, callback) {
        if (this.collection) {
          this.collection.insertOne({ data: chunk, timestamp: new Date(), id: uuidv4() }, (err, res) => {
            if (err) console.error(err);
            callback();
          });
        } else {
          callback(new Error('Stream is not initialized.'));
        }
      },
    });
  }

  async init() {
    try {
      this.client = await MongoClient.connect(this.dbUri);
      this.db = this.client.db();
      this.collection = this.db.collection(this.collectionName);
      return this;
    } catch (err) {
      console.error('Failed to initialize MongoDB connection:', err);
      throw err;
    }
  }

  async pause() {
    if (!this.stream.paused) this.stream.pause();
  }

  async resume() {
    if (this.stream.paused) this.stream.resume();
  }

  destroy() {
    this.stream.destroy();
    this.client.close();
  }
}

module.exports = NetworkStreamDataCollector;
