// Thread pool structure
typedef struct {
    pthread_t* threads;
    int size;
    int count;
} ThreadPool;

// Function prototypes
void* download_thread(void* arg);
size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream);
int init_threadpool(ThreadPool* pool, int threads);
void cleanup_threadpool(ThreadPool* pool);

// Function for parsing the configuration file and creating a list of URLs
// This function is not shown due to space limitations but should return a dynamically allocated array of structs containing URL, expected file size, timeout settings, etc.
URLMetadata* parse_config(const char* config_file);

int main(int argc, char **argv) {
    const char *output_dir = NULL;
    int threads = 4;
    int opt;

    while ((opt = getopt(argc, argv, "d:t:")) != -1) {
        switch (opt) {
            case 'd':
                output_dir = optarg;
                break;
            case 't':
                threads = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d output_directory] [-t number_of_threads]\n", argv[0]);
                exit(1);
        }
    }

    if (output_dir == NULL || threads <= 0) {
        fprintf(stderr, "Error: Output directory and number of threads must be specified.\n");
        exit(1);
    }

    URLMetadata* urls = parse_config("config.json");

    ThreadPool pool;
    if (!init_threadpool(&pool, threads)) {
        fprintf(stderr, "Error: Failed to initialize thread pool.\n");
        exit(1);
    }

    CURL *curl;
    CURLcode res;
    int i;

    for (i = 0; i < urls_len; i++) {
        DownloadTask task = { .url = urls[i].url, .file = fopen((output_dir)/(urls[i].filename), "wb") };
        pthread_queue_push(&pool.queue, &task);
    }

    pthread_join(pool.threads, NULL);
    cleanup_threadpool(&pool);

    return 0;
}

// Thread-safe queue structure for passing tasks to threads
typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size;
    void** items;
} PThreadQueue;

void* download_thread(void* arg) {
    DownloadTask* task = (DownloadTask*)arg;
    CURL *curl = curl_easy_init();

    // Configure the libcurl settings using curl_easy_setopt() function

    res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        fprintf(stderr, "Error: Failed to download %s\n", task->url);
    } else {
        fprintf(stdout, "Downloaded %s\n", task->url);
    }

    fclose(task->file);
    curl_easy_cleanup(curl);
}

int init_threadpool(ThreadPool* pool, int threads) {
    pool->threads = malloc(sizeof(pthread_t) * threads);
    if (!pool->threads) {
        fprintf(stderr, "Error: Failed to allocate memory for thread pool.\n");
        return 0;
    }

    pool->size = threads;
    pool->count = 0;

    int i;
    for (i = 0; i < threads; i++) {
        if (pthread_create(&pool->threads[i], NULL, download_thread, NULL)) {
            fprintf(stderr, "Error: Failed to create thread %d.\n", i);
            return 0;
        }
    }

    return 1;
}

void cleanup_threadpool(ThreadPool* pool) {
    int i;
    for (i = 0; i < pool->size; i++) {
        pthread_join(pool->threads[i], NULL);
    }

    free(pool->threads);
}

// Other helper functions for working with libcurl, such as writing data and handling errors
