        private static byte[] Decrypt(byte[] cipherText, ICryptoTransform cryptoTransform)
        {
            using (var msDecrypt = new MemoryStream())
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, cryptoTransform, CryptoStreamMode.Write))
                {
                    csDecrypt.Write(cipherText, 0, cipherText.Length);
                    csDecrypt.FlushFinalBlock();
                }

                return msDecrypt.ToArray();
            }
        }

        private byte[] GenerateSalt()
        {
            // Generate a random salt for password hashing
            var bytes = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(bytes);
            return bytes;
        }

        private static byte[] ComputeHashSHA256(string data, byte[] salt)
        {
            using (var sha256 = SHA256.Create())
            {
                var hashedData = sha256.ComputeHash(Encoding.UTF8.GetBytes($"{data}{salt}"));
                return hashedData;
            }
        }
    }
}
```

