```javascript
class ScriptLoader {
  constructor(config) {
    this.queue = [];
    this.loadedCount = 0;
    this.failedCount = 0;
    this.config = config || {};
  }

  enqueue(src, priority = 1, fallback = null) {
    const script = { src, priority, fallback };
    if (this.config.enabledScripts && !this.config.enabledScripts.includes(script.src)) return; // Skip scripts not in the enabled list
    this.queue.push(script);
  }

  load() {
    if (!this.queue.length) return Promise.resolve(); // Nothing left to load, resolve instantly

    const currentScript = this.queue.shift();
    const scriptElement = document.createElement('script');
    let loadedScriptPromise;

    // Handle fallback if provided
    if (currentScript.fallback && !navigator.onLine) {
      loadedScriptPromise = Promise.resolve(currentScript.fallback);
    } else {
      // Asynchronously load the script and handle errors gracefully
      scriptElement.src = currentScript.src;
      scriptElement.onload = () => {
        this.loadedCount++;
        if (this.loadedCount === this.queue.length) this.resolve();
      };
      scriptElement.onerror = () => {
        this.failedCount++;
        this.handleError(currentScript); // Log the error and notify user about the issue
      };

      document.head.appendChild(scriptElement);

      loadedScriptPromise = new Promise((resolve) => {
        scriptElement.onload = resolve;
      });
    }

    return loadedScriptPromise.catch(() => this.load()); // If an error occurs, continue loading the next script
  }

  resolve() {
    if (this.loadedCount === this.queue.length) {
      // All scripts have been loaded and executed, execute custom initialization code
      if (this.config.onLoad) this.config.onLoad();
    }
  }

  handleError(script) {
    console.error(`[Script Loader] Error loading ${script.src}:`, err);
    // Provide visual indicators to inform users about the error (e.g., show an error message)
  }
}

