/**
 * Creates a new dynamic list containing all tasks with a priority level higher than or equal to the specified level
 * and that have not yet exceeded their deadline. If there is insufficient memory, returns NULL.
 *
 * @param tasks - Pointer to an array of Task structs.
 * @param numTasks - Integer representing the number of tasks in the tasks array.
 * @param priorityLevel - Integer representing the minimum priority level for tasks to be included in the new list.
 * @param deadlineTimestamp - Long integer representing the deadline timestamp in seconds since 1970-01-01 00:00:00 UTC.
 *
 * @return Pointer to a newly created task list that meets the specified criteria, or NULL if memory allocation fails or there are no tasks meeting the criteria.
 */
Task* createScheduledTasksList(Task* tasks, int numTasks, int priorityLevel, long deadlineTimestamp) {
    // Allocate memory for the new task list header and first node.
    Task *newHead = (Task*) malloc(sizeof(Task));
    if (!newHead) return NULL;
    newHead->next = NULL;

    Task *currentNode = newHead, *task, *lastTaskInNewList = newHead;

    // Iterate through the tasks array.
    for (int i = 0; i < numTasks; ++i) {
        task = &tasks[i];

        // If the task meets both priority and deadline criteria, add it to the new list.
        if (task->priorityLevel >= priorityLevel && task->deadlineTimestamp > deadlineTimestamp) {
            currentNode->next = task;
            currentNode = task;
            lastTaskInNewList = currentNode;
        }
    }

    // Update the 'next' pointer of the last task in the new list to point to NULL, indicating the end of the list.
    lastTaskInNewList->next = NULL;

    return newHead->next;
}
