const cache = new Map();
let scriptLoaderInterval;

function fetchScript(key) {
  return fetch(`/api/scripts/${key}`)
    .then((response) => {
      if (!response.ok) throw new Error('Failed to load script');
      return response.text();
    })
    .catch((error) => {
      console.error(error);
      // Retry logic for transient errors (e.g., network issues) can be added here.
    });
}

async function renderScripts(scripts, appendTo) {
  const scriptElements = scripts.map((scriptObj) => {
    let key;
    if (cache.has(scriptObj.key)) {
      // Use cached script if available and not stale
      key = cache.get(scriptObj.key).key;
    } else {
      // Fetch and cache the script
      key = await fetchScript(scriptObj.key)
        .then((code) => {
          const scriptElement = document.createElement('script');
          scriptElement.innerHTML = code;
          appendTo.appendChild(scriptElement);
          return scriptElement.key;
        })
        .catch((error) => {
          console.error(error);
          // Handle errors and continue rendering remaining scripts if possible.
        });
    }

    // Check if script is missing essential properties and handle accordingly
    if (!scriptObj.code && !scriptObj.type) {
      throw new Error('Script object is missing code or type property');
    }

    const scriptTag = document.createElement('script');
    scriptTag.innerHTML = scriptObj[scriptObj.type || 'code'] || '';
    scriptTag.key = key;
    appendTo.appendChild(scriptTag);
  });

  // Loading spinner or progress indicator can be added here during the rendering process

  return scriptElements;
}

function manageScripts(scripts, appendTo) {
  const existingScriptElements = [...appendTo.children].filter((element) => element.nodeName === 'SCRIPT');

  // Remove old or unused script elements
  existingScriptElements.forEach((scriptElement) => {
    if (!scripts.some((scriptObj) => scriptObj.key === scriptElement.key)) {
      appendTo.removeChild(scriptElement);
    }
  });
}

function updateFooter(scripts) {
  const footer = document.querySelector('footer');
  manageScripts(scripts, footer);
  renderScripts(scripts, footer);

  // Clear cache after a certain time or when new scripts are added to reduce redundant network requests
  clearCache();

  if (!scriptLoaderInterval) {
    scriptLoaderInterval = setInterval(() => updateFooter(scripts), 1000);
  }
}

function clearCache() {
  cache.forEach((value, key) => {
    const timestamp = new Date().getTime();
    if (timestamp - value.timestamp > 60 * 60 * 24) { // Clear cache after 2 days
      cache.delete(key);
    }
  });
}
