        status = k8s_api.read_namespaced_deployment_status(deployment_name, "default")
        if status.status == "Running":
            break
        time.sleep(1)

def retry_on_failure(function, attempts=3, delay=5):
    for _ in range(attempts):
        try:
            return function()
        except Exception as e:
            time.sleep(delay)
    raise Exception("Retry limit exceeded")

