using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using log4net;

namespace FileMetadataProcessor
{
    public class FileMetadataProcessor
    {
        private readonly string _directoryPath;
        private long _minFileSize;
        private long _maxFileSize;

        private static readonly ILog _logger = LogManager.GetLogger(typeof(FileMetadataProcessor));

        public FileMetadataProcessor(string directoryPath, long minFileSize, long maxFileSize)
        {
            _directoryPath = directoryPath;
            _minFileSize = minFileSize;
            _maxFileSize = maxFileSize;
            ValidateFileSizeRange();
        }

        private void ValidateFileSizeRange()
        {
            if (_minFileSize > _maxFileSize)
                throw new ArgumentOutOfRangeException(nameof(_minFileSize), "The minimum file size should be less than or equal to the maximum file size.");
        }

        public IEnumerable<ProcessedFileMetadata> ProcessFiles(Func<FileInfo, bool> filterCallback, int batchSize = 100)
        {
            var processedFiles = new List<ProcessedFileMetadata>();
            DirectoryInfo rootDir = new DirectoryInfo(_directoryPath);

            if (!rootDir.Exists)
                throw new DirectoryNotFoundException($"The specified directory '{_directoryPath}' does not exist.");

            FileInfo[] files = rootDir.GetFiles().Where(f => f.Length >= _minFileSize && f.Length <= _maxFileSize).ToArray();

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            Parallel.ForEach(files, options, (fileInfo) =>
            {
                if (filterCallback(fileInfo))
                    processedFiles.Add(new ProcessedFileMetadata(fileInfo));
            });

            return processedFiles;
        }

        public IEnumerable<string> GetFilePaths(long minFileSize, long maxFileSize)
        {
            _minFileSize = minFileSize;
            _maxFileSize = maxFileSize;
            ValidateFileSizeRange();

            DirectoryInfo rootDir = new DirectoryInfo(_directoryPath);
            return rootDir.GetFiles()
                .Where(f => f.Length >= _minFileSize && f.Length <= _maxFileSize)
                .Select(fi => fi.FullName);
        }

        public override string ToString()
        {
            return $"Size Range: [{_minFileSize} KB, {_maxFileSize} KB]";
        }
    }

    public struct ProcessedFileMetadata
    {
        public FileInfo FileInfo { get; set; }

        public ProcessedFileMetadata(FileInfo fileInfo)
        {
            FileInfo = fileInfo;
        }
    }
}
