    private float _minValue;
    private float _maxValue;
    private int _arraySize;
    private int[] _pooledArrays = new int[_arraySize];

    public ValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        _minValue = Mathf.Clamp01(minValue);
        _maxValue = Mathf.Clamp01(maxValue);
    }

    public float RandomFloat() => UnityEngine.Random.value * (_maxValue - _minValue) + _minValue;

    public int RandomInt() => (int)Mathf.RoundToInt((UnityEngine.Random.value * (_maxValue - _minValue)) + _minValue);

    public int[] GenerateIntArray(int size, bool exclusive = false)
    {
        if (size <= 0) throw new ArgumentOutOfRangeException("Size must be greater than zero.");
        int[] array;

        // Check pool for reusable array
        if (_pooledArrays.Length > size)
            array = _pooledArrays;
        else
            array = new int[size];

        for (int i = 0; i < size; i++)
        {
            if (exclusive)
                array[i] = Mathf.RoundToInt((UnityEngine.Random.value * (_maxValue - _minValue)) + _minValue);
            else
                array[i] = (int)Mathf.RoundToInt((UnityEngine.Random.Range(_minValue, _maxValue)));
        }

        return array;
    }

