#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void log_operation(const char* original, size_t size_limit, size_t trimmed_length, bool slash_appended) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s - Original string: '%s', Size limit: %zu, Trimmed length: %zu, Slash appended: %s\n", timestamp, original, size_limit, trimmed_length, slash_appended ? "yes" : "no");
        fclose(log_file);
    }
}

char* trimAndAppendSlash(char* input, size_t size_limit) {
    if (size_limit == 0 || input == NULL) {
        return NULL;
    }

    size_t length = strlen(input);
    char* trimmed = malloc(length + 1); // plus one for the null terminator

    if (!trimmed) {
        log_operation(input, size_limit, length, false);
        return NULL;
    }

    memcpy(trimmed, input, length);
    trimmed[length] = '\0';

    size_t i = 0;
    for ( ; i < length; ++i) {
        if (isspace(static_cast<unsigned char>(trimmed[i]))) {
            memmove(&trimmed[i], &trimmed[i+1], length - i);
            --length;
        } else {
            break;
        }
    }

    for (size_t j = length - 1; j > i; --j) {
        if (isspace(static_cast<unsigned char>(trimmed[j]))) {
            trimmed[j] = '\0';
            --length;
        } else {
            break;
        }
    }

    size_t new_length = strlen(trimmed);
    if (new_length <= length && new_length + 1 <= size_limit) {
        trimmed[new_length] = '/';
        log_operation(input, size_limit, new_length + 1, true);
    } else {
        free(trimmed);
        log_operation(input, size_limit, length, false);
    }

    return trimmed;
}
