            lock (_dbConnection)
            {
                using var dbTransaction = _dbConnection.BeginTransaction();
                try
                {
                    var parameters = new DynamicParameters();
                    foreach (var value in values)
                        parameters.Add(parameters.ParameterName(), value);
                    var sqlCommand = commandTemplate + parameters;
                    var dbCommand = _dbConnection.CreateCommand();
                    dbCommand.CommandText = sqlCommand.sql;
                    dbCommand.Parameters.AddRange(sqlCommand.parameters);
                    var dataReader = await ExecuteWithRetryAsync(async () => await dbTransaction.ExecuteReaderAsync(dbCommand));
                    dbTransaction.Commit();
                    return dataReader;
                }
                catch (DbException ex)
                {
                    dbTransaction.Rollback();
                    LogError(ex);
                    throw;
                }
            }
        }

