        {
            // Implement validation logic here to prevent SQL injection risks
        }

        public async Task<IDataReader> ExecuteWithRetryAsync(Func<Task<IDataReader>> action, int retryCount = 3, int delayMilliseconds = 500)
        {
            for (int i = 0; i < retryCount; i++)
            {
                try
                {
                    return await action();
                }
                catch (Exception ex) when (ex is TimeoutException || ex is TaskCanceledException)
                {
                    if (i >= retryCount - 1) throw;
                    Console.WriteLine($"Retrying after {delayMilliseconds} milliseconds due to {ex.Message}");
                    await Task.Delay(TimeSpan.FromMilliseconds(delayMilliseconds));
                }
            }
            return null; // Return a sentinel value to indicate that no more retries are being made
        }

        private void LogError(Exception ex)
        {
            // Implement logging functionality here
        }

        public void Dispose()
        {
            _dbConnection?.Dispose();
            _redisConnection?.Close();
        }
    }
}
