namespace ProcessAndSyncData
{
    public class Program
    {
        private static IServiceProvider _serviceProvider;
        private static MemoryCache _memoryCache;

        public static async Task Main(string[] args)
        {
            ConfigureServices();

            var unitTestModuleName = args.FirstOrDefault() ?? "PerformanceTests";

            // Load and run performance-critical tests from the specified module.
            RunUnitTestsInParallel(unitTestModuleName);

            // Your Python function call to ensure the necessary directory exists and environment variable is set goes here.

            // Synchronize data between two systems using an external REST API.
            await SyncDataAsync();

            await new WebSocketServer().StartAsync();
        }

        private static void ConfigureServices()
        {
            var services = new ServiceCollection();
            services.AddIdentity<ApplicationUser, IdentityRole>()
                .AddEntityFrameworkStores<ApplicationDbContext>();
            // Add other necessary services and configurations here.
            _serviceProvider = services.BuildServiceProvider();
            _memoryCache = _serviceProvider.GetRequiredService<IMemoryCache>();
        }

        private static void RunUnitTestsInParallel(string moduleName)
        {
            var assembly = Assembly.Load(new AssemblyName(moduleName));
            var testClasses = assembly.DefinedTypes
                .Where(t => t.IsSubclassOf(typeof(UnitTestBase)));

            Parallel.ForEach(testClasses, RunTest);
        }

        private static void RunTest(Type testClass)
        {
            var instance = Activator.CreateInstance(testClass);
            var methodInfo = testClass.GetMethod("Test");
            methodInfo?.Invoke(instance, null);
        }
    }

    public abstract class UnitTestBase
    {
        protected Timer _timer;
        protected Stopwatch _stopWatch;

        [MethodImpl(MethodImplOptions.NoInlining)]
        protected void StartTimer()
        {
            _stopWatch = Stopwatch.StartNew();
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        protected void EndTimer()
        {
            _timer?.Dispose();
            _timer = null;
            _stopWatch.Stop();
            Console.WriteLine($"Test completed in: {_stopWatch.ElapsedMilliseconds}ms");
        }
    }
}
```

