using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using StackExchange.Redis;

public class DataLoader
{
    private readonly ILogger<DataLoader> _logger;
    private readonly IDatabase _redisDatabase;
    private readonly ISerializerFactory _serializerFactory;

    public DataLoader(ILogger<DataLoader> logger, IServiceProvider serviceProvider)
    {
        _logger = logger;
        _redisDatabase = serviceProvider.GetService<IConnectionMultiplexer>().GetDatabase();
        _serializerFactory = serviceProvider.GetService<ISerializerFactory>();
    }

    public async Task<T> LoadDataAsync<T>(string key) where T : class
    {
        try
        {
            // Check cache first
            var cachedData = await _redisDatabase.GetAsync(key);
            if (!string.IsNullOrEmpty(cachedData))
                return JsonConvert.DeserializeObject<T>(cachedData, _serializerFactory.CreateJsonSerializer());

            using (var fileStream = File.OpenRead($"data/{key}.bin"))
            {
                var serializedData = await fileStream.ReadFullyAsync();

                // Deserialize data with thread safety and handle deserialization issues
                try
                {
                    return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(serializedData), _serializerFactory.CreateJsonSerializer());
                }
                catch (JsonReaderException ex) when (ex.Message.Contains("Invalid"))
                {
                    _logger.LogError(ex, "Failed to deserialize data with key '{Key}': {Message}", key, ex.Message);
                    throw;
                }
                catch (JsonSerializationException ex) when (ex.Message.Contains("Invalid"))
                {
                    _logger.LogError(ex, "Failed to deserialize data with key '{Key}': {Message}", key, ex.Message);
                    throw;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading data with key '{Key}': {Message}", key, ex.Message);
            throw;
        }
    }

    // Implement caching strategy based on your requirements and environment
    public void SetCacheExpiration(TimeSpan expiration) => _redisDatabase.KeyExpire(expiration);
}
