import os
import sys
import logging
import time
import shutil
from threading import Lock
from datetime import datetime, timedelta
import tempfile
import errno
import signal

class RotatingFileHandler(logging.Handlers.RotatingFileHandler):
    def __init__(self, filename, maxBytes=10485760, backupCount=13, encoding=None, delay=0):
        super().__init__(filename, maxBytes, backupCount, encoding, delay)

def init_logging():
    log_dir = "logs" if not os.path.exists(os.path.join(os.getcwd(), "logs")) else get_available_log_dir()
    logging.basicConfig(
        level=get_logging_level(),
        format=get_logging_format(),
        handlers=[RotatingFileHandler(os.path.join(log_dir, "app.log"), maxBytes=10485760, backupCount=13)]
    )

def get_available_log_dir():
    lock = Lock()
    while True:
        try:
            dir_name = f"{datetime.now().strftime('%Y-%m-%d_%H:%M:%S')}"
            log_dir = os.path.join(os.getcwd(), "logs", dir_name)
            os.makedirs(log_dir, exist_ok=True)
            return log_dir
        except OSError as e:
            if e.errno != errno.EEXIST:
                raise e
            time.sleep(1)

def get_logging_level():
    level = os.getenv("LOGGING_LEVEL", "INFO").upper()
    return getattr(logging, level)

def get_logging_format():
    format_string = os.getenv("LOGGING_FORMAT", "%(asctime)s [%(levelname)s] %(message)s")
    return format_string

def clean_logs():
    log_dir = "logs" if not os.path.exists(os.path.join(os.getcwd(), "logs")) else get_available_log_dir()

    for dirpath, _, filenames in sorted(os.walk(log_dir)):
        for filename in filenames:
            if filename.endswith(".log"):
                file_path = os.path.join(dirpath, filename)
                try:
                    os.stat(file_path)
                except OSError:
                    continue

                last_modified = datetime.fromtimestamp(os.path.getmtime(file_path))
                if (datetime.now() - last_modified) > timedelta(days=30):
                    os.remove(file_path)
                elif os.path.getsize(file_path) >= 10485760:
                    shutil.copy2(file_path, f"{file_path}.bak")
                    os.remove(file_path)

if __name__ == "__main__":
    init_logging()
    clean_logs()
```

