using System;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Caching;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace XmlParser
{
    public class XmlManager : IXmlManager
    {
        private readonly ILogger<XmlManager> _logger;
        private readonly ObjectCache _cache;
        private readonly IConfiguration _configuration;
        private XmlDocument _document;
        private XmlSchemaSet _schema;

        public XmlManager(ILogger<XmlManager> logger, IObjectCacheFactory cacheFactory, IConfiguration configuration)
        {
            _logger = logger;
            _cache = cacheFactory.GetCache("XmlCache");
            _configuration = configuration;
        }

        public void ParseAndValidate(Stream xmlStream, Stream xsdStream)
        {
            if (_document != null && _schema != null) return;

            _document = new XmlDocument();
            _document.Load(xmlStream);

            try
            {
                _schema = new XmlSchemaSet();
                _schema.Add(xmlStream);
                _schema.Compile();

                var validationResult = _document.Schemas[0].Validate(_document);
                if (!validationResult) throw new InvalidOperationException("Invalid XML document.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "XML document validation failed.");
                throw;
            }
        }

        public XmlNode GetFirstElementByXPath(string xPathQuery) =>
            FindElementsByXPath(xPathQuery).Length > 1 ?
                ThrowException("Multiple elements match the provided XPath query.") :
                _document.SelectSingleNode(xPathQuery);

        public IEnumerable<XmlNode> FindElementsByXPath(string xPathQuery)
        {
            var nodes = _cache.Get(xPathQuery, GetCacheItemCallback);
            if (nodes != null) return nodes;

            try
            {
                nodes = _document.SelectNodes(xPathQuery);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to find elements by XPath query.");
                throw;
            }

            return nodes;
        }

        private object GetCacheItemCallback(object key)
        {
            var xPathQuery = key as string;
            if (string.IsNullOrEmpty(xPathQuery)) return null;

            var cacheOptions = new CacheItemPolicy();
            cacheOptions.AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(_configuration["CacheSettings:DefaultTTL"]);
            cacheOptions.SlidingExpiration = TimeSpan.FromSeconds(_configuration["CacheSettings:SlidingTime"]);

            return _cache.Get(key, (cacheItem) =>
            {
                if (cacheItem.Value == null || DateTimeOffset.Now > cacheItem.Expiration)
                {
                    ParseAndValidate(_document.OuterXml.ToStream(), null);
                    return _FindElementsByXPath(xPathQuery);
                }

                return cacheItem.Value;
            }, cacheOptions);
        }

        private IEnumerable<XmlNode> _FindElementsByXPath(string xPathQuery) =>
            FindElementsByXPath(xPathQuery).Length > 1 ?
                ThrowException("Multiple elements match the provided XPath query.") :
                _document.SelectNodes(xPathQuery);

        private void ValidateAndHandleUserInputForXPathQueries()
        {
            // Implement user input validation and error handling for XPath queries here.
        }

        private void LogOperationDetails()
        {
            var loggerSettings = _configuration.GetSection("Logging");
            if (!loggerSettings.GetValue<bool>("Enabled")) return;

            _logger.LogInformation($"Starting XML parsing and validation.");
            // Log the execution time, validation results, and any exceptions thrown here.
        }

        private void ThrowException(string message)
        {
            var exception = new InvalidOperationException(message);
            _logger.LogError(exception, message);
            throw exception;
        }
    }
}
```
