    using System;
    using UnityEngine;
    using System.Collections.Generic;
    using System.Linq;

    public enum RangeType { Closed, Open, HalfOpen }
    public struct CustomInterval : IEquatable<CustomInterval>
    {
        public float min;
        public float max;

        public bool IsEqual(CustomInterval other) => this.min == other.min && this.max == other.max;
    }

    public delegate void SeedCallback(int seed);

    public class AdvancedRandomGenerator
    {
        private static readonly SeedManager _seedManager = new SeedManager();
        private static Random _generator;

        private readonly CustomInterval _range;
        private readonly RangeType _rangeType;

        public AdvancedRandomGenerator(CustomInterval range, RangeType rangeType)
        {
            _range = range;
            _rangeType = rangeType;
        }

        public static void RegisterSeedCallback(SeedCallback callback)
        {
            _seedManager.RegisterSeedCallback(callback);
        }

        public float CustomRange()
        {
            switch (_rangeType)
            {
                case RangeType.Closed:
                    return UnityEngine.Random.Range(_range.min, _range.max + 1);
                case RangeType.Open:
                    return UnityEngine.Random.Range(_range.min, _range.max);
                case RangeType.HalfOpen:
                    return UnityEngine.Random.Range(_range.min, _range.max + 1);
                default:
                    throw new ArgumentOutOfRangeException(nameof(_rangeType), _rangeType, null);
            }
        }

        public static AdvancedRandomGenerator Seeded(int seed)
        {
            UnityEngine.Random.Seed(seed);
            return new AdvancedRandomGenerator(_defaultRange, RangeType.Closed); // Default range for seeded generation
        }

        private static CustomInterval _defaultRange = new CustomInterval() { min = 0, max = 1 };
    }

    public class SeedManager
    {
        private readonly List<SeedCallback> _callbacks;
        private int _currentSeed;

        public SeedManager()
        {
            _currentSeed = UnityEngine.Random.Range(int.MinValue, int.MaxValue);
            _callbacks = new List<SeedCallback>();
        }

        public void RegisterSeedCallback(SeedCallback callback)
        {
            if (callback == null)
                throw new ArgumentNullException(nameof(callback));

            _callbacks.Add(callback);
        }

        public int GetNextSeed()
        {
            var nextSeed = UnityEngine.Random.Range(int.MinValue, int.MaxValue);
            while (_currentSeed == nextSeed)
                nextSeed = UnityEngine.Random.Range(int.MinValue, int.MaxValue); // Ensure uniqueness of the seed value

            _callbacks.ForEach(callback => callback(_nextSeed));
            _currentSeed = nextSeed;

            return _currentSeed;
        }
    }
