import express from 'express';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import mongoose from 'mongoose';
import Session from './SessionModel';

const router = express.Router();

// Session creation route (POST /sessions)
router.post('/', async (req, res) => {
  try {
    const user = await User.findOne({ email: req.body.email });

    if (!user) {
      return res.status(401).send('Invalid credentials');
    }

    const isValidPassword = await bcrypt.compare(req.body.password, user.password);

    if (!isValidPassword) {
      return res.status(401).send('Invalid credentials');
    }

    const sessionToken = jwt.sign({ userId: user._id }, process.env.JWT_SECRET);
    const newSession = await Session.create({ userId: user._id, token: sessionToken, expirationTime: Date.now() + 60 * 60 * 24 }); // Expire session in 1 day

    res.status(201).send({ sessionToken });
  } catch (error) {
    console.error(error);
    res.status(500).send('Internal server error');
  }
});
```

