```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading;
using System.Threading.Tasks;

namespace MultiTenantApplication.Data
{
    public class DatabaseConnectionManager
    {
        private readonly Dictionary<string, string> _tenantConnectionStrings;
        private readonly Dictionary<string, PooledDatabaseConnection> _connectionPool;
        private const string ConnectionStringTemplate = "{0}_{1}";

        public DatabaseConnectionManager()
        {
            _tenantConnectionStrings = new Dictionary<string, string>();
            _connectionPool = new Dictionary<string, PooledDatabaseConnection>();
        }

        public void AddTenant(string tenantId, string connectionString)
        {
            if (string.IsNullOrWhiteSpace(tenantId)) throw new ArgumentException("Tenant ID cannot be empty or whitespace.", nameof(tenantId));
            _tenantConnectionStrings[tenantId] = connectionString;
        }

        public PooledDatabaseConnection EstablishConnection(string tenantId)
        {
            if (_connectionPool.TryGetValue(tenantId, out var connection)) return connection;

            lock (_connectionPool)
            {
                if (_connectionPool.TryGetValue(tenantId, out connection)) return connection;

                var connectionString = string.Format(ConnectionStringTemplate, _tenantConnectionStrings[tenantId], Guid.NewGuid());
                connection = new PooledDatabaseConnection(connectionString);
                _connectionPool[tenantId] = connection;
                return connection;
            }
        }

        public IDbCommand ExecuteQuery(string tenantId, string query)
        {
            var connection = EstablishConnection(tenantId);
            using (var command = connection.CreateCommand())
            {
                command.CommandText = query;
                using (var reader = command.ExecuteReader())
                {
                    // Caching and performance optimization here...
                }
                return command;
            }
        }

        public IDbTransaction BeginTransaction(string tenantId)
        {
            var connection = EstablishConnection(tenantId);
            return connection.BeginTransaction();
        }

        public void CommitTransaction(IDbTransaction transaction) => transaction.Commit();

        public void RollbackTransaction(IDbTransaction transaction) => transaction.Rollback();

        public string GetTenantConnectionString(string tenantId)
        {
            if (!_tenantConnectionStrings.TryGetValue(tenantId, out var connectionString)) throw new KeyNotFoundException($"No connection string found for tenant '{tenantId}'.");
            return connectionString;
        }

        public void CloseConnection(PooledDatabaseConnection connection)
        {
            if (connection == null) throw new ArgumentNullException(nameof(connection));

            connection.Close();
            lock (_connectionPool)
            {
                _connectionPool.Remove(connection.TenantId);
            }
        }

        public override string ToString()
        {
            var activeConnection = _connectionPool.Values.FirstOrDefault(c => c.IsActive);
            return $"DatabaseConnectionManager: Active connection for tenant '{activeConnection?.TenantId}'.";
        }
    }

    // Assuming you are using a common interface such as IDbConnection, IDbTransaction and IDbCommand for the external ORM library integration
    public class PooledDatabaseConnection : IDisposable
    {
        public string TenantId { get; }
        public bool IsActive { get; private set; }
        private readonly DbConnection _dbConnection;
        private readonly IDbTransaction _transaction;

        public PooledDatabaseConnection(string connectionString)
        {
            TenantId = Guid.NewGuid().ToString();
            _dbConnection = new DbConnection(connectionString);
        }

        public void Open()
        {
            if (IsActive) throw new InvalidOperationException("The connection is already active.");
            _dbConnection.Open();
            IsActive = true;
        }

        public IDbCommand CreateCommand() => new DbCommand(string.Empty, _dbConnection);

        public IDbTransaction BeginTransaction()
        {
            if (!IsActive) throw new InvalidOperationException("The connection is not active.");
            return _transaction ?? (_transaction = _dbConnection.BeginTransaction());
        }

        public void Close()
        {
            if (!IsActive) throw new InvalidOperationException("The connection is not active.");
            IsActive = false;
            _transaction?.Dispose();
            _transaction = null;
            _dbConnection.Close();
            _dbConnection.Dispose();
        }

        public void Dispose()
        {
            Close();
            GC.SuppressFinalize(this);
        }
    }
}
```

