import json
import os
import threading
import hashlib
from collections import defaultdict
import aiofiles
import logging
from typing import Dict, Any, Callable
import zipp

class Serializable:
    id: str
    __factory__: dict = defaultdict(lambda: None)

    @staticmethod
    def from_json(json_str: str) -> 'Serializable':
        obj = json.loads(json_str)
        return cls.__get_factory__(obj['__class__']).from_json(json_str)

    @classmethod
    def to_json(cls, instance: 'Serializable') -> str:
        return json.dumps(instance.__dict__, default=lambda o: o.__dict__)

    @classmethod
    def get_factory(cls, factory: Callable) -> None:
        cls.__factory__[factory.__name__] = factory

    @staticmethod
    def __get_factory__(cls_name: str) -> Callable:
        return cls.__factory__.get(cls_name, cls)

class JSONLoader:
    def __init__(self):
        self.loaded_files = set()
        self.versions = defaultdict(int)
        self.file_lock = threading.Lock()
        self.logger = logging.getLogger(__name__)

    async def _load_files(self, directory: str) -> None:
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.endswith('.json'):
                    await self._load_file(os.path.join(root, file))

    async def _load_file(self, file_path: str) -> None:
        with self.file_lock:
            if file_path in self.loaded_files:
                return
            self.loaded_files.add(file_path)

        try:
            async with aiofiles.open(file_path, 'r') as f:
                data = await f.read()
                version = int(os.path.basename(file_path).replace('.json', ''))

                if version not in self.versions or version > self.versions[file_path]:
                    self.versions[file_path] = version
                    serializable = Serializable.from_json(data)
                    for base, superclass in serializable.__mro__:
                        if base not in (Serializable, object):  # Prevent circular dependencies
                            self._load_files(os.path.dirname(file_path))

                else:
                    self.logger.warning(f"Skipping already loaded file {file_path}")

        except Exception as e:
            self.logger.error(f"Error loading file {file_path}: {e}", exc_info=True)

    async def load(self, directory: str) -> None:
        tasks = []
        for root, dirs, files in os.walk(directory):
            if len(files) == 0:
                continue
            task = self._load_files(os.path.abspath(root))
            tasks.append(task)
        await asyncio.gather(*tasks)

class SerializationHelper:
    @staticmethod
    def dumps(obj: Any, *, skipkeys=None, default=None, **kw) -> str:
        if not hasattr(obj, '__iter__'):
            obj = (obj, )
        return json.dumps(obj, skipkeys=skipkeys, default=default, **kw)

    @staticmethod
    def loads(s: str) -> Any:
        return json.loads(s)

def serialize(obj):
    """
    Serializes an object using pickle or JSON, depending on the availability of the pickle module.
    """
    try:
        import pickle
        return pickle.dumps(obj)
    except ImportError:
        pass
    return SerializationHelper.dumps(obj)

def deserialize(b: bytes):
    """
    Deserializes a byte array into an object using pickle or JSON, depending on the availability of the pickle module.
    """
    try:
        import pickle
        obj = pickle.loads(b)
        return obj
    except (ImportError, EOFError, TypeError):
        pass
    obj = SerializationHelper.loads(b)
    return obj

def hash_password(password: str) -> str:
    hasher = hashlib.sha256(password.encode())
    return hasher.hexdigest()

if __name__ == "__main__":
    logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')
    json_loader = JSONLoader()
    asyncio.run(json_loader.load('path/to/your/files'))
```

