int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input binary file> <output file> <rules> <log directory> <logging service endpoint>\n", argv[0]);
        return 1;
    }

    // Initialize logging service
    init_log_service(argv[5]);

    // Load rules from string
    char **rules = parse_rules(argv[3]);

    // Open input and output files
    FILE *input_file = fopen(argv[1], "rb");
    if (!input_file) {
        perror("Error opening input file");
        return 2;
    }

    FILE *output_file = fopen(argv[2], "wb");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return 3;
    }

    // Process log files in the specified directory
    DIR *dir = opendir(argv[4]);
    if (!dir) {
        perror("Error opening log directory");
        fclose(input_file);
        fclose(output_file);
        return 4;
    }

    // Cache for frequently accessed log files
    Cache cache;
    initialize_cache(&cache, MAX_CACHE_SIZE);

    // Concurrently process the log files within the specified directory
    bool running = true;
    pthread_t threads[NUM_THREADS];
    DirIterator *iterator = create_dir_iterator(dir);

    while (running) {
        DirEntry *entry = read_directory_entry(iterator);
        if (!entry) {
            destroy_dir_iterator(iterator);
            running = false;
            continue;
        }

        if (strstr(entry->name, ".log")) {
            LogFileData *data = malloc(sizeof(LogFileData));
            data->file = open_log_file(entry->path, &cache);
            if (!data->file) {
                free(data);
                continue;
            }
            data->line = 0;
            pthread_create(&threads[data->line], NULL, process_log_file, data);
            data->line++;
        }
    }

    destroy_dir_iterator(iterator);

    for (int i = 0; i < data->line; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Write output file
    write_output_file(output_file, rules, &cache);

    // Cleanup logging service
    cleanup_log_service();

    return 0;
}
