<?php
namespace App\Authentication;

abstract class Authenticator
{
    protected $provider;
    protected $cache;

    public function __construct($provider, Cache $cache)
    {
        $this->provider = $provider;
        $this->cache = $cache;
    }

    abstract public function authenticate(string $code): bool;

    protected function getUserInfo(string $accessToken)
    {
        if ($userInfo = $this->cache->get($accessToken)) {
            return $userInfo;
        }

        try {
            $response = $this->provider->get('/api/user', $accessToken);
            $userInfo = json_decode((string) $response->getBody(), true);
            $this->cache->set($accessToken, $userInfo, 60 * 60); // Cache for 1 hour
            return $userInfo;
        } catch (\Exception $e) {
            // Log error and fallback mechanism here
        }
    }
}

