using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using StackExchange.Redis;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

namespace UserProfileApi
{
    public class UserIdValidator : JsonConverter<Guid>
    {
        public override Guid ReadJson(JsonReader reader, Type objectType, Guid existingValue, bool hasExistingValue, JsonSerializer serializer)
        {
            var value = serializer.Deserialize<string>(reader);
            return Guid.Parse(value);
        }

        public override void WriteJson(JsonWriter writer, Guid value, JsonSerializer serializer)
        {
            writer.WriteValue(value.ToString());
        }
    }

    public class ApiClient
    {
        private readonly HttpClient _httpClient;
        private readonly IDatabase _cache;
        private readonly TimeSpan _expirationTime;
        private readonly int _maxRetries;
        private readonly string _apiKey;

        public ApiClient(HttpClient httpClient, IDatabase cache, TimeSpan expirationTime = default, int maxRetries = 3, string apiKey = null)
        {
            _httpClient = httpClient;
            _cache = cache;
            _expirationTime = expirationTime;
            _maxRetries = maxRetries;
            _apiKey = apiKey;
        }

        public async Task<IEnumerable<UserProfile>> FetchUserProfilesAsync(IEnumerable<Guid> userIds)
        {
            var tasks = userIds.Select(async id => await FetchUserProfileAsync(id)).ToList();
            var results = await Task.WhenAll(tasks);
            return results.Where(r => r != null).ToList();
        }

        private async Task<UserProfile> FetchUserProfileAsync(Guid userId)
        {
            var cacheKey = $"user-profile:{userId}";
            var cachedResult = _cache.StringGet(cacheKey);

            if (cachedResult.HasValue)
            {
                return JsonConvert.DeserializeObject<UserProfile>(cachedResult);
            }

            var apiEndpoint = "https://api.example.com/user/{userId}"; // Replace this with your actual API endpoint
            var requestUri = new Uri(string.Format(apiEndpoint, userId));

            using (var request = new HttpRequestMessage())
            {
                request.Method = HttpMethod.Get;
                request.RequestUri = requestUri;

                if (_apiKey != null)
                {
                    request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);
                }

                var response = await _httpClient.SendAsync(request).ConfigureAwait(false);

                if (!response.IsSuccessStatusCode)
                {
                    HandleApiRequestFailure(userId, response);
                    return null;
                }

                var contentStream = await response.Content.ReadAsStreamAsync().ConfigureAwait(false);
                using (var reader = new StreamReader(contentStream))
                {
                    var userProfileJson = await reader.ReadToEndAsync().ConfigureAwait(false);
                    var userProfile = JsonConvert.DeserializeObject<UserProfile>(userProfileJson, new UserIdValidator());
                    _cache.StringSet(cacheKey, userProfileJson, _expirationTime);
                    return userProfile;
                }
            }
        }

        private void HandleApiRequestFailure(Guid userId, HttpResponseMessage response)
        {
            var retryCount = _cache.Increment($"api-request-retries:{userId}", 1);

            if (retryCount > _maxRetries)
            {
                LogApiRequestFailure(userId, response);
            }
            else
            {
                Task.Delay(_expirationTime).ContinueWith(t => FetchUserProfileAsync(userId));
            }
        }

        private void LogApiRequestFailure(Guid userId, HttpResponseMessage response)
        {
            // Replace this with your actual logging implementation
            Console.WriteLine($"API request for user '{userId}' failed with status code: {response.StatusCode}");
        }
    }

    public class UserProfile
    {
        // Define properties of the user profile object here
    }
}
