```python
import json
import os
import sys
import concurrent.futures
from typing import Dict, List, Any, Type
import hashlib
import zipfile

class SerializableObject:
    __registry: Dict[str, Type] = {}
    _instances: List["SerializableObject"] = []

    @staticmethod
    def register(cls):
        SerializableObject.__registry[cls.ID] = cls

    @staticmethod
    def from_json(data: str) -> "SerializableObject":
        instance = json.loads(data, cls=SerializableObjectFromJSON)
        SerializableObject._instances.append(instance)
        return instance

    @staticmethod
    def to_json() -> str:
        return json.dumps(SerializableObject._serialize(), default=SerializableObject.default)

    @staticmethod
    def _serialize() -> Dict[str, Any]:
        serialized = {}
        for instance in SerializableObject._instances:
            if hasattr(instance, '_json_keys'):
                serialized[instance.ID] = instance._json_keys(instance)
        return serialized

    @staticmethod
    def default(obj):
        if isinstance(obj, SerializableObject):
            return obj.ID
        raise TypeError(f"Object of type {type(obj)} is not JSON serializable")

class SerializableObjectFromJSON(SerializableObject):
    ID = None

    def __init__(self, data: Dict[str, Any]):
        self._json_keys = lambda obj: obj
        for key, value in data.items():
            setattr(self, key, value)
        self.ID = type(self).ID
        SerializableObject._instances.append(self)

class JsonManager:
    def __init__(self, directory: str):
        self.directory = directory

    async def load_files(self):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = []
            for filename in os.listdir(self.directory):
                if filename.endswith(".json"):
                    futures.append(executor.submit(self._load_file, filename))
            return await concurrent.futures.gather(*futures)

    async def _load_file(self, filename: str):
        try:
            with open(os.path.join(self.directory, filename), "r") as file:
                data = json.load(file)
                cls = SerializableObject.__registry[data["class"]]
                instance = cls.from_json(data["object"])
        except Exception as e:
            print(f"Error loading {filename}: {e}")
            return None
        else:
            return instance

    def insert(self, forward_list: List[str], first: str, second: str, position=None):
        if position is not None and not 0 <= position < len(forward_list):
            raise IndexError("Position index out of bounds")
        index = next((i for i, item in enumerate(forward_list) if item == first), None)
        if index is None:
            forward_list.append(second)
        else:
            forward_list.insert(index + (1 if position is not None and 0 <= position < len(forward_list) else len(forward_list)), second)

class SerializableDirectoryProcessor:
    def __init__(self, directory: str, extensions: List[str] = [".txt", ".log", ".csv", ".json", ".zip"]):
        self.directory = directory
        self.extensions = extensions
        self.stats = {"lines": 0, "words": 0, "characters": 0}

    def process(self):
        for root, dirs, files in os.walk(self.directory):
            for file in files:
                if not any(extension in file for extension in self.extensions):
                    continue
                ext = os.path.splitext(file)[1]
                if ext == ".zip":
                    with zipfile.ZipFile(os.path.join(root, file), "r") as zf:
                        for member in zf.namelist():
                            self._process_file(os.path.join(root, file), member)
                else:
                    self._process_file(os.path.join(root, file))

    def _process_file(self, path: str, member=None):
        try:
            with open(path, "r") as file:
                for line in file:
                    self.stats["lines"] += 1
                    words = len(line.split())
                    self.stats["words"] += words
                    self.stats["characters"] += sum(c.isalpha() and len(c) or 1 for c in line)
        except Exception as e:
            print(f"Error processing {path}: {e}")

class HashingPassword:
    @staticmethod
    def hash_password(password: str):
        hasher = hashlib.sha256()
        hasher.update(password.encode())
        return hasher.hexdigest()

    @staticmethod
    def generate_random_string(serialized_object: bytes) -> str:
        random_string = ""
        for char in HashingPassword.hash_password(serialized_object):
            if len(random_string) > 128:
                break
            random_string += char.upper() if char.isupper() else char.lower()
        return random_string
```

