```c
#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include <string.h>

#define MEM_LIMIT (50 * 1024 * 1024) // 50MB limit

typedef struct {
    int64_t* numbers;
    size_t capacity;
    size_t size;
} IntArray;

IntArray* int_array_new() {
    return calloc(1, sizeof(IntArray));
}

void int_array_destroy(IntArray* array) {
    if (array->numbers) {
        free(array->numbers);
        array->numbers = NULL;
    }
    array->capacity = 0;
    array->size = 0;
}

void int_array_resize(IntArray* array, size_t newCapacity) {
    if (newCapacity > MEM_LIMIT / sizeof(int64_t)) {
        fprintf(stderr, "Memory limit of 50MB exceeded\n");
        return;
    }
    int64_t* temp = realloc(array->numbers, newCapacity * sizeof(int64_t));
    if (!temp) {
        fprintf(stderr, "Out of memory\n");
        return;
    }
    array->numbers = temp;
    array->capacity = newCapacity;
}

void int_array_append(IntArray* array, int64_t number) {
    if (array->size == array->capacity) {
        int_array_resize(array, array->capacity * 2);
    }
    array->numbers[array->size++] = number;
}

void find_max(const IntArray* array, int64_t* max) {
    if (array->size == 0) {
        *max = 0;
        return;
    }
    *max = array->numbers[0];
    size_t i;
    for (i = 1; i < array->size; ++i) {
        if (array->numbers[i] > *max) {
            *max = array->numbers[i];
        }
    }
}

int main() {
    IntArray* array = int_array_new();
    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        char* endptr;
        int64_t number = strtoimax(line, &endptr, 10);
        if (endptr == line + strlen(line)) { // invalid input
            fprintf(stderr, "Invalid integer input: %s\n", line);
            continue;
        }
        if (number < INT64_MIN || number > INT64_MAX) { // out of range
            fprintf(stderr, "Integer out of range: %" PRId64 "\n", number);
            continue;
        }
        int64_t max = 0;
        find_max(array, &max);
        int64_t temp = *endptr == '\n' ? number : -1;
        if (temp >= 0) { // end of input
            int64_t tmp[1] = { max };
            find_max(array, tmp);
            printf("The largest integer is: %" PRId64 "\n", max > tmp[0] ? max : tmp[0]);
            break;
        }
        int_array_append(array, number);
    }
    int_array_destroy(array);
    return 0;
}
```

