        _logger = logger;
        _rabbitMqModel = rabbitMqModel;
    }

    public async Task UpdateAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
            throw new ArgumentException("All parameters must be provided.");

        try
        {
            await _cache.SetAsync(CombineKeys(pageSectionId, elementId), htmlContent);

            var queueName = "PageRefreshQueue";
            _rabbitMqModel.QueueDeclare(queue: queueName, durable: true, exclusive: false, autoDelete: false, arguments: null);
            _rabbitMqModel.BasicPublish(exchange: "", routingKey: queueName, basicProperties: null, body: Encoding.UTF8.GetBytes("PageRefresh"));
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element HTML content.");
            throw;
        }
    }

    private string CombineKeys(string pageSectionId, string elementId) => $"{pageSectionId}:{elementId}";
}
