function renderScripts(scripts) {
    let renderedScripts = [];

    scripts.forEach((script) => {
        if (!script || !script.code || !script.type) return;

        const scriptKey = `${Date.now()}-${Math.random()}`;
        renderedScripts.push(`<script key="${scriptKey}" type="${script.type}" data-async="${script.async}" data-defer="${script.defer}" data-crossorigin="${script.crossorigin || ''}">\n${script.code}\n</script>`);
    });

    return renderedScripts.join('');
