    private readonly ILogger<SiteManager> _logger;
    private readonly IConfiguration _config;
    private readonly Dictionary<string, SiteData> _sites = new Dictionary<string, SiteData>();

    public SiteManager(ILogger<SiteManager> logger, IConfiguration config)
    {
        _logger = logger;
        _config = config;
    }

    public async Task AddSiteAsync(string siteName, string directoryPath)
    {
        // Validate directory path and ensure accessibility
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

        // Ensure the site name follows standard naming conventions
        if (IsInvalidSiteName(siteName))
            throw new ArgumentException("Invalid site name provided.", nameof(siteName));

        lock (_sites)
        {
            if (_sites.ContainsKey(siteName))
                throw new Exception($"The site '{siteName}' already exists.");

            // Check for web.config file; integrate with external configuration service if absent
            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                // Fetch default settings from the external configuration management service
                await FetchDefaultSettingsAsync(_config);
            }

            // Allocate unique base port number for the site
            var availablePort = FindAvailablePort();

            // Create and configure web host builder
            var webHostBuilder = new WebHostBuilder()
                .UseKestrel()
                .UseContentRoot(directoryPath)
                .ConfigureAppConfiguration((hostingContext, configuration) =>
                {
                    // Load the web.config file if it exists
                    if (File.Exists(webConfigPath))
                        configuration.Sources.Add(new FileConfigurationSource(webConfigPath));
                })
                .UseStartup<Startup>()
                .UseUrls($"http://localhost:{availablePort}")
                .UseIISIntegration();

            // Start the web application asynchronously
            var site = new SiteData { Name = siteName, Port = availablePort };
            _sites.Add(siteName, site);
            await webHostBuilder.RunAsync();
        }
    }

    private bool IsInvalidSiteName(string siteName) => string.IsNullOrWhiteSpace(siteName) || siteName.Length > 64 || Regex.IsMatch(siteName, @"[^\w\d\-.]");

