mod logger {
    use super::*;

    pub fn init() {
        let builder = LoggerBuilder::new();
        builder.format(|buf, record| {
            write!(
                buf,
                "[{}] {}: {}",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                record.level(),
                record.args()
            )
        });
        builder.target(Target::Stderr);
        builder.init().unwrap();
    }
}

lazy_static! {
    static ref MY_DIR: Mutex<Option<TempDir>> = Mutex::new(None);
}

pub async fn initialize_directory() {
    let mut env = env::var_os("MY_DIR_PATH");
    let dir_path = if env.is_none() {
        let temp_dir = TempDir::new("my_app").unwrap();
        fs::set_permissions(temp_dir.path(), recursive=true)
            .expect("Failed to set permissions on the new directory.");
        Some(temp_dir)
    } else {
        let dir_path = env.unwrap().into_string().parse::<std::path::PathBuf>().unwrap();
        if !fs::metadata(dir_path).is_ok() {
            panic!("The specified directory does not exist.");
        }
        Some(dir_path)
    };

    *MY_DIR.lock().unwrap() = Some(dir_path);
    env::set_var("MY_DIR_PATH", dir_path.to_str().unwrap());
    logger::info!("Created or used working directory: {}", dir_path.display());

    spawn_blocking(move || {
        let cleanup_interval = std::time::Duration::from_secs(600); // 10 minutes
        loop {
            let mut guard = MY_DIR.lock().unwrap();
            let dir_path = (*guard).take().unwrap();
            let cleanup = || {
                logger::info!("Cleaning up working directory: {}", dir_path.display());
                // Implement your custom cleanup logic here, such as deleting files based on their age or type.
            };

            if let Some(dir) = *guard {
                let used_space = fs::metadata(dir.path())
                    .unwrap()
                    .created()
                    .map(|meta| meta.len() as f64 / 1024.0 / 1024.0)
                    .unwrap_or(0.0);
                let total_space = fs::metadata("/").unwrap().len() as f64 / 1024.0 / 1024.0;
                if used_space > (total_space * 0.8) {
                    cleanup();
                }
            }

            tokio::task::sleep(cleanup_interval).await;
        }
    });
}
```

