```javascript
import axios from 'axios';
import Lodash from 'lodash';

const API_KEYS = {
  API1: 'yourApiKey1',
  API2: 'yourApiKey2',
  API3: 'yourApiKey3'
};

let pendingRequests = 0;
const MAX_REQUESTS = 5; // Adjust as per your rate limit requirements

function fetchDynamicContent(selector) {
  const elements = document.querySelectorAll(selector);

  if (!elements || !elements.length) return;

  const processElement = (element, callback) => {
    pendingRequests++;

    const apiKey = element.dataset.apiKey || '';
    const apiUrl = Lodash.pickBy(API_KEYS, { [apiKey]: true})[apiKey];

    if (!apiUrl) return;

    axios.get(apiUrl)
      .then((response) => {
        pendingRequests--;
        callback(element, response.data);
      })
      .catch((error) => {
        pendingRequests--;
        handleError(element, error);
      });
  };

  const handleError = (element, error) => {
    if (!element.dataset.fallbackContent) return;
    element.innerHTML = element.dataset.fallbackContent;
  };

  Lodash.forEach(elements, (element) => processElement(element, (element, data) => {
    // Use setTimeout for UI thread safety and parallel processing
    setTimeout(() => integrateContent(element, data), 0);
  }));
}

function integrateContent(element, data) {
  if (!element.dataset.contentSelector) return;

  const contentElement = document.querySelector(element.dataset.contentSelector);

  if (contentElement) {
    contentElement.innerHTML = data;
  } else {
    console.error(`Missing content selector element: ${element.dataset.contentSelector}`);
  }
}
```

