    private Map<String, File> cache = new java.util.WeakHashMap<>();
    private ScheduledExecutorService scheduler;

    public void downloadImageResources(List<String> urls) {
        for (String url : urls) {
            validateUrl(url);
            queue.offer(url);
        }
        startDownloadThread();
    }

    private void startDownloadThread() {
        if (scheduler == null || scheduler.isShutdown()) {
            scheduler = Executors.newScheduledThreadPool(Runtime.getRuntime().availableProcessors());
        }
        scheduler.execute(this::processQueue);
    }

    private void processQueue() {
        while (!queue.isEmpty() && !scheduler.isShutdown()) {
            try {
                String url = queue.poll();
                downloadAndProcessImage(url);
            } catch (ConcurrentModificationException e) {
                // Handle concurrent modification exception gracefully, perhaps by retrying the operation later
