```java
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;
import com.google.gson.*;
import org.slf4j.*;

public class UserProfileFetcher {
    private static final Logger LOGGER = LoggerFactory.getLogger(UserProfileFetcher.class);
    private final CacheManager cacheManager;
    private final List<ApiClient> apiClients;

    public UserProfileFetcher(CacheManager cacheManager, List<ApiClient> apiClients) {
        this.cacheManager = cacheManager;
        this.apiClients = apiClients;
    }

    public Future<Map<Integer, UserProfile>> fetchProfilesAsync(List<Integer> userIds) throws ExecutionException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(Math.min(apiClients.size(), Runtime.getRuntime().availableProcessors() * 2));
        Map<Integer, Future<UserProfile>> futures = new ConcurrentHashMap<>();

        for (Integer userId : userIds) {
            ApiClient client = findApiClientForUserId(userId);
            if (client == null) {
                continue; // No API client for this user ID, skip it.
            }

            Callable<UserProfile> callable = () -> fetchAndValidateUserProfile(client, userId);
            Future<UserProfile> future = executor.submit(callable);
            futures.put(userId, future);
        }

        Map<Integer, UserProfile> results = new ConcurrentHashMap<>();
        for (Future<UserProfile> future : futures.values()) {
            try {
                UserProfile userProfile = future.get();
                if (userProfile != null) {
                    results.put(userProfile.getId(), userProfile);
                    cacheManager.put(userId, userProfile);
                }
            } catch (ApiException e) {
                LOGGER.error("Failed to fetch user profile for ID: {}", userId, e);
            } catch (TimeoutException e) {
                LOGGER.warn("Timeout while fetching user profile for ID: {}", userId);
