using System;
using System.Collections.Generic;
using System.Xml.Linq;
using System.Threading;
using System.ServiceProcess;
using Newtonsoft.Json;
using RabbitMQ.Client;

namespace TileWorldServiceManager
{
    public class Configuration
    {
        public int TileSize { get; set; }
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public float CameraSpeed { get; set; }
        public string RabbitMqUrl { get; set; }
    }

    public class ServiceManager
    {
        private Configuration _configuration;
        private ServiceController _serviceController;
        private IModel _rabbitMqChannel;
        private Random _random = new Random();

        public void Initialize(string configFilePath)
        {
            var configurationXml = XDocument.Load(configFilePath);
            _configuration = JsonConvert.DeserializeObject<Configuration>(configurationXml.Root.Value);

            ValidateConfiguration();

            ConnectToRabbitMq();
        }

        private void ValidateConfiguration()
        {
            if (_configuration == null)
                throw new ArgumentNullException(nameof(_configuration));

            if (_configuration.TileSize <= 0)
                throw new ArgumentOutOfRangeException("TileSize must be greater than zero.");

            if (_configuration.WorldWidth <= 0)
                throw new ArgumentOutOfRangeException("WorldWidth must be greater than zero.");

            if (_configuration.WorldHeight <= 0)
                throw new ArgumentOutOfRangeException("WorldHeight must be greater than zero.");

            if (_configuration.CameraSpeed <= 0)
                throw new ArgumentOutOfRangeException("CameraSpeed must be greater than zero.");
        }

        private void ConnectToRabbitMq()
        {
            var factory = new ConnectionFactory { Uri = new Uri(_configuration.RabbitMqUrl) };
            using (var connection = factory.CreateConnection())
            using (var channel = connection.CreateModel())
            {
                _rabbitMqChannel = channel;
            }
        }

        public void StartService()
        {
            if (_serviceController == null)
            {
                var serviceName = "YourServiceName";
                _serviceController = new ServiceController(serviceName);
            }

            if (_serviceController.Status != ServiceControllerStatus.Stopped)
                return;

            _serviceController.Start();
        }

        public void StopService()
        {
            if (_serviceController == null)
                return;

            _serviceController.Stop();
            SendMessageToRabbitMq("YourServiceStopped");
        }

        private void SendMessageToRabbitMq(string message)
        {
            var body = Encoding.UTF8.GetBytes(message);
            _rabbitMqChannel.BasicPublish("", "your_queue", null, body);
        }

        public void Run()
        {
            while (true)
            {
                try
                {
                    Thread.Sleep(_random.Next(1000, 5000)); // Random delay between service starts
                    StartService();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"An error occurred: {ex}");
                }
            }
        }
    }

    class Program
    {
        static void Main()
        {
            var serviceManager = new ServiceManager();
            serviceManager.Initialize("config.xml");
            serviceManager.Run();
        }
    }
}
