const fs = require('fs');
const path = require('path');
const { promises: { readFile } } = fs;
const { exit } = require('process');
const chalk = require('chalk');
const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');
const npm = require('npm');
const yarn = require('yarn');

// ... Implement functions to parse TIFF image and asynchronous reduce() method here

(async () => {
  const argv = yargs(hideBin(process.argv[0]))
    .option('pkgManager', {
      alias: 'p',
      choices: ['npm', 'yarn'],
      default: 'npm',
      describe: 'Package manager to use for dependency resolution',
    })
    .help()
    .alias('h').argv;

  const configPath = path.join(__dirname, 'config.json');
  const configData = JSON.parse(await readFile(configPath, 'utf8'));

  let pkgManager;
  switch (argv.pkgManager) {
    case 'yarn':
      pkgManager = yarn;
      break;
    default:
      pkgManager = npm;
  }

  const modules = new Map();

  async function loadModule(moduleName, dependencies) {
    if (modules.has(moduleName)) return modules.get(moduleName);

    try {
      const modulePath = await pkgManager.load(moduleName, dependencies);
      const module = require(modulePath);
      modules.set(moduleName, module);
      console.log(`Loaded ${chalk.green(moduleName)}`);
      return module;
    } catch (error) {
      console.error(`Error loading ${chalk.red(moduleName)}:`, error.message);
      throw error;
    }
  }

  async function executeModules() {
    for (const [index, moduleName] of configData.modules.entries()) {
      try {
        const module = await loadModule(moduleName, configData.dependencies[moduleName]);
        if (Array.isArray(configData.modules[index + 1])) {
          executeModules().then(() => module.execute());
        } else {
          module.execute();
        }
      } catch (error) {
        console.error(`Error executing ${chalk.red(moduleName)}:`, error.message);
      }
    }
  }

  try {
    await executeModules();
  } catch (error) {
    console.error('An error occurred during the execution of modules:', error.message);
    exit(1);
  }
})();
```

