using System;
using UnityEngine;
using System.Xml.Serialization;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public abstract class CustomRandomGenerator<T> where T : struct, IConvertible
{
    protected T minValue;
    protected T maxValue;
    private readonly Random _random;
    private bool _isSeeded;

    public event Action<int, T> OnNewSeedGenerated;

    public CustomRandomGenerator() : this(new Random()) { }

    public CustomRandomGenerator(Random seed)
    {
        _random = seed;
        _random.AddEntropy(_random.GetState());
        Initialize();
    }

    protected virtual void Initialize()
    {
        XmlSerializer serializer = new XmlSerializer(typeof(RangeLimits<T>));
        using (var reader = new System.IO.StreamReader("config.xml"))
        {
            RangeLimits<T> limits = serializer.Deserialize(reader) as RangeLimits<T>;
            if (limits != null)
            {
                minValue = limits.Min;
                maxValue = limits.Max;
            }
            else
            {
                throw new FileNotFoundException("Could not find configuration file.");
            }
        }
    }

    public virtual T CustomRange(bool inclusive, bool isOpenEnded)
    {
        if (isOpenEnded)
        {
            // Implement open interval logic here.
        }
        else
        {
            // Implement closed interval and half-open interval logic here.
        }
    }

    public virtual T Next(bool inclusive, bool isOpenEnded)
    {
        _isSeeded = true;
        UnityEngine.Random.Seed(_random);
        return CustomRange(inclusive, isOpenEnded);
    }

    public virtual T Next()
    {
        return Next(false, false);
    }

    public void SetSeed(int seed)
    {
        _isSeeded = true;
        UnityEngine.Random.Seed(seed);
        OnNewSeedGenerated?.Invoke(seed, default(T));
    }
}

[XmlRoot("range_limits")]
public class RangeLimits<T> where T : struct, IConvertible
{
    [XmlElement("min")]
    public T Min { get; set; }

    [XmlElement("max")]
    public T Max { get; set; }
}
