using Google.Apis.CryptoKeyManagementService.v1;
using Google.Apis.CryptoKeyManagementService.v1.Data;
using Google.Apis.Services;
using Google.Apis.Util.Collections;

namespace EncryptionLibrary
{
    public class AesGcmEncryptor
    {
        private readonly CryptoKeyManagementServiceClient _keyManagementServiceClient;

        public AesGcmEncryptor(string serviceAccountEmail, string privateKeyFilePath)
        {
            _keyManagementServiceClient = new CryptoKeyManagementServiceClient.Initializer()
            {
                HttpClientInitializer = new System.Net.Http.Credentials(new UserNamePasswordCredentials(serviceAccountEmail, File.ReadAllText(privateKeyFilePath))),
                ApplicationName = "EncryptionLibrary"
            }.Build();
        }

        public async Task<byte[]> EncryptAsync(string keyId, string aad, byte[] dataToEncrypt)
        {
            var key = await GetOrCreateKeyAsync(keyId);

            using (var aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(key.CreationTime.Data.Value);
                var aesAlgorithm = new AesGcm();

                // Handle exceptions and log errors here...

                ICryptoTransform encryptor = aesAlgorithm.CreateEncryptor(aes.Key, Encoding.UTF8.GetBytes(aad));

                byte[] cipherText;
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(dataToEncrypt, 0, dataToEncrypt.Length);
                        cryptoStream.FlushFinalBlock();
                        cipherText = memoryStream.ToArray();
                    }
                }

                // Log encrypted data and incremental progress here...

                return cipherText;
            }
        }

        public async Task<byte[]> DecryptAsync(string keyId, string aad, byte[] encryptedData)
        {
            var key = await GetOrCreateKeyAsync(keyId);

            using (var aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(key.CreationTime.Data.Value);
                var aesAlgorithm = new AesGcm();

                // Handle exceptions and log errors here...

                ICryptoTransform decryptor = aesAlgorithm.CreateDecryptor(aes.Key, Encoding.UTF8.GetBytes(aad));

                byte[] originalData;
                using (MemoryStream memoryStream = new MemoryStream(encryptedData))
                {
                    using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                    {
                        originalData = new byte[encryptedData.Length];
                        int bytesRead;

                        do
                        {
                            bytesRead = cryptoStream.Read(originalData, 0, originalData.Length);
                        } while (bytesRead > 0);
                    }
                }

                // Log decrypted data and incremental progress here...

                return originalData;
            }
        }

        private async Task<CryptoKey> GetOrCreateKeyAsync(string keyId)
        {
            try
            {
                var keyVersionName = $"versions/{DateTime.UtcNow:yyyy-MM-ddTHH:mm:ssZ}";
                var keyResource = CryptoKeyResource.Create(KeyRingId, KeyId);
                var keyVersionResource = keyResource.Versions.Get(keyVersionName);

                if (keyVersionResource.Data == null)
                {
                    await keyVersionResource.CreateAsync();
                    await keyVersionResource.CryptoKey.EncryptAsync(Rsa32EncryptionAlgorithm.RsaOawp256Sha256, RsaPaddingMode.Pkcs1);
                }

                return keyVersionResource.Data;
            }
            catch (Exception ex)
            {
                // Log exception and handle errors here...
                throw;
            }
        }

        private readonly string KeyRingId = "projects/your-project-id/locations/global/keyRings/your-key-ring-id";
    }
}
