#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 4096

struct log_entry {
    time_t timestamp;
    int server_id;
    char event[32];
    // Add more fields as needed
    double numeric_data[3];
};

struct db_conn {
    void* handle;
    pthread_mutex_t mutex;
};

// Thread-safe database functions for opening, querying, and closing connections
void init_db(struct db_conn* conn);
bool query_db(struct db_conn* conn, const char* sql);
void close_db(struct db_conn* conn);

pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
struct db_conn main_db, backup_db;
FILE* log_file;
size_t total_entries = 0;
int current_thread = 0;
char buffer[BUFFER_SIZE];

// Worker thread function
void* worker(void* arg) {
    while (true) {
        size_t read = fread(buffer, sizeof(struct log_entry), BUFFER_SIZE, log_file);
        if (read == 0) break; // Reach EOF

        for (size_t i = 0; i < read; ++i) {
            struct log_entry* entry = (struct log_entry*)(buffer + i * sizeof(struct log_entry));
            // Calculate the average of the last three numeric fields
            double avg = (entry->numeric_data[2] + entry->numeric_data[1] + entry->numeric_data[0]) / 3.0;

            pthread_mutex_lock(&data_mutex);
            // Append average to the end of the line and print in comma-separated format
            snprintf(buffer + i * sizeof(struct log_entry) + sizeof(*entry), BUFFER_SIZE - (i * sizeof(struct log_entry)), ",%f", avg);
            printf("%s\n", buffer + i * sizeof(struct log_entry));
            // Store the processed entry in the database
            store_in_db(&main_db, buffer + i * sizeof(struct log_entry));
            total_entries++;
            pthread_mutex_unlock(&data_mutex);
        }
    }

    return NULL;
}

int main() {
    // Initialize databases and open the log file
    init_db(&main_db);
    init_db(&backup_db);
    log_file = fopen("log.txt", "r");

    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    // Wait for all worker threads to finish processing the log file
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    close_db(&main_db);
    close_db(&backup_db);
    fclose(log_file);

    printf("Total processed entries: %ld\n", total_entries);

    return 0;
}
```

