using System.Threading.Tasks;
using System.Web.Http;
using Newtonsoft.Json;
using StackExchange.Redis;
using ValidationExtensions;
using XssProtectionLibrary;
using NotificationServiceAPI;

namespace MyWebApplication.Controllers
{
    public class UpdateElementController : ApiController
    {
        private readonly IDatabase _cacheDb;
        private readonly IDBConnectionManager _dbConnectionManager;
        private readonly INotificationService _notificationService;
        private readonly XssProtectionLibrary.XSSValidationEngine _xssValidator;
        private readonly SchemaValidator _schemaValidator;
        private const int MaxRequestsPerMinute = 60;
        private const int RateLimitWindowMinutes = 1;

        public UpdateElementController(IDatabase cacheDb, IDBConnectionManager dbConnectionManager, INotificationService notificationService, XssProtectionLibrary.XSSValidationEngine xssValidator, SchemaValidator schemaValidator)
        {
            _cacheDb = cacheDb;
            _dbConnectionManager = dbConnectionManager;
            _notificationService = notificationService;
            _xssValidator = xssValidator;
            _schemaValidator = schemaValidator;
        }

        [HttpPost]
        public async Task<IHttpActionResult> UpdateElement(int pageSectionId, int elementId, string content)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            var userSession = await _dbConnectionManager.GetUserSession();
            if (userSession == null || !RateLimiter.AllowRequest(userSession.UserId))
                return RateLimitReached();

            string decryptedContent;
            try
            {
                decryptedContent = TripleDESDecrypt(content, GetKey(), GetIV());
            }
            catch (CryptoException e)
            {
                return ErrorResponse(e);
            }

            var validatedContent = _xssValidator.Validate(decryptedContent) && _schemaValidator.IsValid(decryptedContent);
            if (!validatedContent)
                return XSSValidationError();

            await _dbConnectionManager.UpdateElementHtmlAsync(pageSectionId, elementId, decryptedContent);
            var logEntry = new LogEntry { Timestamp = DateTime.Now, PageSectionId = pageSectionId, ElementId = elementId, UserId = userSession?.UserId, Content = decryptedContent };
            await _dbConnectionManager.InsertLogAsync(logEntry);

            Cache.Set(CacheKey(pageSectionId, elementId), decryptedContent, TimeSpan.FromMinutes(RateLimitWindowMinutes));

            var notif = new Notification { Type = NotificationType.Update, Data = decryptedContent };
            await _notificationService.SendNotificationAsync(notif);

            return Ok();
        }

        // ... Other methods for rate limiting, caching, versioning, background job scheduler, etc.

        private static string CacheKey(int pageSectionId, int elementId) => $"{nameof(UpdateElementController)}_{pageSectionId}_{elementId}";
        private static byte[] GetKey() { /* Implement key generation logic */ }
        private static byte[] GetIV() { /* Implement IV generation logic */ }
        private static TripleDESCryptoServiceProvider CreateTripleDES() => new TripleDESCryptoServiceProvider();
        private static string TripleDESDecrypt(string encryptedData, byte[] key, byte[] iv)
        {
            using (var md5 = MD5.Create())
                key = md5.ComputeHash(key);

            using (var cryptoService = CreateTripleDES())
                cryptoService.Key = key;
                cryptoService.IV = iv;

            using (var msDecrypt = new MemoryStream(Convert.FromBase64String(encryptedData)))
            {
                var cs = new CryptoStream(msDecrypt, cryptoService.CreateDecryptor(), CryptoStreamMode.Read);
                using (var sr = new StreamReader(cs))
                    return sr.ReadToEnd();
            }
        }

        private IHttpActionResult RateLimitReached() => Json(new { Error = "Rate limit exceeded." }, System.Net.HttpStatusCode.TooManyRequests);
        private IHttpActionResult XSSValidationError() => Json(new { Error = "Invalid HTML content due to potential cross-site scripting vulnerability." }, System.Net.HttpStatusCode.BadRequest);
        private IHttpActionResult ErrorResponse(Exception e) => Json(new { Error = e.Message }, System.Net.HttpStatusCode.InternalServerError);
    }
}
