import asyncio
import json
from typing import Any, Dict, List, Type
import zlib
import hashlib
import logging
from collections import deque

class SerializableObject:
    _registry = {}

    @staticmethod
    def register(cls):
        SerializableObject._registry[cls.__name__] = cls.to_json
        return cls

    @staticmethod
    async def load_from_file(file_path, synchronous=False) -> Any:
        try:
            if synchronous:
                with open(file_path, 'r') as file:
                    data = json.load(file)
                return SerializableObject._registry[data['type']].from_json(data)
            asyncio_loader = asyncio.get_event_loop().run_in_executor(None, lambda: open(file_path, 'r').read())
            data = await asyncio.wait_for(asyncio_loader, timeout=10.0)
            return SerializableObject._registry[json.loads(data)['type']].from_json(json.loads(data))
        except Exception as e:
            logging.error(f"Failed to load file {file_path}: {e}")
            return None

    @staticmethod
    def deserialize_byte_array(byte_array: bytes) -> Any:
        try:
            decompressed = zlib.decompress(byte_array)
            obj = json.loads(decompressed)
            return SerializableObject._registry[obj['type']].from_json(obj)
        except Exception as e:
            logging.error("Failed to deserialize byte array: ", e)
            return None

    @classmethod
    def from_json(cls, data: Dict):
        if cls not in SerializableObject._registry:
            raise ValueError(f"Unknown class type: {cls.__name__}")
        return cls(**data)

    def to_json(self) -> Dict:
        return self.__dict__

    @classmethod
    def from_byte_array(cls, byte_array: bytes) -> Any:
        obj = SerializableObject.deserialize_byte_array(byte_array)
        if obj is not None and isinstance(obj, cls):
            return obj
        else:
            raise ValueError("Deserialized object is not the expected class type.")

    def hash_password(self, password: str) -> bytes:
        hasher = hashlib.sha256()
        hasher.update(password.encode())
        return hasher.digest()

    @classmethod
    def generate_random_string(cls, byte_array: bytes) -> str:
        random_string = base64.b64encode(byte_array).decode("utf-8")
        return random_string

class JsonForwardList(SerializableObject):
    def __init__(self, elements: List[str]):
        self.elements = deque(elements)

    def insert(self, search_item: str, new_items: List[str], position: int = -1) -> None:
        if position < 0:
            for item in new_items:
                self.elements.append(item)
        else:
            try:
                index = self.elements.index(search_item)
                self.elements.insert(index + 1, *new_items[1:])
            except ValueError as e:
                if position == len(self.elements):
                    self.elements.append(*new_items)
                else:
                    logging.error(f"Insertion error: {e}")

class LoggingService:
    def log(self, message: str) -> None:
        print(message)

async def load_and_execute(file_paths: List[str], synchronous=False):
    tasks = [SerializableObject.load_from_file(file_path, synchronous=synchronous) for file_path in file_paths]
    loaded_objects = await asyncio.gather(*tasks)

# Usage example:
class MyClass(SerializableObject):
    @classmethod
    def to_json(cls) -> Dict:
        return {'type': cls.__name__}

    def __init__(self, value: int):
        self.value = value

async def main():
    file_paths = ["file1.json", "file2.json"]
    logging_service = LoggingService()

    my_class_instances = await load_and_execute(file_paths)
    if my_class_instances is not None:
        for instance in my_class_instances:
            logging_service.log(f"Loaded and executed {instance.__class__.__name__}: {instance.value}")

    with open("insertion_data.txt", "r") as file:
        insertion_data = [line.split(",") for line in file.readlines()]

    json_forward_list = JsonForwardList(elements=["item1", "item2"])
    for search_item, new_items in insertion_data:
        try:
            json_forward_list.insert(search_item, new_items)
        except Exception as e:
            logging_service.log(f"Insertion error: {e}")

    password = "secret"
    hashed_password = MyClass().hash_password(password)
    random_string = MyClass().generate_random_string(hashed_password)

if __name__ == "__main__":
    asyncio.run(main())
