    private $auditLogger;

    public function __construct($db, $ipAddress, $userID, Redis $redis, Mailer $mailer, AuditLogger $auditLogger) {
        $this->db = $db;
        $this->ipAddress = $ipAddress;
        $this->userID = $userID;
        $this->redis = $redis;
        $this->mailer = $mailer;
        $this->auditLogger = $audisLogger;
    }

    public function updateClinicStatus($clinicIDs, $status, $reason) {
        try {
            // Rate limiting and IP address validation
            if (!$this->canUpdate($this->ipAddress)) {
                throw new Exception("Rate limit exceeded for your IP address.");
            }

            // Transaction start
            $this->db->beginTransaction();

            foreach ($clinicIDs as $id) {
                try {
                    // Validate clinic ID and check if it's already being updated
                    if (!$this->validateClinicID($id)) {
                        throw new Exception("Invalid clinic ID: {$id}.");
                    }

                    // Update clinic status, last modified IP address, and last modified date in the transaction
                    $this->db->exec("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
                    $this->db->bindValue(':status', $status);
                    $this->db->bindValue(':ip', $this->ipAddress);
                    $this->db->bindValue(':id', $id);
                } catch (Exception $e) {
                    // Rollback the transaction if an error occurs for a specific clinic ID
                    $this->db->rollBack();
                    throw $e;
                }
            }

            // Transaction commit and auditing
            $this->db->commit();
            $this->auditLogger->log($this->userID, $clinicIDs, $status, $reason);

            // Notify clinic administrators via email
            foreach ($clinicIDs as $id) {
                try {
                    $adminEmail = $this->db->query("SELECT admin_email FROM clinics WHERE id = :id", [':id' => $id])->fetchColumn();
                    if (!empty($adminEmail)) {
                        $this->mailer->sendNotificationEmail($adminEmail, "Clinic Status Update", "Your clinic status has been updated.");
                    }
                } catch (Exception $e) {
                    // Handle email sending errors gracefully
                }
            }
        } catch (Exception $e) {
            // Transaction rollback and logging of any exceptions or errors
            $this->db->rollBack();
            $this->auditLogger->log($this->userID, $clinicIDs, null, "Error: {$e->getMessage()}");
        }
    }

