import fetch from 'node-fetch';
import { v4 as uuidv4 } from 'uuid';
import logger from './logger'; // Centralized logging system

class ScriptTag {
  constructor(script, dependencies) {
    this.id = script.id || uuidv4();
    this.key = `script-${this.id}`;
    this.attributes = { ...script.attributes }; // Custom attributes support
    this.src = script.src;
    this.type = script.type;
    this.async = script.async || false;
    this.defer = script.defer || false;
    this.dependencies = dependencies || [];
  }
}

class ScriptManager {
  constructor() {
    this.scripts = new Map();
  }

  async fetchScripts(urls) {
    const promises = urls.map(async (url) => {
      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch script from ${url}`);
        return await response.json();
      } catch (error) {
        logger.error(`Error fetching scripts: ${error.message}`);
        return null;
      }
    });

    const results = await Promise.all(promises);
    return results.filter((result) => result !== null);
  }

  sortScriptsByDependencies(scripts) {
    const sortedScripts = scripts.slice().sort((a, b) => a.dependencies.length - b.dependencies.length);
    for (let i = 0; i < sortedScripts.length; i++) {
      for (const dependency of sortedScripts[i].dependencies) {
        const index = scripts.findIndex((script) => script.id === dependency);
        if (index !== -1 && index < i) {
          sortedScripts[i].dependencies.push(sortedScripts[index]);
          sortedScripts.splice(index, 1);
          i--;
        }
      }
    }
    return sortedScripts;
  }

  renderScripts(scripts) {
    const renderedScripts = scripts.map((script) => `<script key="${script.key}" ${Object.entries(script.attributes).map(([k, v]) => `${k}="${v}"`).join(' ')} type="${script.type}" async="${script.async}" defer="${script.defer}" src="${script.src}"></script>`);
    return renderedScripts.join('\n');
  }

  cacheScript(id, script) {
    this.scripts.set(id, script);
  }

  getCachedScript(id) {
    return this.scripts.get(id);
  }

  removeScript(id) {
    const script = this.scripts.get(id);
    if (script) this.scripts.delete(id);
    return script;
  }

  updateScript(id, newScript) {
    const oldScript = this.scripts.get(id);
    this.scripts.set(id, newScript);
    return oldScript;
  }
}

async function renderFooter(scriptObjects, apiUrl) {
  const scriptManager = new ScriptManager();

  // Fetch and sort scripts based on dependencies
  let urls = scriptObjects.map((scriptObject) => scriptObject.src);
  if (apiUrl) urls.push(apiUrl);
  const scripts = await scriptManager.fetchScripts(urls).then((fetchedScripts) => fetchedScripts.map((script) => new ScriptTag(script, script.dependencies)));
  const sortedScripts = scriptManager.sortScriptsByDependencies(scripts);

  // Render and return the HTML footer
  return scriptManager.renderScripts(sortedScripts);
}
