public class CustomDataService implements Runnable {
    private static final long serialVersionUID = 1L;
    private Object data;
    private transient JsonMapper mapper;
    private String messagingSystemUrl;

    public void loadData(String fileName) throws IOException, ClassNotFoundException {
        try (FileInputStream fis = new FileInputStream(fileName)) {
            BinaryInputStream bis = new BinaryInputStream(fis);
            this.data = mapper.readValue(bis, getDataClass());
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error while loading data from file: " + e.getMessage());
        }
    }

    public static Class<?> getDataClass() {
        // Replace with your custom data structure class
        return CustomDataStructure.class;
    }

    @Override
    public void run() {
        Random random = new Random();
        boolean serviceRunning = true;
        while (serviceRunning) {
            try {
                Thread.sleep(random.nextInt(5000));
                startService();
                Thread.sleep(random.nextInt(10000));
            } catch (InterruptedException e) {
                System.err.println("Thread interrupted while waiting: " + e.getMessage());
            }

            serviceRunning = false;
            try {
                Thread.sleep(random.nextInt(10000));
            } catch (InterruptedException e) {
                System.err.println("Thread interrupted while waiting: " + e.getMessage());
            }

            stopService();
            sendMessage();
        }
