    public class AuthController : ControllerBase {
        private readonly HttpClient _httpClient;
        private const string ApiKey = "YOUR_API_KEY";

        public AuthController(HttpClient httpClient) {
            _httpClient = httpClient;
            _httpClient.DefaultRequestHeaders.Add("X-Api-Key", ApiKey);
        }

        [HttpPost]
        public async Task<IActionResult> HashPassword([FromBody] string password) {
            if (string.IsNullOrEmpty(password)) return BadRequest();

            using (var md5 = MD5.Create()) {
                var hashedPasswordBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(password));
                var hashedPassword = BitConverter.ToString(hashedPasswordBytes).Replace("-", "");
                return Ok(hashedPassword);
            }
        }

        [HttpPost]
        public async Task<IActionResult> VerifyPassword([FromBody] VerifyPasswordRequest request) {
            if (request == null || string.IsNullOrEmpty(request.StoredHash) || string.IsNullOrEmpty(request.ProvidedPassword)) return BadRequest();

            using (var md5 = MD5.Create()) {
                var hashedProvidedPasswordBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(request.ProvidedPassword));
                if (BitConverter.ToString(hashedProvidedPasswordBytes).Replace("-", "") == request.StoredHash) return Ok();
            }

            return Unauthorized();
        }
    }

    public class VerifyPasswordRequest {
        public string StoredHash { get; set; }
        public string ProvidedPassword { get; set; }
    }
}
