#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <jansson.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sqlite3.h>
#include <curl/curl.h>

typedef struct {
    char *email;
    char *password;
    json_t *resource_bundle;
} UserAccountData;

static sqlite3 *db;
static pthread_mutex_t db_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_db() {
    sqlite3_open("users.db", &db);
}

int create_table(const char *sql) {
    char *error_message = NULL;
    if (sqlite3_exec(db, sql, NULL, 0, &error_message)) {
        fprintf(stderr, "SQL error: %s\n", error_message);
        sqlite3_free(error_message);
        return -1;
    }
    return 0;
}

int load_resource_bundle(const char *filepath, json_t **bundle) {
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    size_t len = 0;
    ssize_t bytes_read;
    char *buffer = NULL;
    while ((bytes_read = read(fd, &buffer[len], 1)) > 0) {
        len += bytes_read;
        buffer = realloc(buffer, len + 1);
        if (buffer == NULL) {
            perror("realloc");
            close(fd);
            return -1;
        }
    }

    if (len < 0) {
        perror("read");
        close(fd);
        return -1;
    }

    buffer[len] = '\0';
    *bundle = json_loads(buffer, 0, NULL);
    free(buffer);
    if (*bundle == NULL) {
        fprintf(stderr, "JSON error: %s\n", json_error_string());
        return -1;
    }

    return 0;
}

UserAccountData *get_user(const char *email) {
    UserAccountData result;
    result.email = strdup(email);

    pthread_mutex_lock(&db_mutex);
    char sql[256];
    snprintf(sql, sizeof(sql), "SELECT * FROM users WHERE email='%s';", email);
    sqlite3_stmt *statement;
    if (sqlite3_prepare_v2(db, sql, -1, &statement, 0) == SQLITE_OK) {
        while (sqlite3_step(statement) == SQLITE_ROW) {
            result.password = strdup(sqlite3_column_text(statement, 1));
            json_t *user_data = json_loads(sqlite3_column_text(statement, 2), 0, NULL);
            result.resource_bundle = user_data;
        }
    } else {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
    }
    pthread_mutex_unlock(&db_mutex);

    if (result.password == NULL) result.password = strdup("");
    if (result.resource_bundle == NULL) result.resource_bundle = json_object();

    return &result;
}

int process_request(UserAccountData *data, const char *sub_action, json_t **response) {
    json_t *sub_action_obj = json_object();
    if (strcmp(sub_action, "create") == 0 || strcmp(sub_action, "update") == 0 || strcmp(sub_action, "delete") == 0) {
        json_object_set_new(sub_action_obj, "success", json_boolean(!validate_request(data->resource_bundle)));
    } else {
        json_object_set_new(sub_action_obj, "error", json_string("Invalid sub action"));
        return -1;
    }

    if (strcmp(sub_action, "create") == 0) {
        // Create a new user in the database
    } else if (strcmp(sub_action, "update") == 0) {
        UserAccountData existing = *data;
        existing.password[0] = '\0'; // Remove password for updating
        UserAccountData *user = get_user(existing.email);
        if (!json_equal(user->resource_bundle, data->resource_bundle)) {
            // Update the user account in the database
        }
    } else if (strcmp(sub_action, "delete") == 0) {
        UserAccountData *user = get_user(data->email);
        if (user != NULL && json_equal(user->resource_bundle, data->resource_bundle)) {
            // Remove the user account from the database
        }
    }

    json_t *response_obj = json_pack("{ss,{ss}}", "status", "", "message", "");
    if (strcmp(sub_action, "create") == 0 || strcmp(sub_action, "update") == 0) {
        // Integrate with the external API to send a confirmation email
    }
    json_object_set(response_obj, "sub_action", sub_action_obj);
    *response = response_obj;

    return 0;
}

json_t *load_and_process_resource_bundle(const char *filepath, const char *token) {
    json_t *bundle;
    if (load_resource_bundle(filepath, &bundle) != 0) return json_pack("{ss,{ss}}", "status", "error", "message", "Failed to load resource bundle");

    UserAccountData *user = get_user((char *)json_object_get(bundle, "email"));
    if (strcmp(token, user->password) != 0) return json_pack("{ss,{ss}}", "status", "error", "message", "Invalid token");

    const char *sub_action = json_string_value(json_object_get(bundle, "sub_action"));
    json_t *response;
    if (process_request(user, sub_action, &response) != 0) return response;

    json_t *result = json_pack("{ss,{ss}}", "status", "", "message", "");
    json_object_set(result, "response", response);
    return result;
}
