async function executeCommandAndLog(command, pattern) {
  try {
    const result = await execPromise(`${command}`, { encoding: 'utf8' });
    return result.split('\n').filter((line) => line.match(pattern));
  } catch (error) {
    console.error(`Error executing command: ${command}`);
    logStream.write(`\nError: ${error.message}\nCommand: ${command}\n`);
    return [];
  }
}

async function saveResultsToDatabase(results) {
  try {
    for (const result of results) {
      await pool.query('INSERT INTO command_output (result) VALUES ($1)', [result]);
    }
  } catch (error) {
    console.error('Error saving results to database:', error);
    logStream.write(`\nError: ${error.message}\n`);
  }
}

module.exports = async function shellCommand(command, pattern) {
  const commandResults = await executeCommandAndLog(command, pattern);
  await saveResultsToDatabase(commandResults);
};
