class TestEnvironment {
public:
    virtual ~TestEnvironment() {}
    virtual void InitializeMocks(ResourceManager& resourceManager) = 0;
    virtual void Reset() = 0;
};

class AttackModuleTestEnvironment : public TestEnvironment {
public:
    explicit AttackModuleTestEnvironment(ResourceManager& resourceManager) { InitializeMocks(resourceManager); }
    void Reset() override { mocking_library::ResetAllMocks(); }
    // Implement the initialization of mocks specific to the attack module under test
