// Function Declaration
void runModuleTests(const std::string& moduleLabel, const std::vector<TestFunction>& testSuite,
                     const std::string& loggingLevel, int cooldown, ResourceManager& resourceManager);

void runModuleTests(const std::string& moduleLabel, const std::vector<TestFunction>& testSuite,
                     const std::string& loggingLevel, int cooldown, ResourceManager& resourceManager) {
    auto testEnvironment = std::make_unique<AttackModuleTestEnvironment>(resourceManager);
    testEnvironment->InitializeMocks(resourceManager);

    std::mutex logMutex;
    auto getLogLevel = [&](const std::string& level) -> bool {
        if (loggingLevel == level) return true;
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "Logging level is set to " << loggingLevel << ", but requested level is " << level << "\n";
        return false;
    };

    auto log = [&](const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::time_t now = std::time(nullptr);
        auto tm = *std::localtime(&now);
        std::cout << std::put_time(&tm, "%Y-%m-%d %H:%M:%S") << " - [" << loggingLevel << "] - " << message << "\n";
    };

    // Validation
    if (!moduleLabel.empty() && moduleLabel != nullptr) {
        log("Validating module label", std::logger::INFO);
    } else {
        log("Module label is empty or null", std::logger::ERROR);
        return;
    }

    auto connection = resourceManager.GetConnectionStructure();
    if (connection && !connection->title.empty() && connection->title != nullptr) {
        log("Validating connection title", std::logger::INFO);
    } else {
        log("Connection structure has an invalid or null title", std::logger::ERROR);
        return;
    }

    auto attackPassword = resourceManager.GetAttackPassword();
    if (attackPassword && !attackPassword->empty() && attackPassword != nullptr) {
        log("Validating attack password", std::logger::INFO);
    } else {
        log("Attack password is empty or null", std::logger::ERROR);
        return;
    }

    auto callback = resourceManager.GetCallbackFunction();
    if (!callback || !callback()) {
        log("Callback function is not set or returned false", std::logger::ERROR);
        return;
    }

    // Test execution
    for (auto test : testSuite) {
        auto start = std::chrono::steady_clock::now();
        test(moduleLabel, [&](const std::function<void()>& attackFunction) {
            using namespace std::chrono_literals;
            // Run the actual test here with asynchronous operations and mocking library calls.
            // Ensure proper initialization of the mocks before running the test and resetting them after the test.
            std::this_thread::sleep_for(cooldown * 1s);
            attackFunction();
        });
        auto end = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
