using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Threading;
using Microsoft.Extensions.Logging;
using Flurl;

public class DynamicFileMetadataAnalyzer
{
    private readonly ILogger _logger;
    private readonly string _directoryPath;
    private readonly long _minimumFileSizeThreshold;
    private readonly long _maximumFileSizeThreshold;
    private readonly int _batchSize;
    private readonly Func<FileInfo, bool> _filterCallback;
    private readonly Url _fileStorageServiceUrl;

    public DynamicFileMetadataAnalyzer(ILogger logger, string directoryPath, long minimumFileSizeThreshold, long maximumFileSizeThreshold, int batchSize, Func<FileInfo, bool> filterCallback, Url fileStorageServiceUrl)
    {
        _logger = logger;
        _directoryPath = directoryPath;
        _minimumFileSizeThreshold = minimumFileSizeThreshold;
        _maximumFileSizeThreshold = maximumFileSizeThreshold;
        _batchSize = batchSize;
        _filterCallback = filterCallback;
        _fileStorageServiceUrl = fileStorageServiceUrl;
    }

    public async IAsyncEnumerable<ProcessedMetadata> Analyze()
    {
        if (_maximumFileSizeThreshold <= _minimumFileSizeThreshold)
            throw new ArgumentException("Maximum file size threshold should be greater than minimum file size threshold.");

        var allFiles = Directory.EnumerateFiles(_directoryPath);

        foreach (var batch in allFiles.Chunk(_batchSize))
        {
            var filesToProcess = batch.Where(f => File.Exists(f) && _filterCallback(new FileInfo(f)));

            if (!filesToProcess.Any())
                continue;

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            var tasks = filesToProcess.Select(file => AnalyzeFileAsync(file, _fileStorageServiceUrl, CancellationToken.None)).AsParallel(options);
            await Task.WhenAll(tasks);
        }
    }

    private async Task AnalyzeFileAsync(string filePath, Url fileStorageServiceUrl, CancellationToken cancellationToken)
    {
        try
        {
            var fileInfo = new FileInfo(filePath);
            if (fileInfo.Length < _minimumFileSizeThreshold || fileInfo.Length > _maximumFileSizeThreshold)
                return;

            var fileMetadata = await fileStorageServiceUrl.AppendPathSegment(fileInfo.Name).GetAsync<FileMetadata>(cancellationToken);
            if (fileMetadata == null)
            {
                _logger.LogError($"Failed to retrieve metadata for '{filePath}'.");
                return;
            }

            var processedMetadata = MapToProcessedMetadata(fileInfo, fileMetadata);
            yield return processedMetadata;
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while processing file '{filePath}': {ex.Message}");
        }
    }

    private ProcessedMetadata MapToProcessedMetadata(FileInfo fileInfo, FileMetadata fileMetadata)
    {
        // Customize this method to map the desired metadata fields
        return new ProcessedMetadata
        {
            FileName = fileInfo.Name,
            FileSize = fileInfo.Length,
            CreationDate = fileInfo.CreationTimeUtc,
            LastModifiedDate = fileInfo.LastWriteTimeUtc,
            CustomField1 = fileMetadata?.CustomField1, // Replace with your custom metadata field names
            CustomField2 = fileMetadata?.CustomField2 // Replace with your custom metadata field names
        };
    }
}

public class FileMetadata
{
    public string CustomField1 { get; set; }
    public string CustomField2 { get; set; }
}

public class ProcessedMetadata
{
    public string FileName { get; set; }
    public long FileSize { get; set; }
    public DateTime CreationDate { get; set; }
    public DateTime LastModifiedDate { get; set; }
    // Add custom properties here for any additional metadata fields you want to process
}
