// Define the StateList struct and its associated functions
typedef struct StateList {
    int* data; // Pointer to the dynamically allocated data array
    size_t capacity; // The maximum capacity of the list
    size_t size; // The current number of elements in the list
} StateList;

StateList* createStateList(size_t capacity) {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) {
        return NULL;
    }
    list->data = (int*)calloc(capacity, sizeof(int));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->size = 0;
    return list;
}

void appendStateList(StateList* list, int state) {
    if (list->size >= list->capacity) {
        // Resize the array if it's full
        size_t newCapacity = (list->capacity * 2 > num_states) ? num_states : (list->capacity * 2);
        int* newData = (int*)realloc(list->data, newCapacity * sizeof(int));
        if (!newData) {
            return; // Exit the function early on failure to reallocate memory
        }
        list->data = newData;
        list->capacity = newCapacity;
    }
    list->data[list->size++] = state;
}

void freeStateList(StateList* list) {
    free(list->data);
    free(list);
}

// Define the TransactionCriteria struct and its associated functions (if needed for your specific use case)

// Implement the filterAndCollectStates function
StateList* filterAndCollectStates(int const* states, size_t num_states, FSA* fsa, int last_state, time_t current_time, TransactionCriteria criteria) {
    // Perform DFS traversal and filter transactions simultaneously
    StateList* state_list = createStateList(num_states);
    if (!state_list) {
        return NULL; // Exit the function early on failure to allocate memory for the state list
    }

    std::set<int> visited_states;
    std::map<int, TransactionMetrics> filtered_transactions;
    dfs(fa, last_state, current_time, criteria, visited_states, filtered_transactions);

    // Populate the state list with the states in the correct order and return it
    for (size_t i = 0; i < num_states; ++i) {
        if (!visited_states.count(i)) {
            appendStateList(state_list, i);
        }
    }

    return state_list;
}

// Define the dfs function (recursive depth-first search implementation for FSA traversal)
void dfs(FSA* fa, int current_state, time_t current_time, TransactionCriteria criteria, std::set<int>& visited_states, std::map<int, TransactionMetrics>& filtered_transactions) {
    // Check if the current state has been visited already or if it's out of scope
    if (visited_states.count(current_state)) {
        return;
    }
    visited_states.insert(current_state);

    // Filter transactions based on provided criteria and update the filtered_transactions map
    // Traverse the FSA from the current state using your FSA structure (transition function, etc.)

    // Recursively call dfs for each reachable state
    for (int next_state : fa->getReachableStates(current_state)) {
        dfs(fa, next_state, current_time, criteria, visited_states, filtered_transactions);
    }
}
