```python
import functools
from dataclasses import @dataclass
from typing import Dict, Union, Callable
from concurrent.futures import ThreadPoolExecutor

@dataclass
class Temperature:
    celsius: float
    fahrenheit: float
    kelvin: float

    def __post_init__(self):
        self.celsius, self.fahrenheit, self.kelvin = map(float, (self.celsius, self.fahrenheit, self.kelvin))

    def to_celsius(self) -> 'Temperature':
        return Temperature(self.celsius, _f2c(self.fahrenheit), _k2c(self.kelvin))

    def to_fahrenheit(self) -> 'Temperature':
        return Temperature(_c2f(self.celsius), self.fahrenheit, _k2f(self.kelvin))

    def to_kelvin(self) -> 'Temperature':
        return Temperature(self.celsius, self.fahrenheit, self.kelvin)

def _c2f(c: float) -> float:
    return (c * 9/5) + 32

def _f2c(f: float) -> float:
    return (f - 32) * 5/9

def _k2c(k: float) -> float:
    return k - 273.15

def _k2f(k: float) -> float:
    return (_k2c(k) + 459.67) * 9/5

CACHE = {}
TEMP_CONV_FN_MAP: Dict[str, Callable[[float], 'Temperature']] = {
    "Celsius": lambda c: Temperature(c, _f2c(c), _k2c(c)),
    "Fahrenheit": lambda f: Temperature(_c2f(f), f, _k2f(f)),
    "Kelvin": lambda k: Temperature(_c2f(k - 273.15), _f2c(k - 459.67), k)
}

def convert_temperature(source: str, target: str, temperature: float) -> 'Temperature':
    key = f"{source}-{target}-{temperature}"
    if key in CACHE:
        return CACHE[key]

    temp = TEMP_CONV_FN_MAP[source](temperature)
    converted_temp = temp.to_target(target)
    CACHE[key] = converted_temp
    return converted_temp

def batch_convert(source: str, target: str, temperatures: list[float]) -> list['Temperature']:
    with ThreadPoolExecutor() as executor:
        results = executor.map(lambda t: convert_temperature(source, target, t), temperatures)
    return list(results)
