import express from 'express';
import bodyParser from 'body-parser';

const app = express();
app.use(bodyParser.json());

const convertTemperature = require('./temperature_converter');

// Define routes for Celsius, Fahrenheit, and Kelvin conversions.
app.get('/convert/C/:source/:target/:temperature', (req, res) => {
    const source = req.params.source;
    const target = req.params.target;
    const temperature = parseFloat(req.params.temperature);

    if (!isValidTemperatureScale(source) || !isValidTemperatureScale(target)) {
        return res.status(400).send({ error: 'Invalid temperature scale' });
    }

    try {
        const result = convertTemperature(source, target, temperature);
        res.json(result);
    } catch (error) {
        console.error(error);
        res.status(500).send({ error: 'Internal Server Error' });
    }
});

app.post('/batch_convert', express.json(), (req, res) => {
    const source = req.body.source;
    const target = req.body.target;
    const temperatures = req.body.temperatures;

    if (!isValidTemperatureScale(source) || !isValidTemperatureScale(target)) {
        return res.status(400).send({ error: 'Invalid temperature scale' });
    }

    try {
        const results = convertTemperature.batchConvert(source, target, temperatures);
        res.json(results);
    } catch (error) {
        console.error(error);
        res.status(500).send({ error: 'Internal Server Error' });
    }
});

function isValidTemperatureScale(scale: string): boolean {
    return ['Celsius', 'Fahrenheit', 'Kelvin'].includes(scale);
}

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Temperature Conversion API listening on port ${PORT}`));
