std::vector<EncryptionResult> encryptFiles(const json& config) {
    std::vector<EncryptionResult> results;
    std::atomic<bool> running{true};

    for (const auto& filePath : config["filePaths"]) {
        if (!fs::exists(filePath)) {
            SPDLOG_ERROR("File does not exist: {}", filePath);
            continue;
        }

        if (!fs::permissions(filePath).allow_read()) {
            SPDLOG_ERROR("Cannot read file: {}", filePath);
            continue;
        }

        OpenSSL::EVP_CIPHER_CTX ctx;
        AES_KEY key;

        if (OpenSSL::initEncryptionContext(config, key) != 0) {
            SPDLOG_ERROR("Error initializing encryption context");
            continue;
        }

        const auto startTime = std::chrono::high_resolution_clock::now();
        EncryptionResult result{0, 0.0, 0};

        OpenSSL::AES_CBC_encrypt(filePath, ctx, key);

        const auto endTime = std::chrono::high_resolution_clock::now();
        const auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();

        result.encryptionTime = duration / 1000.0;
        result.memoryUsage = OpenSSL::getMemoryUsage();

        if (OpenSSL::verifyChecksum(filePath)) {
            SPDLOG_INFO("File is not corrupted: {}", filePath);
            result.exitCode = 0;
        } else {
            SPDLOG_ERROR("File is corrupted: {}", filePath);
            result.exitCode = 1;
        }

        results.push_back(result);
    }

    running.store(false);

    return results;
}

