```javascript
const fs = require('fs');
const path = require('path');
const chokidar = require('chokidar');
const express = require('express');
const watcher = chokidar.watch(process.cwd() + '/modules', { persistent: true, ignoreInitial: true });

let dependencies = {};
let currentModules = {};

function loadModule(modulePath) {
  try {
    const module = require(modulePath);
    return module;
  } catch (error) {
    console.error(`Error loading module ${modulePath}:`, error);
    return null;
  }
}

function resolveDependencies(module, dependencies) {
  if (!module.dependencies || !Object.keys(module.dependencies).length) return;

  for (const dependency of Object.values(module.dependencies)) {
    const resolvedPath = path.resolve(process.cwd() + '/modules', dependency);
    let moduleInstance = currentModules[dependency] || loadModule(resolvedPath);

    if (!moduleInstance) continue;

    if (moduleInstance.run) {
      resolveDependencies(moduleInstance, dependencies);
    } else {
      dependencies[dependency] = true;
    }
  }
}

function setupModules() {
  fs.readdirSync('./modules').forEach((file) => {
    const modulePath = path.resolve(process.cwd() + '/modules', file);
    const stats = fs.statSync(modulePath);

    if (stats.isDirectory()) {
      const manifestPath = path.join(modulePath, 'manifest.json');
      if (!fs.existsSync(manifestPath)) return;

      const manifestData = require(manifestPath);

      currentModules[file] = { ...manifestData };
      resolveDependencies(currentModules[file], dependencies);
    }
  });
}

function runModules() {
  for (const module of Object.values(currentModules)) {
    if (!module || !module.run) continue;

    try {
      module.run();
    } catch (error) {
      console.error(`Error running module ${module.name}:`, error);
    }
  }
}

setupModules();
watcher.on('all', () => {
  setupModules();
  runModules();
});

const app = express();
app.listen(3000, () => console.log('Application listening on port 3000!'));
```

This code uses Express.js as a simple server to keep the application running, and Chokidar to monitor changes in the specified directory (`./modules`) for any updated or new modules. The program loads each module's `manifest.json` file, which should define the dependencies of the module, if any, and a run function that executes when the module is loaded. If a module has an error or is missing, it will log the appropriate message without causing the application to fail. To update modules without restarting the application, simply replace or modify the `manifest.json` files in the `./modules` directory.

