```python
import os
import io
import base64
from PIL import Image
from datetime import datetime
from google.oauth2 import service_account
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError
from redis import Redis
import uuid

class Dao:
    def __init__(self, storage_api_credentials, cache, user_lockout):
        self.storage_api = self._get_google_drive_service(storage_api_credentials)
        self.cache = cache
        self.user_lockout = user_lockout

    def _validate_image(self, img_file):
        if img_file.size > 5 * 1024 ** 2: # 5MB limit
            raise ValueError("Image file size is too large.")
        if not img_file.name.lower().endswith(('.png', '.jpg', '.jpeg')):
            raise ValueError("Invalid image format.")

    def _get_google_drive_service(self, credentials):
        return build('drive', 'v3', credentials=credentials)

    def update_profile_picture(self, user_id, img_file):
        self._validate_image(img_file)
        cache_key = f"user_{user_id}_profile_picture"
        self.cache.set(cache_key, img_file.read(), ex=3600) # cache for 1 hour

        file_metadata = {'name': f'{user_id}_profile_picture.jpg', 'parents': [f'{user_id}']}
        media = MediaIoBaseUpload(io.BytesIO(img_file.read()), mimetype=img_file.content_type, resumable=True)
        try:
            file = self.storage_api.files().create(body=file_metadata, media_body=media, fields='id').execute()
        except HttpError as error:
            if 409 == error.resposed.statusCode: # Conflict error (concurrent updates)
                self.update_profile_picture(user_id, self.cache.get(cache_key))
            else:
                raise

        return file['id']

    def increment_failed_attempts(self, user_id):
        if not self.user_lockout.exists(f"user_{user_id}_lockout"):
            self.user_lockout.set(f"user_{user_id}_lockout", 0)
        current_value = self.user_lockout.incr(f"user_{user_id}_lockout")
        if current_value > 5: # lock account after 5 failed attempts for 60 minutes
            self.user_lockout.set(f"user_{user_id}_lockout", datetime.now() + timedelta(minutes=60))
        return current_value

