from fastapi import FastAPI

app = FastAPI()
celery_app = Celery('tasks', broker='redis://localhost:6379')

class IoTDevice:
    def __init__(self, ip, port):
        self.ip = ip
        self.port = port
        self.connected = False

async def read_sensor_data(device):
    # Use async-socket library to establish and read data from the device
    sock = await asyncio.get_event_loop().create_connection(lambda: socket.socket(), device.ip, device.port)
    while True:
        try:
            data = await socks.recv(1024)
            # Process the data here
            pass
        except ConnectionResetError:
            logger.error(f'Device {device.ip}:{device.port} disconnected')
            device.connected = False
        except Exception as e:
            logger.exception(e)
        finally:
            if not device.connected:
                try:
                    await socks.close()
                except Exception as e:
                    logger.error(e)
            else:
                device.connected = False

async def connect_device(device):
    try:
        sock = await asyncio.get_event_loop().create_connection(lambda: socket.socket(), device.ip, device.port)
        logger.info(f'Device {device.ip}:{device.port} connected')
        device.connected = True
        return sock
    except ConnectionRefusedError:
        logger.error(f'Device {device.ip}:{device.port} refused connection, retrying...')
        await asyncio.sleep(5)
        return await connect_device(device)

def process_sensor_data():
    devices = [IoTDevice('192.168.0.1', 8080), IoTDevice('192.168.0.2', 8081)]
    tasks = []

    for device in devices:
        task = asyncio.create_task(connect_device(device))
        tasks.append(task)

    while True:
        try:
            await asyncio.gather(*tasks, return_exceptions=True)
        except Exception as e:
            logger.exception(e)
        finally:
            for task in tasks:
                if not task.done():
                    task.cancel()
            tasks = [asyncio.create_task(connect_device(device)) for device in devices]

        # Process and trigger alerts or updates based on the received data
        pass

