```csharp
    using System;
    using UnityEngine;
    using System.Collections.Generic;
    using System.Linq;

    public enum RangeType { Closed, Open, HalfOpen }
    public class CustomInterval
    {
        public double Min { get; set; }
        public double Max { get; set; }
        public RangeType Type { get; set; }

        public CustomInterval(double min, double max, RangeType type)
        {
            Min = min;
            Max = max;
            Type = type;
        }
    }

    public delegate void SeedCallback(int seed);

    public class SeedManager
    {
        private static readonly object _lock = new object();
        private static int _currentSeed;
        private static readonly List<SeedCallback> _seedCallbacks = new List<SeedCallback>();

        public static void RegisterSeedCallback(SeedCallback callback)
        {
            lock (_lock)
            {
                _seedCallbacks.Add(callback);
            }
        }

        public static int Seed
        {
            get
            {
                lock (_lock)
                {
                    return _currentSeed;
                }
            }
            set
            {
                lock (_lock)
                {
                    if (value > Int32.MaxValue || value < Int32.MinValue)
                        throw new ArgumentOutOfRangeException(nameof(value), "Seed must be within the range of Int32.");

                    _currentSeed = value;
                    NotifySeedChanged();
                }
            }
        }

        private static void NotifySeedChanged()
        {
            foreach (var callback in _seedCallbacks)
            {
                lock (_lock)
                {
                    callback(_currentSeed);
                }
            }
        }
    }

    public class AdvancedRandomGenerator
    {
        private static readonly Random _random = new Random(SeedManager.Seed);
        private CustomInterval _cache;

        public double CustomRange(CustomInterval range, RangeType type)
        {
            if (range.Min >= range.Max)
                throw new ArgumentOutOfRangeException($"The minimum value '{range.Min}' must be less than or equal to the maximum value '{range.Max}'.");

            double delta = range.Max - range.Min;
            switch (type)
            {
                case RangeType.Closed:
                    return _random.NextDouble() * delta + range.Min;
                case RangeType.Open:
                    return _random.NextDouble() * (delta + 1) + range.Min;
                case RangeType.HalfOpen:
                    if (range.Min % 2 != 0)
                        throw new ArgumentOutOfRangeException($"The minimum value '{range.Min}' must be even for a half-open interval.");

                    return _random.NextDouble() * delta + range.Min;
            }

            throw new NotSupportedException("Invalid range type provided.");
        }

        public void SetSeed(int seed)
        {
            SeedManager.Seed = seed;
        }
    }
    ```

