import okhttp3.*;
import org.imgscalr.Scalr;
import java.io.File;
import java.util.Collections;
import java.util.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import com.google.common.cache.*;

public class ImageManager {
    private static final Cache<String, File> imageCache = CacheBuilder.newBuilder()
            .maximumSize(100) // Max cache size
            .expireAfterAccess(5, TimeUnit.MINUTES) // Evict unused images after 5 minutes
            .build();

    public void downloadImageResources(String[] urls) {
        ExecutorService executor = Executors.newFixedThreadPool(Math.min(10, urls.length));

        LoadingCache<String, Boolean> accessibilityCache = CacheBuilder.newBuilder()
                .maximumSize(1000) // Max cache size for URL accessibility checks
                .expireAfterWrite(5, TimeUnit.MINUTES) // Evict unused accessibility entries after 5 minutes
                .build((key) -> {
                    try {
                        HttpUrl url = HttpUrl.parse(key);
                        Request request = new Request.Builder().url(url).build();
                        Response response = OkHttpClient.newBuilder()
                                .call(request)
                                .execute();
                        return (response.code() < 400); // Accept HTTP status codes under 400 as accessible
                    } catch (IOException e) {
                        return false;
                    }
                });

        for (String url : urls) {
            final String finalUrl = url;
            Runnable runnable = () -> {
                if (!accessibilityCache.getIfPresent(finalUrl)) {
                    System.out.println("Skipping URL: " + finalUrl);
                    return;
                }

                try {
                    HttpUrl url = HttpUrl.parse(finalUrl);
                    Request request = new Request.Builder().url(url).build();
                    Response response = OkHttpClient.newBuilder()
                            .callTimeout(10, TimeUnit.SECONDS) // Set timeout for each download attempt
                            .retryOnConnectionFailure(true) // Implement retry mechanism with backoff for transient failures
                            .build()
                            .newCall(request)
                            .execute();

                    File cachedImage = imageCache.getIfPresent(finalUrl);
                    if (cachedImage != null && !cachedImage.delete()) {
                        System.out.println("Failed to delete existing cache for: " + finalUrl);
                    }

                    File downloadedImage = new File(finalUrl + ".jpg"); // Assuming images are .jpg format
                    if (!downloadedImage.getParentFile().exists() && !downloadedImage.getParentFile().mkdirs()) {
                        System.out.println("Failed to create directories for: " + finalUrl);
                    }

                    if (response.body() != null) {
                        try (ResponseBody responseBody = response.body()) {
                            FileUtils.copyInputStreamToFile(responseBody.byteStream(), downloadedImage);
                        } catch (IOException e) {
                            System.out.println("Failed to save image: " + finalUrl + ". Error: " + e.getMessage());
                        }

                        // Implement resizing and conversion using an existing library such as ImgScalr here...
                    } else {
                        System.out.println("No response body for URL: " + finalUrl);
                    }
                } catch (Exception e) {
                    System.out.println("Failed to download image from URL: " + finalUrl + ". Error: " + e.getMessage());
                }
            };

            executor.execute(runnable);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
