    private readonly string _databaseProvider;
    private readonly ConnectionPool _connectionPool;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(10, 10); // Configure the maximum number of concurrent connections

    public DynamicDatabaseConnectionManager(IConfiguration configuration)
    {
        _configuration = configuration;
        _databaseProvider = configuration["Database:Provider"];

        switch (_databaseProvider.ToLower())
        {
            case "mysql":
                InitializeMySqlConnectionPool();
                break;
            case "postgresql":
                InitializeNpgsqlConnectionPool();
                break;
            case "sqlite":
                InitializeSQLiteConnectionPool();
                break;
            default:
                _connectionPool = new ConnectionPool(DefaultConnection);
                break;
