    private void InitializeSQLiteConnectionPool()
    {
        // Implement SQLite PCL connection pooling here...
    }

    private IDbConnection DefaultConnection => _configuration.GetConnection();

    public async Task<IDbConnection> GetConnectionAsync(CancellationToken cancellationToken)
    {
        await _semaphore.WaitAsync(cancellationToken);

        try
        {
            if (_connectionPool != null)
            {
                return _connectionPool.Take();
            }

            return await Task.Run(() => new ConnectionFactory(_configuration).CreateConnection(), cancellationToken);
        }
        catch (Exception ex)
        {
            WriteLine($"Error getting database connection: {ex.Message}");
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public void Dispose()
    {
        if (_connectionPool != null)
        {
            _connectionPool.DisposeAsync().Wait();
        }
    }
}
