```csharp
using System;
using System.Collections.Concurrent;
using System.Data;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Dapper;

public class DatabaseConnectionManager
{
    private readonly IConfiguration _config;
    private readonly string _configSource;
    private readonly ConcurrentPool<IDbConnection> _connectionPool;
    private int _maxConnections;
    private int _idleTimeout;
    private int _maxIdleTime;
    private int _minIdle;

    public DatabaseConnectionManager(IConfiguration config, string configSource)
    {
        _config = config;
        _configSource = configSource;
        InitializeFromConfiguration(_configSource);
        _connectionPool = new ConcurrentPool<IDbConnection>(CreateConnection);
    }

    private IDbConnection CreateConnection(string provider, string connectionString)
    {
        using var connection = new ConnectionFactory(provider, connectionString).CreateConnection();
        connection.Open();
        return connection;
    }

    public async Task<IDbConnection> GetConnection(string provider, string connectionString)
    {
        IDbConnection connection;
        if (_connectionPool.TryTake(out connection))
            return connection;

        connection = CreateConnection(provider, connectionString);
        await AddConnectionToPoolAsync(connection);
        return connection;
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        if (connection != null && _connectionPool.TryAdd(connection))
            connection.Close();
    }

    private async Task AddConnectionToPoolAsync(IDbConnection connection)
    {
        await Task.Delay(_idleTimeout);

        if (!_connectionPool.Any(c => c.State == ConnectionState.Open))
        {
            connection.Open();
            _connectionPool.AddOrUpdate((connection, v) =>
            {
                if (v != null)
                    v.Close();
                return connection;
            });
        }

        var idleConnections = _connectionPool.Count(c => c.State == ConnectionState.Closed);
        if (idleConnections > _maxIdle)
            await EvictOldestConnectionAsync();
    }

    private async Task EvictOldestConnectionAsync()
    {
        var oldestConnection = _connectionPool.OrderBy(c => c.CreationTime).FirstOrDefault();
        if (oldestConnection != null && !oldestConnection.IsClosed)
            await oldestConnection.CloseAsync();
    }

    public void InitializeFromConfiguration(string configSource)
    {
        var config = _config.GetSection("DatabaseConnections").Get<Config>(configSource);
        _maxConnections = config.MaxConnections;
        _idleTimeout = config.IdleTimeout;
        _maxIdleTime = config.MaxIdleTime;
        _minIdle = config.MinIdle;
    }

    public override string ToString() => $"ConnectionManager (PoolSize: {_connectionPool.Count}, ActiveConnections: {_connectionPool.Count(c => c.State == ConnectionState.Open)})";
}

public class Config
{
    public int MaxConnections { get; set; }
    public int IdleTimeout { get; set; } // in seconds
    public int MaxIdleTime { get; set; } // in minutes
    public int MinIdle { get; set; }
}
```

