```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Node {
    int value;
    struct SubNode* subNodes;
    size_t subNodeCount;
    pthread_mutex_t mutex;
} Node;

typedef struct SubNode {
    char string[100];
    double value;
    struct NestedSubNode* nestedSubNodes;
    size_t nestedSubNodeCount;
    pthread_mutex_t mutex;
} SubNode;

typedef struct NestedSubNode {
    char* array;
    float value;
} NestedSubNode;

void initNodeArray(Node** nodeArray, size_t size, size_t nodeValueRange, size_t subNodeCount, size_t nestedSubNodeCount) {
    *nodeArray = malloc(size * sizeof(Node));
    if (!*nodeArray) return;

    for (size_t i = 0; i < size; ++i) {
        Node* node = &(*nodeArray)[i];
        pthread_mutex_init(&(node->mutex), NULL);
        node->value = rand() % nodeValueRange;
        node->subNodes = malloc(subNodeCount * sizeof(SubNode));
        if (!node->subNodes) {
            free(*nodeArray);
            return;
        }
        node->subNodeCount = subNodeCount;

        for (size_t j = 0; j < subNodeCount; ++j) {
            SubNode* subNode = &((*node)->subNodes)[j];
            pthread_mutex_init(&(subNode->mutex), NULL);
            strncpy(subNode->string, "", sizeof(subNode->string));
            subNode->value = (double)rand() / RAND_MAX;
            subNode->nestedSubNodes = malloc(nestedSubNodeCount * sizeof(NestedSubNode));
            if (!subNode->nestedSubNodes) {
                free(node->subNodes);
                free(*nodeArray);
                return;
            }
            subNode->nestedSubNodeCount = nestedSubNodeCount;

            for (size_t k = 0; k < nestedSubNodeCount; ++k) {
                NestedSubNode* nestedSubNode = &((subNode->nestedSubNodes)[k]);
                nestedSubNode->array = malloc(sizeof(char) * 100);
                if (!nestedSubNode->array) {
                    free(subNode->nestedSubNodes);
                    free(node->subNodes);
                    free(*nodeArray);
                    return;
                }
                strncpy(nestedSubNode->array, "", sizeof(nestedSubNode->array));
                nestedSubNode->value = (float)rand() / RAND_MAX;
            }
        }
    }
}

void freeNodeArray(Node** nodeArray, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        Node* node = &(*nodeArray)[i];

        for (size_t j = 0; j < node->subNodeCount; ++j) {
            SubNode* subNode = &node->subNodes[j];

            free(subNode->nestedSubNodes);
            pthread_mutex_destroy(&(subNode->mutex));
        }

        free(node->subNodes);
        pthread_mutex_destroy(&(node->mutex));
    }

    free(*nodeArray);
}
```

This code provides a function for initializing an array of `Node` structures with random data. Each `Node` contains an integer value and a linked list of `SubNode` structures. Each `SubNode` structure holds a string, a double value, and another linked list of `NestedSubNode` structures. The `NestedSubNode` structure contains a pointer to a dynamically allocated char array and a float value. The function handles memory allocation errors gracefully by validating input parameters and freeing all allocated memory when done. It also uses pthread_mutex_t for thread safety.

