```javascript
class AdvancedRandomValueGenerator {
  static FindElementsBySelector(root, selector, testFunc) {
    const queue = [root];
    const visited = new Set();
    let elements = [];

    function traverse(node) {
      if (visited.has(node)) return;

      if (testFunc(node)) elements.push(node);

      if (!node.querySelectorAll || !selector) return;
      const matchedNodes = node.querySelectorAll(selector);

      Array.from(matchedNodes).forEach((childNode) => {
        traverse(childNode);
      });

      visited.add(node);
    }

    while (queue.length > 0) {
      const currentNode = queue.shift();
      traverse(currentNode);
    }

    return elements;
  }
}
