#include <iostream>
#include <thread>
#include <vector>
#include <random>
#include <memory>
#include <cstdlib>
#include <cstring>
#include <pthread.h>

namespace RandomService {
    class ThreadSafeGenerator {
        std::mt19937_64 generator;
        pthread_key_t key;

    public:
        ThreadSafeGenerator() : key(pthread_key_create) {
            int seed = std::hash<std::this_thread::id>{}(std::this_thread::get_id());
            if (seed < 0) seed *= -1;
            generator.seed(seed);
        }

        ~ThreadSafeGenerator() {
            pthread_key_delete(key, nullptr);
        }

        static int SeedFromThreadID() {
            std::this_thread::id id = std::this_thread::get_id();
            return std::hash<std::this_thread::id>{}(id);
        }

        static ThreadSafeGenerator* GetInstance() {
            void* value = pthread_getspecific(key);
            if (value == nullptr) {
                ThreadSafeGenerator* instance = new ThreadSafeGenerator();
                pthread_setspecific(key, instance);
                return instance;
            }
            return static_cast<ThreadSafeGenerator*>(value);
        }

        uint64_t GetRandomNumber() {
            return generator();
        }
    };

    void TestMultiThreadedGeneration() {
        const int numThreads = 10;
        std::vector<std::thread> threads;

        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back( [&](){
                ThreadSafeGenerator* gen = RandomService::ThreadSafeGenerator::GetInstance();
                for (int j = 0; j < 1000000; ++j) {
                    gen->GetRandomNumber();
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }
}

int main() {
    try {
        RandomService::TestMultiThreadedGeneration();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
```

