#!/usr/bin/env node

const path = require('path');
const fs = require('fs');
const { Series } = require('./modules'); // Assuming each module exports a Series object
const yargs = require('yargs');
const chalk = require('chalk');
const ora = require('ora');
const semver = require('semver');

// Read configuration from JSON file
const configPath = path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(configPath));

// Ensure that each module is loaded only once
const modules = new Map();

function loadModule(moduleName) {
  if (!modules.has(moduleName)) {
    try {
      const module = require(moduleName);
      modules.set(moduleName, module);
    } catch (error) {
      console.error(`Error loading module "${moduleName}":`, error.message);
    }
  }
  return modules.get(moduleName);
}

// Main function to execute the specified sequence of modules
async function run() {
  const spinner = ora('Initializing...').start();

  try {
    // Load and execute each module in the specified order
    for (const moduleConfig of config.modules) {
      const module = loadModule(moduleConfig.name);

      if (!module) continue;

      spinner.text = `Executing "${chalk.green(moduleConfig.name)}"`;
      await module[moduleConfig.method](...moduleConfig.args);
    }
  } catch (error) {
    console.error('An error occurred during execution:', error.message);
  } finally {
    spinner.stop();
    process.exit(0);
  }
}

