3. Asynchronous reduce implementation in JavaScript:

```javascript
function asyncReduce(arr, initialValue, callback, concurrency = 4) {
  const semaphore = new Limit(concurrency);

  let accumulator = initialValue;
  const processedIndexes = new Set();

  function processElement(index) {
    if (processedIndexes.has(index)) return;

    processedIndexes.add(index);
    semaphore.take(() => {
      callback(accumulator, arr[index], (result, currentAccumulator) => {
        accumulator = result;
        if (processedIndexes.size === arr.length) {
          console.log(`Reduced array with concurrency ${concurrency}:`, accumulator);
        } else {
          processElement(index + 1);
        }
      });
    });
  }

  for (let i = 0; i < arr.length; i++) {
    processElement(i);
  }
}
```

