class OAuthAuthenticator {
    private $provider;
    private $clientId;
    private $clientSecret;
    private $redirectUri;
    private $scopes;
    private $rateLimit;
    private $logFile;

    public function __construct($provider, $clientId, $clientSecret, $redirectUri, $scopes = [], $rateLimit = 60, $logFile = 'auth_logs.txt') {
        $this->provider = $provider;
        $this->clientId = $clientId;
        $this->clientSecret = $clientSecret;
        $this->redirectUri = $redirectUri;
        $this->scopes = $scopes;
        $this->rateLimit = $rateLimit;
        $this->logFile = $logFile;
    }

    public function authenticate() {
        $state = bin2hex(random_bytes(16));
        $authUrl = $this->provider->getAuthorizationUrl($this->clientId, $this->scopes, $state);

        // Log successful authentication attempt
        $this->logSuccess('Authenticate request sent to ' . $authUrl);

        // Redirect user to OAuth provider for authorization
        header('Location: ' . $authUrl);
    }

    public function handleCallback() {
        if (!isset($_GET['state']) || $_GET['state'] !== bin2hex(random_bytes(16))) {
            // Invalid state, likely a CSRF attack or error in callback handling
            $this->logError('Invalid state received');
            return;
        }

        try {
            $accessToken = $this->provider->getAccessToken($_GET['code'], $this->clientId, $this->clientSecret);

            // Store the access token securely in a session variable
            $_SESSION[$this->provider->getName() . '_access_token'] = $accessToken;

            // Retrieve user information using the access token
            $userInfo = $this->provider->getUserInfo($accessToken);

            // Update last activity time to reset rate limit timer
            $this->updateRateLimit();

            // Log successful authentication attempt
            $this->logSuccess('Authentication successful for ' . $userInfo['username']);

            // Return the user information
            return $userInfo;
        } catch (\Exception $e) {
            // Handle network issues or server downtime during the OAuth process
            $this->logError($e->getMessage());
            return [];
        }
    }

    private function updateRateLimit() {
