public class AttackSelector {
    private static final String[] ATTACKS = {"Attack 1", "Attack 2"};
    private static final long COOLDOWN_PERIOD = TimeUnit.SECONDS.toMillis(9);
    private static final AtomicLong lastSelectionTime = new AtomicLong();
    private static final Random random = new Random();

    public String selectAttack() {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastSelectionTime.get() < COOLDOWN_PERIOD) {
            return "Cooldown period not yet expired";
        }
        synchronized (ATTACKS) {
            int randomIndex = random.nextInt(ATTACKS.length);
            String attackChoice = ATTACKS[randomIndex];
            lastSelectionTime.set(currentTime);
            return attackChoice;
        }
    }

    public boolean validateImage(BufferedImage image) {
        if (image == null || image.getSampleModel() == null) {
            return false;
        }
        DataBufferSampleModel sampleModel = (DataBufferSampleModel) image.getSampleModel();
        switch (sampleModel.getNumBands()) {
            case 1:
            case 2:
            case 4:
            case 8:
            case 16:
                return true;
            default:
                return false;
        }
    }
}
