    public ImageDownloader(ImageProcessor imageProcessor) {
        this.imageProcessor = imageProcessor;
        configureCache();
        configureThreadPool();
        configureHttpClient();
    }

    private void configureCache() {
        ConcurrentMap<String, File> cacheMap = CacheBuilder.newBuilder()
                .maximumWeightPerKey(10L * 1024 * 1024) // 10MB per key (image)
                .expireAfterAccess(CACHE_EVICTION_AGE_SECS, TimeUnit.SECONDS)
                .removalListener((url, file, cause) -> LOGGER.log(Level.INFO, "Evicted image: {0}", url))
                .build();
        this.imageCache = CacheBuilder.newBuilder()
                .maximumWeight(100 * 1024 * 1024) // 100MB maximum cache size
                .concurrencyLevel(Runtime.getRuntime().availableProcessors())
                .build(cacheMap);
    }

    private void configureThreadPool() {
        this.semaphore = new Semaphore(MAX_CONCURRENT_DOWNLOADS);
    }

    private void configureHttpClient() {
        this.httpClient = new OkHttpClient.Builder()
                .connectTimeout(10, TimeUnit.SECONDS) // configurable timeout for each download attempt
                .build();
    }

    public void downloadImageResources(String[] imageUrls, Consumer<File> onDownloadComplete) {
        Deque<String> urlQueue = new LinkedList<>(Arrays.asList(imageUrls));

        Runnable downloadTask = () -> {
            try {
                semaphore.acquire();
                String url = urlQueue.poll();
                if (url == null) return; // no more URLs to process

                File cachedImage = imageCache.get(url);
                if (cachedImage != null && shouldEvictFromCache(url, cachedImage)) {
                    LOGGER.log(Level.INFO, "Evicted image: {0}", url);
                    cachedImage.delete();
                }

                File outputFile = downloadAndProcessImage(url);
                onDownloadComplete.accept(outputFile);

                semaphore.release();
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error while downloading image: {0}", url, e);
                semaphore.release();
            }
        };

        Executors.newCachedThreadPool().submit(downloadTask);
        configureBackoffRetryPolicy();
    }

    private File downloadAndProcessImage(String url) throws IOException {
        try (Response response = httpClient.newCall(new Request.Builder().url(url).build()).execute()) {
            if (!response.isSuccessful()) throw new IOException("Failed to download image: " + url);

            File outputFile = File.createTempFile("downloaded_image", null);
            try (OutputStream out = new BufferedOutputStream(Files.newOutputStream(outputFile.toPath()))) {
                response.body().writeTo(out);
            }

            imageProcessor.processImage(outputFile);
            return outputFile;
        }
    }

