using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

namespace AsyncDbService
{
    public interface IDbService
    {
        Task<List<TResult>> ExecuteStoredProcedureAsync<TResult>(string storedProcedureName, object parameters);
        Task HealthCheckAsync();
    }

    public class DbService : IDbService
    {
        private readonly ILogger _logger;
        private readonly IConnectionMultiplexer _redis;
        private readonly IDatabase _cache;
        private readonly string _connectionString;
        private readonly TimeSpan _defaultCacheExpiration = TimeSpan.FromMinutes(5);

        public DbService(ILogger<DbService> logger, IConnectionMultiplexer redis, string connectionString)
        {
            _logger = logger;
            _redis = redis;
            _connectionString = connectionString;
            _cache = redis.GetDatabase();
        }

        public async Task<List<TResult>> ExecuteStoredProcedureAsync<TResult>(string storedProcedureName, object parameters)
        {
            var cacheKey = GenerateCacheKey(storedProcedureName, parameters);
            var cachedResults = await _cache.GetAsync<List<TResult>>(cacheKey);

            if (cachedResults != null) return cachedResults;

            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            var command = new SqlCommand(storedProcedureName, connection) { CommandType = CommandType.StoredProcedure };
            command.Parameters.AddWithValue("@parameters", parameters);

            using var reader = await command.ExecuteReaderAsync();

            var results = (await reader.CastAsync<TResult>()).ToList();

            if (_cache.IsOpen) _cache.Set(cacheKey, results, _defaultCacheExpiration);

            return results;
        }

        private string GenerateCacheKey(string storedProcedureName, object parameters) => $"{storedProcedureName}:{parameters.GetHashCode()}";

        public async Task HealthCheckAsync()
        {
            // Implement health check logic here, e.g., check database connection, cache server availability, etc.
        }
    }
}
```

