import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.stereotype.Component;

@Component
@EnableCaching
public class RedisCacheConfig {
    @Bean
    public CacheManager cacheManager(LettuceConnectionFactory connectionFactory) {
        // configure different cache configurations based on product categories
        RedisCacheConfiguration defaultCacheConfig = RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(10))
            .disableCachingNullValues();

        RedisCacheConfiguration electronicsConfig = defaultCacheConfig.entryTtl(Duration.ofMinutes(5));
        RedisCacheConfiguration clothingConfig = defaultCacheConfig.entryTtl(Duration.ofMinutes(30));
        //... for other categories

        return CacheManagerBuilder.fromConnectionFactory(connectionFactory)
            .cacheDefaults(defaultCacheConfig)
            .withInitialCacheConcurrencyStrategy(RedisCacheWriterBeanPostProcessor.CacheConcurrencyStrategy.LIFO_EVICTION)
            .withCacheConfiguration("product", electronicsConfig, clothingConfig, ...) // cache configuration based on product category
            .build();
    }
}
