using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Serilog;

namespace StringHasher
{
    public class StringHasher
    {
        private readonly HashAlgorithm hashAlgorithm;
        private readonly ILogger logger;
        private const int ChunkSize = 1000;

        public StringHasher(HashAlgorithmType hashAlgorithmType, LoggingService loggingService)
        {
            switch (hashAlgorithmType)
            {
                case HashAlgorithmType.MD5:
                    hashAlgorithm = MD5.Create();
                    break;
                case HashAlgorithmType.SHA256:
                    hashAlgorithm = SHA256.Create();
                    break;
                default:
                    throw new ArgumentException("Invalid hash algorithm type.");
            }

            logger = loggingService.CreateLogger(typeof(StringHasher).Name);
        }

        public string Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input));

            using var ms = new MemoryStream();
            Encoding.ASCII.GetBytes(input).AsMemory().Span.CopyTo(ms);
            return hashAlgorithm.ComputeHash(ms).ToHexString();
        }

        public async Task<IReadOnlyDictionary<string, string>> HashAsync(string[] inputs)
        {
            if (inputs == null || !inputs.Any())
                throw new ArgumentNullException(nameof(inputs));

            var tasks = Enumerable.Range(0, inputs.Length).Select(i => Task.Run(() => Hash(inputs[i]))).ToList();
            await Task.WhenAll(tasks);

            return tasks.ToDictionary(t => t.Result.Substring(0, 64), StringComparer.OrdinalIgnoreCase);
        }

        public void ValidateHash(string input, string expectedHash)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input));
            if (string.IsNullOrEmpty(expectedHash))
                throw new ArgumentNullException(nameof(expectedHash));

            var computedHash = Hash(input);
            if (!computedHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase))
            {
                logger.Error($"Invalid hash for input '{input}'. Expected: {expectedHash}. Computed: {computedHash}");
            }
        }

        public IEnumerable<IReadOnlyDictionary<string, string>> HashAsync(string[] inputs, int chunkSize = ChunkSize)
        {
            if (inputs == null || !inputs.Any())
                throw new ArgumentNullException(nameof(inputs));

            var tasks = Enumerable.Range(0, inputs.Length).Chunk(chunkSize).Select(chunk => HashAsync(chunk.ToArray()).Result);
            return tasks;
        }

        private static string ToHexString(this byte[] array)
        {
            return BitConverter.ToString(array).Replace("-", string.Empty);
        }
    }

    public class Settings
    {
        public HashAlgorithmType HashAlgorithmType { get; set; } = HashAlgorithmType.MD5;
        public LoggingService LoggingService { get; set; } = new SerilogLoggingService();
    }

    public interface ILoggingService
    {
        ILogger CreateLogger(string name);
    }

    public class SerilogLoggingService : ILoggingService
    {
        // Implement Serilog-specific logic here, writing logs to a specified file or external service.
    }
}
