Here's a high-level outline of the `SecureCipherService` class in C# with some key components implemented. Keep in mind that this is not an exhaustive solution but rather a starting point for a more comprehensive implementation.

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace SecureCipherService
{
    public class SecureCipherService
    {
        private readonly ConcurrentDictionary<string, (Token token, byte[] key, byte[] iv)> _cache = new ConcurrentDictionary<string, (Token token, byte[] key, byte[] iv)>();
        private readonly IAuthenticationService _authService;
        private readonly int _maxCacheAgeSeconds = 600; // Cache expiration policy
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(100);

        public SecureCipherService(IAuthenticationService authService)
        {
            _authService = authService;
        }

        public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, long offset, CancellationToken cancellationToken)
        {
            var tokenKeyPair = await GetOrRefreshTokenKeyPair(ciphertext);

            using (var aes = AES.Create())
            {
                aes.Key = tokenKeyPair.key;
                aes.IV = tokenKeyPair.iv;
                aes.Mode = CipherMode.CBC;

                var decryptStream = new CryptoStream(new MemoryStream(ciphertext), aes.CreateDecryptor(), CryptoStreamMode.Read);
                var chunkSize = 1024 * 16; // Optimize for large files (16KB chunks)
                var result = new List<byte>();

                var buffer = new byte[chunkSize];
                int bytesRead;

                cancellationToken.ThrowIfCancellationRequested();
                while ((bytesRead = await decryptStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    if (offset > result.LongLength) offset -= result.LongLength;
                    Array.Copy(buffer, 0, result.GetBuffer(), (int)offset, bytesRead);
                    offset += bytesRead;

                    cancellationToken.ThrowIfCancellationRequested();
                }

                return result.ToArray();
            }
        }

        private async Task<(Token token, byte[] key, byte[] iv)> GetOrRefreshTokenKeyPair(byte[] ciphertext)
        {
            var keyIvCacheId = HashUtil.ComputeSha256Hash(ciphertext);
            if (_cache.TryGetValue(keyIvCacheId, out var cached))
                return cached;

            var token = await _authService.GetTokenAsync();
            if (token == null)
                throw new Exception("Failed to obtain a valid token.");

            // In case of network issues during token retrieval, retry up to three times with exponential backoff.
            for (var attempt = 1; attempt <= 3; attempt++)
            {
                try
                {
                    var keyIvResponse = await _authService.GetKeyIVAsync(token);
                    if (keyIvResponse == null)
                        throw new Exception("Failed to obtain decryption keys and IV.");

                    var key = keyIvResponse.key;
                    var iv = keyIvResponse.iv;
                    _cache.TryAdd(keyIvCacheId, (token, key, iv));
                    return (token, key, iv);
                }
                catch when (attempt < 3)
                {
                    await Task.Delay(Math.Pow(2, attempt - 1) * 500);
                }
            }

            throw new Exception("Failed to obtain decryption keys and IV after three attempts.");
        }
    }
}
```

