class RunTestsAsync {
  constructor(testFramework) {
    this.testFramework = testFramework;
  }

  async run(moduleLabel, testSuite) {
    Blueslip.setup(); // Initialize mocking library

    const modulePath = path.resolve(`./${moduleLabel}`);
    const module = await promisify(require)(modulePath);

    let testsCompleted = 0;
    let totalTests = testSuite.length;

    const test = (testIndex, { label, testFunction }) => {
      console.log(`\n=== Testing ${chalk.bold(moduleLabel)}: ${label} ===`);
      const startTime = Date.now();

      if (this.testFramework === 'mocha') {
        mocha.run(function () {
          this.timeout(10000); // Set a timeout of 10 seconds for each test
          it(`${label}`, testFunction);
        });
      } else if (this.testFramework === 'jest') {
        jest.resetModules(); // Reset the test environment
        jest.run(testFunction, {
          setupFiles: '<rootDir>/setupTests.js',
          setupFilesAfterEnv: '<rootDir>/setupEachTest.js'
        });
      }

      Blueslip.teardown(); // Clean up after each test

      const endTime = Date.now();
      console.log(`\nTest ${label} completed in ${(endTime - startTime) / 1000} seconds`);
      testsCompleted++;
    };

    if (this.testFramework === 'mocha') {
      return Series(testSuite, test).then(() => console.log(`All ${totalTests} tests for ${moduleLabel} completed.`));
    } else if (this.testFramework === 'jest') {
      return parallel(testSuite, test).then(() => console.log(`All ${totalTests} tests for ${moduleLabel} completed.`));
    }
  }
}
