using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;
using StackExchange.Redis;

public class QueryRunner
{
    private readonly IDatabase _cache;
    private readonly string _connectionString;
    private readonly EncryptionMode _encryptionMode;
    private readonly int _maxConnections;
    private readonly int _maxRetries;
    private readonly TimeSpan _retryInterval;
    private readonly Func<string> _config; // Injected configuration source (in-memory or file)

    public QueryRunner(IDatabase cache, string connectionString, EncryptionMode encryptionMode, int maxConnections, int maxRetries, TimeSpan retryInterval, Func<string> config)
    {
        _cache = cache;
        _connectionString = connectionString;
        _encryptionMode = encryptionMode;
        _maxConnections = maxConnections;
        _maxRetries = maxRetries;
        _retryInterval = retryInterval;
        _config = config;
    }

    public IDataReader ExecuteQuery(string commandTemplate, IDictionary<string, object> parameters)
    {
        if (parameters == null || !parameters.Any()) throw new ArgumentNullException(nameof(parameters));

        var command = GenerateCommand(commandTemplate, parameters);
        return ExecuteCommand(command);
    }

    private SqlCommand GenerateCommand(string commandTemplate, IDictionary<string, object> parameters)
    {
        // Dynamic query generation and parameter binding
        var builder = new SqlCommandBuilder(_connectionString);
        var command = new SqlCommand();

        // Support for nested lists and dictionaries as parameters
        foreach (var param in parameters)
        {
            builder.AddParameter(param.Key, param.Value);
        }

        builder.UseCommandText(commandTemplate).BuildUp(command);
        return command;
    }

    private IDataReader ExecuteCommand(SqlCommand command)
    {
        using (var connection = GetConnection())
        {
            if (!connection.State.Equals(ConnectionState.Open)) connection.Open();
            var reader = command.ExecuteReader();

            // External caching integration and performance optimization
            CacheResult(command, reader);
            return reader;
        }
    }

    private SqlConnection GetConnection()
    {
        if (_connections.Count >= _maxConnections)
        {
            // Connection pooling and resource monitoring
            var connection = _connectionPool.GetConnection();
            _openConnections.Remove(connection);
            return connection;
        }

        return new SqlConnection(_connectionString);
    }

    private void CacheResult(SqlCommand command, IDataReader reader)
    {
        // If the result can be cached, store it in the cache with the corresponding key
        if (_cache.IsInstanceReady && ShouldCache(command))
        {
            var commandKey = BuildCacheKey(command);
            _cache.HashTags.Add(commandKey, "query");
            using (var transaction = _cache.CreateTransaction())
            {
                _cache.StringSet(commandKey, GenerateCacheValue(reader), DateTime.UtcNow.AddMinutes(10));
                transaction.Commit();
            }
        }
    }

    private bool ShouldCache(SqlCommand command)
    {
        // Implement caching rules based on the query complexity and other factors
        return true;
    }

    private string GenerateCacheValue(IDataReader reader)
    {
        // Serialize the result set for caching
        var builder = new StringBuilder();
        while (reader.Read())
        {
            builder.AppendLine(reader[0].ToString());
        }
        return builder.ToString();
    }

    private string BuildCacheKey(SqlCommand command)
    {
        // Implement a key generation strategy based on the query and parameters
        var key = $"{_config()}_{command.CommandText}";
        foreach (var param in command.Parameters)
        {
            key += $"_{param.ParameterName}:{param.Value}";
        }
        return key;
    }

    // Implement the remaining features:
