public class RandomStringGenerator {
    private static final Lock REQUEST_LOCK = new ReentrantLock();
    private final ExternalApiClient apiClient;
    private final ConfigurationManager configManager;
    private final PasswordHasher passwordHasher;
    private final LoadingCache<Long, Map<String, Object>> cache;

    public RandomStringGenerator(ExternalApiClient apiClient, ConfigurationManager configManager, PasswordHasher passwordHasher) {
        this.apiClient = apiClient;
        this.configManager = configManager;
        this.passwordHasher = passwordHasher;
        this.cache = CacheBuilder.newBuilder()
            .maximumSize(1000)
            .expireAfterAccess(1, TimeUnit.HOURS)
            .build(this::loadConfig);
    }

    public String generateRandomString(@NotNull ByteArray byteArray, int length, char[] allowedChars, @Nullable String seed, HashingAlgorithm hashingAlgorithm) {
        REQUEST_LOCK.lock();
        try {
            Map<String, Object> config = cache.getIfPresent(System.currentTimeMillis());
            if (config == null) {
                config = apiClient.fetchConfig();
                cache.put(System.currentTimeMillis(), config);
            }

            byte[] deserializedObject = SerializationUtils.deserialize(byteArray);
            List<Character> characters = new ArrayList<>();
            for (char c : allowedChars) {
                characters.add(c);
            }
            for (char c : (String) config.get("allowed_chars")) {
                characters.add(c);
            }

            String randomString = new String(new Random().nextBytes(length));
            for (int i = 0; i < length; i++) {
                if (!characters.contains(randomString.charAt(i))) {
                    randomString = randomString.substring(0, i) + config.get("default_char") + randomString.substring(i + 1);
                }
            }

            String hashedPassword = passwordHasher.create(hashingAlgorithm, seed).hashToString();
            // Use the rest of your code for implementing asynchronous requests and logging here
        } finally {
            REQUEST_LOCK.unlock();
        }
    }
}
