const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const chokidar = require('chokidar');

// Configuration file parser
const configPath = './config.json';
const config = JSON.parse(fs.readFileSync(configPath));
const envVariable = process.env.NODE_ENV || 'development';

// Conditional module loading based on runtime environment variables
const loadModules = (modules, env) => modules.filter(module => module.env === env);

// Dynamic module loader
const createRequireContext = require.context;
const requireModule = (id) => createRequireContext(`./modules`).call(null, id);

// Asynchronous Reducer Function
const asyncReduce = (arr, initialValue, callback) => {
  let accumulator = initialValue;
  return new Promise((resolve, reject) => {
    const reduceCallback = (accumulator, currentValue, index, array) => {
      callback(accumulator, currentValue, index, array).then(newAccumulator => {
        if (array.length === index + 1) {
          resolve(newAccumulator);
        } else {
          accumulator = newAccumulator;
        }
      }).catch(error => reject(error));
    };

    arr.forEach((value, index) => reduceCallback(accumulator, value, index, arr));
  });
};

// Dynamic module execution
const executeModules = async (modules) => {
  try {
    const promises = modules.map(moduleId => requireModule(moduleId).default());
    let results = await Promise.all(promises);
    console.log(`Executed ${results.length} modules successfully:`);
    // Log the execution results here
  } catch (error) {
    console.error('Error while executing modules:', error.message);
  }
};

// Load and execute modules based on the configuration file
const modules = loadModules(config.modules, envVariable);
executeModules(modules);

// Watch for changes in the modules folder
const watcher = chokidar.watch('./modules', { persistent: true });
watcher.on('all', (event, path) => {
  if (event === 'add' || event === 'change') {
    console.log(`File ${path} was ${event}. Re-executing modules...`);
    executeModules(loadModules(config.modules, envVariable));
  }
});
