enum ResourceType { IMAGE, TEXT, AUDIO };

struct Resource {
    ResourceType type;
    string path;
};

class ResourceBundle {
public:
    void loadResourceBundle(const fs::path& filePath) {
        ptree pt;
        read_xml(fileStreamFromXmLFile(filePath), pt);

        for (auto& r : pt.get_child("resources")) {
            Resource res;
            string typeStr = r.get<string>("type");
            if (typeStr == "IMAGE") res.type = IMAGE;
            else if (typeStr == "TEXT") res.type = TEXT;
            else if (typeStr == "AUDIO") res.type = AUDIO;
            res.path = r.get<string>("path");

            unique_lock<mutex> lock(mtx);
            resourceList[res.type].push_back(move(res));
            lock.unlock();
        }
    }

private:
    mutex mtx;
    map<ResourceType, vector<Resource>> resourceList;
};

