using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using GraphQL;
using GraphQL.Client.Serializer.Newtonsoft;
using GraphQL.Client.Http;
using Newtonsoft.Json;
using System.Net.Http;

public async Task<T> ExecuteGraphqlQuery<T>(string queryTemplate, IDictionary<string, object> variables, HttpClient graphqlClient)
{
    // Validate input parameters
    if (string.IsNullOrEmpty(queryTemplate)) throw new ArgumentException("The provided query template is invalid.");
    if (variables == null || !variables.Any()) throw new ArgumentException("The provided variables dictionary is empty.");

    // Construct the final GraphQL query with variables interpolated
    var graphqlQuery = Interpolate(queryTemplate, variables);

    // Create the GraphQL request object
    var request = new GraphQLRequest
    {
        Query = graphqlQuery,
        OperationName = null, // Set operation name if needed
        Variables = variables
    };

    try
    {
        // Execute the query and deserialize the response
        var response = await graphqlClient.SendAsync(request);
        var content = await response.Content.ReadAsStringAsync();

        // Parse the GraphQL response
        var result = JsonConvert.DeserializeObject<GraphQLResponse<T>>(content);

        if (result == null || !result.HasErrors)
            return result.Data;

        // Log errors and throw exception
        foreach (var error in result.Errors)
            Console.WriteLine($"Error: {error.Message}");

        throw new Exception("An error occurred while executing the GraphQL query.");
    }
    catch (Exception ex)
    {
        // Log errors and rethrow exception
        Console.WriteLine($"Error: {ex.Message}");
        throw;
    }
}
```

This method performs some basic input validation, constructs the GraphQL query with provided variables, executes it using Apollo Client (GraphQL.Client.Http and Newtonsoft.Json), and deserializes the response. It also includes error handling and logging for errors that may occur during query execution.

