        except Self.ValidationException as e:
            return str(e)

        num_retries = 3
        backoff_factor = 2
        while True:
            result = self.payment_gateway.processPayment(orderId, cardNumber, expirationDate, cvv)
            if result["status"] == "success":
                break
            if result["status"] == "transient error":
                sleep(num_retries ** backoff_factor)
                num_retries += 1
                continue
            return result["error_message"]
        self.local_database.updatePaymentStatus(orderId, "processing")
        # Simulate shipping and fulfillment process here...
        self.local_database.updatePaymentStatus(orderId, "captured")
        return f"Payment for order {orderId} processed successfully."

