        if not self.local_database.checkCapturedPayment(orderId):
            self.local_database.updatePaymentStatus(orderId, "captured")
            return f"Payment for order {orderId} captured successfully."
        return f"Payment for order {orderId} has already been captured."

    def refundPayment(self, orderId):
        if self.local_database.getOrderById(orderId)["status"] == "captured":
            result = self.payment_gateway.refundPayment(orderId)
            if result["status"] == "success":
