```cpp
#include <nlohmann/json.hpp>

// Function to parse a JSON string and validate it
bool parse_and_validate(const std::string& json, nlohmann::json& result) {
    try {
        result = nlohmann::json::parse(json);
    } catch (nlohmann::json::error & e) {
        return false;
    }
    if (!result.count("access_token") || !result["access_token"].is_string() ||
        !result.count("expires_in") || !result["expires_in"].is_number_integer() ||
        result["expires_in"] <= 0) {
        return false;
    }
    if (result.count("token_type") && !(result["token_type"].is_string())) {
        return false;
    }
    if (result.count("refresh_token")) {
        if (!result["refresh_token"].is_string()) {
            return false;
        }
    }
    return true;
}
```

