void process_json(std::istream& is, std::vector<nlohmann::json>& tokens) {
    std::string line;
    nlohmann::json token;
    std::istringstream iss;

    while (getline(is, line)) {
        iss.clear();
        iss.str(line);
        if (parse_and_validate(iss, token)) {
            tokens.push_back(token);
        }
