void process_files(const std::vector<std::string>& file_paths,
                   std::vector<nlohmann::json>& tokens,
                   uint32_t concurrency) {
    boost::asio::io_service io_service;
    std::vector<std::promise<void>> promises(concurrency);

    for (size_t i = 0; i < file_paths.size(); ++i) {
        auto& promise = promises[i % concurrency];
        boost::thread t(&process_json, std::ref(io_service), std::ref(tokens), file_paths[i]);
        promise.get_future().wait();
    }
}
