#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct Product {
    char *name;
    double price;
    struct Review **reviews;
    size_t reviewCount;
    size_t capacity;
};

typedef struct Review {
    double rating;
    char *comment;
    struct Review *next;
};

void product_init(struct Product **product) {
    *product = malloc(sizeof(struct Product));
    if (!*product) {
        perror("malloc");
        exit(1);
    }

    (*product)->name = NULL;
    (*product)->price = 0.0;
    (*product)->reviews = NULL;
    (*product)->reviewCount = 0;
    (*product)->capacity = 0;
}

void product_destroy(struct Product **product) {
    if (!*product) return;

    free((*product)->name);
    for (size_t i = 0; i < (*product)->reviewCount; ++i) {
        struct Review *review = (*product)->reviews[i];
        free(review->comment);
        free(review);
    }
    free(*product);
}

void product_add_review(struct Product *product, double rating, const char *comment) {
    if (!product || !comment) return;

    if (product->capacity == product->reviewCount) {
        product->capacity *= 2;
        product->reviews = realloc(product->reviews, sizeof(struct Review *) * product->capacity);
        if (!product->reviews) {
            perror("realloc");
            exit(1);
        }
    }

    struct Review *review = malloc(sizeof(struct Review));
    if (!review) {
        perror("malloc");
        exit(1);
    }

    review->rating = rating;
    review->comment = strdup(comment);
    if (!review->comment) {
        free(review);
        perror("strdup");
        exit(1);
    }

    product->reviews[product->reviewCount] = review;
    ++product->reviewCount;
}

double product_average_rating(const struct Product *product) {
    double total = 0.0;
    for (size_t i = 0; i < product->reviewCount; ++i) {
        total += product->reviews[i]->rating;
    }
    return total / product->reviewCount;
}

int product_serialize(const struct Product *product, char **buffer) {
    json_object *json = json_object_new_object();
    json_object_object_add(json, "name", json_object_new_string(product->name));
    json_object_object_add(json, "price", json_object_new_double(product->price));
    json_array *reviews = json_array_new();

    for (size_t i = 0; i < product->reviewCount; ++i) {
        struct Review *r = product->reviews[i];
        json_array_add(reviews, json_object_new_object());
        json_object_object_add(json_array_get_obj(reviews, i), "rating", json_object_new_double(r->rating));
        json_object_object_add(json_array_get_obj(reviews, i), "comment", json_object_new_string(r->comment));
    }
    json_object_object_add(json, "reviews", reviews);

    *buffer = json_writestring(json, 0);
    json_object_put(json);
    if (*buffer == NULL) {
        perror("json_writestring");
        exit(1);
    }

    return 0;
}

int product_deserialize(struct Product **product, const char *buffer) {
    json_object *json = json_tokener_parse(buffer, 0);
    if (IS_ERROR(json)) {
        fprintf(stderr, "%s\n", json_get_error(json));
        exit(1);
    }

    const char *name = json_object_get_string(json, "name");
    double price = json_object_get_double(json, "price");
    cJSON *reviewsArray = json_object_get_c_obj(json, "reviews");
    cJSON *review;

    product_init(product);
    (*product)->name = strdup(name);
    if (!(*product)->name) {
        perror("strdup");
        exit(1);
    }
    (*product)->price = price;

    cJSON_ArrayForEach(review, reviewsArray) {
        struct Review *r = malloc(sizeof(struct Review));
        if (!r) {
            perror("malloc");
            exit(1);
        }

        r->rating = json_object_get_double(json_object_get_c_obj(review, "rating"));
        r->comment = strdup(json_object_get_string(json_object_get_c_obj(review, "comment")));
        if (!r->comment) {
            free(r);
            perror("strdup");
            exit(1);
        }

        (*product)->reviews[(*product)->reviewCount] = r;
        ++((*product)->reviewCount);
    }

    json_object_put(json);
    return 0;
}
