using System;
using System.Collections.Generic;
using UnityEngine;
using static System.Math;

public sealed class CustomRandomGenerator
{
    private readonly Dictionary<string, Action<int>> _seedProviders;
    private Func<float> _randomFunction;
    private long _currentSeed;
    private DateTime _startTime;
    private long _memoryUsage;
    private bool _isDisposed;

    public CustomRandomGenerator()
    {
        _seedProviders = new Dictionary<string, Action<int>>();
        _randomFunction = UnityEngine.Random.Range;
        _currentSeed = UnityEngine.Random.Seed;
        _startTime = DateTime.UtcNow;
        _memoryUsage = GC.GetTotalMemory(false);
    }

    public void RegisterSeedProvider(string key, Action<int> provider)
    {
        _seedProviders[key] = provider;
    }

    public float CustomRange(float min, float max, bool isExclusive, bool seeded = false)
    {
        if (max < min)
            throw new ArgumentException($"Invalid range ({min} > {max})");

        long desiredSeed;
        if (seeded)
        {
            if (_seedProviders.Count == 0 && !isExclusive)
                throw new InvalidOperationException("No seed providers registered.");

            _seedProviders.TryGetValue(nameof(CustomRange), out var provider);
            desiredSeed = provider?.Invoke((int)_currentSeed) ?? (int)_currentSeed;
        }
        else
            desiredSeed = _currentSeed;

        _currentSeed = UnityEngine.Random.Seed = (desiredSeed * 1234567 + 12345) & long.MaxValue;

        float range = max - min;
        if (isExclusive)
            return _randomFunction() * range + min;
        else
            return Min(max, Max(_randomFunction(), min)) - min;
    }

    public int CustomRange(int min, int max, bool isExclusive, bool seeded = false)
    {
        if (max < min)
            throw new ArgumentException($"Invalid range ({min} > {max})");

        long desiredSeed;
        if (seeded)
        {
            if (_seedProviders.Count == 0 && !isExclusive)
                throw new InvalidOperationException("No seed providers registered.");

            _seedProviders.TryGetValue(nameof(CustomRange), out var provider);
            desiredSeed = provider?.Invoke((int)_currentSeed) ?? (int)_currentSeed;
        }
        else
            desiredSeed = _currentSeed;

        _currentSeed = UnityEngine.Random.Seed = (desiredSeed * 1234567 + 12345) & long.MaxValue;

        int range = max - min;
        if (isExclusive)
            return (int)(_randomFunction() * range) + min;
        else
            return Min(max, Max((int)_randomFunction(), min)) - min;
    }

    public override string ToString()
    {
        TimeSpan elapsed = DateTime.UtcNow - _startTime;
        long currentMemoryUsage = GC.GetTotalMemory(false);
        return $"Elapsed: {elapsed.TotalMilliseconds}ms, Memory usage: {currentMemoryUsage - _memoryUsage}bytes";
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_isDisposed) return;
        if (disposing)
        {
            // Cleanup any temporary files or resources here.
        }
        _isDisposed = true;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
