#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#define MAP_SIZE 1048576 // 1MB
void *map_file(const char *path) {
    int fd = open(path, O_RDONLY);
    void *ptr;
    off_t filesize;
    if (fd == -1 || (filesize = lseek(fd, 0, SEEK_END)) == (off_t)-1) {
        perror("open or lseek");
        return NULL;
    }
    ptr = mmap(NULL, filesize, PROT_READ, MAP_ANON | MAP_PRIVATE, fd, 0);
    close(fd);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
    return ptr;
}
