        perror("EVP_EncryptInit_ex");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate key and IV securely
    if (1 != EVP_bytes_to_key(EVP_aes_256_gcm(), salt, saltLength, key, keySize) ||
        1 != RAND_bytes(iv, sizeof(iv))) {
        perror("EVP_bytes_to_key");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the key and IV in the cipher context
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        perror("EVP_EncryptInit_ex");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the chosen mode (GCM or CBC)
    if (mode == GCM_MODE) {
        ctx->cipher_iv = iv;
        ctx->key_length = keySize;
    } else if (mode == CBC_MODE) {
        ctx->cipher_init = EVP_CIPHER_CTX_ctor_cbc;
        ctx->cipher_iv  = iv;
        ctx->key_length = keySize;
    } else {
        fprintf(stderr, "Invalid cipher mode.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
```

This code uses the OpenSSL library for AES encryption with GCM and CBC modes. The `init_cryptographic_cipher` function takes a key size, cipher mode, and custom salt value (optional) as input parameters and returns an initialized `EVP_CIPHER_CTX` structure. It handles error cases, securely generates keys and IVs, and sets the appropriate context options based on the chosen mode.

