        try {
            channel = AsynchronousSocketChannel.open().thenApply(socket -> {
                socket.connectNow(serverAddress);
                return socket;
            });
            Future<Void> future = channel.thenAccept(socket -> System.out.println("Connected to server"))
                    .exceptionally(throwable -> {
                        if (!isConnectionLost()) {
                            retryConnect();
                        }
                        return null;
                    });
            future.get(10, TimeUnit.SECONDS);
        } catch (IOException | InterruptedException | ExecutionException e) {
            System.err.println("Error connecting to server: " + e.getMessage());
        } catch (TimeoutException e) {
            retryConnect();
        }
    }

    private void retryConnect() {
        scheduler.schedule(() -> connect(), 5, TimeUnit.SECONDS);
