```cpp
#include <atomic>
#include <memory>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <stdexcept>
#include <new>

class OctreeNode {
public:
    double position[3]; // Coordinates for the node
    std::unique_ptr<OctreeNode> children[8]; // Pointers to child nodes
    std::vector<int> sensorIDs; // Sensor IDs associated with this node

    OctreeNode() {} // Default constructor
    ~OctreeNode(); // Destructor for memory deallocation
};

class Octree {
private:
    size_t maxDepth; // Maximum depth of the octree
    double sideLength; // Side length of a single cube in the octree
    std::atomic<size_t> rootNodeID; // Atomic counter for root node ID
    std::mutex mutex; // Mutex for thread safety
    std::condition_variable cv; // Condition variable for notifying threads
    std::unordered_map<size_t, std::shared_ptr<OctreeNode>> nodes; // Map of node IDs to shared pointers
    std::vector<std::thread> workerThreads; // Vector of worker threads

public:
    Octree(size_t maxDepth); // Constructor for the octree
    ~Octree(); // Destructor for cleaning up resources

    void addSensorData(const double position[], int sensorID); // Function to add sensor data
    size_t queryNodesContainingPosition(const double position[], std::vector<size_t>& result) const; // Function to query nodes containing a position
    void startWorkerThreads(); // Function to start worker threads for concurrent updates and queries
};

// Function definitions
Octree::Octree(size_t maxDepth) : maxDepth(maxDepth), sideLength(1.0 / (1 << maxDepth)), rootNodeID(1) {}

Octree::~Octree() {
    for (auto& node : nodes) {
        delete node.second.get(); // Deallocate memory for each node
    }
}

void Octree::addSensorData(const double position[], int sensorID) {
    std::unique_lock<std::mutex> lock(mutex);
    cv.wait(lock, [this]() { return rootNodeID.load() != 0; }); // Wait for the root node to be initialized

    size_t nodeID = rootNodeID.fetch_add(1); // Increment the root node ID and get the new ID for this sensor data point
    auto currentNode = nodes[nodeID].get();

    if (!currentNode->position[0]) { // Check if the current node has already been initialized (root node should be initialized)
        currentNode->position = position;
        currentNode->sensorIDs.push_back(sensorID);
        return;
    }

    double quarterSideLength = sideLength / 2;
    size_t childIndex = findChildIndex(position, quarterSideLength);

    if (!currentNode->children[childIndex]) { // Check if the corresponding child node has been initialized
        currentNode->children[childIndex] = std::make_unique<OctreeNode>();
    }

    auto childNode = currentNode->children[childIndex].get();
    childNode->position = position;
    childNode->sensorIDs.push_back(sensorID);

    if (quarterSideLength >= sideLength) { // If we reached the maximum depth, we're done
        return;
    }

    for (size_t i = 0; i < 8; ++i) {
        if (childIndex & (1 << i)) {
            addSensorData(position + getOctreeCoordOffset(i, quarterSideLength), sensorID);
        }
    }
}

size_t Octree::queryNodesContainingPosition(const double position[], std::vector<size_t>& result) const {
    size_t nodeID = findNodeID(position, sideLength);
    if (!nodes.count(nodeID)) {
        return 0;
    }

    auto currentNode = nodes[nodeID].get();
    if (currentNode->sensorIDs.empty()) {
        return 0;
    }

    result.insert(currentNode->sensorIDs.cbegin(), currentNode->sensorIDs.cend());

    double quarterSideLength = sideLength / 2;
    for (size_t i = 0; i < 8; ++i) {
        if (nodeID & (1 << i)) {
            auto childNodes = findChildNodes(position + getOctreeCoordOffset(i, quarterSideLength));
            result.insert(result.end(), childNodes.second.cbegin(), childNodes.second.cend());
        }
    }

    return result.size();
}

void Octree::startWorkerThreads() {
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workerThreads.emplace_back(std::thread([this]() { processUpdatesAndQueries(); }));
    }
}

// Utility functions (omitted for brevity)
size_t Octree::findChildIndex(const double position[], double sideLength) const;
std::pair<size_t, std::vector<size_t>> Octree::findNodeID(const double position[], double sideLength) const;
std::vector<double> Octree::getOctreeCoordOffset(size_t index, double sideLength) const;
std::vector<size_t> Octree::findChildNodes(const double position[], double sideLength) const;

// Function definitions for the utility functions (omitted for brevity)
