import java.io.*;
import java.nio.channels.FileChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.stream.LongStream;

public class FileProcessor {

    public static String processFileChunksParallelly(String fileName, long chunkSize, int numWorkers, String logFileName) throws IOException {
        FileChannel fileChannel = new RandomAccessFile(fileName, "r").getChannel();
        try (PrintWriter logWriter = new PrintWriter(new FileWriter(logFileName))) {
            long fileLength = fileChannel.size();
            List<ChunkProcessor> chunkProcessors = new ArrayList<>();

            for (int i = 0; i < numWorkers; i++) {
                long startPosition = i * fileLength / numWorkers;
                long endPosition = (i == numWorkers - 1) ? fileLength : (i + 1) * fileLength / numWorkers;
                chunkProcessors.add(new ChunkProcessor(fileChannel, startPosition, endPosition, logWriter));
            }

            ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(numWorkers);

            for (ChunkProcessor processor : chunkProcessors) {
                executor.execute(processor);
            }

            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

            StringBuilder report = new StringBuilder("Report:\n");
            for (ChunkProcessor processor : chunkProcessors) {
                report.append(processor.getStatus()).append("\n");
            }

            return report.toString();
        }
    }

    static class ChunkProcessor implements Runnable {
        private final FileChannel fileChannel;
        private final long startPosition;
        private final long endPosition;
        private final PrintWriter logWriter;

        public ChunkProcessor(FileChannel fileChannel, long startPosition, long endPosition, PrintWriter logWriter) {
            this.fileChannel = fileChannel;
            this.startPosition = startPosition;
            this.endPosition = endPosition;
            this.logWriter = logWriter;
        }

        @Override
        public void run() {
            try (RandomAccessFile chunkFile = new RandomAccessFile(fileChannel, "r")) {
                chunkFile.seek(startPosition);
                byte[] buffer = new byte[(int) (endPosition - startPosition)];
                int bytesRead = chunkFile.read(buffer);
                if (bytesRead != buffer.length) {
                    logWriter.printf("Error reading chunk %d: Expected to read %d bytes, but only %d bytes were read.\n", Thread.currentThread().getId(), buffer.length, bytesRead);
                    return;
                }

                // Process the byte array here (e.g., parse it, perform calculations, etc.)

            } catch (IOException e) {
                logWriter.printf("Error processing chunk %d: %s\n", Thread.currentThread().getId(), e.getMessage());
            }
        }

        public String getStatus() {
            return String.format("Chunk %d: Processed successfully.", Thread.currentThread().getId());
        }
    }
}
