    public abstract class DataLoader
    {
        private string dataSourceType;
        private string connectionString;
        private Dictionary<string, DataType> schemaDefinition;

        protected virtual void OnLoadDataCompleted(List<Dictionary<string, object>> data) { }
        protected virtual void OnPreprocessDataCompleted(List<Dictionary<string, object>> preprocessedData) { }

        public string ToString()
        {
            return $"DataLoader: SourceType={dataSourceType}, ConnectionString={connectionString}, SchemaDefinition={string.Join(", ", schemaDefinition.Select(x => $"{x.Key}: {x.Value}"))}";
        }

        public virtual async Task LoadDataFromSourceAsync()
        {
            // Implement data loading logic based on the source type (CSV, JSON, SQL database)
            // Call OnLoadDataCompleted event with the loaded data
            var data = await LoadData();
            OnLoadDataCompleted(data);
        }

        public virtual void PreprocessData()
        {
            // Implement preprocessing logic based on schema definition and handle missing values, normalization, etc.
            var preprocessedData = new List<Dictionary<string, object>>();
            foreach (var row in Data)
            {
                var preprocessedRow = new Dictionary<string, object>();
                foreach (var keyValuePair in row)
                {
                    // Apply transformations based on schema definition
                    preprocessedRow[key] = Normalize(keyValuePair.Value);
                }
                preprocessedData.Add(preprocessedRow);
            }
            OnPreprocessDataCompleted(preprocessedData);
        }

        public virtual void ValidateSchema()
        {
            // Implement schema validation logic and throw exceptions if discrepancies are found
            if (Data.Select(x => x.Keys).FirstOrDefault() != schemaDefinition.Keys)
            {
                throw new InvalidSchemaException("Incorrect schema structure.");
            }

            foreach (var row in Data)
            {
                foreach (var key in row.Keys)
                {
                    if (!schemaDefinition.ContainsKey(key))
                    {
                        throw new InvalidSchemaException($"Unexpected column '{key}'.");
                    }

                    var value = row[key];
                    var dataType = schemaDefinition[key];

                    if (dataType == DataType.Int && !int.TryParse(value as string, out _))
                    {
                        throw new InvalidSchemaException($"Invalid integer value for column '{key}'. Expected int.");
                    }
                    else if (dataType == DataType.Double && !double.TryParse(value as string, out _))
                    {
                        throw new InvalidSchemaException($"Invalid double value for column '{key}'. Expected double.");
                    }
                }
            }
        }

        public List<Dictionary<string, object>> GetSampleData()
        {
            // Implement logic to return a random sample of the preprocessed data
            const int SAMPLE_SIZE = 10;
            return preprocessedData.OrderBy(_ => Guid.NewGuid()).Take(SAMPLE_SIZE).ToList();
        }

        public void SavePreprocessedData()
        {
            // Implement logic to save the preprocessed data in a suitable format for machine learning models (e.g., CSV, JSON)
            using var writer = new StreamWriter("data.csv");
            foreach (var row in PreprocessedData)
            {
                var keys = row.Keys.OrderBy(x => x).ToList();
                writer.WriteLine(string.Join(",", keys.Select(x => $"{row[x]}")));
            }
        }

        protected abstract Task<List<Dictionary<string, object>>> LoadData();
        public enum DataType { Int, Double }
    }
}
