<?php

class FileStorageManager {
    private $storage;
    private $cache = [];
    private $lock;

    public function __construct() {
        $this->storage = new SimulatedFileStorage(); // Use an appropriate storage system here
        $this->lock = new Flock();
    }

    public function uploadFile($filename, $fileContent) {
        $this->lock->lock();
        try {
            $this->storage->uploadFile($filename, $fileContent);
        } finally {
            $this->lock->unlock();
        }
    }

    public function downloadFile($filename) {
        if (!isset($this->cache[$filename])) {
            $this->lock->lock();
            try {
                $content = $this->storage->downloadFile($filename);
                $this->cache[$filename] = $content;
            } finally {
                $this->lock->unlock();
            }
        }
        return $this->cache[$filename];
    }

    public function listFiles() {
        return $this->storage->listFiles(); // Optimize the method implementation based on your storage system
    }

    public function deleteFile($filename) {
        $this->lock->lock();
        try {
            if ($this->storage->deleteFile($filename)) {
                unset($this->cache[$filename]);
            }
        } finally {
            $this->lock->unlock();
        }
    }

    public function renameFile($oldFilename, $newFilename) {
        if ($oldFilename !== $newFilename) {
            $this->lock->lock();
            try {
                $result = $this->storage->renameFile($oldFilename, $newFilename);

                if (!$result && isset($this->cache[$oldFilename])) {
                    $this->cache[$newFilename] = $this->cache[$oldFilename];
                    unset($this->cache[$oldFilename]);
                }
            } finally {
                $this->lock->unlock();
            }
        }
    }
}

