    virtual void setData(const std::vector<char>& data) = 0;
    virtual const std::vector<char>& getData() const = 0;
};

class LeafNode : public OctreeNode {
private:
    std::vector<char> data_;
public:
    LeafNode(const std::vector<char>& data) : data_(data) {}
    void setData(const std::vector<char>& data) override { data_ = data; }
    const std::vector<char>& getData() const override { return data_; }
};

class InternalNode : public OctreeNode {
private:
    std::unique_ptr<OctreeNode> child_[8];
public:
    void setChild(int index, std::unique_ptr<OctreeNode> node) { child_[index] = std::move(node); }
    const std::unique_ptr<OctreeNode>& getChild(int index) const { return child_[index]; }
};

