import java.io.IOException;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class FileUploadProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileUploadProcessor.class);
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final StorageHandlerFactory storageHandlerFactory;
    private final int maxConcurrency;

    public FileUploadProcessor(StorageHandlerFactory storageHandlerFactory, int maxConcurrency) {
        this.storageHandlerFactory = storageHandlerFactory;
        this.maxConcurrency = Math.min(maxConcurrency, 10);
    }

    public void processFileUploads(BlockingQueue<MultipartFile> uploadQueue) {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleWithFixedDelay(() -> {
            if (!uploadQueue.isEmpty()) {
                Runnable runnable = this::processFile;
                executorService.submit(runnable, runnable);
            }
        }, 0, 100, TimeUnit.MILLISECONDS);
    }

    private void processFile() {
        try {
            MultipartFile file = uploadQueue.take();
            StorageHandler storageHandler = storageHandlerFactory.createStorageHandler(file.getContentType());
            long startTime = System.currentTimeMillis();

            try (InputStream inputStream = file.getInputStream()) {
                storageHandler.store(inputStream, file.getOriginalFilename(), file.getSize());
            } catch (IOException e) {
                LOGGER.error("Error while storing file: " + file.getOriginalFilename() + ", error: " + e.getMessage());
                // Handle the error appropriately, such as by returning an error response to the client.
            }

            long endTime = System.currentTimeMillis();
            double durationInSeconds = (endTime - startTime) / 1000.0;
            LOGGER.info("File '{}' uploaded successfully in {} seconds.", file.getOriginalFilename(), durationInSeconds);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            // Handle the InterruptedException appropriately, such as by returning an error response to the client.
        }
    }

    // Add a method for configurable upload timeouts and retry mechanisms if needed.
}
