    def run_concurrent_operations(self, operations: List[FileOperation], num_threads: int = 4, max_queue_size: int = 10) -> List[PerformanceMetrics]:
        for operation in operations:
            self.operations_queue.put(operation)

        self.worker_threads = [threading.Thread(target=self._process_file_operation, args=(num_threads, max_queue_size)) for _ in range(num_threads)]

        for thread in self.worker_threads:
            thread.start()

        for thread in self.worker_threads:
            thread.join()

        metrics = []
        while not self.operations_queue.empty():
            operation = self.operations_queue.get()
            metrics.append(PerformanceMetrics(**operation.as_dict()))

        return metrics

    def _process_file_operation(self, num_threads: int, max_queue_size: int):
