const newTestamentBooks = /(Matthew|Mark|Luke|John|Acts|Romans|1Corinthians|2Corinthians|Galatians|Ephesians|Philippians|Colossians|1Thessalonians|2Thessalonians|1Timothy|2Timothy|Titus|Philemon|Hebrews|James|1Peter|2Peter|1John|2John|3John|Jude|Revelation)/gi;

function countBibleBookMentions(text) {
    let bookCounts = {};
    const words = text.toLowerCase().match(/\b\w+\b/g);

    for (let word of words) {
        if (oldTestamentBooks.test(word)) {
            if (bookCounts[word]) bookCounts[word]++;
            else bookCounts[word] = 1;
        } else if (newTestamentBooks.test(word)) {
            // Add support for translations and user preferences here
            if (bookCounts[word]) bookCounts[word]++;
            else bookCounts[word] = 1;
        }
    }

    return Object.entries(bookCounts).sort((a, b) => b[1] - a[1]).reduce((obj, [key, value]) => {
        obj[key] = value;
        return obj;
    }, {});
}
