void SessionIdGenerator::SeedEngine() {
    timeval tv;
    gettimeofday(&tv, NULL);
    unsigned long int seed = (tv.tv_sec * 1000 + tv.tv_usec) % INT64_MAX;
    _rd.reset(new std::random_device(seed));
    _engine.reset(new std::mt19937_64(*_rd));
}

SessionIdGenerator::SessionIdGenerator(const std::string& nodeName) : _nodeName(nodeName) {
    if (_generators.count(nodeName) > 0) {
        throw std::runtime_error("Multiple generators for the same node are not allowed.");
    }
    SeedEngine();
}

void SessionIdGenerator::GenerateRandomChars(char* chars, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        chars[i] = RANDOM_CHARS[_engine->generate() % sizeof(RANDOM_CHARS)];
    }
}

