```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <errno.h>

typedef struct Record {
    long offset;
    int key;
} Record;

struct DataSource {
    sem_t stream_mutex; // Mutex for data source access
    sem_t eof_signal;   // Signal when end of stream is reached
    bool has_more_data; // Flag to indicate if more data available
};

// External data source callback function
void populate_records(struct DataSource* ds, Record* records, size_t capacity);

sem_t records_mutex; // Mutex for record array access
Record* initialize_record_array(size_t num_records) {
    if (num_records == 0) return NULL;

    Record* records = (Record*)malloc(sizeof(Record) * num_records);
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    sem_init(&records_mutex, 0, 1); // Lock initially

    struct DataSource ds = { .has_more_data = true };
    sem_init(&ds.stream_mutex, 0, 1);
    sem_init(&ds.eof_signal, 0, 0);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_data_source, &ds);

    // Process records in the meantime
    size_t processed_records = 0;
    for (size_t i = 0; i < num_records && ds.has_more_data; ++i) {
        sem_wait(&records_mutex);
        records[i].offset = -1; // Placeholder value
        sem_post(&records_mutex);
    }

    pthread_join(thread_id, NULL);

    // Sort records by offset and clear placeholder values
    qsort(records, processed_records, sizeof(Record), compare_records);
    for (size_t i = 0; i < processed_records; ++i) {
        records[i].offset = -1;
    }

    sem_destroy(&records_mutex);
    sem_destroy(&ds.stream_mutex);
    sem_destroy(&ds.eof_signal);

    if (processed_records < num_records) {
        perror("Failed to populate all records");
        free(records);
        return NULL;
    }

    return records;
}

void* process_data_source(void* data_source) {
    struct DataSource* ds = (struct DataSource*)data_source;

    while (ds->has_more_data) {
        sem_wait(&ds->stream_mutex);

        // Populate records with data from the external source
        populate_records(ds, records, num_records);

        if (!ds->has_more_data) {
            sem_post(&ds->eof_signal);
        }

        sem_post(&ds->stream_mutex);
    }

    return NULL;
}

int compare_records(const void* a, const void* b) {
    return (*(Record*)a).offset - *(Record*)b).offset;
}
```

In this code:

1. The `initialize_record_array` function takes the number of records as a parameter and returns a pointer to the initialized array. It initializes the record array, creates and starts the data source processing thread, processes some records in parallel, sorts the records by offset, clears placeholder values, and finally destroys mutexes and returns the sorted array.

2. The function `process_data_source` is a worker thread that processes data from the external data source.

3. The `populate_records` function should be implemented based on your specific data source integration needs.

4. Semaphores are used to synchronize access to the record array and the data source.

5. Error messages are displayed using perror() or by returning NULL when memory allocation fails or if there is an issue with the external data source.

6. The code is modular, readable, and maintainable, though unit tests and documentation should be added as part of a complete implementation.

