from typing import List, Dict, Any
import concurrent.futures

def execute_unit_tests(module_name: str, config: Dict[str, Any], skip_tests: List[str] = [], flaky_test_threshold: int = 3) -> Dict[str, Any]:
    test_results = {}
    log_format = "%(asctime)s [%(threadName)s] %(levelname)s - %(message)s"
    logging.basicConfig(format=log_format, level=logging.INFO)

    def _run_test(test_func):
        try:
            test_func()
            return {"status": "pass", "execution_time": time.time() - start_time}
        except Exception as e:
            logging.exception(e)
            return {"status": "fail", "exception": str(e), "execution_time": time.time() - start_time}

    def _discover_tests():
        tests = []
        module = importlib.import_module(module_name)
        for name, obj in vars(module).items():
            if callable(obj) and not name.startswith("__"):
                tests.append((name, obj))
        return tests

    def _run_tests_in_parallel(tests: List[(str, Any)]):
        with concurrent.futures.ThreadPoolExecutor(max_workers=config["concurrency"]) as executor:
            results = [executor.submit(_run_test, test) for test in tests]
            for result in concurrent.futures.as_completed(results):
                test_result = result.result()
                test_name = test_result["func_name"]
                if test_name not in skip_tests:
                    test_results[test_name] = test_result

    start_time = time.time()
    tests = _discover_tests()
    _run_tests_in_parallel(tests)

    test_report_html = generate_test_report_html(test_results, config["logging"]["filename"])
    logging.info("Test report generated: %s", test_report_html)

    return {"test_results": test_results, "test_report_html": test_report_html}

