// Module for fetching scripts
async function fetchScript(script) {
    const cacheKey = `script-${script.version}`;

    if (self.cache.has(cacheKey)) {
        return self.cache.get(cacheKey);
    }

    const response = await fetch(`/api/scripts/${script.id}`);
    const scriptTag = document.createElement('script');
    scriptTag.innerHTML = await response.text();
    scriptTag.async = true;

    // Cache the fetched script and return it
    self.cache.set(cacheKey, scriptTag);
    return scriptTag;
}

// Module for managing cache
const worker = new Worker('script-worker.js');
let scriptsCache = new Map();

// Module for rendering scripts
async function renderFooter(scripts) {
    const loadingIndicator = document.getElementById('loading-indicator');
    loadingIndicator.style.display = 'block';

    const scriptPromises = scripts.map((script) => fetchScript(script));
    await Promise.all(scriptPromises);

    // Render the fetched scripts in the footer container
    const footerContainer = document.getElementById('footer-container');
    for (const script of scripts) {
        const existingScript = footerContainer.querySelector(`[data-id="${script.id}"]`);

        if (!existingScript) {
            const scriptTag = await fetchScript(script);
            footerContainer.appendChild(scriptTag);
        }
    }

    loadingIndicator.style.display = 'none';
}

// Example usage:
const scripts = [
    { id: 1, version: 'v1' }, // ...add more script objects here
];
renderFooter(scripts);
