std::vector<Node> loadNodesFromConfig(const fs::path& configFile) {
    ptree pt;
    read_xml(configFile, pt);

    std::vector<Node> nodes;
    for (auto& item : pt.get_child("nodes")) {
        int key = item.get<int>("key");
        std::string value = item.get<std::string>("value");
        time_t creationTime = item.get<time_t>("creation_time");
        time_t lastAccessTime = item.get<time_t>("last_access_time");
        nodes.push_back({ key, value, creationTime, lastAccessTime });
    }
    return nodes;
}
