Create a function to serialize and deserialize the `Node` array:

```cpp
rapidjson::Document serializeNodes(const std::vector<Node>& nodes) {
    rapidjson::Document doc(rapidjson::kObjectType);
    rapidjson::Document::AllocatorType allocator = doc.GetAllocator();
    doc.AddMember("nodes", rapidjson::Value(rapidjson::kArrayType).Move(), allocator);

    for (const auto& node : nodes) {
        rapidjson::Document nodeDoc(rapidjson::kObjectType);
        nodeDoc.AddMember("key", node.key, allocator);
        nodeDoc.AddMember("value", node.value.c_str(), allocator);
        nodeDoc.AddMember("creation_time", rapidjson::Value(node.creation_time).Move(), allocator);
        nodeDoc.AddMember("last_access_time", rapidjson::Value(node.last_access_time).Move(), allocator);
        doc["nodes"].PushBack(nodeDoc, allocator);
    }

    return doc;
}

void deserializeNodes(const rapidjson::Document& doc, std::vector<Node>& nodes) {
    const auto& nodesArray = doc["nodes"];
    for (size_t i = 0; i < nodesArray.Size(); ++i) {
        Node node;
        auto currentNode = nodesArray[i];

        node.key = currentNode["key"].GetInt();
        node.value = currentNode["value"].GetString();
        node.creation_time = static_cast<time_t>(currentNode["creation_time"].GetUint64());
        node.last_access_time = static_cast<time_t>(currentNode["last_access_time"].GetUint64());
        nodes.push_back(node);
    }
}
```

