```python
import os
import pathlib
import logging
from functools import lru_cache
from multiprocessing import Pool

def is_valid_file(file):
    valid_extensions = [".txt", ".csv"]
    _, ext = os.path.splitext(file)
    return ext in valid_extensions

@lru_cache()
def get_creation_time(file):
    try:
        return pathlib.Path(file).stat().ctime
    except Exception as e:
        logging.error(f"Error getting creation time for {file}: {e}")
        return None

@lru_cache()
def get_file_size(file):
    try:
        return pathlib.Path(file).stat().st_size
    except Exception as e:
        logging.error(f"Error getting file size for {file}: {e}")
        return None

def count_stats(directory, output=None, min_creation_time=None, max_creation_time=None, min_size=None, max_size=None):
    total_lines = 0
    total_words = 0
    total_chars = 0
    file_count = 0

    def process_file(file):
        nonlocal total_lines, total_words, total_chars, file_count
        if is_valid_file(file) and (not min_creation_time or get_creation_time(file) >= min_creation_time) \
           and (not max_creation_time or get_creation_time(file) <= max_creation_time) and (not min_size or get_file_size(file) >= min_size) \
           and (not max_size or get_file_size(file) <= max_size):
            with open(file, "r") as f:
                for line in f:
                    total_lines += 1
                    total_words += sum(1 for word in line.split())
                    total_chars += len(line)
            file_count += 1

    if __name__ == "__main__":
        path = pathlib.Path(directory)
        if not path.is_dir():
            logging.error(f"Invalid directory path: {directory}")
            return

        pool = Pool()
        pool.map(process_file, list(path.glob("**/*")))

        print(f"Total files processed: {file_count}")
        print(f"Total lines: {total_lines}")
        print(f"Total words: {total_words}")
        print(f"Total characters: {total_chars}")
