    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<PasswordManager> _logger;
        private readonly ICache _cache;
        private readonly ExternalAuthenticationAPI _externalAuth;

        public PasswordManager(IConfiguration configuration, ILogger<PasswordManager> logger, ICache cache, ExternalAuthenticationAPI externalAuth)
        {
            _configuration = configuration;
            _logger = logger;
            _cache = cache;
            _externalAuth = externalAuth;
        }

        public void SetHashingAlgorithm(string algorithm) => _configuration.GetSection("Security").GetValue<string>("HashingAlgorithm", "Argon2");

        public string HashPassword(string password)
        {
            var hashingAlgorithm = GetHashingAlgorithm();
            switch (hashingAlgorithm)
            {
                case "SHA-256": return SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(password)).ToHexString();
                case "bcrypt": return BCrypt.Net.BCrypt.HashPassword(password);
                case "Argon2": return Argon2.id.DeriveBytes256(password).ToString();
                default: throw new Exception("Invalid hashing algorithm.");
            }
        }

        public bool VerifyPassword(string hashedPassword, string plainTextPassword)
        {
            var hashingAlgorithm = GetHashingAlgorithm();
            switch (hashingAlgorithm)
            {
                case "SHA-256": return SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(plainTextPassword)).Equals(HexStringToByteArray(hashedPassword));
                case "bcrypt": return BCrypt.Net.BCrypt.Verify(plainTextPassword, hashedPassword);
                case "Argon2": return Argon2.id.Verify(hashedPassword, Encoding.UTF8.GetBytes(plainTextPassword));
                default: throw new Exception("Invalid hashing algorithm.");
            }
        }

