int convertImageToPdf(const char *input_file, const char *output_file, const Config *config) {
    struct stat input_stat;
    if (stat(input_file, &input_stat) != 0) {
        fprintf(stderr, "Error: Unable to find the input file.\n");
        return 1;
    }

    if (!S_ISREG(input_stat.st_mode)) {
        fprintf(stderr, "Error: The input file is not a regular file.\n");
        return 1;
    }

    int width = ... // Read image dimensions from input_file
    int height = ... // Read image dimensions from input_file

    if (width < config->min_width || width > config->max_width || height < config->min_height || height > config->max_height) {
        fprintf(stderr, "Error: Image dimensions out of range. Width: %d, Height: %d\n", width, height);
        return 1;
    }

    pid_t pid = fork();

    if (pid == -1) {
        perror("Error: Fork failed");
        return 1;
    } else if (pid > 0) { // Parent process
        waitpid(pid, NULL, 0);
    } else { // Child process
        char *args[] = {"/path/to/tool", input_file, output_file, NULL};
        execv(config->tool_path, args);
        perror("Error: Executing the tool failed");
        _exit(1);
    }

