void parse_args(int argc, char **argv, Config *config) {
    const char *short_opts = "t:w:h:m:M:";
    const struct option long_opts[] = {
        {"tool", required_argument, NULL, 't'},
        {"min-width", required_argument, NULL, 'w'},
        {"max-width", required_argument, NULL, 'M'},
        {"min-height", required_argument, NULL, 'h'},
        {"max-height", required_argument, NULL, 'm'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    char c;

    while ((c = getopt_long(argc, argv, short_opts, long_opts, &option_index)) != -1) {
        switch (c) {
            case 't': config->tool_path = optarg; break;
            case 'w': config->min_width = atoi(optarg); break;
            case 'M': config->max_width = atoi(optarg); break;
            case 'h': config->min_height = atoi(optarg); break;
            case 'm': config->max_height = atoi(optarg); break;
        }
    }

    // Set default values for configuration properties here if not specified on the command-line.
}

int main(int argc, char **argv) {
    Config config;
    parse_args(argc, argv, &config);

    if (convertImageToPdf(argv[optind], argv[optind + 1], &config) != 0)
        return 1;

    // Additional cleanup or logging code here if needed.
    return 0;
}
