```python
import xml.etree.ElementTree as ET
import requests
from urllib.parse import urljoin

class XPathIterator:
    def __init__(self, document, xpath_expression):
        self.document = document
        self.iterator = iter(self._filtered_elements(xpath_expression))

    def __iter__(self):
        return self

    def __next__(self):
        try:
            return next(self.iterator)
        except StopIteration:
            raise StopIteration("No more elements")

    def _filtered_elements(self, xpath_expression):
        for event, element in self.document.iterfind(xpath_expression, {None: "namespaces"}):
            yield element

def validate_element(element):
    url = f"https://api.example.com/validate-schema"
    schema_response = requests.post(url, json={"xml": ET.tostring(element)})

    if schema_response.status_code == 200:
        return schema_response.json()["valid"]
    else:
        print(f"Error validating element: {schema_response.reason}")
        return False

def parse_and_iterate(xml_data, xpath_expression):
    root = ET.fromstring(xml_data)
    for element in XPathIterator(root, xpath_expression):
        if validate_element(element):
            yield element
