using System;
using UnityEngine;
using System.Collections.Generic;
using System.Linq;

public class ValueGenerator : MonoBehaviour
{
    private readonly (float min, float max) _range;
    private readonly bool _isClamped;
    private const int MaxArraySize = 1000;

    public ValueGenerator((float min, float max) range, bool isClamped = false)
    {
        if (range.min > range.max)
            throw new ArgumentOutOfRangeException(nameof(range), "Minimum value must be less than or equal to maximum value.");

        _range = range;
        _isClamped = isClamped;
    }

    public float GenerateFloat() => _isClamped ? UnityEngine.Random.Range(_range.min, _range.max + (_range.max - _range.min) * 0.001f) : UnityEngine.Random.Range(_range.min, _range.max);

    public int GenerateInt() => (int)Mathf.Round(GenerateFloat());

    public int[] GenerateIntArray(int size)
    {
        if (size > MaxArraySize) throw new ArgumentOutOfRangeException(nameof(size), "Array size cannot exceed 1000 elements to prevent potential performance issues.");

        int[] array = Enumerable.Repeat(0, size).Select(GenerateInt).ToArray();
        Array.Sort(array);
        return array;
    }

    public float[] GenerateFloatArray(int size) => size > MaxArraySize ? throw new ArgumentOutOfRangeException(nameof(size), "Array size cannot exceed 1000 elements to prevent potential performance issues.") : Enumerable.Repeat(0f, size).Select(GenerateFloat).ToArray();

    public int[] GeneratePermutation(int size)
    {
        if (size > MaxArraySize) throw new ArgumentOutOfRangeException(nameof(size), "Array size cannot exceed 1000 elements to prevent potential performance issues.");

        int[] array = Enumerable.Repeat(0, size).ToArray();
        for (int i = 0; i < array.Length; ++i)
            Swap(ref array[i], UnityEngine.Random.Range(0, i));
        return array;
    }

    private void Swap(ref int a, int b) => (a, a = b) = (b, a);

    public override string ToString() => $"ValueGenerator [min: {_range.min}, max: {_range.max}, clamped: {_isClamped}]";

    private void OnValidate() => _range.min <= _range.max;
}
```

