from schema import Schema, And, Use, Or, Text, List, Dict

# External configuration management system interface
config_manager = ConfigManagementSystem()

# Protocol configuration schema validation
protocol_schema = Schema(
    {
        "name": And(Text(), lambda x: not x in protocols),  # Unique name for each protocol
        "implementation_module": Text(),
        "description": Text(),
        "supported_features": List(Text()),
        "default_config": Dict(Text(), Any()),
        "feature_flags": Dict(Text(), bool),
    }
)

def load_protocols(directory: str):
    protocols = {}
    cache = {}

    def _load_module(module_path: str):
        try:
            module = importlib.import_module(module_path)
        except ModuleNotFoundError as e:
            logging.error(f"Failed to load module {module_path}: {e}")
            return None
        return module

    for file in os.listdir(directory):
        if not file.endswith(".py"):
            continue
        module_name = f"{os.path.splitext(file)[0]}"
        module_path = os.path.join(directory, file)
        cached_module = cache.get(module_name)
        if cached_module is not None:
            module = cached_module
        else:
            module = _load_module(module_name)
            if module is None:
                continue
            cache[module_name] = module

        for name, obj in inspect.getmembers(module, inspect.isclass):
            if issubclass(obj, ProtocolImplementation) and not callable(obj):
                config = config_manager.get_config(f"protocols.{name}")
                if not protocol_schema.validate(config):
                    logging.error(f"Invalid configuration for protocol {name}: {protocol_schema.validate(config, inplace=True)}")
                    continue
                protocols[config["name"]] = {
                    "implementation_class": obj,
                    # ... other fields can be populated based on the config here
                }

    return protocols

class ProtocolImplementation:
    pass

def main():
