class FileReader():
    def __init__(self, filename):
        self.filename = filename

    def readlines(self):
        try:
            with open(self.filename) as file:
                return slist(line for line in file)
        except IOError as e:
            print("File Reading Error:", str(e))

    def sorted(self):
        self.readlines()
        return sorted(self)

    def tail(self, n):
        self.sorted()
        return self[-n:]

    def value(self):
        if len(self) > 0:
            return self[-1].value
        else:
