                            break;
                        case FileFormats.Xml:
                            ProcessXml(fileStream);
                            break;
                        default:
                            _logger.Error($"Unsupported file format '{fileFormat}'.");
                            throw new NotSupportedException("Unsupported file format.");
                    }
                }
            });
