        }

        private async Task WithReadLockAsync(Func<Task> action)
        {
            await _rwLock.ReadLockAsync(() =>
            {
                if (_concurrentOperations.Any())
                {
                    _concurrentOperations.Enqueue(action);
                }
                else
                {
                    action().ContinueWith(_ => _rwLock.ReleaseReadLock());
                }
            });
        }
    }

