    public IDataReader ExecuteCommand(string commandTemplate, List<object> parameters)
    {
        if (_rateLimiter.IsRateLimited())
            throw new Exception("Rate limit exceeded.");

        lock (_semaphore)
        {
            if (_currentProvider == null || _currentProvider.GetHashCode() != GetCurrentProvider().GetHashCode())
                _currentProvider = GetCurrentProvider();
        }

        var command = PrepareCommand(commandTemplate, parameters);
        return _currentProvider().ExecuteCommand(command, parameters.ToArray());
    }

    private string PrepareCommand(string commandTemplate, List<object> parameters)
    {
        // Implement SQL injection prevention and logging here.

        var command = new StringBuilder();
        command.Append(commandTemplate);

        for (int i = 0; i < parameters.Count; i++)
            command.AppendFormat("@{0}", i);

        using (var connection = GetCurrentProvider().CreateConnection())
        {
            connection.Open();

            var parameterBuilder = new SqlCommand(command.ToString(), connection).Parameters;
            for (int i = 0; i < parameters.Count; i++)
                parameterBuilder.AddWithValue($"@{i}", parameters[i]);

            return command.Replace(new Regex(@"\@{[0-9]+}"), m => parameterBuilder[int.Parse(m.Groups[1].Value)].ParameterName);
        }
    }

    private Func<IDatabaseProvider> GetCurrentProvider()
    {
        var key = GetEnvironmentKey();
        return _providers[key];
    }

    private string GetEnvironmentKey()
    {
        // Implement environment-specific configurations here.
    }

    public void Dispose()
    {
        if (_currentProvider != null)
            _currentProvider.Dispose();
    }
}
