public async Task<T> LoadDataFromBinaryAsync(string fileName, ILogger<T> logger, bool useCache = true)
{
    Func<Task<T>> loadFunction;
    object cachedData;

    if (useCache && Cache.TryGetValue(fileName, out cachedData))
        return (T)cachedData;

    lock (fileLocker)
    {
        if (!File.Exists(fileName))
        {
            logger.LogError($"The file '{fileName}' does not exist.");
            throw new FileNotFoundException();
        }

        loadFunction = () => JsonConvert.DeserializeObjectAsync<T>(await File.ReadAllTextAsync(fileName));
    }

    try
    {
        return await loadFunction();
    }
    catch (JsonReaderException ex) when (ex.Message.Contains("Version"))
    {
        logger.LogWarning($"Data file '{fileName}' has an older version, migrating data...");
        var oldData = JsonConvert.DeserializeObject<OldDataType>(await File.ReadAllTextAsync(fileName));
        return Mapper.Map<T>(oldData);
    }
    catch (Exception ex)
    {
        logger.LogError($"An error occurred while deserializing the data file '{fileName}': {ex.Message}", ex);
        throw;
    }
    finally
    {
        if (!useCache)
            Cache.Add(fileName, loadFunction.Invoke());
    }
}
