Here is the C++ code for the function `SelectAttack()` with the requested features. I've used `std::mutex` for thread-safety, `boost::property_tree` library for logging, and a `std::unordered_map` to track attack usage.

```cpp
#include <iostream>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <unordered_map>
#include <chrono>

namespace pt = boost::property_tree;
using namespace std::chrono_literals;
using Clock = std::chrono::high_resolution_clock;

std::mutex mtx;
std::unordered_map<int, int> attackUsages; // Attack number, Usage count
const int maxAttackUsage = 100;

void UpdateEnergy(int delta) {
    std::scoped_lock lock(mtx);
    auto now = Clock::now();
    energy += delta;
    if (energy < 0) energy = 100;
}

void LogWarning(const std::string& message) {
    pt::ptree log;
    log.put("message", message);

    // Load the logger configuration file
    std::ifstream configFile("logger_config.json");
    pt::read_json(configFile, root);
    auto logger = root.get<std::string>("Logger.Logfile");

    boost::property_tree::write_json(std::ofstream(logger), log);
}

void SelectAttack() {
    std::scoped_lock lock(mtx);
    Clock::time_point lastUsed[3]{}; // Last used time for each attack
    int energy = 100; // Character's energy level

    auto now = Clock::now();
    auto duration[3] = {5s, 7s, 10s}; // Cooldown periods for each attack

    std::uniform_int_distribution<> dist(1, 3);
    int selectedAttack = dist(std::random_device{});

    if (attackUsages[selectedAttack] >= maxAttackUsage) {
        LogWarning("Attack limit reached for Attack " + std::to_string(selectedAttack));
        return;
    }

    // Check cooldown period
    auto elapsed = now - lastUsed[selectedAttack - 1];
    if (elapsed < duration[selectedAttack - 1]) return;

    UpdateEnergy(-10 * selectedAttack);
    attackUsages[selectedAttack]++;
    std::cout << "Selected Attack: " << selectedAttack << "\n";

    lastUsed[selectedAttack - 1] = now;
}
