    private static final String OAUTH2_TOKEN_URL = "YOUR_OAUTH2_TOKEN_URL";
    private static final int MAX_RETRIES = 5;
    private static final TimeUnit TIME_UNIT = TimeUnit.MINUTES;
    private static final ScheduledExecutorService EXECUTOR = Executors.newScheduledThreadPool(10);

    public void sendNotificationEmails(List<String> recipients, Map<String, String> notificationRule, String subject, String body) {
        // Validate email addresses and notificationRule
        for (String recipient : recipients) {
            if (!isValidEmail(recipient)) {
                log("Invalid email address: " + recipient);
                continue;
            }
        }

        if (notificationRule == null || notificationRule.isEmpty()) {
            log("No valid notification rules provided");
            return;
        }

        // Fetch OAuth2 token if needed
        String accessToken = getAccessTokenIfNeeded();

        for (String recipient : recipients) {
            Email email = createEmail(recipient, subject, body, notificationRule);

            Runnable sendTask = () -> sendEmailViaSMTPService(accessToken, email);
            sendTask.run();
        }
    }

    private boolean isValidEmail(String email) {
        // Implement a simple email validation here, or use a library like javax.mail.internet.Address for more comprehensive checks
        return email.contains("@") && email.contains(".");
    }

    private String getAccessTokenIfNeeded() {
        // Integrate with OAuth2 provider to fetch an access token if necessary
        // ...
        return "YOUR_ACCESS_TOKEN";
    }

    private Email createEmail(String recipient, String subject, String body, Map<String, String> notificationRule) {
        // Customize email content based on the notification rule and create an Email object
        Email email = new Email();
        email.setRecipient(recipient);
        email.setSubject(subject);
        email.setBody(body);

        if (notificationRule.containsKey("critical_alert")) {
            email.setTemplate("critical_alert");
        } else {
            email.setTemplate("routine_reminder");
        }

        return email;
    }

    private void sendEmailViaSMTPService(String accessToken, Email email) {
        try {
            // Implement SMTP service integration here using a library like java-smtp-api or javax.mail
            // ...

            log("Sent email to " + email.getRecipient() + ", subject: " + email.getSubject() + ", body: " + email.getBody());
        } catch (Exception e) {
            logError("Failed to send email", e);

            if (email.getRetries() < MAX_RETRIES) {
                scheduleRetry(email);
            }
        }
    }

    private void scheduleRetry(Email email) {
        int backoff = (int) Math.pow(2, email.getRetries());
        long delay = (long) (Math.min(backoff * TIME_UNIT.toMillis(1), Long.MAX_VALUE)) * TimeUnit.MILLISECONDS;
        EXECUTOR.schedule(() -> sendEmailViaSMTPService(email.getAccessToken(), email), delay, TimeUnit.MILLISECONDS);
    }

