        // Execute the loaded instance as appropriate
    }

public:
    void add_factory_function(const FactoryFunction& function) {
        std::unique_lock<std::mutex> lock(_mutex);
        _registry[function.id] = function;
    }

    void update_factory_function(const std::string& id, const FactoryFunction& function) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = _registry.find(id);
        if (it != _registry.end()) {
            it->second = function;
        }
    }

    void delete_factory_function(const std::string& id) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = _registry.find(id);
        if (it != _registry.end()) {
            _registry.erase(it);
        }
    }
};
