import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class ConnectionPool {
    private final ConcurrentHashMap<Integer, Channel> connectionMap = new ConcurrentHashMap<>();
    private final int maxConnections;
    private final EventLoopGroup workerGroup;
    private final Bootstrap bootstrap;
    private final String host;
    private final int port;

    public ConnectionPool(String host, int port, int maxConnections) {
        this.host = host;
        this.port = port;
        this.maxConnections = maxConnections;

        this.workerGroup = new NioEventLoopGroup();
        this.bootstrap = new Bootstrap();
        this.bootstrap.group(this.workerGroup)
                .channel(NioSocketChannel.class)
                .option(ChannelOption.SO_KEEPALIVE, true)
                .handler(new ChannelInitializer<SocketChannel>() {
                    @Override
                    protected void initChannel(SocketChannel ch) throws Exception {
                        // Initialize your messaging system here
                    }
                });
    }

    public Channel getConnection(int index) {
        Channel channel = connectionMap.get(index);
        if (channel == null || !channel.isActive()) {
            synchronized (connectionMap) {
                channel = connectionMap.get(index);
                if (channel == null || !channel.isActive()) {
                    channel = acquireConnection();
                    connectionMap.putIfAbsent(index, channel);
                }
            }
        }
        return channel;
    }

    private Channel acquireConnection() {
        Channel channel = bootstrap.connect(host, port).sync().channel();
        if (connectionMap.size() > maxConnections) {
            connectionMap.keySet().stream()
                    .filter(i -> !connectionMap.get(i).isActive())
                    .findFirst()
                    .ifPresent(index -> closeConnection(index));
        }
        return channel;
    }

    private void closeConnection(int index) {
        Channel channel = connectionMap.remove(index);
        if (channel != null && channel.isActive()) {
            channel.close().syncUninterruptibly();
        }
    }

    public void shutdown() throws InterruptedException {
        workerGroup.shutdownGracefully(0, 30, TimeUnit.SECONDS).sync();
    }
}
```

