```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class HashService
{
    private readonly ConcurrentDictionary<string, byte[]> _cache;
    private readonly ILogger<HashService> _logger;

    public HashService(ILogger<HashService> logger)
    {
        _cache = new ConcurrentDictionary<string, byte[]>();
        _logger = logger;
    }

    public async Task<byte[]> ComputeHashAsync(string input)
    {
        if (_cache.TryGetValue(input, out var cachedHash))
        {
            return cachedHash;
        }

        using (var sha256 = SHA256.Create())
        {
            var data = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            _cache.TryAdd(input, data);

            // Log the performance metric - time taken to compute hash
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
            stopwatch.Stop();
            _logger.LogInformation("Hash computed for '{Input}' in {Elapsed}ms", input, stopwatch.ElapsedMilliseconds);

            return data;
        }
    }
}
```

Here's a brief explanation of the code:

- `ConcurrentDictionary<string, byte[]> _cache` is used to store recently computed hashes. It provides thread-safe access to the cache since it's a concurrent collection.
- The function `ComputeHashAsync` takes a string input and returns its SHA-256 hash. If the hash for the given input already exists in the cache, it returns that instead of recomputing the hash to improve performance.
- The code uses the `SHA256.Create()` method from the standard library cryptographic hash function to compute the hash.
- A logger is used to log errors or performance metrics for debugging and monitoring purposes. In this example, we log the time taken to compute each hash.

