        char *filename = malloc(strlen(global_args.dir_path) + strlen(entry->d_name) + 2);
        strcpy(filename, global_args.dir_path);
        strcat(filename, "/");
        strcat(filename, entry->d_name);

        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            free(filename);
            continue;
        }

        pthread_create(&tid, NULL, process_log_file, filename);
        pthread_detach(tid);
    }

    closedir(dir);

    // Continue with logging, error reporting, cleanup, etc.
    ...
}
```

