    private static final ExecutorService EXECUTOR = Executors.newSingleThreadExecutor();
    private static final ScheduledExecutorService COOLDOWN_EXECUTOR = Executors.newScheduledThreadPool(1);
    private static final AtomicInteger ATTACK_COOLDOWN = new AtomicInteger(9000); // in milliseconds
    private static final AtomicInteger MAX_RETRIES = new AtomicInteger(5);
    private static final long RETRY_DELAY = TimeUnit.SECONDS.toMillis(1);
