    }

    private void startConnectionHandlingThread() {
        EXECUTOR.submit(() -> connectionHandler());
    }

    private void connectionHandler() {
        while (true) {
            try {
                validateRemoteAddress();
                connectToRemoteAddress();
                break; // Successfully connected, no need to retry
            } catch (Exception e) {
                handleConnectionError(e);
            }
            delayBeforeRetry();
        }
    }

    private void validateRemoteAddress() throws URISyntaxException {
        // Validate the remote address using appropriate methods, such as URI.create().normalize().getHost() and URI.create().normalize().getScheme()
    }

    private void connectToRemoteAddress() throws IOException {
        // Create a SelectableChannel for the connection and establish it using a SocketChannel
    }

    private void handleConnectionError(Exception e) {
        int retriesLeft = MAX_RETRIES.decrementAndGet();
        if (retriesLeft > 0) {
            LOGGER.warning("Failed to connect; retrying in " + RETRY_DELAY + "ms (" + retriesLeft + " retries left)");
            slackNotifier.sendErrorMessage("Connection failure", e.getMessage());
        } else {
            LOGGER.severe("Maximum number of connection retries exceeded; giving up.");
            slackNotifier.sendErrorMessage("Connection failed after max retries", e.getMessage());
        }
    }

    private void delayBeforeRetry() throws InterruptedException {
        Thread.sleep(RETRY_DELAY);
    }

    private void attackSelection() {
        if (!attacking && ATTACK_COOLDOWN.get() <= (Instant.now().toEpochMilli() - lastAttackTime.toEpochMillis())) {
            attacking = true;
            LOGGER.info("Selected attack " + (new Random().nextInt(2) + 1)); // Generate a random number between 1 and 2 for the attack selection
            lastAttackTime = Instant.now();
        }
    }

