const { Worker, isMainThread, parentPort } = require('worker_threads');
const fs = require('fs');
const path = require('path');
const chokidar = require('chokidar');
const logger = require('./logger'); // Assume you have a logger module to handle logs

function executePluginTestsParallelly(label, f, plugins, numWorkers = 4) {
    const workerData = plugins.map((pluginName) => ({ name: pluginName, testFns: [] }));

    if (isMainThread) {
        const watcher = chokidar.watch(path.join(__dirname, 'plugins'), { persistent: true });
        watcher.on('add', (filePath) => {
            loadTestFunctionsFromFile(filePath).forEach((fn) => {
                workerData.find(({ name }) => fn.pluginName === name).testFns.push(fn);
            });
        });

        for (let i = 0; i < numWorkers; i++) {
            const worker = new Worker(__filename, { workerData: JSON.stringify({ index: i }) });
            worker.on('message', handleWorkerMessage);
        }
    } else {
        handleWorkerMessage(parentPort.send('workerInit'));
    }

    function loadTestFunctionsFromFile(filePath) {
        try {
            const fileContent = fs.readFileSync(filePath, 'utf8');
            return fileContent.trim().split('\n').filter(Boolean).map((line) => {
                const [pluginName, testName] = line.split(':');
                return { pluginName, testName, testFn: new Function(`return () => ${testName}(...arguments);`, line) };
            });
        } catch (err) {
            logger.error(`Error while loading tests from ${filePath}:`, err.message);
            return [];
        }
    }

    function handleWorkerMessage(msg) {
        if (msg === 'start') {
            const { name, testFns } = workerData.shift();
            if (!testFns.length) {
                logger.info(`No tests found for plugin ${name}`);
                return;
            }

            let totalTestDuration = 0;

            testFns.forEach(({ testFn }) => {
                const startTime = Date.now();
                try {
                    testFn()(label, () => {
                        totalTestDuration += (Date.now() - startTime);
                        logger.info(`Completed test for plugin ${name}: ${testName}`);
                    });
                } catch (err) {
                    logger.error(`Error during execution of test for plugin ${name}: ${testName}`, err.message);
                }
            });

            process.send({ plugin: name, duration: totalTestDuration });
        } else if (msg === 'end') {
            // Main thread will collect and log the results here when all workers are done.
        }
    }
}
