```javascript
class ScriptLoader {
  constructor() {
    this.scripts = new Map();
  }

  load(url, onLoad, onError) {
    if (this.scripts.has(url)) return this.scripts.get(url);

    const promise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = url;
      script.onload = () => resolve();
      script.onerror = (err) => reject(err);

      document.head.appendChild(script);
    });

    promise.then(() => {
      if (!this.scripts.has(url)) this.scripts.set(url, null);
      onLoad && onLoad();
    }).catch((error) => {
      if (onError) onError(error);
      console.error(`Script loading error: ${url} - ${error}`);
    });

    return promise;
  }

  loadInOrder(urls, onAllLoaded) {
    const promises = urls.map((url) => this.load(url));

    Promise.all(promises).then(() => {
      if (onAllLoaded) onAllLoaded();
    });
  }
}
```

