import json
import os
import concurrent.futures
from typing import Dict, Any, List, Union, Tuple
import hashlib
import hmac

class Serializable:
    def to_json(self) -> str:
        return json.dumps(self.__dict__, default=lambda o: o.__dict__)

    @staticmethod
    def from_json(data: Any, cls: type) -> 'Serializable':
        obj = cls()
        obj.__dict__.update(json.loads(data))
        return obj

class Registry:
    _registry: Dict[str, type] = {}
    @staticmethod
    def register(cls):
        Registry._registry[cls.__name__] = cls

class Factory:
    _registry: Dict[str, Any] = {}

    @staticmethod
    def register_factory(factory):
        Factory._registry[factory.id] = factory

    @staticmethod
    async def create(cls_name: str, **kwargs) -> Serializable:
        if cls_name not in Factory._registry:
            raise ValueError(f"Factory for class '{cls_name}' not found.")

        factory = Factory._registry[cls_name]
        return factory(**kwargs).create()

class SubclassA(Serializable):
    id = "SubclassA"
    Registry.register(SubclassA)

    def __init__(self, data: Dict[str, Any]):
        super().__init__()
        self.data = data

    async def create(self):
        pass

class SubclassB(Serializable):
    id = "SubclassB"
    Registry.register(SubclassB)

    def __init__(self, data: Dict[str, Any]):
        super().__init__()
        self.data = data

    async def create(self):
        pass

async def load_files(file_paths: List[str]) -> List[Serializable]:
    loaded_objects = []
    executor = concurrent.futures.ThreadPoolExecutor(max_workers=len(file_paths))

    for file in file_paths:
        try:
            with open(file, 'r') as f:
                data = json.load(f)
                cls_name = data['class']
                obj = await Factory.create(cls_name, **data)
                loaded_objects.append(obj)
        except Exception as e:
            print(f"Error loading file {file}: {e}")

    return loaded_objects

def insert_after(lst: List[str], key: str, value: str, position: int = -1) -> List[str]:
    if position < 0 or position > len(lst):
        raise ValueError("Invalid position")

    index = next((i for i, x in enumerate(lst) if x == key), None)

    if index is None:
        lst.append(value)
    else:
        del lst[index + 1:position]
        lst[index+1:position] = [value]* (position - index - 1)
        lst.insert(index + position, value)

    return lst

def serialize_password(password: str, salt: bytes) -> Tuple[str, str]:
    msg = password.encode() + salt
    digest = hmac.new(salt, msg, hashlib.sha256).digest()
    random_string = base64.b64encode(digest).decode()
    return (random_string, hashlib.sha256(password.encode()).hexdigest())
