```python
from abc import ABC, abstractmethod
import concurrent.futures as cf
from typing import Callable, Any, List

class TaskProcessorCallback(ABC):
    @abstractmethod
    def process_task(self, task: Any) -> Any:
        pass

class AsyncTaskQueueManager:

    def __init__(self, concurrency_level: int, max_queue_size: int, priority_enabled: bool = False):
        self.concurrency_level = concurrency_level
        self._max_queue_size = max_queue_size
        self.priority_enabled = priority_enabled
        self.task_queue = cf.PriorityQueue() if priority_enabled else cf.Queue()
        self.executor = cf.ThreadPoolExecutor(max_workers=concurrency_level)

    def initialize_task_queue(self, concurrency_level: int, max_queue_size: int, priority_enabled: bool, task_processor_callback: TaskProcessorCallback):
        if not (1 <= concurrency_level <= 1000 and max_queue_size >= concurrency_level):
            raise ValueError("Invalid parameters for concurrency_level or max_queue_size.")

        self.concurrency_level = concurrency_level
        self._max_queue_size = max(self._max_queue_size, concurrency_level)
        self.priority_enabled = priority_enabled

        if priority_enabled:
            self.task_queue = cf.PriorityQueue()
        else:
            self.task_queue = cf.Queue()

        self.executor = cf.ThreadPoolExecutor(max_workers=concurrency_level)
        self.task_processor_callback = task_processor_callback

    def add_task(self, task: Any):
        if self.priority_enabled:
            self.task_queue.put((task, priority), task)
        else:
            self.task_queue.put(task)

    def process_next_task(self):
        try:
            if self.priority_enabled:
                task, priority = self.task_queue.get_nowait()
                for task in self._process_tasks():
                    self.add_task(task)
            else:
                task = self.task_queue.get_nowait()
                for task in self._process_tasks():
                    self.add_task(task)
        except cf.QueueEmpty:
            pass

    def _process_tasks(self):
        tasks = []
        if self.task_processor_callback is not None:
            with self.executor.shutdown(wait=False):
                for task in self.executor.map(self.task_processor_callback.process_task, [task for task in self.task_queue]):
                    tasks.append(task)
        else:
            with self.executor.shutdown(wait=False):
                for task in self.executor.map([self.task_processor_callback.process_task for _ in range(len(self.task_queue))], [task for task in self.task_queue]):
                    tasks.append(task)
        return tasks
