```javascript
const mocha = require('mocha');
const Blueslip = require('blueslip'); // Assuming you have the library installed

function runModuleTests(moduleLabel, testSuite, logLevel) {
  const blueslipMock = new Blueslip();
  const suite = mocha.createSuite();

  let currentTestInfo;

  function log(level, message) {
    if (logLevel && logLevel !== level) return;
    console.log(`[${moduleLabel}]: ${message}`);
  }

  // Load the module using require()
  const Module = require(`./${moduleLabel}`);

  // Initialize blueslipMock before each test
  suite.beforeEach(function () {
    blueslipMock.reset();
  });

  testSuite.forEach(([testLabel, testFunction]) => {
    const test = mocha.describe(`${moduleLabel}: ${testLabel}`, function () {
      this.timeout(3000); // Set a timeout for each test

      // Define the test as either synchronous or asynchronous depending on the implementation of the testFunction
      testFunction((label, done) => {
        currentTestInfo = { label, status: 'running' };
        log('info', `Starting ${testLabel}`);

        try {
          const result = testFunction();
          if (result.then) { // Handle asynchronous tests
            result.then(function () {
              currentTestInfo.status = 'passed';
              log('pass', `Successfully completed ${testLabel}`);
              done();
            }, function (error) {
              currentTestInfo.status = 'failed';
              log('fail', `Failed: ${testLabel} - Error: ${error.message}`);
              done();
            });
          } else { // Handle synchronous tests
            const resultStatus = testFunction() ? 'passed' : 'failed';
            currentTestInfo.status = resultStatus;
            log(resultStatus, `${testLabel} - Result: ${resultStatus}`);
            done();
          }
        } catch (error) {
          currentTestInfo.status = 'error';
          log('fail', `Error while running ${testLabel}: ${error.message}`);
          done();
        }
      });
    });

    suite.add(test);
  });

  // Run the tests and provide feedback on the status of each test
  suite.run(function (failures) {
    log('info', `Completed running ${moduleLabel}`);
    log(`Failures: ${failures}`);
  });
}
```

