// Configuration structure for logging
typedef struct LogConfig {
    FILE **file_pointers;
    bool enable_console_output;
} LogConfig;

void logFormattedError(const char *log_level, const char *format, ...) {
    va_list args;
    time_t current_time;
    char timestamp[20], message[4096];

    // Get the current time
    time(&current_time);
    strftime(timestamp, sizeof(timestamp), "[%Y-%m-%d %H:%M:%S] ", localtime(&current_time));

    // Format the log message
    va_start(args, format);
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);

    // Iterate through log file pointers based on the log level
    for (int i = 0; i < config.file_pointers_count && strcmp(log_level, config.file_pointers[i]->log_level) <= 0; ++i) {
        if (config.file_pointers[i] != NULL) {
            // Log to the current file pointer
            fprintf(*config.file_pointers[i], "%s%s", timestamp, message);

            // If console output is enabled, also log to console
            if (config.enable_console_output) {
                printf("%s%s\n", timestamp, message);
            }
        }
    }
}

// Helper function for initializing the logging system
void initLogging(LogConfig *config, int file_pointers_count, const char *file_names[], const char *log_levels[], bool enable_console_output) {
    config->file_pointers = malloc(sizeof(FILE *) * file_pointers_count);
    config->enable_console_output = enable_console_output;

    for (int i = 0; i < file_pointers_count; ++i) {
        if (!strcmp(log_levels[i], "ERROR")) {
            config->file_pointers[i] = fopen(file_names[i], "a");
            if (config->file_pointers[i] == NULL) {
                perror("Error opening log file");
                exit(EXIT_FAILURE);
            }
        } else if (!strcmp(log_levels[i], "WARNING")) {
            config->file_pointers[i] = fopen(file_names[i], "a");
            if (config->file_pointers[i] == NULL) {
                perror("Error opening log file");
                exit(EXIT_FAILURE);
            }
        } else if (!strcmp(log_levels[i], "INFO")) {
            config->file_pointers[i] = fopen(file_names[i], "a");
            if (config->file_pointers[i] == NULL) {
                perror("Error opening log file");
                exit(EXIT_FAILURE);
            }
        }
    }
}
