<?php

class OAuth2 {
    private $provider;
    private $redis;
    private $rateLimiter;
    private $logger;

    public function __construct($provider, Redis $redis, RateLimiter $rateLimiter, Logger $logger) {
        $this->provider = $provider;
        $this->redis = $redis;
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
    }

    public function authenticate($code, $ipAddress, $userAgent) {
        if (!$this->rateLimiter->allow($ipAddress)) {
            $this->logger->log("Rate limit exceeded for IP address: {$ipAddress}");
            throw new Exception("Too many requests from this IP.");
        }

        try {
            $accessToken = $this->provider->getAccessToken($code);
            $this->redis->set("access_token:{$accessToken}", json_encode([
                "ttl" => $this->provider->getSessionTTL()
            ]), 'ex');
        } catch (Exception $e) {
            $this->logger->log("Authentication error: {$e->getMessage()}");
            throw new Exception("Failed to authenticate user.");
        }

        try {
            $userInfo = json_decode($this->provider->getUserInfo($accessToken), true);
            if (empty($userInfo)) {
                $this->logger->log("Invalid or expired access token");
                throw new Exception("Invalid or expired access token.");
            }
        } catch (Exception $e) {
            $this->logger->log("Error fetching user info: {$e->getMessage()}");
            throw new Exception("Failed to retrieve user information.");
        }

        return $userInfo;
    }
}

