   class Queue {
       private queue: (() => Promise<any>)[];
       private maxConcurrentRequests = 5;

       add(task: () => Promise<any>): void {
           this.queue.push(task);
       }

       process(): void {
           if (this.queue.length === 0) return;

           const task = this.queue.shift();

           Promise.race([task(), ...Array(this.maxConcurrentRequests - 1).fill(new Promise((_, reject) => setTimeout(() => reject(new Error("Task queue is full")), 500)))]).then((result) => {
               if (result instanceof Error && result.message === "Task queue is full") {
                   this.process();
               } else {
                   this.process();
               }
           });
       }
   }

   class ApiClientsPool {
       private clients: Map<string, ApiClient>;
       private maxConcurrentClients = 5;

       getApiClient(url: string): Promise<ApiClient> {
           if (this.clients.has(url)) return Promise.resolve(this.clients.get(url)!);

           return this.createAndCacheApiClient(url).then((client) => {
               this.clients.set(url, client);
               return client;
           });
       }

       private createAndCacheApiClient(url: string): Promise<ApiClient> {
           if (this.clients.size >= this.maxConcurrentClients) {
               throw new Error("API clients pool is full");
           }

           return this.ApiClientFactory.createApiClient(url).then((client) => {
               return client;
           });
       }
   }

   class ApiRequestRetryStrategy {
       private retryCount = 3;

       shouldRetry(error: Error): boolean {
           // Implementation to decide if a failed API request should be retried based on error type or other criteria
       }

       async handleErrorAndRetryIfNeeded(promise: Promise<any>, retryStrategy: ApiRequestRetryStrategy): Promise<void> {
           try {
               return await promise;
           } catch (error) {
               if (!retryStrategy.shouldRetry(error)) {
                   throw error;
               }

               if (retryStrategy.retryCount-- === 0) {
                   throw error;
               }

               return retryStrategy.handleErrorAndRetryIfNeeded(promise, retryStrategy);
           }
       }
   }

