        self.api = ExternalAPI()

    async def handle_request(self, payload: Dict[str, any]):
        try:
            if not payload or 'action' not in payload:
                return json.dumps({'message': 'error', 'data': None})

            action = payload['action']
            product_id = payload.get('product_id')
            quantity = int(payload['quantity'])
            price = float(payload['price'])
            category = payload['category']

            if not validate_data(quantity, price):
                return json.dumps({'message': 'error', 'data': None})

            with self.conn.cursor() as cursor:
                if action == 'add':
                    cursor.callproc('add_product', (quantity, price, category))
                elif action in {'update', 'delete'}:
                    cursor.callproc(f'{action}_product', (product_id, quantity, price, category))

                self.conn.commit()
                self.api.sync_inventory(cursor.fetchone())

            return json.dumps({'message': 'success', 'data': None})
        except psycopg2.Error as e:
            return json.dumps({'message': f'error: {e}', 'data': None})
        except Exception as e:
            return json.dumps({'message': f'error: {str(e)}', 'data': None})

