import os
import hashlib
import threading
import queue
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import psycopg2.pool
import requests
from datetime import timedelta
import logging
import re
import zipfile
from aiofiles import listdir, walk
from typing import Dict, List

class IntegrityChecker:
    def __init__(self, config: Dict):
        self.config = config
        self.log_dir = config['log_dir']
        self.exclusion_patterns = re.compile(config['exclusion_patterns'])
        self.db_pool = psycopg2.pool.SimpleConnectionPool(**config['db_params'])
        self.cache = {}
        self.cache_ttl = timedelta(minutes=config['cache_ttl'])
        self.quarantine_dir = config['quarantine_dir']
        self.monitoring_api = config['monitoring_api']
        self.rate_limiter = RateLimiter(**config['rate_limiter'])
        self.encryption_key = config['encryption_key'].encode()

    def check_integrity(self):
        file_queue = queue.Queue()
        for root, dirs, files in walk(self.log_dir):
            for file in files:
                if self.exclusion_patterns.match(file):
                    continue
                filepath = os.path.join(root, file)
                if not os.access(filepath, os.R_OK):
                    logging.warning(f"Unable to read {filepath}")
                    continue
                file_queue.put(filepath)

        with ThreadPoolExecutor() as executor:
            results = executor.map(self._check_single_file, file_queue)

    def _check_single_file(self, filepath):
        try:
            hash_val = self._get_hash_value(filepath)
            if hash_val in self.cache and time.time() - self.cache[hash_val]['timestamp'] < self.cache_ttl.total_seconds():
                return self.cache[hash_val]['status']

            with open(filepath, 'rb') as f:
                hasher = hashlib.sha256()
                while True:
                    data = f.read(8192)
                    if not data:
                        break
                    hasher.update(data)
                calculated_hash = hasher.hexdigest()

            self._cache_result(calculated_hash, True)

            result = self._report_to_monitoring_api(calculated_hash)
            return result
        except Exception as e:
            logging.error(f"Error checking integrity of {filepath}: {e}")
            self._cache_result(calculated_hash, False)
            os.makedirs(self.quarantine_dir, exist_ok=True)
            os.rename(filepath, os.path.join(self.quarantine_dir, filepath))
            return False

    def _get_hash_value(self, filepath):
        cache_key = hashlib.sha256(open(filepath, 'rb').read()).hexdigest()
        return cache_key

    def _cache_result(self, key: str, status: bool):
        self.cache[key] = {'timestamp': time.time(), 'status': status}

    async def _report_to_monitoring_api(self, hash_val: str) -> bool:
        encrypted_hash_val = encrypt(hash_val.encode(), self.encryption_key)
        success = self.rate_limiter.call()
        if success:
            response = requests.post(self.monitoring_api, data={'hash': encrypted_hash_val})
            return response.ok
        else:
            logging.warning(f"Rate limited from reporting integrity status for {hash_val}")
            return False

class RateLimiter:
    def __init__(self, thresholds: Dict[str, int], backoff: List[float]):
        self.thresholds = thresholds
        self.backoff = backoff
        self.reset_timer = {}
        self.current_requests = 0

    def call(self) -> bool:
        self.current_requests += 1
        now = time.time()
        for resource, threshold in self.thresholds.items():
            if self.current_requests > threshold:
                sleep_time = min([now + delay for delay in self.backoff if now + delay > self.reset_timer[resource]]) - now
                if sleep_time > 0:
                    logging.warning(f"{resource} rate limit exceeded, sleeping for {sleep_time} seconds")
                    time.sleep(sleep_time)
                else:
                    self.reset()
            elif resource in self.reset_timer and now > self.reset_timer[resource]:
                self.reset(resource)
        return True

    def reset(self, resource=None):
        if resource is None:
            for resource in self.thresholds:
                self.reset_timer[resource] = time.time() + 60
        else:
            self.reset_timer[resource] = time.time() + 60
        self.current_requests -= 1
