<?php
namespace App\API;

use GuzzleHttp\Client as GuzzleClient;
use League\OAuth2\Client\Provider\AbstractProvider;
use Psr\Cache\CacheItemPoolInterface;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;

class AuthenticationModule {
    protected $provider;
    protected $cache;
    protected $token;
    protected $client;

    public function __construct(AbstractProvider $provider, CacheItemPoolInterface $cache) {
        $this->provider = $provider;
        $this->cache = $cache;
        $this->client = new GuzzleClient();
    }

    public function authenticate(string $code) {
        $accessToken = $this->provider->getAccessToken('authorization_code', [
            'code' => $code
        ]);
        if (!$accessToken) {
            return new JsonResponse(['error' => 'Invalid authentication'], 401);
        }
        $this->token = $accessToken;
        return new JsonResponse($this->getUserInfo());
    }

    public function updateResource(int $resourceId, string $body) {
        if (!$this->token) {
            return new JsonResponse(['error' => 'Unauthorized'], 401);
        }
        try {
            $response = $this->client->put("https://api.example.com/resources/{$resourceId}", [
                'headers' => [
                    'Authorization' => "Bearer {$this->token}"
                ],
                'json' => json_decode($body)
            ]);
            return new JsonResponse($response->getBody()->getContents());
        } catch (\Exception $e) {
            return new JsonResponse(['error' => $e->getMessage()], 500);
        }
    }

    public function deleteResource(int $resourceId) {
        if (!$this->token) {
            return new JsonResponse(['error' => 'Unauthorized'], 401);
        }
        try {
            $response = $this->client->delete("https://api.example.com/resources/{$resourceId}", [
                'headers' => [
                    'Authorization' => "Bearer {$this->token}"
                ]
            ]);
            if ($response->getStatusCode() === 204) {
                return new JsonResponse(json_encode([
                    'id' => $resourceId,
                    // Provide default values for the deleted resource here
                ]), 200);
            } else {
                return new JsonResponse(['error' => 'Failed to delete resource'], 500);
            }
        } catch (\Exception $e) {
            return new JsonResponse(['error' => $e->getMessage()], 500);
        }
    }

    protected function getUserInfo() {
        $cacheKey = 'user_' . $this->token;
        $item = $this->cache->getItem($cacheKey);

        if (!$item->isMiss()) {
            return $item->get();
        }

        try {
            $response = $this->client->get("https://api.example.com/userinfo", [
                'headers' => [
                    'Authorization' => "Bearer {$this->token}"
                ]
            ]);
            $item->expiresAfter(600); // Cache for 10 minutes
            $item->set($response->getBody()->getContents());
            return $item->get();
        } catch (\Exception $e) {
            $this->clearSession();
            return new JsonResponse(['error' => $e->getMessage()], 500);
        }
    }

    protected function clearSession() {
        $this->token = null;
    }
}
```

