    public void updateUserPreferences(Long userId, Long tenantId, Map<String, Object> preferenceUpdates) {
        Specification<UserPreference> userPreferenceSpec = (root, query, cb) -> {
            Predicate predicate = cb.equal(root.get("userId"), userId);
            predicate = cb.and(predicate, cb.equal(root.get("tenantId"), tenantId));
            return predicate;
        };

        Supplier<UserPreference> userPreferenceSupplier = () -> userPreferenceRepository.findOne(userPreferenceSpec)
                .orElseGet(() -> new UserPreference(userId, tenantId));

        Optional<UserPreference> cachedUserPreference = cacheManager.getCache("userPreferences")
                .get(userId + "_" + tenantId, UserPreference.class, CREATE_MISSING);
        if (cachedUserPreference.isPresent()) {
            UserPreference existingUserPreference = cachedUserPreference.get();
            // Handle preference conflicts here based on your application's requirements
            existingUserPreference.mergePreferences(preferenceUpdates);
            cacheManager.getCache("userPreferences").put(userId + "_" + tenantId, existingUserPreference);
        } else {
            UserPreference userPreference = userPreferenceSupplier.get();
            userPreference.updatePreferences(preferenceUpdates);
            userPreferenceRepository.save(userPreference);
            cacheManager.getCache("userPreferences").put(userId + "_" + tenantId, userPreference);
        }

        // Implement RBAC here based on your application's requirements
        Tenant tenant = tenantRepository.findById(tenantId).orElseThrow(() -> new RuntimeException("Tenant not found"));
        if (!isUserAuthorizedToUpdatePreferences(userId, tenant)) {
            throw new SecurityException("User is not authorized to update preferences");
        }

        logPreferenceChangeAuditTrail(userId, tenantId, preferenceUpdates);
