void validateToken(const std::string& tokenJson) {
    nlohmann::json j = nlohmann::json::parse(tokenJson);

    // Validate JSON structure and fields
    if (!j.contains("access_token") || !j["access_token"].is_string() ||
        !j.contains("expires_in") || !j["expires_in"].is_number() ||
        j["expires_in"] < 0 ||
        (j.contains("token_type") && j["token_type"] != "Bearer")) {
        return; // Invalid token, do not process further
    }

    const std::string& accessToken = j["access_token"].get<std::string>();
    int expiresIn = j["expires_in"];
    const std::string& tokenType = j.count("token_type") > 0 ? j["token_type"] : "";
    const std::string& refreshToken = j.contains("refresh_token") ? j["refresh_token"].get<std::string>() : "";

    // Rate limiting and caching
    if (std::chrono::system_clock::now() < currentRateLimitResetTime) {
        return; // Exceeded rate limit, queue the request for later processing
    }

    if (cache.count(accessToken)) {
        if (std::chrono::system_clock::now() - cache[accessToken] < std::chrono::seconds(5)) {
            return; // Token is still cached and valid, do not revalidate
