        {
            var load = (double)GC.GetTotalMemory(false)/1024/1024; // memory in MB
            if (load > 75) return "argon2";
            var securityLevel = int.Parse(_config["SecurityLevel"]);
            if (securityLevel == 3) return "bcrypt";
            return "sha256";
