```python
import os
import logging.config
from concurrent.futures import ThreadPoolExecutor
from datetime import timedelta

def init_logging(log_format, log_level, rotation_size=10485760, rotation_time=timedelta(days=3)):
    # Define the centralized logging configuration
    config = {
        'version': 1,
        'formatters': {'default': {'format': log_format}},
        'handlers': [
            {
                'class': 'logging.FileHandler',
                'level': log_level,
                'formatter': 'default',
                'filename': 'webapp.log',
                'backupCount': rotation_size/rotation_size + 1
            },
            {
                'class': 'logging.StreamHandler',
                'level': log_level,
                'formatter': 'default'
            }
        ],
        'root': {'handlers': ['console', 'file'], 'level': log_level}
    }
    logging.config.dictConfig(config)

    def rotate_logs(log_handler):
        while True:
            try:
                log_handler.doRollover()
            except Exception as e:
                print(f'Error during log rotation: {e}')
            finally:
                pass
                # Send logs to external aggregation service here

    with ThreadPoolExecutor(max_workers=5) as executor:
        executor.submit(rotate_logs, logging.FileHandler('webapp.log'))
```

In this example, the function initializes the logging configuration and sets up a thread pool to handle log rotation in parallel across all instances. The log format, level, rotation size, and rotation time can be set using environment variables or a centralized configuration service.

