function copyBuffer(buffers, offset, count) {
  const dest = Buffer.allocUnsafe(count);

  for (let i = 0; i < count; ++i) {
    if (offset + i >= buffers.length || !buffers[offset + i]) {
      throw new Error('Buffer out of range or empty');
    }
    dest[i] = buffers[offset + i][0];
  }

  return Buffer.concat([dest]);
}
