// Thread-safe token cache class
class TokenCache {
public:
    void insert(const std::string& key, const std::string& value, std::time_t expiration) {
        std::unique_lock<std::mutex> lock(m_);
        tokens_.emplace(key, std::make_pair(value, expiration));
        lock.unlock();
        cv_.notify_one();
    }

    bool get(const std::string& key, std::string& value, std::time_t& expiration) {
        std::unique_lock<std::mutex> lock(m_);
        auto it = tokens_.find(key);
        if (it != tokens_.end() && it->second.second > std::time(nullptr)) {
            value = it->second.first;
            expiration = it->second.second;
            return true;
        }
        lock.unlock();
        return false;
    }

private:
    std::unordered_map<std::string, std::pair<std::string, std::time_t>> tokens_;
    std::mutex m_;
    std::condition_variable cv_;
};

