public class DynamicValueGenerator
{
    private readonly SeedManager _seedManager;
    private readonly ConcurrentDictionary<string, RangeConfig> _rangeConfigs = new();
    private readonly ConcurrentCache<RangeConfig> _rangeConfigCache;

    public DynamicValueGenerator(SeedManager seedManager)
    {
        _seedManager = seedManager;
        _rangeConfigCache = new ConcurrentCache<RangeConfig>(GetRangeConfigFromDataSource);
    }

    private T GetOrAdd<T>(ConcurrentDictionary<string, T> dictionary, string key, Func<string, T> valueFactory)
    {
        if (dictionary.TryGetValue(key, out var value)) return value;
        lock (this)
        {
            if (!dictionary.TryGetValue(key, out value))
                dictionary[key] = valueFactory(key);
            return value;
        }
    }

    private async Task<RangeConfig> GetRangeConfigFromDataSource(string key)
    {
        // Fetch range configuration from data source here
    }

    public double GenerateValue(double min, double max, RangeType type)
    {
        var configKey = $"{min}_{max}_{type}";
        var config = GetOrAdd(_rangeConfigs, configKey, () =>
        {
            var rangeConfig = new RangeConfig
            {
                MinValue = min,
                MaxValue = max,
                Type = type
            };

            switch (type)
            {
                case RangeType.Closed:
                    if (max <= min) throw new ArgumentException("Min value must be less than or equal to max value in closed range.");
                    break;
                case RangeType.Open:
                    if (min > max) throw new ArgumentException("Min value must be greater than max value in open range.");
                    break;
                case RangeType.HalfOpen:
                    if (max <= min) throw new ArgumentException("Min value must be less than or equal to max value in half-open range.");
                    break;
            }

            return rangeConfig;
        });

        var cachedConfig = _rangeConfigCache.Get(configKey, () => config);
        return GetRandomValue(cachedConfig);
    }

    private double GetRandomValue(RangeConfig config)
    {
        // Implement random value generation logic here using the cached range configuration
    }
}
```

