#include <stdlib.h>
#include <stdio.h>

typedef struct FSA {
    int statesCount;
    int *states;
    int **next;
    // Add other FSA properties as needed
} FSA;

void integrateAndOptimizeFSACreator(int **newStates, int numNewStates, FSA *fsa, int lastState) {
    fsa->states = (int *)realloc(fsa->states, sizeof(int) * (fsa->statesCount + numNewStates));
    for (int i = fsa->statesCount; i < fsa->statesCount + numNewStates; ++i) {
        fsa->states[i] = -1; // Or any other value to indicate new state
    }

    fsa->next = (int **)realloc(fsa->next, sizeof(int *) * (fsa->statesCount + numNewStates));
    for (int i = fsa->statesCount; i < fsa->statesCount + numNewStates; ++i) {
        fsa->next[i] = malloc(sizeof(int) * fsa->statesCount); // Or any other appropriate size calculation
    }

    int currentState = lastState;
    for (int i = 0; i < newStates[currentState]; ++i) {
        int nextState = newStates[currentState][i];
        fsa->next[currentState][i] = currentState + i; // Update 'next' pointers to new states
    }

    fsa->statesCount += numNewStates;
}
```

This code creates a simple `FSA` structure with properties for the number of states, an array of states, and a two-dimensional array for the 'next' pointers between states. The provided function integrates new states into the FSA by reallocating memory for both arrays, updating the 'next' pointers for the current state, and incrementing the total number of states in the FSA structure.

Error handling has been omitted from this code example for brevity, but it should be included in a production environment to handle potential issues such as memory allocation failures or out-of-bounds accesses.

This solution is scalable and can accommodate future growth by dynamically reallocating memory as needed. It prioritizes user experience by seamlessly integrating the new states into the existing FSA structure without requiring manual updates or modifications to the FSA's 'next' pointers.

