```csharp
using System;
using System.Xml;
using System.IO;
using System.Linq;
using System.Xml.XPath;
using System.Diagnostics;
using System.Collections.Generic;

public class XmlParser
{
    private const int MAX_CACHE_SIZE = 10; // Adjust this value according to your needs
    private readonly Dictionary<string, XmlDocument> _cache = new Dictionary<string, XmlDocument>();

    public XmlElement GetFirstMatchingElement(string xmlContentOrPath, string xpathExpression)
    {
        if (string.IsNullOrWhiteSpace(xmlContentOrPath))
            throw new ArgumentNullException(nameof(xmlContentOrPath));

        if (string.IsNullOrWhiteSpace(xpathExpression))
            throw new ArgumentNullException(nameof(xpathExpression));

        ValidateXml(xmlContentOrPath);

        XmlDocument doc;
        if (_cache.TryGetValue(xmlContentOrPath, out doc))
        {
            return doc.SelectSingleNode(xpathExpression) ?? ThrowMultipleMatchesException(xpathExpression);
        }

        using (var stringReader = new StringReader(xmlContentOrPath))
        {
            doc = new XmlDocument();
            doc.Load(stringReader);
            _cache[xmlContentOrPath] = doc;
            return doc.SelectSingleNode(xpathExpression) ?? ThrowMultipleMatchesException(xpathExpression);
        }
    }

    private void ValidateXml(string xmlContentOrPath)
    {
        try
        {
            var xDoc = new XmlDocument();
            using (var stringReader = new StringReader(xmlContentOrPath))
            {
                xDoc.Load(stringReader);
            }
        }
        catch (XmlException ex)
        {
            throw new Exception($"Error while validating XML: {ex.Message}", ex);
        }
    }

    private XmlElement ThrowMultipleMatchesException(string xpathExpression)
    {
        throw new MultipleElementsFoundException($"More than one element found with the given XPath expression '{xpathExpression}'.");
    }
}

public class MultipleElementsFoundException : Exception
{
    public MultipleElementsFoundException(string message) : base(message) { }
}

namespace XmlParserApp
{
    internal static class Program
    {
        private const string USAGE = "XmlParser.exe [XML|path] [XPathExpression] [--help]";

        private static void Main(string[] args)
        {
            if (args.Any(arg => arg.Equals("--help", StringComparison.OrdinalIgnoreCase)))
            {
                Console.WriteLine(USAGE);
                return;
            }

            var xmlParser = new XmlParser();
            try
            {
                var element = xmlParser.GetFirstMatchingElement(args[0], args[1]);
                if (element != null)
                    Console.WriteLine($"First matching element: {element.OuterXml}");
                else
                    Console.WriteLine("No matching element found.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
    }
}
```

