#include <boost/random.hpp>
#include <boost/asio/connect.hpp>
#include <boost/asio/websocket.hpp>
#include <openssl/rand.h>

namespace rng {
    boost::mt19937 pool; // thread-local random number generator pool
    std::vector<unsigned char> seed_data; // seed data for OpenSSL's RAND_bytes() function

    void init() {
        unsigned int seed = std::chrono::system_clock::now().time_since_epoch().count();
        RAND_seed(&seed, sizeof(seed)); // seed OpenSSL RNG with current time
        boost::random::seed_from_vector(seed_data); // seed thread-local pool with /dev/urandom data
    }

    uint64_t get_remote_seed() {
        using namespace boost::asio;
        io_context context;
        websocket::stream<tcp::socket> ws(context);
        tcp::resolver resolver(context);
        auto endpoint_iterator = resolver.resolve("websocket-server", "port");
        connect(ws.next_layer(), endpoint_iterator->first, endpoint_iterator->second);
        ws.handshake(endpoint_iterator->target().endpoint());
        uint64_t seed;
        read(ws, buffer(&seed, sizeof(seed)));
        return seed;
    }
}
