pyclass!(PythonModuleLoader);
impl PythonModuleLoader {
    fn new() -> Self {
        PythonModuleLoader {}
    }

    async fn run_module_tests_async(&self, module_name: &str) -> Result<()> {
        let py = Python::take(&gil::PyGILState::with_name(&format!("run_module_{}", module_name)));
        let module = match py.get_module_with_name(module_name) {
            Ok(m) => m,
            Err(_) => return Err(anyhow::Error::new(format!("Unable to find module '{}'", module_name))),
        };

        let test_funcs = module.items().filter_map(|item| match item {
            pyo3::PyObject::PyDict({dict, _key}, _) if dict.get("__test__") == Some(true) => {
                if let Ok(func) = item.0.get_attr("__name__").and_then(|name| name.downcast_ref::<str>()) {
                    Some((item.0.clone(), func))
                } else {
                    None
                }
            },
            _ => None,
        });

        let rate_limiter = RateLimiter::new();
        let log = Arc::new(RwLock::new(Vec::new()));

        task::spawn_blocking(move || {
            for (func, name) in test_funcs {
                if !rate_limiter.is_allowed() {
                    continue;
                }

                let func = wrap_pyfunction!(|_, __args: &PyTuple| -> PyResult<()> {
                    let res = (__args.get(0).as_ref().unwrap().call1(module, &[()]?)).context("Unable to call test function")?;
                    log.write_log(format!("Test '{}' executed with result: {}", name, res));
                    Ok(())
                });

                let _ = func.as_ref().unwrap()(&py, &[module.getattr(name)?]);
            }
        }).await;

        Ok(())
    }
}

struct RateLimiter {
    interval: u64,
    reset_timer: Option<tokio::time::Instant>,
}

impl RateLimiter {
    fn new() -> Self {
        RateLimiter { interval: 60, reset_timer: None }
    }

    fn is_allowed(&self) -> bool {
        match self.reset_timer {
            Some(ref timer) if timer.elapsed().as_secs() > self.interval => {
                self.reset_timer = Some(tokio::time::Instant::now());
                true
            },
            _ => false,
        }
    }
}

struct Log {
    messages: Arc<RwLock<Vec<String>>>,
}

impl Log {
    fn new() -> Self {
        Log { messages: Arc::new(RwLock::new(Vec::new())) }
    }

    fn write_log(&self, message: String) {
        let mut logs = self.messages.write().lock();
        logs.push(message);
    }
}

