    private readonly ILogger<UpdateContentService> _logger;
    private readonly RateLimiter _rateLimiter;
    private readonly HttpClient _httpClient;

    public UpdateContentService(IDistributedCache cache, ILogger<UpdateContentService> logger, HttpClient httpClient)
    {
        _cache = cache;
        _logger = logger;
        _httpClient = httpClient;
        _rateLimiter = new RateLimiter(requestsPerMinute: 60);
    }

    public async Task<IActionResult> UpdateContentAsync(int pageSectionId, int elementId, string htmlContent)
    {
        if (!_rateLimiter.Take())
            return StatusCodes.TooManyRequests;

        var key = $"pageSection_{pageSectionId}_element_{elementId}";
        await _cache.SetAsync(key, htmlContent);

        if (await _queueService.NotifyPageRefreshAsync())
            return Ok();

        return BadRequest("Failed to notify page refresh.");
    }
}
