    private static readonly Mock<ITestOutputHelper> _testOutputHelperMock = new Mock<ITestOutputHelper>();

    public async Task ExecuteAsync(string[] args)
    {
        var assemblyNames = args.Where(x => x.EndsWith(".dll"));
        foreach (var assemblyName in assemblyNames)
        {
            using (var assembly = Assembly.LoadFrom(assemblyName))
            {
                var testClasses = assembly.DefinedTypes
                    .Where(t => typeof(IClassFixture<TestStartup>).IsAssignableFrom(t));

                foreach (var testClass in testClasses)
                {
                    _testOutputHelperMock.Reset();
                    using (_testOutputHelperMock.Object)
                    {
                        var testInstance = Activator.CreateInstance(testClass);
                        var testMethods = testClass.GetMethods()
                            .Where(m => m.IsPublic && m.CustomAttributes.Any(a => a.AttributeType == typeof(XunitTestAttribute)));

                        foreach (var testMethod in testMethods)
