const fs = require('fs');
const path = require('path');
const FileUploader = require('file-uploader');

function readFileSync(filePath) {
    if (!fs.existsSync(filePath)) throw new Error("File does not exist.");
    return fs.readFileSync(filePath, 'utf8');
}

function uploadFileUsingBluebird(filePath) {
    const fileUploader = new FileUploader({
        multipart: true,
        server: {
            module: 'express',
            path: '/api/upload' // Replace this with the endpoint to your chosen server.
        }
    });

    return new Promise((resolve, reject) => {
        fs.readFile(filePath, (err, data) => {
            if (err) return reject(err);
            fileUploader.upload(data, { filename: path.basename(filePath) }, (err, res) => {
                if (err) return reject(err);
                resolve(res.location); // URL of the uploaded file.
            });
        });
    });
}
