```cpp
#include <memory>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <future>
#include <iostream>

#define MAX_NODES 10000000
#define NODE_CAPACITY 256

struct OctreeNode {
    double feature; // Feature size for this node
    int depth; // Depth of this node in the octree
    std::vector<OctreeNode*> children; // Children nodes, null if leaf
    std::unordered_map<std::string, float> data; // Data associated with this node from external sources
    OctreeNode* parent = nullptr;
};

class Octree {
public:
    Octree(double initialFeatureSize) : root(std::make_unique<OctreeNode>()), currentNode(root.get()) {}

    void insertData(const std::string& dataSource, const std::vector<float>& dataPoints, int startIndex = 0, int numDataPoints = -1) {
        if (numDataPoints <= 0) numDataPoints = dataPoints.size();

        std::function<void()> task = [this, dataSource, dataPoints, startIndex, numDataPoints]() mutable {
            for (int i = startIndex; i < numDataPoints; ++i) {
                auto [x, y, z] = extractCoordinates(dataPoints[i]);
                insertDataAt(currentNode.get(), x, y, z, dataSource, dataPoints[i]);
            }
        };

        std::vector<std::future<void>> tasks;
        int chunkSize = numDataPoints / MAX_THREADS;
        for (int i = 0; i < MAX_THREADS; ++i) {
            if (i * chunkSize + chunkSize > numDataPoints) break;
            tasks.push_back(std::async(std::launch::async, task));
        }

        // Wait for all tasks to complete
        for (auto& task : tasks) task.wait();
    }

    void query(const std::function<void(OctreeNode*, const std::string&, float)>& callback, double radius, const std::vector<float>& point) const {
        auto [x, y, z] = extractCoordinates(point[0]);
        queryAt(root.get(), x, y, z, radius, callback);
    }

private:
    void insertDataAt(OctreeNode* node, double x, double y, double z, const std::string& dataSource, float value) {
        if (!node->children.empty()) return; // Leaf node

        double halfEdge = node->feature / 2.0f;
        bool insideBoundingBox = (x >= -halfEdge && x <= halfEdge) &&
                                 (y >= -halfEdge && y <= halfEdge) &&
                                 (z >= -halfEdge && z <= halfEdge);
        if (!insideBoundingBox) return;

        auto depthIncrement = node->depth + 1;
        if (depthIncrement > MAX_DEPTH) return; // Maximum tree depth reached

        for (size_t i = 0; i < 8; ++i) {
            double newX, newY, newZ;
            switch (i) {
                case 0: newX = x + halfEdge; newY = y + halfEdge; newZ = z + halfEdge; break;
                case 1: newX = x + halfEdge; newY = y - halfEdge; newZ = z + halfEdge; break;
                case 2: newX = x - halfEdge; newY = y + halfEdge; newZ = z + halfEdge; break;
                case 3: newX = x - halfEdge; newY = y + halfEdge; newZ = z - halfEdge; break;
                case 4: newX = x + halfEdge; newY = y + halfEdge; newZ = z - halfEdge; break;
                case 5: newX = x - halfEdge; newY = y + halfEdge; newZ = z - halfEdge; break;
                case 6: newX = x + halfEdge; newY = y - halfEdge; newZ = z - halfEdge; break;
                case 7: newX = x - halfEdge; newY = y - halfEdge; newZ = z - halfEdge; break;
            }

            auto childIndex = (i >> 3) * 8 + (i & 0b11);
            if (!node->children[childIndex]) {
                auto newNode = std::make_unique<OctreeNode>();
                node->children[childIndex] = newNode.get();
                newNode->parent = node;
                newNode->depth = depthIncrement;
                newNode->feature = node->feature / 2.0f;

                if (node->data.find(dataSource) != node->data.end()) {
                    auto dataValue = node->data[dataSource];
                    newNode->data[dataSource] = dataValue + value * static_cast<float>(1.0 / NODE_CAPACITY);
                } else {
                    newNode->data[dataSource] = value;
                }

                currentNode = newNode.get();
                insertDataAt(newNode.get(), newX, newY, newZ, dataSource, value);
            }
        }
    }

    void queryAt(OctreeNode* node, double x, double y, double z, double radius, const std::function<void(OctreeNode*, const std::string&, float)>& callback) const {
        if (!node->children.empty()) return; // Leaf node

        double halfEdge = node->feature / 2.0f;
        bool insideBoundingBox = (x >= -halfEdge && x <= halfEdge) &&
                                 (y >= -halfEdge && y <= halfEdge) &&
                                 (z >= -halfEdge && z <= halfEdge);
        if (!insideBoundingBox || sqrt(pow(x - node->feature / 2.0f, 2) + pow(y - node->feature / 2.0f, 2) + pow(z - node->feature / 2.0f, 2)) > radius) return;

        for (size_t i = 0; i < node->children.size(); ++i) {
            queryAt(node->children[i], x, y, z, radius, callback);
        }

        if (!callback(node, "", 0)) return; // Fallback mechanism for unreliable data sources or missing information
    }

    static std::tuple<double, double, double> extractCoordinates(float point) {
        return std::make_tuple((point >> 56) & 0xFFFFFF, (point >> 40) & 0xFFFFFF, (point >> 24) & 0xFFFFFF);
    }

private:
    std::unique_ptr<OctreeNode> root; // Root node of the octree
    OctreeNode* currentNode; // Current node being inserted into or queried from
    static const int MAX_THREADS = 16;
    static const int MAX_DEPTH = 20;
};
```

