   public class DynamicResourcePoolManager<T extends Connection> {

       private final Lock poolLock = new ReentrantLock();
       private final AtomicInteger activeConnections = new AtomicInteger(0);
       private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
       private int minConnections;
       private int maxConnections;
       private long connectionTimeout;
       private ConnectionConfigCallback connectionConfigCallback;
       private T[] resourcePool;
       private boolean isInitialized;

       public void initializeResourcePool(int minConnections, int maxConnections, long connectionTimeout, ConnectionConfigCallback connectionConfigCallback) {
           if (minConnections < 1 || maxConnections <= minConnections) {
               throw new IllegalArgumentException("Invalid minimum or maximum number of connections.");
           }
           if (connectionTimeout <= 0) {
               throw new IllegalArgumentException("Connection timeout must be greater than zero.");
           }

           this.minConnections = minConnections;
           this.maxConnections = maxConnections;
           this.connectionTimeout = connectionTimeout;
           this.connectionConfigCallback = connectionConfigCallback;

           if (!isInitialized) {
               initializePool();
           }
       }

       private void initializePool() {
           synchronized (this) {
               if (resourcePool != null || isInitialized) {
                   throw new ConcurrentModificationException("Cannot re-initialize the resource pool.");
               }
               isInitialized = true;
           }

           // Implement seeding mechanisms here for thread safety.

           // Perform external configuration integration using connectionConfigCallback.
           int effectiveMinConnections = minConnections;
           int effectiveMaxConnections = maxConnections;

           ConnectionConfig config = new ConnectionConfig();
           ConnectionConfig modifiedConfig = connectionConfigCallback.configure(config);

           if (modifiedConfig != null) {
               effectiveMinConnections = modifiedConfig.getMinConnections();
               effectiveMaxConnections = modifiedConfig.getMaxConnections();
           }

           resourcePool = new T[effectiveMaxConnections];

           for (int i = 0; i < effectiveMinConnections; i++) {
               if (resourcePool[i] != null) {
                   continue;
               }
               synchronized (this.resourcePool) {
                   resourcePool[i] = createConnection();
               }
