```rust
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;
use std::process::Command;
use rusty_llvm as llvm;
use regex::Regex;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 5 {
        eprintln!("Usage: {} <target_directory> <output_file> <extension> <lexer>", args[0]);
        return;
    }

    let target_dir = &args[1];
    let output_file = &args[2];
    let extension = &args[3];
    let lexer = &args[4];

    let re = Regex::new(format!("\\.{}\\z", extension)).unwrap();

    let mut module = llvm::LLVMContext::create().create_module("generated");

    let mut errors: Vec<String> = Vec::new();

    walk_dir(target_dir, &mut |entry| {
        if re.is_match(&entry) {
            match process_file(entry, lexer, &mut module) {
                Ok(_) => println!("Processed file: {}", entry),
                Err(e) => {
                    errors.push(format!("Error processing file: {}", e));
                    println!("{}", e);
                }
            }
        }
        true
    });

    if !errors.is_empty() {
        eprintln!("{}", errors.join("\n"));
        return;
    }

    let output = File::create(output_file).unwrap();
    module.write_to_memory_buffer(&mut |buf| output.write_all(buf).unwrap());
}

fn process_file(path: String, lexer: &str, module: &mut llvm::Module) -> Result<(), String> {
    let mut buffer = Vec::new();
    File::open(&path)?.read_to_end(&mut buffer)?;

    // Parse the contents of the file into a node tree.
    let nodes = parse(lexer, &buffer)?;

    // Generate LLVM IR code for each parsed node and validate it before writing to the module.
    let mut validation_errors: Vec<String> = Vec::new();
    for node in nodes {
        if let Err(e) = generate_and_validate(node, module) {
            validation_errors.push(e);
        }
    }

    if !validation_errors.is_empty() {
        return Err(validation_errors.join("\n"));
    }

    Ok(())
}

fn generate_and_validate(node: Node, module: &mut llvm::Module) -> Result<(), String> {
    // Generate the LLVM IR code for the node and insert it into the module.
    let ir = generate(node)?;

    // Validate the generated LLVM IR code.
    match module.add_named_module_section(ir.as_bytes()) {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("Failed to insert LLVM IR: {}", e)),
    }
}

fn walk_dir<P, F>(path: P, f: &mut F) -> bool
where
    P: AsRef<Path>,
    F: FnMut(String) -> bool,
{
    let path = Path::new(path.as_ref());
    let mut entries = match std::fs::read_dir(path) {
        Err(_) => return false,
        Ok(entries) => entries,
    };

    while let Some(entry) = entries.next() {
        if !f(entry.file_name().to_str().unwrap().to_owned()) {
            continue;
        }

        match entry.path().is_dir() {
            true => walk_dir(entry.path(), f),
            false => {}
        }
    }

    true
}
```

