import express from 'express';
import fs from 'fs';
import path from 'path';
import yargs from 'yargs';
import readlineSync from 'readline-sync';

import ModuleLoader from './moduleLoader';
import { TiffParser } from './tiffParser';
import { ConcurrentReduce } from './concurrentReduce';

// Load the configuration file
const config = JSON.parse(fs.readFileSync(path.join(__dirname, 'config', 'config.json'), 'utf8'));

// Initialize Express app
const app = express();

// Handle incoming requests and execute modules sequentially
const moduleLoader = new ModuleLoader(config);
moduleLoader.loadModules().then(() => {
  // Start the image processing pipeline
  const rl = readlineSync.createInterface({
    input: process.stdin,
    output: process.stdout
  });

  rl.question('Enter the path to your TIFF image file: ', (filePath) => {
    const tiffParser = new TiffParser();
    const imgInfo = tiffParser.parseImage(filePath);

    if (!imgInfo) {
      console.error('Error parsing the image file');
      return;
    }

    // Execute concurrent reduce on numerical data using the loaded modules
    const concurrentReduce = new ConcurrentReduce(config, imgInfo);
    concurrentReduce.run((err, result) => {
      if (err) {
        console.error('Error during data reduction:', err);
      } else {
        console.log('Result of the reduction:', result);
