```csharp
using System;
using System.Threading.Tasks;

public static class RetryHelper
{
    private const int MaxRetries = 5;
    private const TimeSpan InitialDelay = TimeSpan.FromMilliseconds(100);

    public static async Task<T> WithRetry<T>(Func<Task<T>> action)
    {
        for (int i = 0; i < MaxRetries; i++)
        {
            try
            {
                return await action();
            }
            catch (Exception ex) when (i < MaxRetries - 1)
            {
                Console.WriteLine($"Retrying operation ({i + 1}/{MaxRetries}) due to exception: {ex}");
                await Task.Delay((long)(Math.Pow(2, i) * InitialDelay.TotalMilliseconds));
            }
        }

        throw new Exception("Operation failed after max retries.");
    }
}
```

