        private static ConfigurationManager _instance;
        private Logger _logger;

        public static ConfigurationManager Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new ConfigurationManager(new Logger("ConfigurationManager"));
                return _instance;
            }
        }

        public void AddService(ApiService service)
        {
            _services[service.ConfigName] = service;
        }

        private ConfigurationManager(Logger logger)
        {
            _logger = logger;
        }

        public async Task ProcessFilesAsync(string[] filePaths)
        {
            var tasks = filePaths.Select(ProcessFileAsync).ToArray();
            await Task.WhenAll(tasks);
        }

        private async Task ProcessFileAsync(string filePath)
        {
            if (!File.Exists(filePath) || !Directory.Exists(Path.GetDirectoryName(filePath)))
            {
                _logger.Error($"Invalid file or directory: {filePath}");
                return;
            }

            using var reader = new StreamReader(filePath);
            using var csv = new CsvReader(reader, CultureInfo.InvariantCulture);

            // Process the CSV data concurrently
            while (csv.Read())
            {
                var numberSequence = await GenerateNumberSequenceAsync();
                // Process the generated number sequence
            }
        }

        private async Task<List<ApiService>> GenerateNumberSequenceAsync()
        {
            var services = new List<ApiService>();

            foreach (var apiService in _services.Values)
            {
                try
                {
                    services.Add(await apiService.GetServiceAsync());
                }
                catch (Exception ex)
                {
                    // Handle errors and fallback mechanisms
                }
            }

            return services;
        }

        private async Task<ApiService> GetServiceAsync(ApiService apiService)
        {
            if (!apiService.IsConfigured())
            {
                _logger.Error($"Configuration not found for service: {apiService.ConfigName}");
                throw new Exception("Configuration not found for service.");
            }

            return apiService;
        }
    }

    public abstract class ApiService : INotifyPropertyChanged
    {
        private string _configName;
        public event PropertyChangedEventHandler PropertyChanged;

        protected void OnPropertyChanged(string propertyName)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        public string ConfigName
        {
            get => _configName;
            set
            {
                if (_configName != value)
                {
                    _configName = value;
                    OnPropertyChanged("ConfigName");
                }
            }
        }

        public abstract Task<ApiService> GetServiceAsync();

        public bool IsConfigured()
        {
            return !string.IsNullOrEmpty(ConfigName);
        }
    }
}
```

