class AdvancedOctreeManager {
public:
    enum class HashingAlgorithm { SHA1, MD5 };
    enum class LoggingService { Console, File };

    AdvancedOctreeManager(const std::string& dirPath, HashingAlgorithm hashing, LoggingService logging)
        : m_dirPath(dirPath), m_hashing(hashing), m_logging(logging), m_octree(), m_statistics() {}

    void run();

private:
    std::string m_dirPath;
    HashingAlgorithm m_hashing;
    LoggingService m_logging;
    // Octree data structure, locking, condition variables and read-write locks implementation here
    // ...

    void compileStatistics(const path& path, const recursive_directory_iterator& it);
    void filterFiles(std::vector<path>& files, time_t minTime, size_t minSize);

    hash_map<std::string, unsigned> m_statistics;
};

void AdvancedOctreeManager::run() {
    // Implement octree initialization and concurrent updates here

    std::vector<path> files;
    for (const auto& entry : fs::recursive_directory_iterator(m_dirPath)) {
        if (entry.is_regular_file()) {
            if (entry.path().extension() != ".md" && entry.path().extension() != ".pdf") {
                files.push_back(entry.path());
            }
        }
    }

    std::thread pool[std::thread::hardware_concurrency()];
    for (auto& thread : pool) {
        thread = std::thread([this]() { compileStatistics(m_dirPath, std::prev(fs::recursive_directory_iterator(m_dirPath)))); });
    }

    for (auto& thread : pool) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    // Implement octree pruning and memory optimization here
}

void AdvancedOctreeManager::compileStatistics(const path& path, const recursive_directory_iterator& it) {
    if (!fs::is_regular_file(path)) return;

    std::ifstream ifs(path);
    std::string line, words, chars;
    size_t lines = 0, wordsCount = 0, charsCount = 0;

    while (std::getline(ifs, line)) {
        ++lines;
        std::istringstream iss(line);
        while (iss >> word) {
            ++wordsCount;
            charsCount += word.length();
        }
    }

    ifs.close();

    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    auto mtime = now - path.timestamp().time_since_epoch().count();
    auto fileSize = static_cast<size_t>(path.file_size());

    if (mtime >= minTime && fileSize >= minSize) {
        m_statistics[hash(line)] += lines;
        m_statistics[hash(words)] += wordsCount;
        m_statistics[hash(chars)] += charsCount;
    }
}

void AdvancedOctreeManager::filterFiles(std::vector<path>& files, time_t minTime, size_t minSize) {
    for (auto it = files.begin(); it != files.end(); ) {
        auto now = std::chrono::system_clock::now().time_since_epoch().count();
        auto mtime = now - it->timestamp().time_since_epoch().count();

        if (mtime < minTime || it->file_size() < minSize) {
            it = files.erase(it);
        } else {
            ++it;
        }
    }
}

