    private static final Logger LOGGER = LoggerFactory.getLogger(DataProcessor.class);
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private final String kafkaTopic;
    private final String binaryFile;
    private final long interval;
    private final ExecutorService executor;
    private KafkaProducer<String, String> producer;

    public DataProcessor(Properties props) {
        this.kafkaTopic = props.getProperty("kafka.topic");
        this.binaryFile = props.getProperty("binary.file");
        this.interval = Long.parseLong(props.getProperty("interval"));
        this.executor = Executors.newFixedThreadPool(Integer.parseInt(props.getProperty("concurrency")));
    }

    public void start() {
        producer = new KafkaProducer<>(props);
        Runnable dataProcessorTask = () -> {
            try (BufferedInputStream in = new BufferedInputStream(new FileInputStream(binaryFile))) {
