                LOGGER.error("Error processing data", e);
                // Recovery logic here, such as restarting the task or notifying a supervisor
            }
        };
        executor.submit(dataProcessorTask);
        Timer timer = new Timer();
        timer.scheduleAtFixedRate(new TimerTask() {
            @Override
            public void run() {
                dataProcessorTask.run();
            }
        }, interval, interval);
    }

    public void stop() throws InterruptedException {
        executor.shutdown();
        producer.close();
