```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <syslog>

#define MAX_SEMAPHORES 1024
typedef struct Semaphore {
    sem_t sem;
    char name[64];
    pthread_mutex_t lock;
    int ref_count;
} Semaphore;

void semaphore_init(Semaphore* sem, const char* name, int value) {
    if (sem == NULL || name == NULL || *name == '\0') {
        syslog(LOG_ERR, "Invalid arguments for semaphore creation.");
        return;
    }

    sem->ref_count = 1;
    strncpy(sem->name, name, sizeof(sem->name));
    pthread_mutex_init(&sem->lock, NULL);
    sem_init(&sem->sem, 0, value);
}

void semaphore_acquire(Semaphore* sem) {
    if (sem == NULL || sem->ref_count <= 0) {
        syslog(LOG_ERR, "Invalid or released semaphore.");
        return;
    }

    pthread_mutex_lock(&sem->lock);

    while (sem_wait(&sem->sem) != 0) {
        if (errno == EINTR) {
            continue;
        }
        syslog(LOG_ERR, "Semaphore acquisition failed.");
        pthread_mutex_unlock(&sem->lock);
        return;
    }

    sem->ref_count++;
    printf("[INFO] Acquired %s\n", sem->name);
    pthread_mutex_unlock(&sem->lock);
}

void semaphore_release(Semaphore* sem) {
    if (sem == NULL || sem->ref_count <= 0) {
        syslog(LOG_ERR, "Invalid or not acquired semaphore.");
        return;
    }

    pthread_mutex_lock(&sem->lock);

    if (--sem->ref_count > 0) {
        pthread_mutex_unlock(&sem->lock);
    } else {
        printf("[INFO] Released %s\n", sem->name);
        sem_post(&sem->sem);
        pthread_mutex_unlock(&sem->lock);
        sem->ref_count = 0;
    }
}

void semaphore_cleanup(Semaphore* sem) {
    if (sem == NULL || sem->ref_count > 0) {
        return;
    }

    pthread_mutex_destroy(&sem->lock);
    sem_destroy(&sem->sem);
}
```

