    std::function<void(std::string, std::function<void(std::string, void*, const std::unordered_map<std::string, std::string>&), const std::unordered_map<std::string, std::string>&)> attackFunction;
    std::unordered_map<std::string, std::string> configuration;
};

void runModuleTests(const std::string& moduleLabel, const std::vector<TestFunction>& testSuite, const std::string& loggingLevel, int cooldown, ResourceManager& resourceManager, DatabaseConnection& dbConnection, int maxConcurrentTests, int testTimeout, MockingLibrary& mockLibrary) {
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::thread> threads;
    int currentTests = 0;

    for (auto& test : testSuite) {
        auto testFuncThread = std::thread([&, test]() {
            mockLibrary.initialize(dbConnection);

            try {
                test.attackFunction(test.label, nullptr, test.configuration);
            } catch (const std::exception& e) {
                LoggingManager::log(loggingLevel, "Test [" + test.label + "] failed: " + e.what());
            }

            mockLibrary.reset();
        });
        threads.push_back(std::move(testFuncThread));

        if (currentTests < maxConcurrentTests) {
            currentTests++;
        } else {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [&]() { return currentTests < maxConcurrentTests; });
        }
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

