typedef struct mmaped_file MmapedFile;
struct mmaped_file {
    void *ptr;
    size_t length;
    size_t max_length;
};

MmapedFile* map_file(const char *path) {
    struct stat sb;
    int fd = open(path, O_RDONLY);
    if (fd == -1) return NULL;

    fstat(fd, &sb);
    MmapedFile *mf = malloc(sizeof(MmapedFile));
    if (!mf) {
        close(fd);
        return NULL;
    }

    mf->ptr = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (mf->ptr == MAP_FAILED) {
        free(mf);
        close(fd);
        return NULL;
    }

    mf->length = sb.st_size;
    mf->max_length = sb.st_st_size;
    close(fd);
    return mf;
}

void unmap_file(MmapedFile *mf) {
    if (munmap(mf->ptr, mf->length) == -1) {} // Ignore error for simplicity
    free(mf);
}

const char* get_resource_extension(const char *path) {
    const char *dot = strrchr(path, '.');
    if (!dot) return "";
    return dot + 1;
}

void load_and_process_resource_bundle(const char *path, nlohmann::json &response) {
    MmapedFile *mf = map_file(path);
    if (!mf) {
        response["success"] = false;
        response["message"] = "Failed to load resource bundle.";
        unmap_file(mf);
        return;
    }

    const char *ext = get_resource_extension(path);
    if (strcmp(ext, "json") == 0) {
        nlohmann::json j = nlohmann::json::parse(reinterpret_cast<char*>(mf->ptr), reinterpret_cast<char*>(mf->ptr + mf->length));
        // Process JSON here...
    } else if (strcmp(ext, "yaml") == 0) {
        YAML::Node node = YAML::Load(reinterpret_cast<char*>(mf->ptr), mf->length);
        // Process YAML here...
    }

    unmap_file(mf);
}

