#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

static pthread_once_t once = PTHREAD_ONCE_INIT;
static char *tempStr = NULL;
static size_t tempCapacity = 0;

void initializeTemp() {
    if (tempStr) return;
    tempStr = malloc(sizeof(char));
    tempCapacity = 1;
}

char *appendSlashIfWithinLimit(const char *input, size_t sizeLimit) {
    pthread_once(&once, initializeTemp);

    size_t inputLen = strlen(input);

    if (sizeLimit <= 0 || inputLen > sizeLimit - 1) {
        free(tempStr);
        return NULL;
    }

    if (inputLen + 2 >= tempCapacity) {
        size_t newCapacity = tempCapacity * 2;
        while (newCapacity < inputLen + 2) {
            newCapacity *= 2;
        }
        char *newTempStr = realloc(tempStr, newCapacity);
        if (!newTempStr) {
            free(tempStr);
            return NULL;
        }
        tempStr = newTempStr;
        tempCapacity = newCapacity;
    }

    strcpy(tempStr, input);
    tempStr[inputLen] = '/';
    tempStr[inputLen + 1] = '\0';

    return tempStr;
}
```

