#include <iostream>
#include <fstream>
#include <random>
#include <vector>
#include <sstream>
#include <cstdlib>
#include <stdexcept>

namespace RandomGenerator {
    class SecureMersenneTwister {
        std::mt19937_64 generator;

    public:
        SecureMersenneTwister(const std::string& seed) {
            if (seed.empty()) throw std::invalid_argument("Seed cannot be empty");

            // Initialize the seed sequence with the given seed and data from /dev/urandom
            std::vector<unsigned long long> seeds;
            seeds.push_back(std::hash<std::string>{}(seed));
            std::random_device rd;
            seeds.insert(seeds.end(), rd().begin(), rd().end());

            std::seed_seq seq(seeds.begin(), seeds.end());
            generator.seed(seq);
        }

        ~SecureMersenneTwister() {} // Trivial destructor

        unsigned long long uniform() {
            return generator();
        }

        double normal() {
            std::normal_distribution<double> dist(0, 1);
            return dist(generator);
        }

        static SecureMersenneTwister createFromFile(const std::string& filePath) {
            if (filePath.empty()) throw std::invalid_argument("File path cannot be empty");

            std::ifstream inputFile(filePath);
            if (!inputFile.is_open()) throw std::runtime_error("Failed to open the specified file");

            std::string seed;
            std::getline(inputFile, seed);

            return SecureMersenneTwister(seed);
        }
    };
} // namespace RandomGenerator

int main() {
    RandomGenerator::SecureMersenneTwister gen(std::string("MySeed"));

    for (size_t i = 0; i < 10; ++i) {
        std::cout << "Uniform: " << gen.uniform() << std::endl;
        std::cout << "Normal: " << gen.normal() << std::endl;
    }

    RandomGenerator::SecureMersenneTwister fileGen("path/to/my_seed.txt");

    return 0;
}
```

