const retryInterval = { default: 500, configurable: true };
let activeRetries = 0;

function fetchScript(script, callback) {
  const key = script.url;

  if (cache[key]) return Promise.resolve(cache[key]); // Return cached script if available

  return fetch(script.url)
    .then((response) => {
      if (!response.ok) throw new Error(`Error ${response.status} when loading script: ${script.url}`);
      return response.text();
    })
    .then((content) => {
      cache[key] = content; // Cache the fetched script
      return content;
    })
    .catch((error) => {
      if (activeRetries < maxRetries) {
        activeRetries++;
        setTimeout(() => fetchScript(script, callback), retryInterval * activeRetries);
      } else {
        throw error; // If max retries reached, re-throw the error
      }
    });
}

function renderScript({ key, type = "text/javascript", code }) {
  const scriptElement = document.createElement("script");
  scriptElement.key = key;
  scriptElement.type = type;
  scriptElement.innerHTML = code;
  return scriptElement;
}

function renderScripts(scripts, callback) {
  let priorityQueue = [...scripts];
  const loadingSpinner = document.createElement("div"); // Add a loading spinner here
  const scriptsContainer = document.createElement("div");

  function processNextScript() {
    if (!priorityQueue.length) {
      callback();
      return;
    }

    const script = priorityQueue.shift();
    fetchScript(script)
      .then((content) => scriptsContainer.appendChild(renderScript({ key: script.url, code: content })))
      .catch((error) => console.error(`Error while loading script ${script.url}:`, error))
      .finally(() => processNextScript());
  }

  priorityQueue.sort((a, b) => a.priority - b.priority); // Sort scripts based on priority (16th requirement)
  scriptsContainer.appendChild(loadingSpinner);
  document.body.appendChild(scriptsContainer);
  processNextScript();
}

// Usage example:
const myScripts = [
  { url: "https://my-api.com/script1", code: "...", priority: 1 },
  { url: "https://my-api.com/script2" },
  // ... more script objects
];

renderScripts(myScripts, () => {
  // All scripts have been rendered, hide the loading spinner and perform any necessary actions
});
```

