public class AzureImageManager
{
    private readonly CloudBlobClient _blobClient;
    private readonly ConcurrentDictionary<(string userId, string size), CloudBlockBlob> _cache = new();

    public AzureImageManager()
    {
        var accountName = GetEnvironmentVariable("AZURE_BLOB_ACCOUNT_NAME");
        var accountKey = GetEnvironmentVariable("AZURE_BLOB_ACCOUNT_KEY");

        CloudStorageAccount storageAccount = new CloudStorageAccount(new StorageCredentials(accountName, accountKey), useHttps: true);
        _blobClient = storageAccount.CreateCloudBlobClient();
    }

    public async Task<CloudBlockBlob> GetImageAsync(string userId, string size)
    {
        if (_cache.TryGetValue((userId, size), out var cachedImage))
            return cachedImage;

        CloudBlockBlob imageBlob = _blobClient.GetBlockBlobReference($"{userId}/{size}/image.{GetImageFormat(size)}");

        lock (_cache)
        {
            _cache[(userId, size)] = imageBlob;
        }

        return await imageBlob.DownloadToMemoryAsync();
    }

    public async Task UploadImagesAsync(IEnumerable<(CloudBlockBlob blob, string userId, string size)> images)
    {
        ParallelOptions options = new() { MaxDegreeOfParallelism = Environment.ProcessorCount };
        await Parallel.ForEachAsync(images, options, (imageGroup, token) =>
        {
            imageGroup.blob.UploadFromStream(imageGroup.blob.OpenWrite(), token);
            token.Wait();
        });
    }
}
