const renderFooterScripts = (scripts, config = {}) => {
  let cachedScripts = JSON.parse(localStorage.getItem('cachedScripts')) || {};

  const fetchScript = async (url, key) => {
    if (cachedScripts[key]) return Promise.resolve(cachedScripts[key]);

    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`Error: ${response.statusText}`);
      const scriptCode = await response.text();
      cachedScripts[key] = scriptCode;
      localStorage.setItem('cachedScripts', JSON.stringify(cachedScripts));
      return scriptCode;
    } catch (error) {
      console.error(`Error fetching script from ${url}:`, error);
      if (config.fallbackUrl) return fetchScript(config.fallbackUrl, key);
      return Promise.resolve(''); // Provide a fallback value for missing scripts
    }
  };

  const renderScript = (script, key) => {
    script.key = key;
    if (!script.code || !script.type) {
      console.warn(`Missing essential properties in script: ${JSON.stringify(script)}`);
      return '';
    }
    return `<script id="script-${key}" type="${script.type}">${script.code}</script>`;
  };

  const renderFooter = () => scripts
    .map((script, i) => renderScript(script, i))
    .join('\n');

  const loadAndRenderScripts = async () => {
    const promises = scripts.map((script, i) => fetchScript(script.url || '', `script-${i}`));
    const fetchedScripts = await Promise.all(promises);
    const renderedScriptsHtml = renderFooter(fetchedScripts);
    const footer = document.createElement('footer');
    footer.innerHTML = renderedScriptsHtml;

    if (config.loadingIndicator) {
      config.loadingIndicator.classList.add('hidden');
    }

    document.body.appendChild(footer);
    handleScriptErrors(footer);
  };

  const handleScriptErrors = (element) => {
    element.addEventListener('error', (event) => {
      console.error(`Error loading script: ${event.target.src}`, event);
      if (config.errorHandler) config.errorHandler(event);
    });
  };

  const cleanUpOldScripts = () => {
    // Implement a custom cleanup function to remove old or unused script elements
  };

  if (config.loadingIndicator) {
    config.loadingIndicator.classList.remove('hidden');
  }

  loadAndRenderScripts();
};
