    public Future<Void> processLargeFileAsync(String filePath, Function<List<Byte>, Void> processingFunction) throws InterruptedException, ExecutionException {
        Configuration conf = new Configuration();
        conf.set("spark.cassandra.connection.host", "your_cassandra_cluster_address");

        JavaRDD<Byte> fileBytes = SparkSession.create().read()
                .textFile(filePath)
                .flatMap(line -> Collections.splitList(Arrays.asList(line), "\n"))
                .map(bytes -> {
                    ByteBuffer buffer = ByteBuffer.allocate(1024); // Adjust buffer size as needed
                    buffer.put(bytes);
                    buffer.flip();
                    return buffer;
                });

        fileBytes.saveAsTextFile("file_chunks", true, conf);

        JavaRDD<List<Byte>> chunkedData = fileBytes.map(buffer -> {
            List<Byte> chunk = new ArrayList<>();
            while (buffer.hasRemaining()) {
                chunk.add((byte) buffer.get()); // Read and process data chunks concurrently
            }
            return chunk;
        });

        Future<Void> futureResult = chunkedData.foreach(processingFunction);
        return futureResult;
    }
}
