const readConfigFiles = async (dir, extensions, defaults) => {
  const configs = {};
  const fileExtensionsRegex = new RegExp(`\\.[${extensions.join('.')}]$`, 'i');

  try {
    const files = await fsPromises.readdir(dir);

    for (const file of files) {
      const filePath = path.resolve(dir, file);
      const statResult = await fsPromises.stat(filePath);

      if (statResult.isDirectory()) continue;
      if (!fileExtensionsRegex.test(file)) continue;

      try {
        const configContent = await fsPromises.readFile(filePath, 'utf8');
        const parsedConfig = parseConfig(configContent);

        if (parsedConfig) {
          configs[file] = parsedConfig;
        } else {
          logger.error(`Invalid configuration file: ${file}`);
        }
      } catch (err) {
        logger.error(`Error reading configuration file: ${file}. Error: ${err.message}`);
      }
    }

    return merge({}, ...Object.values(configs), defaults);
  } catch (err) {
    logger.error(`Error reading configuration directory: ${dir}. Error: ${err.message}`);
    throw err;
  }
};

const parseConfig = content => {
  // Implement parsing logic for supported file types here, e.g., JSON, YAML, etc.
  try {
    return JSON.parse(content);
  } catch (err) {
    return undefined;
  }
};

export default readConfigFiles;
