3. Implement the function to insert strings into a forward list:

```cpp
void insertStrings(std::forward_list<std::string>& list, const std::string& first, const std::string& second, int times) {
    // Iterate through the list and insert second after each occurrence of first
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == first) {
            list.insert(++it, std::move(second));
            if (times > 1) times--;
        }
        it++;
    }

    // Insert second at the end of the list if first was not found
    if (list.end() != it && times == 0) list.insert(it, std::move(second));
}
```

