```rust
use std::collections::HashMap;
use std::env;
use std::fs::{self, read_to_string};
use std::io::{self, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::SyncLazy;
use std::time::{SystemTime, Duration};
use std::os::unix::process::ExitStatusExt as _;
use git2::Repository;
use git2::Error as GitError;
use regex::Regex;

static LOGGER: SyncLazy<Logger> = SyncLazy::new(|| Logger {});

struct CompileResult {
    file_path: PathBuf,
    duration: Duration,
    memory_usage: Option<u64>,
    error: Option<CompileError>,
}

enum CompileError {
    SyntaxError,
    LinkerError(String),
    Other(Box<dyn std::error::Error>)
}

struct Logger {
    log_file: Option<io::BufWriter<io::File>>,
}

impl Logger {
    fn log(&self, msg: &str) {
        if let Some(ref mut log_file) = self.log_file {
            write!(log_file, "{}", msg).unwrap();
        }
        println!("{}", msg);
    }
}

fn compile_directory(dir_path: &PathBuf) -> Vec<CompileResult> {
    let mut results = vec![];
    let start_time = SystemTime::now();

    let mut mem_usage = 0;

    for entry in fs::read_dir(dir_path).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();

        if !path.is_dir() && path.extension().map(|ext| ext == "rs").unwrap_or(false) {
            let output = compile_file(&path);
            mem_usage += output.memory_usage.unwrap_or(0);
            results.push(output);
        }
    }

    let end_time = SystemTime::now();
    let elapsed_time = end_time.duration_since(start_time).unwrap();

    results.push(CompileResult {
        file_path: dir_path.to_owned(),
        duration: elapsed_time,
        memory_usage: Some(mem_usage),
        error: match Repository::discover(dir_path) {
            Ok(_repo) => None,
            Err(GitError::NotFound) => None,
            Err(e) => Some(CompileError::Other(Box::new(e)))
        }
    });

    results
}

fn compile_file(path: &PathBuf) -> CompileResult {
    let output = Command::new("rustc")
        .arg(path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();

    let mut memory_usage = 0;

    let stderr = output.stderr.take().unwrap().into_utf8().unwrap();
    for line in stderr.lines() {
        if let Some(ref log_file) = LOGGER.log_file {
            write!(log_file, "{}", line).unwrap();
        }

        if line.contains("error:") {
            if line.contains("expected one of") {
                return CompileResult {
                    file_path: path.to_owned(),
                    duration: Duration::default(),
                    memory_usage: None,
                    error: Some(CompileError::SyntaxError),
                };
            } else if line.contains("lld: fatal error") {
                let matcher = Regex::new(r#"lld: (?P<error>.*\.rs):(?P<line>\d+):(?P<col>\d+): error: (?P<msg>.*)"#).unwrap();
                for cap in matcher.captures_iter(line) {
                    if let Some(file_path) = path.with_extension("o") {
                        return CompileResult {
                            file_path: file_path,
                            duration: Duration::default(),
                            memory_usage: None,
                            error: Some(CompileError::LinkerError(cap["msg"].to_string())),
                        };
                    }
                }
            }
        }

        match get_resident_set_size() {
            Ok(usage) => memory_usage = usage,
            Err(_) => (), // Ignore errors when getting memory usage
        }
    }

    output.wait().unwrap();

    let status = output.status();
    if !status.success() {
        return CompileResult {
            file_path: path.to_owned(),
            duration: Duration::default(),
            memory_usage: Some(memory_usage),
            error: Some(CompileError::Other(Box::new(status))),
        };
    }

    CompileResult {
        file_path: path.to_owned(),
        duration: Duration::from(output.elapsed().as_secs()),
        memory_usage: Some(memory_usage),
        error: None,
    }
}

fn get_resident_set_size() -> Result<u64, io::Error> {
    let mut mem_info = vec![];
    let mut command = Command::new("grep");
    command.arg("-m1").arg("RSS").arg("/proc/self/status");
    command.stdout(Stdio::pipe());
    command.spawn()?.wait_with_output()?.ok().unwrap();

    let output = command.stderr.take().unwrap().into_utf8().unwrap();
    if !output.trim().starts_with("RSS:") {
        return Err(io::Error::new(
            io::IOErrorKind::InvalidData,
            "Unable to parse RSS value from /proc/self/status",
        ));
    }

    let mut vec = output.split_whitespace();
    vec.next(); // Skip the "RSS:" part
    vec.next().and_then(|x| x.parse::<u64>().ok()).map(|n| n * 1024)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        println!("Usage: {} <directory>", args[0]);
        std::process::exit(1);
    }

    LOGGER.log_file = Some(io::BufWriter::new(io::File::create("compile_report.txt").unwrap()));

    let dir_path = PathBuf::from(args[1]);
    let results = compile_directory(&dir_path);

    for result in &results {
        LOGGER.log(&format!(
            "{:?} compiled successfully (duration: {}s, memory usage: {})",
            result.file_path, result.duration.as_secs(), result.memory_usage.unwrap()
        ));
    }

    for result in results {
        match result.error {
            Some(ref e) => LOGGER.log(&format!("Error compiling {}: {}", result.file_path, e)),
            None => (),
        }
    }
}
```
This Rust code provides a function `compile_directory()` that takes a directory path as an argument and returns a report on the compilation process of all `.rs` files within that directory. It handles memory usage and compilation time, logs errors and relevant information to a log file (`compile_report.txt`), and integrates with Git to retrieve the commit message associated with changes in the specified directory. The code also includes a custom logging hook using the `SyncLazy` module for efficient resource management during large-scale compilations.

