        using (var reader = new StreamReader("config.xml"))
        {
            var configDict = (Dictionary<string, CustomRangeConfig[]>)serializer.Deserialize(reader);
            _rangeLimitsCache = new Dictionary<string, CustomRangeConfig[]>(configDict);
        }
    }

    public Tuple<float, float> CustomRange(params int[] dimensions)
    {
        if (dimensions.Length <= 0) throw new ArgumentException("Dimensions cannot be empty.");

        var rangeLimits = _rangeLimitsCache.GetValueOrDefault($"{string.Join(",", dimensions)}");

        if (rangeLimits == null) throw new ArgumentOutOfRangeException("Invalid or missing range limits for the provided dimensions.");

        return Enumerable.Range(0, dimensions.Length).Select(i => rangeLimits[i].min + UnityEngine.Random.value * (rangeLimits[i].max - rangeLimits[i].min)).ToTuple();
    }

    public Tuple<float, float> CustomRange(Func<float> customDistribution)
