        {
            _customDistributionsCache[customDistribution.Method.Name] = customDistribution;
            // Load the distribution function from a custom configuration here
        }

        return Tuple.Create(_customDistributionsCache[customDistribution.Method.Name](), _customDistributionsCache[customDistribution.Method.Name]());
    }

    public void OnNewSeedGenerated(Action<int> onNewSeed)
    {
        // Integrate with external systems here, for example:
