Here is a simplified version of a modular data aggregation service in Node.js using `stream` module for handling network streams, `bluebird` for Promise-based asynchronous operations, and `winston` for logging. This code does not include all the requirements mentioned but provides a starting point.

```javascript
const stream = require('stream');
const { promisify } = require('util');
const bluebird = require('bluebird');
const winston = require('winston');

// Define configurable options
const DEFAULT_BUFFER_SIZE = 1024;
const MAX_CONCURRENT_STREAMS = 10;
const LOGGING = true;

class DataAggregator extends stream.Transform {
  constructor(options) {
    super(options);
    this.sources = [];
    this._bufferedData = Buffer.alloc(DEFAULT_BUFFER_SIZE);
    this.bufferSize = options.bufferSize || DEFAULT_BUFFER_SIZE;
    this.maxConcurrentStreams = options.maxConcurrentStreams || MAX_CONCURRENT_STREAMS;
  }

  // Add source stream to the aggregator
  addSource(source) {
    if (this.sources.length >= this.maxConcurrentStreams) return;
    source.on('data', this._handleData.bind(this));
    source.on('error', this._handleError.bind(this));
    source.on('end', this._handleEnd.bind(this));
    this.sources.push(source);
  }

  // Handle data from a source stream, buffer it and log metadata
  async _handleData(chunk) {
    if (LOGGING) winston.info(`Source: ${this.sources[this.sources.indexOf(this._currentSource)]}, ByteRange: ${Buffer.byteLength(chunk)}, Timestamp: ${Date.now()}`);
    this._bufferedData = Buffer.concat([this._bufferedData, chunk]);
  }

  // Handle errors from a source stream and log metadata
  _handleError(err) {
    if (LOGGING) winston.error(`Source: ${this.sources[this.sources.indexOf(this._currentSource)]}, Error: ${err}`);
  }

  // Handle 'end' event from a source stream and log metadata
  _handleEnd() {
    if (LOGGING) winston.info(`Source: ${this.sources[this.sources.indexOf(this._currentSource)]} ended, Timestamp: ${Date.now()}`);
  }

  // Implement the transform method for buffering data
  _transform(chunk, encoding, callback) {
    this._currentSource = this.sources[this.sources.length - 1];
    callback(null, chunk);
  }

  // Flush the buffered data when the stream ends
  _flush(callback) {
    callback(null, this._bufferedData);
  }
}

// Promisify Transform stream methods for easier asynchronous handling
const pipelineAsync = promisify(bluebird.coroutine(function* (streams, dest) {
  yield streams[0].pipe(dest, {end: false});
  for (let i = 1; i < streams.length; i++) {
    yield streams[i].pipe(dest);
  }
}));

// Usage example
const aggregator = new DataAggregator({ bufferSize: 8192 });
const sources = [stream1, stream2]; // Assuming stream1 and stream2 are network streams

// Add each source to the aggregator
sources.forEach(source => aggregator.addSource(source));

// Create a writable stream as destination for the pipeline (e.g., an HTTP response)
const destination = new stream.Writable({
  write: (chunk, encoding, callback) {
    // Write the aggregated data to the destination here
    callback();
  }
});

// Start the data aggregation and piping
pipelineAsync([...sources, aggregator])
  .then(() => aggregator._flush())
  .then(data => {
    // Handle the aggregated data after flushing here
  })
  .catch(err => winston.error(err));
```

