    public async Task<XPathNavigator> GetXml(string url, string xsdFilePath)
    {
        var key = url + xsdFilePath;
        if (_cache.TryGetValue(key, out XPathNavigator nav))
        {
            if (DateTimeOffset.UtcNow - nav.BaseURI.LastModifiedUtc > _cacheDuration)
                _cache[key] = await ReloadXml(url);

            return nav;
        }

        var navigator = await ReloadXml(url);
        ValidateXsd(xsdFilePath, navigator);
        _cache.TryAdd(key, navigator);

