```csharp
using System;
using System.Collections.Concurrent;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class XmlDocumentManager
{
    private readonly ILogger<XmlDocumentManager> _logger;
    private readonly ConcurrentDictionary<string, Task<XmlDocument>> _xmlDocuments;
    private readonly XmlSchemaSet _xsdSchema;
    private readonly string _dataSourceUrl;
    private readonly IVersionControlService _versionControl;
    private readonly TimeSpan _cacheExpirationTime;

    public XmlDocumentManager(ILogger<XmlDocumentManager> logger, IConfiguration configuration, IVersionControlService versionControl)
    {
        _logger = logger;
        _xmlDocuments = new ConcurrentDictionary<string, Task<XmlDocument>>();
        _xsdSchema = new XmlSchemaSet();
        _dataSourceUrl = configuration.GetValue<string>("XmlData:DataSourceUrl");
        _versionControl = versionControl;
        _cacheExpirationTime = TimeSpan.FromMinutes(5);
    }

    public async Task<XmlDocument> GetXmlDocumentAsync(string documentName, CancellationToken cancellationToken)
    {
        if (!_xmlDocuments.TryGetValue(documentName, out var task))
        {
            _xmlDocuments[documentName] = LoadXmlDocumentAsync(documentName);
        }

        XmlDocument xmlDocument;
        bool isNewVersion;
        lock (_xmlDocuments)
        {
            if (_xmlDocuments.TryGetValue(documentName, out task))
            {
                xmlDocument = await task;
                isNewVersion = _versionControl.IsNewVersion(documentName);
            }
            else
            {
                xmlDocument = null;
                isNewVersion = false;
            }
        }

        if (isNewVersion)
        {
            _xmlDocuments[documentName] = LoadXmlDocumentAsync(documentName);
            xmlDocument = await _xmlDocuments[documentName];
        }

        ValidateAndLogInput(documentName, xmlDocument);
        return xmlDocument;
    }

    private Task<XmlDocument> LoadXmlDocumentAsync(string documentName)
    {
        var httpClient = ServiceProvider.GetService<HttpClient>();
        return httpClient.DownloadStringAsync($"{_dataSourceUrl}/{documentName}.xml")
            .ContinueWith(task => XmlDocument.Load(new StringReader(task.Result)), cancellationToken: CancellationToken.None)
            .ContinueWith(async task => ValidateAndCacheXmlDocumentAsync(documentName, task.Result), cancellationToken: CancellationToken.None);
    }

    private void ValidateAndCacheXmlDocumentAsync(string documentName, XmlDocument xmlDocument)
    {
        if (!_xsdSchema.IsValid(xmlDocument))
            throw new Exception("Invalid XML document.");

        var validationResults = _xsdSchema.Validate(xmlDocument);
        foreach (var error in validationResults.Errors())
            _logger.LogError(error, "Validation Error: {DocumentName}", documentName);

        _cacheExpirationTime = TimeSpan.FromMinutes(_validationResults.Count > 0 ? 1 : 5);
        CacheXmlDocument(documentName, xmlDocument);
    }

    private void ValidateAndLogInput(string documentName, XmlDocument xmlDocument)
    {
        if (string.IsNullOrWhiteSpace(xmlDocument.XPathSelectElement("/metadata/xsd:schemaLocation").OuterXml))
            throw new Exception("Missing schema location.");

        var xpathQuery = ServiceProvider.GetService<IXPathQueryValidator>();
        xpathQuery.Validate(xmlDocument, out var validationResults);

        if (validationResults.Errors.Any())
            _logger.LogError(validationResults.Errors, "XPath Query Validation Error: {DocumentName}", documentName);
    }

    private void CacheXmlDocument(string documentName, XmlDocument xmlDocument)
    {
        var cachePolicy = new CacheItemPolicy();
        cachePolicy.AbsoluteExpiration = DateTimeOffset.UtcNow + _cacheExpirationTime;
        MemoryCache.Default.Set(documentName, xmlDocument, cachePolicy);
    }
}
```

