Here is a simplified version of the code you requested. This is not an exhaustive solution, but it covers some essential aspects like thread pool management, logging, error handling, and basic file system interaction. It uses libcurl, pthreads for multithreading, and system libraries for command-line arguments parsing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>

typedef struct {
    char *url;
    FILE *output_file;
    size_t written_bytes;
} DownloadJob;

struct config {
    int max_threads;
    int timeout;
    int retry_interval;
};

struct config config;

static CURLcode curl_callback(CURL *curl, void *userdata, curl_off_t dltotal, curl_off_t dlnow, curl_off_t ultotal, curl_off_t ultnow) {
    DownloadJob *job = userdata;
    job->written_bytes = dlnow;
    return 0;
}

void download(DownloadJob *job) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        printf("Failed to initialize libcurl\n");
        exit(EXIT_FAILURE);
    }

    curl_easy_setopt(curl, CURLOPT_URL, job->url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, curl_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, job);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, config.timeout);

    FILE *output = fopen(job->url, "wb");
    if (!output) {
        printf("Failed to open output file: %s\n", job->url);
        exit(EXIT_FAILURE);
    }

    job->output_file = output;
    curl_easy_setopt(curl, CURLOPT_FDPASS, 1);
    curl_easy_setopt(curl, CURLOPT_FILEDESCRIPTOR, fileno(output));

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        printf("Download failed: %s\n", curl_easy_strerror(res));
        fclose(job->output_file);
    }

    curl_easy_cleanup(curl);
}

void* thread_func(void *arg) {
    DownloadJob *job = arg;
    download(job);
    free(job);
    return NULL;
}

void manage_threads() {
    pthread_t threads[config.max_threads];
    DownloadJob **jobs = malloc(sizeof(DownloadJob*) * config.max_threads);

    int num_finished = 0, i;
    DIR *dir = opendir("input");
    if (!dir) {
        printf("Failed to open input directory\n");
        exit(EXIT_FAILURE);
    }

    struct dirent *entry;
    while ((entry = readdir(dir))) {
        char *url = malloc((strlen(entry->d_name) + 24));
        sprintf(url, "http://example.com/%s", entry->d_name);
        jobs[num_finished] = malloc(sizeof(DownloadJob));
        jobs[num_finished]->url = url;
        num_finished++;
    }
    closedir(dir);

    for (i = 0; i < num_finished; ++i) {
        pthread_create(&threads[i], NULL, thread_func, jobs[i]);
    }

    for (i = 0; i < config.max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(jobs);
}

int main(int argc, char **argv) {
    if (argc < 5 || strcmp(argv[1], "--config") != 0) {
        printf("Usage: %s --config config_file input output max_threads\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *cfg = fopen(argv[2], "r");
    if (!cfg) {
        printf("Failed to open configuration file\n");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    while (fgets(line, sizeof(line), cfg)) {
        char *key = strtok(line, "=");
        if (!key) continue;

        key = strtok(NULL, "\n");
        if (!key) continue;

        if (strcmp(key, "max_threads") == 0) {
            sscanf(line, "%d", &config.max_threads);
        } else if (strcmp(key, "timeout") == 0) {
            sscanf(line, "%d", &config.timeout);
        } else if (strcmp(key, "retry_interval") == 0) {
            sscanf(line, "%d", &config.retry_interval);
        }
    }
    fclose(cfg);

    manage_threads();
    return 0;
}
```

