import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;
import java.util.zip.GzipInputStream;
import okhttp3.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileHashValidator {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileHashValidator.class);

    private static final int MAX_RETRIES = 3;
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors() * 2);
    private static final ConcurrentMap<Path, BigInteger> cache = new ConcurrentHashMap<>();

    public Map<Path, BigInteger> validateFileHashes(List<Path> filePaths) throws IOException {
        Map<Path, BigInteger> fileHashes = new LinkedHashMap<>();

        CompletionService<Call> completionService = Executors.newCompletionService(executor);
        List<Callable<Call>> tasks = createTasks(filePaths);

        for (int i = 0; i < MAX_RETRIES + 1; i++) {
            for (Call call : tasks) {
                Call callToService = OkHttpClient.newBuilder()
                        .retryOnConnectionFailure(true)
                        .build()
                        .newCall(call);
                completionService.submit(callToService);
            }

            List<Future<Call>> futures = completionService.takeOutOfOrder(MAX_RETRIES + 1).drainTo(new ArrayList<>());
            for (Future<Call> future : futures) {
                if (!future.isDone() || !future.get().isSuccessful()) {
                    // Handle failed API calls here, e.g., by retrying or logging the error
                } else {
                    Response response = future.get().response();
                    if (Objects.requireNonNull(response.body()).contentLength() > 0) {
                        BigInteger serviceHash = new BigInteger(Objects.requireNonNull(response.bytes()));
                        fileHashes.put(task.getFile(), computeFileHash(task.getFile()));
                        if (!serviceHash.equals(fileHashes.get(task.getFile()))) {
                            throw new HashMismatchException(task.getFile(), serviceHash, fileHashes.get(task.getFile()));
                        }
                    } else {
                        // Handle empty response or other API errors here, e.g., by retrying or logging the error
                    }
                }
            }
        }

        return fileHashes;
    }

    private Callable<Call> createTask(Path filePath) {
        return () -> OkHttpClient.newBuilder()
                .followRedirects(FollowRedirects.NEVER) // Avoid redirect loops
                .build()
                .newCall(createRequest(filePath));
    }

    private Request createRequest(Path filePath) {
        Request.Builder builder = new Request.Builder().url("https://your-api-endpoint/validateHash").get();

        try (BufferedReader reader = Files.newBufferedReader(filePath, StandardCharsets.UTF_8)) {
            if (filePath.toString().endsWith(".gz")) {
                builder.addHeader("Content-Encoding", "gzip");
            }

            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
            }
            builder.addHeader("Content-Type", "application/x-www-form-urlencoded")
                    .post(new FormBody.Builder()
                            .add("fileContent", content.toString())
                            .build());
        } catch (IOException e) {
            throw new RuntimeException("Error reading file:", e);
        }

        return builder.build();
    }

    private BigInteger computeFileHash(Path filePath) {
        try (MessageDigest digest = MessageDigest.getInstance("MD5")) {
            BufferedInputStream inputStream;
            if (filePath.toString().endsWith(".gz")) {
                inputStream = new BufferedInputStream(new GzipInputStream(Files.newInputStream(filePath)));
            } else {
                inputStream = new BufferedInputStream(Files.newInputStream(filePath));
            }
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
            return digest.digest();
        } catch (NoSuchAlgorithmException | IOException e) {
            throw new RuntimeException("Error computing file hash:", e);
        }
    }

    private List<Callable<Call>> createTasks(List<Path> filePaths) {
        return Executors.newSingleThreadExecutor()
                .submit(() -> {
                    List<Callable<Call>> tasks = new ArrayList<>();
                    for (Path filePath : filePaths) {
                        tasks.add(createTask(filePath));
                    }
                    return tasks;
                }).get();
    }
}

class HashMismatchException extends Exception {
    private final Path mismatchedFile;
    private final BigInteger serviceHash;
    private final BigInteger computedHash;

    public HashMismatchException(Path mismatchedFile, BigInteger serviceHash, BigInteger computedHash) {
        this.mismatchedFile = mismatchedFile;
        this.serviceHash = serviceHash;
        this.computedHash = computedHash;
    }

    // Add necessary getters and methods here
}
