#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define MIN_KEY 1
#define MAX_KEY 1000000

typedef struct {
    int key;
} Record;

pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;
int *keys, unique_keys[MAX_KEY + 1];
long *offsets;
Record *records;

void populate_unique_keys(int min, int max) {
    for (int i = min; i <= max; ++i) {
        pthread_mutex_lock(&keys_mutex);
        if (!unique_keys[i]) {
            unique_keys[i] = 1;
            keys = realloc(keys, sizeof(int)*(i + 1));
            keys[i] = i;
        }
        pthread_mutex_unlock(&keys_mutex);
    }
}

void *get_random_key() {
    int key;
    do {
        key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    } while (unique_keys[key]);
    return &keys[key];
}

void fetch_data(void *arg) {
    // Implement the logic to connect to an external data source and fetch data.
    // This example uses a sleep function to simulate varying response times.
    time_t delay = rand() % 10 + 5;
    sleep(delay);
}

void create_records(int num_threads) {
    pthread_t threads[num_threads];

    populate_unique_keys(MIN_KEY, MAX_KEY);
    offsets = malloc(sizeof(long));
    *offsets = 0;
    records = malloc(sizeof(Record) * MAX_RECORDS);

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, fetch_data, NULL);
    }

    for (int i = 0; i < num_threads; ++i) {
        void *status;
        pthread_join(threads[i], &status);
    }

    Record *record_ptr = records + *offsets;
    long current_offset = *offsets;

    for (int i = 0; i < num_threads; ++i) {
        void *key_ptr = get_random_key();
        record_ptr->key = *((int *) key_ptr);
        ++current_offset;
        ++record_ptr;
    }

    free(keys);
    free(unique_keys);
    free(offsets);
}

