#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Maximum message count before rotation
#define MAX_MESSAGES 1000

// Logging levels
enum { ERROR, WARNING, INFO, DEBUG, TRACE1, TRACE2, TRACE3, TRACE4, TRACE5, TRACE6 };

typedef struct _log_ctx {
    FILE *file;
    char buffer[1024];
    size_t pos;
} log_ctx;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static log_ctx ctx = { NULL };

void log_init() {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    ctx.file = fopen("logs/log_" __func__ "_" timestamp ".log", "a");
}

void log_cleanup() {
    if (ctx.file) {
        fclose(ctx.file);
        ctx.file = NULL;
    }
}

int logCondition(const char *level, const char *format, ...) {
    va_list args;
    int level_idx;

    if (!ctx.file || !level || !format) {
        return -1;
    }

    if (strlen(level) > 6) { // Maximum length for logging levels
        return -2;
    }

    // Map log level string to enum index
    if (strcmp(level, "ERROR") == 0) {
        level_idx = ERROR;
    } else if (strcmp(level, "WARNING") == 0) {
        level_idx = WARNING;
    } else if (strcmp(level, "INFO") == 0) {
        level_idx = INFO;
    } else if (strcmp(level, "DEBUG") == 0) {
        level_idx = DEBUG;
    } else if (strcmp(level, "TRACE1") == 0) {
        level_idx = TRACE1;
    } else if (strcmp(level, "TRACE2") == 0) {
        level_idx = TRACE2;
    } else if (strcmp(level, "TRACE3") == 0) {
        level_idx = TRACE3;
    } else if (strcmp(level, "TRACE4") == 0) {
        level_idx = TRACE4;
    } else if (strcmp(level, "TRACE5") == 0) {
        level_idx = TRACE5;
    } else if (strcmp(level, "TRACE6") == 0) {
        level_idx = TRACE6;
    } else { // Invalid log level
        return -3;
    }

    pthread_mutex_lock(&mutex);

    if (ctx.pos + strlen(format) + 128 > sizeof(ctx.buffer)) { // Buffer overflow check
        ctx.file = fopen("logs/log_" __func__ "_" time(NULL) "%s".log, "w");
        if (!ctx.file) {
            fprintf(stderr, "Error: Failed to rotate log file\n");
            pthread_mutex_unlock(&mutex);
            return -4;
        }
    }

    va_start(args, format);
    vsnprintf(ctx.buffer + ctx.pos, sizeof(ctx.buffer) - ctx.pos, format, args);
    ctx.pos += strlen(ctx.buffer + ctx.pos);
    va_end(args);

    if (level_idx >= ctx.file_threshold || level_idx > log_level) { // Log only at or above the specified level and when the maximum count is reached
        fputs("[", ctx.file);
        fputs(level, ctx.file);
        fputs("] ", ctx.file);
        fputs(ctx.buffer, ctx.file);
        fputc('\n', ctx.file);
    }

    pthread_mutex_unlock(&mutex);

    if (ctx.pos >= sizeof(ctx.buffer)) { // Reset buffer position when it's full
        ctx.pos = 0;
    }

    return 0;
}
