#include <spdlog/spdlog.h>

namespace fs = std::filesystem;
using json = nlohmann::json;
using ConfigMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;

ConfigMap loadConfig(const std::string& filePath) {
    try {
        if (!fs::exists(filePath)) {
            spdlog::error("Configuration file does not exist: {}", filePath);
            throw std::runtime_error("Configuration file not found");
        }

        std::ifstream jsonFile(filePath);
        if (!jsonFile.is_open()) {
            spdlog::error("Failed to open configuration file: {}", filePath);
            throw std::runtime_error("Failed to open configuration file");
        }

        json j;
        jsonFile >> j;

        ConfigMap config;
        for (auto& item : j.items()) {
            if (!item.second.is_null()) {
                if (!item.second.is_number() && !item.second.is_boolean() && !item.second.is_string() && !item.second.is_number_unsigned()) {
                    spdlog::error("Malformed configuration: {} is not a valid type", item.first);
                    throw std::runtime_error("Malformed configuration");
                }

                config[item.first] = item.second;
            } else {
                spdlog::error("Missing key in configuration file: {}", item.first);
                throw std::runtime_error("Missing key in configuration file");
            }
        }

        return config;
    } catch (const std::exception& e) {
        spdlog::error("Error loading configuration: {}", e.what());
        throw;
    }
}
