from kubernetes import client, config
from kubernetes.client import ApiException

def deploy_application(namespace, app_manifest, parent_namespace='default', retry_attempts=3):
    # Load Kubernetes configuration
    config.load_kube_config()

    # Check if the namespace exists and create a lock file to prevent simultaneous creation
    k8s_api = k8s.CoreV1Api()
    namespace_exists = k8s_api.list_namespace(watch=False).body['items']
    lockfile.acquire(f'/tmp/{namespace}-lock', timeout=60)

    try:
        # Validate the application manifest
        validate_manifest(app_manifest)

        # Create or use the specified parent namespace
        if namespace not in [ns['metadata']['name'] for ns in namespace_exists]:
            try:
                k8s_api.create_namespace(f'/api/v1/namespaces/{namespace}')
                print(f'Namespace {namespace} created.')
            except ApiException as e:
                if retry_attempts > 0:
                    time.sleep(5)
                    deploy_application(namespace, app_manifest, parent_namespace, retry_attempts - 1)
                else:
                    raise Exception(f'Failed to create namespace {namespace}: {e}')
        namespace = k8s_api.list_namespace(watch=False).body['items'][0]['metadata']['name'] if namespace not in [ns['metadata']['name'] for ns in namespace_exists] else parent_namespace

        # Deploy the application to the namespace
        k8s_api.create_namespaced_deployment(namespace, body=app_manifest)
        print(f'Application deployed to namespace {namespace}.')
    finally:
        lockfile.release(f'/tmp/{namespace}-lock')

def validate_manifest(manifest):
