public class RandomStringGenerator {
    private static final char[] CHARACTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".toCharArray();

    public static String generateRandomString(int length, byte[] serializedObject) {
        try (ObjectInput objectInputStream = new ObjectInputStream(new ByteArrayInputStream(serializedObject))) {
            Object obj = objectInputStream.readObject();
            if (obj instanceof Class<?> clazz) {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                byte[] digest = md.digest(clazz.getName().getBytes());

                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < length; i++) {
                    sb.append(CHARACTERS[digest[i % digest.length] & 0xff]);
                }
                return sb.toString();
            } else {
                throw new IllegalArgumentException("Invalid serialized object");
            }
        } catch (IOException | ClassNotFoundException | NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

