#include <openssl/aes.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

typedef struct {
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
} aes_ctx;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *config_file = NULL;
static int key_length = AES_KEYLEN_256;

void cleanup() {
    if (config_file) fclose(config_file);
    EVP_cleanup(); // Cleans up OpenSSL library resources
}

void load_config() {
    if (!config_file) {
        config_file = fopen("config.txt", "r");
        if (!config_file) {
            fprintf(stderr, "Error: Unable to open configuration file\n");
            cleanup();
            exit(1);
        }
    }

    char line[256];
    char *token;
    int key_len = 0;

    while (fgets(line, sizeof(line), config_file)) {
        token = strtok(line, "=");
        if (!token) continue;
        if (strcasecmp(token, "key_length") == 0) {
            token = strtok(NULL, "\n");
            key_len = atoi(token);
            if (key_len < AES_KEYLEN_128 || key_len > AES_KEYLEN_256) {
                fprintf(stderr, "Error: Invalid key length specified in configuration file\n");
                cleanup();
                exit(1);
            }
        }
    }

    key_length = key_len * 8; // Convert to bits
}

void generate_key_iv(const unsigned char *password, aes_ctx *ctx) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx_sha;

    SHA256_Init(&ctx_sha);
    SHA256_Update(&ctx_sha, password, strlen((const char*)password));
    SHA256_Final(digest, &ctx_sha);

    pthread_mutex_lock(&mutex);
    memmove(ctx->key, digest, key_length / 8); // Adjust IV length according to key length
    memset(ctx->iv, 0, AES_BLOCK_SIZE); // Set IV to zero except for the first 16 bytes
    memcpy(ctx->iv, &digest[key_length / 8], AES_BLOCK_SIZE - (key_length / 8));
    pthread_mutex_unlock(&mutex);
}

aes_ctx *init_cipher(const unsigned char *password) {
    aes_ctx *ctx = mmap(NULL, sizeof(aes_ctx), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!ctx) {
        fprintf(stderr, "Error: Failed to allocate memory for AES context\n");
        cleanup();
        exit(1);
    }

    load_config();
    generate_key_iv(password, ctx);

    AES_KEY aes_key;
    AES_set_encrypt_key((const unsigned char *)ctx->key, key_length, &aes_key);

    return ctx;
}

void disable_cipher(aes_ctx *ctx) {
    munmap(ctx, sizeof(aes_ctx));
}
```

