use sysinfo::{CpuExt, SystemExt, SystemRef};
use reqwest::blocking::get;
use serde_json::from_str;
use log::{error, info};
use lazy_static::lazy_static;

#[derive(Debug)]
enum Error {
    CycleDetected,
    InsufficientMemory,
    IoError(std::io::Error),
    ParseJsonError(serde_json::Error),
    GitError(Box<dyn std::error::Error + Send + Sync>),
}

type Task = String;
type Dependencies = HashMap<Task, Vec<Task>>;
type ProjectGraph = (Dependencies, HashSet<Task>);

lazy_static! {
    static ref LOGGER: LazyLock<log::Logger> = log::Logger::new(|| info!(""));
}

fn setup_logging() {
    let _guard = LOGGER.block();
}

fn get_commit_message(repo_path: &PathBuf) -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
    let output = Command::new("git")
        .args(&["log", "-1", "--pretty=%s"])
        .current_dir(repo_path)
        .output()?;
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

fn get_resident_set_size() -> usize {
    let mut sys = System::new();
    sys.refresh_memstats();
    sys.current_memory().total_resident
}

fn traverse(graph: &ProjectGraph, start: &Task, max_depth: u32) -> Result<Vec<Task>, Error> {
    let mut worklist = vec![start];
    let mut visited = HashSet::new();
    let mut result = Vec::new();
    let mut depth = 0;

    while !worklist.is_empty() && depth <= max_depth as usize {
        let task = worklist.pop().unwrap();
        if visited.contains(task) {
            return Err(Error::CycleDetected);
        }
        visited.insert(task.clone());

        result.push(task.clone());
        let deps = &graph.0;
        if let Some(deps) = deps.get(task) {
            for dep in deps {
                if !visited.contains(dep) {
                    worklist.push(dep.clone());
                }
            }
        }

        depth += 1;
    }

    Ok(result)
}

fn execute_task(task: &Task) -> Result<(), Error> {
    // Implement task execution and return a success or failure result.
    unimplemented!()
}

fn measure_and_log_memory_usage() {
    let start = Instant::now();
    let memory_usage = get_resident_set_size();
    info!(target: "memory", "Memory usage: {}", memory_usage);
    info!(target: "time", "Traversal time: {}", start.elapsed().as_secs_f64());
}

fn traverse_and_execute(start_dir: &PathBuf, start_task: &Task, max_depth: u32) -> Result<(), Error> {
    setup_logging();

    let repo_path = start_dir.join(".git");
    if !repo_path.exists() {
        return Err(Error::GitError(Box::new(std::io::Error::new(std::io::ErrorKind::NotFound, "Repository not found"))));
    }

    let commit_message = get_commit_message(&repo_path)?;
    info!("Starting task '{}' (commit: {})", start_task, &commit_message);

    let project_graph = load_project_graph(start_dir)?;
    measure_and_log_memory_usage();

    traverse(&project_graph, start_task, max_depth)?;
    execute_task(start_task)?;
    info!("Task '{}' completed.", start_task);

    Ok(())
}

fn load_project_graph(root: &PathBuf) -> Result<ProjectGraph, Error> {
    unimplemented!()
}

