import os
import sys
import re
import zipfile
import time
from functools import lru_cache
from collections import Counter, deque
import concurrent.futures
import requests

def get_stats(filename):
    with open(filename, "r", encoding="utf-8") as f:
        lines = [l for l in f]
        chars = sum([len(l) for l in lines])
        words = len(re.findall(r'\w+', '\n'.join(lines)))
    return {"lines": len(lines), "words": words, "chars": chars}

def filter_files(filelist, ext_exclude):
    return [f for f in filelist if not any(ext == f.split(".")[-1] for ext in ext_exclude)]

@lru_cache(maxsize=None)
def compress_data(data, output):
    with zipfile.ZipFile(output, "w") as zf:
        for k, v in data.items():
            zf.writestr(k, str(v))

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("path", help="Directory path to scan")
    parser.add_argument("--ext-include", nargs="*", default=["txt"], help="File extensions to include (default: txt)")
    parser.add_argument("--ext-exclude", nargs="*", default=[], help="File extensions to exclude (default: none)")
    parser.add_argument("--output", help="Output ZIP file path (if the number of files exceeds 100)")
    args = parser.parse_args()

    data = Counter()
    fileq = deque(os.listdir(args.path))
    processed = 0

    with concurrent.futures.ProcessPoolExecutor() as executor:
        progress = tqdm(total=len(fileq), leave=True)
        while fileq:
            filename = fileq.popleft()
            if not os.path.isdir(os.path.join(args.path, filename)):
                try:
                    files = filter_files([filename], args.ext_exclude)
                    if files:
                        data.update(get_stats(os.path.join(args.path, filename)))
                        processed += len(files)
                    progress.update(len(files))
                except Exception as e:
                    print(f"Error processing {filename}: {e}")
            else:
                fileq.extendleft(os.listdir(os.path.join(args.path, filename)))
            if processed >= 100 and args.output:
                compressed_data = compress_data(data, args.output)

    print("\nTotal statistics:\n", data)

    if processed >= 100 and args.output:
        upload_to_cloud(compressed_data, args.output)

def upload_to_cloud(zipfile_data, output):
