import time
import threading
import requests
import logging
from collections import defaultdict, namedtuple
from functools import lru_cache
from datetime import timedelta
from concurrent.futures import ThreadPoolExecutor, as_completed

Order = namedtuple('Order', ['id', 'status', 'assigned_deliverer', 'estimated_delivery_time'])

class BackendAPI:
    def __init__(self, base_url, retries=5, delay_between_retries=3, max_requests_per_minute=60):
        self.base_url = base_url
        self.session = requests.Session()
        self.retries = retries
        self.delay_between_retries = delay_between_retries
        self.max_requests_per_minute = max_requests_per_minute

    def fetch_deliverer(self, deliverer_id):
        url = f"{self.base_url}/deliverers/{deliverer_id}"
        return self._make_request(url)

    @lru_cache(maxsize=None)
    def _make_request(self, url, **kwargs):
        start_time = time.time()
        for attempt in range(self.retries):
            try:
                response = self.session.get(url, **kwargs)
                if response.status_code == 200:
                    return response.json()
                else:
                    raise Exception(f"Request failed with status code {response.status_code}")
            except requests.exceptions.RequestException as e:
                elapsed_time = time.time() - start_time
                if attempt < self.retries-1:
                    wait_time = min(self.delay_between_retries, (self.max_requests_per_minute / 60 - (elapsed_time + self.delay_between_retries * attempt)) / self.retries)
                    logging.warning(f"Request failed ({url}). Attempt {attempt+1} of {self.retries}. Retrying in {wait_time} seconds...")
                    time.sleep(wait_time)
                else:
                    raise e
        return None

def handle_order_batch_processing(orders, backend):
    order_status_cache = defaultdict(lambda: timedelta(minutes=60))  # Cache expiration times for each status

    def process_order(order):
        order.assigned_deliverer = backend.fetch_deliverer(order.id % len(backend.fetch_deliverer(_)) if len(backend.fetch_deliverer(_)) > 0 else None)['id']
        backend._make_request(f"{backend.base_url}/orders/{order.id}", json={"status": order.status, "assigned_deliverer": order.assigned_deliverer}, allow_redirects=False)

    with ThreadPoolExecutor() as executor:
        processed_orders = []
        for sub_batch in [orders[i:i+100] for i in range(0, len(orders), 100)]:  # Partition orders into smaller sub-batches
            results = list(executor.map(process_order, sub_batch))
            processed_orders += [result for result in results if result is not None]  # Filter out failed updates

    # Log detailed error messages for each failed update
    for order in orders:
        if order not in processed_orders:
            current_time = time.strftime('%Y-%m-%d %H:%M:%S')
            missing_fields = [field for field, value in [('status', order.status), ('assigned_deliverer', order.assigned_deliverer)] if value is None]
            logging.error(f"Failed to process order #{order.id}. Missing fields: {missing_fields}.")

def main():
    backend = BackendAPI("http://your-backend-api.com")  # Replace with your actual backend API URL
    orders = [Order(i, f"Preparing", None, time.time() + i/10) for i in range(500)]  # Sample order data
    handle_order_batch_processing(orders, backend)

if __name__ == "__main__":
    main()
```

