let scriptCache = new Map();
let activeRequests = 0;

function fetchScript(scriptObj) {
  const key = scriptObj.src + '_' + scriptObj.version;
  if (scriptCache.has(key)) return Promise.resolve(scriptCache.get(key));

  return fetch(scriptObj.src).then((response) => {
    if (!response.ok) throw new Error(`Error ${response.status}: ${response.statusText}`);
    scriptCache.set(key, response);
    activeRequests--;
    updateFooter();
    return response;
  }).catch((error) => {
