async function renderScripts(scripts) {
  activeRequests = scripts.length;
  for (const scriptObj of scripts) {
    const scriptPromise = fetchScript(scriptObj);
    scripts[scripts.indexOf(scriptObj)].promise = scriptPromise;
  }
  await Promise.all(scripts.map(({ promise }) => promise));
}

function updateFooter() {
  footer.innerHTML = '';
  for (const [key, value] of scriptCache.entries()) {
    const scriptElement = document.createElement('script');
    scriptElement.src = key;
    scriptElement.innerText = value;
    footer.appendChild(scriptElement);
  }
}

