```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

void dynamicFileNameUpdate(char *filename, char *fileType, int version) {
    int i;
    int hasExtension = 0;
    int extensionIndex = -1;
    int versionIndex = -1;

    for (i = 0; filename[i] != '\0' && i < MAX_FILENAME_LENGTH; ++i) {
        if (filename[i] == '.') {
            hasExtension = 1;
            extensionIndex = i;
        }
        if (isdigit((int)filename[i])) {
            versionIndex = i;
        }
    }

    // Handle multiple extensions or version numbers, and ensure file type is non-empty
    if (hasExtension && (extensionIndex == -1 || versionIndex != -1)) {
        printf("Invalid filename format\n");
        return;
    }

    if (!versionIndex) {
        strcat(filename, ".v");
        itoa(version, filename + strlen(filename), 10);
    }

    if (extensionIndex != -1 && versionIndex == -1) {
        int extensionLength = strlen(&filename[extensionIndex]);
        char newExtension[MAX_FILENAME_LENGTH] = {0};
        strncpy(newExtension, &filename[extensionIndex], extensionLength);
        strcat(newExtension, fileType);
        if (strlen(newExtension) > MAX_FILENAME_LENGTH - strlen(filename)) {
            printf("Filename too long\n");
            return;
        }
        memmove(&filename[extensionIndex + strlen(newExtension)], &filename[extensionIndex], strlen(&filename[extensionIndex]));
        strcat(filename, newExtension);
    } else if (versionIndex != -1 && extensionIndex != -1) {
        // Handle cases where both version number and extension exist
    }
}
