import asyncio
import json
import re
import hashlib
import hmac
import time
import os
from datetime import datetime
from aiohttp import web, ClientSession, WSMsgType
from base64 import b64encode, b64decode
import threading
import queue
import functools
import logging
from zlib import decompress

class JSONObject:
    def __init__(self, data):
        self._data = json.loads(json.dumps(data)) if isinstance(data, str) else data

    @staticmethod
    def from_string(s):
        return JSONObject(s)

    def to_string(self):
        return json.dumps(self._data)

    def __getitem__(self, item):
        return self._data[item]

    def append(self, *items):
        if not isinstance(items, (list, tuple)):
            items = [items]
        for item in items:
            if type(item) == JSONObject:
                self._data.append(item._data)
            else:
                self._data.append(item)

    def insert(self, position, *items):
        if not isinstance(items, (list, tuple)):
            items = [items]
        if position >= len(self._data):
            raise IndexError("Position out of bounds")
        self._data.insert(position, items)

class AttackDatabase:
    def __init__(self, url, cache=None):
        self.url = url
        self.cache = cache or {}
        self.lock = threading.Lock()

    async def get_attacks(self):
        with self.lock:
            if not self.cache:
                async with ClientSession() as session:
                    async with session.get(self.url) as response:
                        data = await response.read()
                        self.cache = json.loads(data)
        return self.cache

    async def query_attacks(self, text):
        matches = [match[0] for match in re.findall(r'<attack>(.*?)<\/attack>', text)]
        attacks = await self.get_attacks()
        results = [attack for attack in matches if attack in attacks]
        return results

class Character:
    def __init__(self, id, name):
        self.id = id
        self.name = name
        self._attacks = JSONObject([])
        self.session = None

    async def load_attacks(self):
        database = AttackDatabase('http://attack-database-url')
        attacks = await database.query_attacks(self.name)
        for attack in attacks:
            self._attacks.append(JSONObject({'id': attack, 'cooldown': 0}))

async def rate_limit(function):
    def wrapped(*args, **kwargs):
        timestamp = int(time.time()) // 60
        count = kwargs['db']._rate_limits.get((timestamp, args[0].id), 0)
        if count >= 500:
            raise ValueError("Rate limit exceeded")
        kwargs['db']._rate_limits[(timestamp, args[0].id)] += 1
        return await function(*args, **kwargs)
    return wrapped

async def authenticate(function):
    def wrapped(request):
        auth = request.headers.get('Authorization')
        if not auth:
            return web.Response(status=401, text="Unauthorized")
        key = os.environ['SECRET_KEY']
        decoded = b64decode(auth[7:]).decode()
        signature = hmac.new(key.encode(), msg=request.url + request.method + decoded, digestmod=hashlib.sha256).digest()
        if hmac.compare_digest(signature, decoded):
            return await function(request)
        else:
            return web.Response(status=401, text="Invalid signature")
    return wrapped

class WebSocketHandler(web.WebsocketResource):
    def __init__(self, character, db):
        self.character = character
        self.db = db
        super().__init__()

    async def on_message(self, message):
        data = json.loads(message)
        if 'action' not in data or data['action'] not in ['insert', 'update', 'delete']:
            return
        action = data['action']
        position = data.get('position')
        attack_data = data.get('attack')

        async with self.db.get_attacks() as attacks:
            if action == 'insert':
                if not attack_data['name'] in attacks:
                    await self.character._attacks.append(JSONObject(attack_data))
            elif action == 'update':
                index = [i for i, a in enumerate(self.character._attacks) if a['name'] == attack_data['name']][0]
                if index < len(self.character._attacks):
                    self.character._attacks[index] = JSONObject(attack_data)
            elif action == 'delete':
                index = [i for i, a in enumerate(self.character._attacks) if a['name'] == attack_data['name']][0]
                if index < len(self.character._attacks):
                    del self.character._attacks[index]

class App:
    def __init__(self, db):
        self.db = db
        self.characters = JSONObject([])

    async def load_characters(self):
        with open('characters.txt', 'r') as file:
            for line in file:
                data = json.loads(line)
                character = Character(**data)
                await character.load_attacks()
                self.characters.append(character)

async def startup(app):
    app.db.rate_limits = {}
    characters = JSONObject([])
    async with app.db.get_attacks() as attacks:
        for attack in attacks:
            characters.append({'id': attack, 'cooldown': 0})
    await app.load_characters()

def main():
    app = App(AttackDatabase('http://attack-database-url'))
    web.run_app(app, host='0.0.0.0', port=8080)

if __name__ == "__main__":
    main()
```

