class Compressor:
    COMPRESSION_ALGORITHMS = ["lz4", "zstandard", "brotli"]

    def __init__(self, compression="lz4"):
        self.compression = compression

    @staticmethod
    def compress(data, algorithm):
        if algorithm == "lz4":
            return compressBound(data) + decompressAll(None, lz4.compress(data))
        elif algorithm == "zstandard":
            return compressBound(data) + zstd_compress(data)
        elif algorithm == "brotli":
            with BrotliEncoder().encoder(quality=11) as enc:
                return compressBound(data) + enc.compress(data)

    @staticmethod
    def decompress(data, algorithm):
        offset = data.find(b"\n") if data else 0
        compressed_data = data[offset:]
        decompressed_data = None
        if algorithm == "lz4":
            decompressed_data = lz4.decompress(compressed_data)
        elif algorithm == "zstandard":
            decompressed_data = zstd.decompress(compressed_data, max_length=math.inf)
        elif algorithm == "brotli":
            with BrotliDecoder() as dec:
                decompressed_data = dec.decompress(compressed_data)
        return decompressed_data

class Encryptor:
    def __init__(self, key):
        self.cipher = AES.new(key, AES.MODE_CBC, iv=get_random_bytes(16))

    @staticmethod
    def encrypt(data, key):
        return pad(self.cipher.encrypt(data), AES.block_size)

    @staticmethod
    def decrypt(data, key):
        return unpad(self.cipher.decrypt(data), AES.block_size)

def compress_and_encrypt_file(filepath, compression, key):
