import threading
import time
import requests
from functools import lru_cache, partial
from collections import OrderedDict
from compressor import Compressor
from load_balancer import LoadBalancer
from logger import Logger
from api import API
from retention_policy import RetentionPolicy

class DistributedCache:
    def __init__(self, config, compressor=Compressor(), logger=Logger(), balancer=LoadBalancer()):
        self.config = config
        self.compressor = compressor
        self.logger = logger
        self.balancer = balancer
        self.api = API(config)
        self.cache = {}
        self.policies = {
            'LRU': lru_cache(maxsize=self.config['lru_cache_size']),
            'LFU': OrderedDict()
        }
        self.pruning_thread = threading.Thread(target=self.prune)

    def __getitem__(self, key):
        return self.policies['LRU'][key] if key in self.policies['LRU'] else self.policies['LFU'][key]

    def __setitem__(self, key, value):
        self.logger.log(f'Cache update: {key}')
        if key not in self.cache:
            self.cache[key] = self.api.get_stock_data(key)
            compressed_data = self.compressor.compress(self.cache[key])
            self.cache[key] = compressed_data

        if key in self.policies['LRU']:
            self.policies['LRU'][key] = value
        else:
            self.policies['LFU'][key] = value
            self.prune()

    def prune(self):
        for key in list(self.policies['LFU'].keys()):
            if len(self.policies['LFU']) > self.config['cache_size']:
                least_frequently_used = min(self.policies['LFU'], key=lambda k: len(self.policies['LFU'][k]))
                del self.cache[least_frequently_used]
                del self.policies['LFU'][least_frequently_used]

    def start(self):
        self.pruning_thread.start()
        while True:
            for key in self.config['tickers']:
                if key not in self.cache:
                    node = self.balancer.choose()
                    self.__setitem__(key, self.api.get_stock_data(key, node))
            time.sleep(self.config['update_interval'])

    def stop(self):
        self.pruning_thread.join()

def main():
    config = {
        'tickers': ['AAPL', 'GOOG', 'AMZN'],
        'lru_cache_size': 100,
        'cache_size': 500,
        'update_interval': 60,
        # Add more configuration parameters as needed
    }
    cache = DistributedCache(config)
    cache.start()

if __name__ == "__main__":
    main()
