```c
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/sha.h>
#include <stddef.h>
#include <stdlib.h>

typedef struct AES256_GCM {
    AES_KEY aes;
    GCm_ctx *gcm;
    unsigned char iv[16];
    unsigned char tag[16]; // default to 16 bytes
    size_t tag_len;
} AES256_GCM;

AES256_GCM* aes256_gcm_init(const char *password, const unsigned char *iv, size_t iv_len, size_t tag_len) {
    if (!password || !*password) return NULL;

    AES_KEY key;
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final((unsigned char*)key.kt_skey, &sha256);

    AES256_GCM *ctx = malloc(sizeof(AES256_GCM));
    if (!ctx) return NULL;

    memset(ctx->iv, 0, sizeof(ctx->iv));
    memcpy(ctx->iv, iv, iv_len);
    ctx->tag_len = tag_len > 16 ? 16 : tag_len;

    AES_set_encrypt_key((const unsigned char*)key.kt_skey, 256, &ctx->aes);
    GCm_init(&ctx->gcm, &ctx->aes, ctx->iv, ctx->tag_len * 8);

    return ctx;
}

void aes256_gcm_cleanup(AES256_GCM* ctx) {
    if (!ctx) return;

    GCm_cleanup(ctx->gcm);
    free(ctx);
}

int aes256_gcm_encrypt(AES256_GCM *ctx, const unsigned char *data, size_t data_len, unsigned char **out) {
    if (!ctx || !data || !*data || !out) return 0;

    gcry_cipher_authenticate(ctx->gcm, GCRY_CIPHER_MODE_GCM, data, data_len, NULL, 0, ctx->tag);
    *out = malloc(data_len + ctx->tag_len);
    memcpy(*out, data, data_len);
    memcpy((*out) + data_len, ctx->tag, ctx->tag_len);

    return 1;
}

int aes256_gcm_decrypt(AES256_GCM *ctx, const unsigned char *data, size_t data_len, unsigned char **out) {
    if (!ctx || !data || !*data || !out) return 0;

    if (data_len < ctx->tag_len) return 0;

    memcpy(ctx->tag, data + data_len - ctx->tag_len, ctx->tag_len);
    gcry_cipher_authenticate(ctx->gcm, GCRY_CIPHER_MODE_GCM, data, data_len - ctx->tag_len, NULL, 0, ctx->tag);

    *out = malloc(data_len - ctx->tag_len);
    memcpy(*out, data, data_len - ctx->tag_len);

    return 1;
}

int aes256_gcm_verify_tag(AES256_GCM *ctx, const unsigned char *data, size_t data_len) {
    if (!ctx || !data || !*data) return 0;

    if (data_len < ctx->tag_len) return 0;

    memcpy(ctx->tag, data + data_len - ctx->tag_len, ctx->tag_len);
    gcry_cipher_authenticate(ctx->gcm, GCRY_CIPHER_MODE_GCM, data, data_len - ctx->tag_len, NULL, 0, ctx->tag);

    return 1;
}
```
