public class WebsiteManager
{
    private readonly string _directoryPath;
    private readonly ILogger<WebsiteManager> _logger;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1);
    private readonly ConcurrentDictionary<int, Task> _runningTasks = new ConcurrentDictionary<int, Task>();
    private readonly TimeSpan _timeout = TimeSpan.FromMinutes(5);

    public WebsiteManager(string directoryPath, ILogger<WebsiteManager> logger)
    {
        _directoryPath = directoryPath;
        _logger = logger;
    }

    public async Task AddSiteAsync(string siteName, int portNumber)
    {
        await _semaphore.WaitAsync();
        try
        {
            if (!Directory.Exists(_directoryPath))
                throw new DirectoryNotFoundException($"The directory '{_directoryPath}' does not exist.");

            var webConfigPath = Path.Combine(_directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
                await GenerateWebConfigAsync(siteName);

            if (!ValidateSiteName(siteName))
                throw new ArgumentException("Invalid site name.");

            var webHostBuilder = CreateWebHostBuilder(siteName, portNumber);
            var host = webHostBuilder.Build();

            var task = Task.Run(() =>
            {
                try
                {
                    host.Run();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "An error occurred while starting the site.");
                }
            });

            _runningTasks[portNumber] = task;

            await Task.DelayUntil(() => !_runningTasks.Any(), _timeout);
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private bool ValidateSiteName(string siteName)
    {
        // Implement your validation logic here, for example:
        return !char.IsControl(siteName[0]) &&
                siteName.All(c => char.IsLetterOrDigit(c) || c == '_');
    }

    private async Task GenerateWebConfigAsync(string siteName)
    {
        // Implement your external configuration management system here, for example:
        var builder = new ConfigurationBuilder()
            .AddJsonFile("websettings.json");
        var configuration = builder.Build();

        var webConfigContent = configuration.GetSection("DefaultWebConfig").GetChildren().Select(s => s.CreateEditor()).WriteToStream(new MemoryStream());
        File.WriteAllBytes(Path.Combine(_directoryPath, "web.config"), webConfigContent.ToArray());
    }

    private IWebHostBuilder CreateWebHostBuilder(string siteName, int portNumber)
    {
        // Implement your custom hosting model here using ASP.NET Core or any other framework.
        return Microsoft.AspNetCore.WebHost.CreateDefaultBuilder()
            .UseStartup<Startup>()
            .ConfigureAppConfiguration((hostingContext, configuration) =>
            {
                configuration.Sources.Clear();
                var appSettings = hostingContext.HostingEnvironment.ContentRootFileProvider
                    .GetFiles("appsettings.json")
                    .FirstOrDefault();
                if (appSettings != null)
                    configuration.AddJsonFile(appSettings.PhysicalPath);
            })
            .UseUrls($"http://localhost:{portNumber}")
            .UseIISIntegration()
            .UseContentRoot(_directoryPath)
            .ConfigureLogging((hostingContext, builder) =>
            {
                builder.ClearProviders();
                builder.AddConsole();
                builder.AddDebug();
            });
    }

    public void StopSite(int portNumber)
    {
        if (_runningTasks.TryRemove(portNumber, out var task))
            task.Wait();
    }
}
