```csharp
using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.Common;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;

public class DynamicDatabaseConnectionManager
{
    private readonly string _connectionStringTemplate;
    private readonly ConcurrentDictionary<string, string> _tenantConnectionStrings;
    private readonly ConcurrentPool<DbConnection> _dbConnectionPool;
    private readonly IConfiguration _configuration;

    public DynamicDatabaseConnectionManager(IConfiguration configuration)
    {
        _configuration = configuration;
        _connectionStringTemplate = configuration["connectionStrings:template"];
        _tenantConnectionStrings = new ConcurrentDictionary<string, string>();
        _dbConnectionPool = new ConcurrentPool<DbConnection>(EstablishConnection);
    }

    public DbConnection EstablishConnection(string tenantId)
    {
        var connectionString = GetTenantConnectionString(tenantId);
        return new DatabaseProvider(connectionString).CreateConnection();
    }

    public async Task<DataTable> ExecuteQuery(string query, string tenantId)
    {
        using (var connection = _dbConnectionPool.Take())
        {
            await connection.OpenAsync();
            var cmd = new DbCommand(query, connection);
            var adapter = new DbDataAdapter(cmd);
            var dataSet = new DataSet();
            adapter.Fill(dataSet);
            return dataSet.Tables[0];
        }
    }

    public async Task BeginTransaction(string tenantId)
    {
        using (var connection = _dbConnectionPool.Take())
        {
            await connection.OpenAsync();
            var cmd = new DbCommand("BEGIN TRANSACTION", connection);
            await cmd.ExecuteNonQueryAsync();
        }
    }

    public async Task CommitTransaction(string tenantId)
    {
        using (var connection = _dbConnectionPool.Take())
        {
            await connection.OpenAsync();
            var cmd = new DbCommand("COMMIT TRANSACTION", connection);
            await cmd.ExecuteNonQueryAsync();
        }
    }

    public async Task RollbackTransaction(string tenantId)
    {
        using (var connection = _dbConnectionPool.Take())
        {
            await connection.OpenAsync();
            var cmd = new DbCommand("ROLLBACK TRANSACTION", connection);
            await cmd.ExecuteNonQueryAsync();
        }
    }

    public string GetTenantConnectionString(string tenantId)
    {
        return _tenantConnectionStrings.GetOrAdd(tenantId, () => FetchLatestConnectionString());
    }

    public void CloseConnection(DbConnection connection)
    {
        if (connection != null && connection.State == ConnectionState.Open)
            connection.Close();
        _dbConnectionPool.Return(connection);
    }

    public async Task UpdateConfiguration()
    {
        var newConfig = await FetchLatestConfiguration();
        if (newConfig != null && newConfig.IsChanged())
        {
            _connectionStringTemplate = newConfig["connectionStrings:template"];
            _tenantConnectionStrings.Clear();
        }
    }

    public override string ToString()
    {
        var builder = new System.Text.StringBuilder();
        builder.AppendLine($"DynamicDatabaseConnectionManager - Connection Template: {_connectionStringTemplate}");
        builder.AppendLine("Tenant Connection Strings:");
        _tenantConnectionStrings.ToList().ForEach(kv => builder.AppendLine($"{kv.Key}: {kv.Value}"));

        return builder.ToString();
    }

    // ... Implement FetchLatestConfiguration, DatabaseProvider, and other required classes or methods for performance optimization and edge cases handling.
}
